#[test]
fn cpython_type_ignore_comments_inside_brackets_diff_subset() {
    assert_cpython_output_parity(&DiffCase {
        origin: "Lib/test/test_type_comments.py public type: ignore comments inside signatures and brackets",
        name: "type-ignore-comments-inside-brackets",
        source: r#"import ast
def signature(
    first,  # type: ignore
    second=2,  # type: ignore[assignment]
    *args,  # type: ignore
    keyword=3,  # type: ignore[misc]
    **kwargs  # type: ignore
):  # type: ignore
    return first + second + keyword + len(args) + len(kwargs)
print('signature', signature(1))
def opened(  # type: ignore
    value,
    /,  # type: ignore
    other,
):
    return value - other
print('opened', opened(5, 2))
def own_line(
    # type: ignore
    value,
):
    return value
print('own-line', own_line(7))
total = signature(  # type: ignore
    10,  # type: ignore[arg-type]
)
print('call', total)
items = [
    1,  # type: ignore
    2,
]
print('list', items)
pick = (lambda a,  # type: ignore
        b: a + b)
print('lambda', pick(1, 2))
def with_default(
    value=(1,  # type: ignore
           2),
):
    return value
print('default', with_default())
namespace = {}
exec(compile('def compiled(\n    a,  # type: ignore\n):\n    return a * 2\n', '<type-ignore>', 'exec'), namespace)
print('compiled', namespace['compiled'](4))
sources = {
    'after-comma': 'def f(\n    a,  # type: ignore\n    b,  # type: ignore[assignment]\n):\n    pass\n',
    'last-no-comma': 'def f(\n    a  # type: ignore\n):\n    pass\n',
    'after-open': 'def f(  # type: ignore\n    a,\n):\n    pass\n',
    'then-comment': 'def f(\n    a,  # type: ignore\n    b,  # type: int\n):\n    pass\n',
    'star': 'def f(\n    *args,  # type: ignore\n    **kwargs  # type: ignore[misc]\n):\n    pass\n',
    'keyword-only': 'def f(\n    *,\n    a=1,  # type: ignore\n):\n    pass\n',
    'slash': 'def f(\n    a,\n    /,  # type: ignore\n    b,\n):\n    pass\n',
}
for label, source in sources.items():
    plain = ast.parse(source)
    typed = ast.parse(source, type_comments=True)
    arguments = typed.body[0].args
    params = arguments.posonlyargs + arguments.args + arguments.kwonlyargs + [arg for arg in (arguments.vararg, arguments.kwarg) if arg]
    print(label, len(plain.type_ignores), [(node.lineno, node.tag) for node in typed.type_ignores], [param.type_comment for param in params])"#,
    });
}

