#[test]
fn cpython_json_loads_nonfinite_constants_diff_subset() {
    assert_cpython_output_parity(&DiffCase {
        origin: "Lib/json public loads non-finite constant subset",
        name: "json-loads-nonfinite-constants",
        source: r#"import json, math
for source in ['NaN', 'Infinity', '-Infinity', '[NaN, Infinity, -Infinity]', '{"x": NaN, "y": Infinity}']:
    value = json.loads(source)
    print(source, type(value).__name__, repr(value))
    encoded = json.dumps(value)
    print(encoded)
    reparsed = json.loads(encoded)
    if isinstance(reparsed, list):
        print(math.isnan(reparsed[0]), math.isinf(reparsed[1]), math.isinf(reparsed[2]), reparsed[2] < 0)
    elif isinstance(reparsed, dict):
        print(math.isnan(reparsed['x']), math.isinf(reparsed['y']))
    else:
        print(math.isnan(reparsed) if source == 'NaN' else math.isinf(reparsed), reparsed < 0)"#,
    });
}

#[test]
fn cpython_json_loads_parse_hooks_diff_subset() {
    assert_cpython_output_parity(&DiffCase {
        origin: "Lib/json public loads parse_int/parse_float/parse_constant hook subset",
        name: "json-loads-parse-hooks",
        source: r#"import json

def pint(s):
    print('parse_int', s)
    return 'I:' + s

def pfloat(s):
    print('parse_float', s)
    return 'F:' + s

def pconst(s):
    print('parse_constant', s)
    return 'C:' + s

value = json.loads('[1, -2, 3.5, -0.0, 6.02e+23, NaN, Infinity, -Infinity]', parse_int=pint, parse_float=pfloat, parse_constant=pconst)
print(value)
print(json.loads('{"a": 123, "b": 4.5}', parse_int=lambda s: ('int', s), parse_float=lambda s: ('float', s)))
print(json.loads('"x"', parse_int=1))
print(json.loads('1', parse_int=lambda s: None))
print(json.loads('1', parse_int=lambda s: [s]))
print(json.loads('1.5', parse_float=lambda s: None))
print(json.loads('NaN', parse_constant=lambda s: [s]))
print(json.loads('[1, 2]', parse_int=lambda s: {'n': s}))
for label, source, kwargs in [
    ('int-false', '1', dict(parse_int=False)),
    ('int-zero', '1', dict(parse_int=0)),
    ('int-empty-string', '1', dict(parse_int='')),
    ('int-empty-list', '1', dict(parse_int=[])),
    ('float-false', '1.5', dict(parse_float=False)),
    ('constant-false', 'NaN', dict(parse_constant=False)),
]:
    value = json.loads(source, **kwargs)
    print(label, type(value).__name__, repr(value), value != value)
class FalseHook:
    def __bool__(self):
        print('bool falsehook')
        return False
class BoolBoom:
    def __bool__(self):
        print('bool boom')
        raise ValueError('bool-boom')
print('falsehook', json.loads('1', parse_int=FalseHook()))
try:
    json.loads('1', parse_int=BoolBoom())
except Exception as error:
    print('boom', type(error).__name__, str(error))
def boom_int(s):
    raise ValueError('boom-int')

def boom_float(s):
    raise ValueError('boom-float')

def boom_constant(s):
    raise ValueError('boom-constant')

# expected non-callable hook error: 'int' object is not callable
for label, source, kwargs in [
    ('int-noncallable', '1', dict(parse_int=1)),
    ('float-noncallable', '1.5', dict(parse_float=1)),
    ('constant-noncallable', 'NaN', dict(parse_constant=1)),
]:
    try:
        json.loads(source, **kwargs)
    except Exception as error:
        print(label, type(error).__name__, str(error))
for label, kwargs in [
    ('int-boom', dict(parse_int=boom_int)),
    ('float-boom', dict(parse_float=boom_float)),
    ('constant-boom', dict(parse_constant=boom_constant)),
]:
    try:
        json.loads({'int-boom':'1','float-boom':'1.5','constant-boom':'NaN'}[label], **kwargs)
    except Exception as error:
        print(label, type(error).__name__, str(error))"#,
    });
}

#[test]
fn cpython_json_loads_object_hook_diff_subset() {
    assert_cpython_output_parity(&DiffCase {
        origin: "Lib/json public loads object_hook subset",
        name: "json-loads-object-hook",
        source: r#"import json

events = []
def hook(value):
    print('hook', sorted(value.items()))
    events.append(sorted(value.items()))
    return {'seen': len(events), 'value': value}

print(json.loads('{}', object_hook=hook))
print(json.loads('{"outer": {"inner": 1}, "list": [{"x": 2}]}', object_hook=hook))
print(json.loads('{"a": 1}', object_hook=lambda value: None))
print(json.loads('{"a": 1}', object_hook=lambda value: [value]))
print(json.loads('{"outer": {"inner": 1}}', object_hook=lambda value: list(sorted(value))))
print(json.loads('[1, 2]', object_hook=1))

def boom(value):
    raise ValueError('boom-object')

# expected non-callable hook error: 'int' object is not callable
for label, source, kwargs in [
    ('object-hook-noncallable', '{}', dict(object_hook=1)),
    ('object-hook-boom', '{}', dict(object_hook=boom)),
]:
    try:
        json.loads(source, **kwargs)
    except Exception as error:
        if label == 'object-hook-boom':
            print(label, type(error).__name__, str(error))
        else:
            print(label, type(error).__name__, str(error))"#,
    });
}

