/// Bit-exact logarithms of integers too large for a float, where the
/// platforms differ: CPython's `log(x) + log(2) * e` is a fused
/// multiply-add only on Apple silicon (tests/README.md, "Platform-dependent
/// behavior").
#[test]
fn cpython_math_big_int_log_diff() {
    assert_cpython_output_parity(&DiffCase {
        origin: "math.log, log2, log10 of huge integers (CPython 3.14.6 oracle)",
        name: "math-big-int-log",
        source: r#"import math
state = 12345
ints = [2 ** 1024, 2 ** 1024 - 1, 10 ** 400, 10 ** 1000, 3 ** 2000, 7 ** 900, 2 ** 2000 + 1]
for i in range(150):
    state = (state * 6364136223846793005 + 1442695040888963407) % 2 ** 64
    ints.append((state | 1 << 63) << (1000 + state % 9000) | state % 4)
print([(math.log(n).hex(), math.log2(n).hex(), math.log10(n).hex(), math.log(n, 10).hex()) for n in ints])"#,
    });
}

/// math.cbrt against CPython with the platform's listed differences
/// (tests/oracles/math/cbrt-exclusions.txt; tests/README.md,
/// "Platform-dependent behavior"). The release gate applies the same
/// comparison to the shipped binary (tests/release_gate/math_probe.py).
#[test]
fn cpython_math_cbrt_diff_subset() {
    let source = include_str!("oracles/math/cbrt_case.py");
    // The oracle's differences for this platform (`OS-ARCH`).
    let platform = format!("{}-{}", std::env::consts::OS, std::env::consts::ARCH);
    let exclusions = include_str!("oracles/math/cbrt-exclusions.txt")
        .lines()
        .filter(|line| !line.starts_with('#') && !line.trim().is_empty())
        .filter_map(|line| {
            let mut fields = line.split_whitespace();
            (fields.next() == Some(platform.as_str()))
                .then(|| (fields.next().expect("input"), fields.next().expect("oracle result")))
        })
        .collect::<Vec<_>>();
    let cpython = run_cpython(source).expect("failed to run CPython for math.cbrt");
    assert!(
        cpython.status.success(),
        "CPython rejected the math.cbrt case:\n{}",
        String::from_utf8_lossy(&cpython.stderr)
    );
    let cpython = String::from_utf8(cpython.stdout).expect("CPython emitted UTF-8");
    let cpython = cpython.lines().collect::<Vec<_>>();
    let mnpy = run_minipython_source(source).expect("MiniPython runs the math.cbrt case");
    assert_eq!(mnpy.len(), cpython.len(), "line count: mnpy {mnpy:?}");

    let ulp_distance = |a: f64, b: f64| (a.to_bits() as i64 - b.to_bits() as i64).unsigned_abs();
    let parse_hex = |text: &str| -> f64 {
        let (negative, digits) = match text.strip_prefix('-') {
            Some(rest) => (true, rest),
            None => (false, text),
        };
        let digits = digits.strip_prefix("0x").expect("float.hex() output");
        let (mantissa, exponent) = digits.split_once('p').expect("float.hex() exponent");
        let (lead, fraction) = mantissa.split_once('.').expect("float.hex() fraction");
        let bits = u64::from_str_radix(fraction, 16).expect("hex fraction");
        let exponent: i32 = exponent.parse().expect("decimal exponent");
        let lead: u64 = lead.parse().expect("leading digit");
        let value = (lead as f64 + bits as f64 / 2f64.powi(52)) * 2f64.powi(exponent);
        if negative { -value } else { value }
    };
    let mut used = Vec::new();
    let mut problems = Vec::new();
    for (theirs, ours) in cpython.iter().zip(&mnpy) {
        let input = theirs
            .strip_prefix("cbrt ")
            .and_then(|rest| rest.split(' ').nth(1));
        let listed = input.and_then(|input| {
            exclusions
                .iter()
                .find(|(listed, _)| *listed == input)
        });
        match listed {
            Some((input, oracle)) => {
                used.push(*input);
                let theirs_value = theirs.rsplit(' ').next().unwrap_or_default();
                let ours_value = ours.rsplit(' ').next().unwrap_or_default();
                let same_input = theirs.rsplit_once(' ').map(|(head, _)| head)
                    == ours.rsplit_once(' ').map(|(head, _)| head);
                if theirs == ours {
                    problems.push(format!("stale exclusion {input}: CPython now matches ({theirs})"));
                } else if theirs_value != *oracle || !same_input {
                    problems.push(format!("{input}: expected CPython {oracle}, got {theirs:?} vs mnpy {ours:?}"));
                } else if ulp_distance(parse_hex(theirs_value), parse_hex(ours_value)) > 2 {
                    problems.push(format!("{input}: mnpy {ours_value} is not within 2 ulp of {oracle}"));
                }
            }
            None if theirs != ours => problems.push(format!("CPython {theirs:?} vs mnpy {ours:?}")),
            None => {}
        }
    }
    for (input, _) in &exclusions {
        if !used.contains(input) {
            problems.push(format!("exclusion {input} is not an input of the case"));
        }
    }
    assert!(problems.is_empty(), "math.cbrt differs from CPython:\n{}", problems.join("\n"));
}

#[test]
fn cpython_math_erf_erfc_diff_subset() {
    assert_cpython_output_parity(&DiffCase {
        origin: "Lib/test/test_math.py::MathTests erf/erfc public stable subset",
        name: "math-erf-erfc",
        source: r#"import math
for fn in [math.erf, math.erfc]:
    print(fn.__name__, type(fn(0)).__name__)
    for value in [-2.0, -1.0, 0.5, 1.0, 2.0]:
        print(value, round(fn(value), 6))
    print('zero', repr(fn(-0.0)), repr(fn(0.0)))
    print('special', fn(math.inf), fn(-math.inf), math.isnan(fn(math.nan)))

class Carrier:
    # holds one number and hands it back through a single conversion hook
    def __init__(self, payload):
        self.payload = payload
class FloatLike(Carrier):
    def __float__(self):
        return self.payload
class IndexLike(Carrier):
    def __index__(self):
        return self.payload
class BadFloat:
    def __float__(self):
        return 1
class RaisesFloat:
    def __float__(self):
        raise ValueError('bad float')

print(round(math.erf(FloatLike(1.0)), 6), round(math.erfc(FloatLike(1.0)), 6))
print(math.erf(IndexLike(0)), math.erfc(IndexLike(0)))
for label, expr in [
    ('erf-0', lambda: math.erf()),
    ('erfc-0', lambda: math.erfc()),
    ('erf-2', lambda: math.erf(1, 2)),
    ('erfc-2', lambda: math.erfc(1, 2)),
    ('erf-str', lambda: math.erf('1.0')),
    ('erfc-complex', lambda: math.erfc(1+2j)),
    ('erf-big-index', lambda: math.erf(IndexLike(10**10000))),
    ('erfc-bad-float', lambda: math.erfc(BadFloat())),
    ('erf-raises', lambda: math.erf(RaisesFloat())),
    ('erfc-keyword', lambda: math.erfc(x=1)),
]:
    try:
        expr()
    except Exception as error:
        print(label, error.__class__.__name__)"#,
    });
}

