#[test]
fn cpython_collections_abc_sequence_mixins_diff_subset() {
    assert_cpython_output_parity(&DiffCase {
        origin: "Lib/test/test_collections.py::TestCollectionABCs::test_Sequence_mixins",
        name: "collections-abc-sequence-mixins",
        source: r#"from collections.abc import Sequence
class Frozen(Sequence):
    # only __getitem__ and __len__ are provided; index/count/contains/iter/reversed come from Sequence
    def __init__(self, items):
        self._items = tuple(items)
    def __len__(self):
        return len(self._items)
    def __getitem__(self, position):
        return self._items[position]
def outcome(target, *args):
    try:
        return target.index(*args)
    except ValueError:
        return 'missing'
word = 'mississippi'
bounds = [None, -10**6, 10**6] + list(range(-len(word) - 2, len(word) + 3, 2))
checked = 0
differences = []
for source in (word, list(word)):
    shadow = Frozen(source)
    for needle in sorted(set(word)) + ['q']:
        for args in [(needle,)] + [(needle, lo) for lo in bounds if lo is not None] + [
                (needle, lo, hi) for lo in bounds if lo is not None for hi in bounds if hi is not None]:
            checked += 1
            if outcome(source, *args) != outcome(shadow, *args):
                differences.append(args)
print(checked, differences)
shadow = Frozen(word)
print(''.join(shadow), ''.join(reversed(shadow)), list(iter(Frozen(range(3)))))
print(shadow.count('s'), shadow.count('q'), shadow.__contains__('p'), shadow.__contains__('q'), 'm' in shadow, 'x' in shadow)
print(shadow.index(value='p'), shadow.index('s', start=4), shadow.count(value='i'))
try:
    shadow.index('q')
except ValueError as error:
    print(type(error).__name__)"#,
    });
}

