fn cpython_collections_abc_set_from_iterable_operator_diff_subset() {
    assert_cpython_output_parity(&DiffCase {
        origin: "Lib/test/test_collections.py::test_Set_from_iterable public subset",
        name: "collections-abc-set-from-iterable-operator",
        source: r#"from collections.abc import MutableSet
class Labelled(MutableSet):
    # __init__ needs an extra argument, so the operators must go through _from_iterable
    def __init__(self, items, label):
        if not label:
            raise ValueError('a label is required')
        self.label = label
        self.items = set(items)
    def _from_iterable(self, items):
        return type(self)(items, 'derived')
    def __len__(self):
        return len(self.items)
    def __iter__(self):
        return iter(self.items)
    def __contains__(self, item):
        return item in self.items
    def add(self, item):
        self.items.add(item)
    def discard(self, item):
        self.items.discard(item)
base = Labelled('abc', 'base')
for result in (base | {'d'}, base & ['b', 'c', 'z'], base - {'a'}, base ^ {'c', 'e'}):
    print(type(result).__name__, result.label, sorted(result))
try:
    Labelled('ab', '')
except ValueError as error:
    print('ValueError', error)
# in-place operators mutate and keep the original label
before = base
base ^= ['a', 'q']
base |= 'r'
base -= {'b'}
print(base is before, base.label, sorted(base))"#,
    });
}

