#[test]
fn cpython_collections_abc_async_generator_throw_close_mixin_diff_subset() {
    assert_cpython_output_parity(&DiffCase {
        origin: "Lib/_collections_abc.py::AsyncGenerator / Lib/test/test_collections.py::TestOneTrickPonyABCs::test_AsyncGenerator",
        name: "collections-abc-async-generator-throw-close-mixin",
        source: r#"from collections.abc import AsyncGenerator, Awaitable, Coroutine
class Defaults(AsyncGenerator):
    # athrow defers to the ABC's default, which re-raises what it is given
    async def asend(self, value):
        return value
    async def athrow(self, kind, value=None, traceback=None):
        return await super().athrow(kind, value, traceback)
class Swallows(AsyncGenerator):
    async def asend(self, value):
        return value
    async def athrow(self, *exc):
        return 'kept going'
class Explodes(AsyncGenerator):
    async def asend(self, value):
        return value
    async def athrow(self, *exc):
        raise KeyError('during close')
def drive(awaitable):
    while True:
        try:
            awaitable.send(None)
        except StopIteration as stop:
            return stop.value
async def main():
    gen = Defaults()
    pending = AsyncGenerator.athrow(gen, LookupError)
    print(type(pending).__name__, isinstance(pending, Awaitable), isinstance(pending, Coroutine))
    try:
        drive(pending)
    except LookupError:
        print('default athrow raised LookupError')
    closing = AsyncGenerator.aclose(gen)
    print(type(closing).__name__, isinstance(closing, Awaitable), isinstance(closing, Coroutine), drive(closing))
    unused = AsyncGenerator.aclose(gen)
    print(unused.close())
    try:
        unused.send(None)
    except RuntimeError as error:
        print('reuse:', error)
    print(await gen.aclose())
    try:
        await gen.athrow(OSError)
    except OSError as error:
        print('class only:', type(error).__name__, error.args)
    try:
        await gen.athrow(OSError, OSError('given instance'))
    except OSError as error:
        print('class and value:', error)
    try:
        {}['missing']
    except KeyError as error:
        saved = error.__traceback__
    try:
        await gen.athrow(OSError, None, saved)
    except OSError as error:
        print('traceback kept:', error.__traceback__ is saved)
    try:
        await gen.athrow(OSError, None, 'not a traceback')
    except TypeError as error:
        print('bad traceback:', error)
    try:
        await Explodes().aclose()
    except KeyError as error:
        print('close error:', error)
    try:
        await Swallows().aclose()
    except RuntimeError as error:
        print('ignored exit:', error)
runner = main()
try:
    runner.send(None)
except StopIteration:
    pass"#,
    });
}

