// CPython's exception info is a stack: leaving a nested handler (normally,
// through return/continue/break, or by an exception escaping it, in a
// finally block, or in an except* clause) makes the outer handled
// exception current again for sys.exc_info(), a bare raise, and implicit
// __context__; a called function sees its caller's handled exception; a
// suspended generator keeps its own.
#[test]
fn cpython_nested_handlers_restore_exception_info_diff() {
    assert_cpython_output_parity(&DiffCase {
        origin: "Python/ceval.c PUSH_EXC_INFO/POP_EXCEPT; Lib/test/test_exceptions.py test_exc_info_*",
        name: "nested-handlers-restore-exception-info",
        source: r#"import sys
def show(tag):
    print(tag, repr(sys.exc_info()[1]))
try:
    raise ValueError("outer")
except ValueError:
    show("in outer")
    try:
        raise TypeError("inner")
    except TypeError:
        show("in inner")
    show("after inner")
    try:
        raise KeyError("k")
    except KeyError as e:
        show("inner as")
    show("after inner as")
    try:
        try:
            raise OSError("deep")
        finally:
            show("finally")
    except OSError:
        show("caught deep")
    show("after deep")
    try:
        raise RuntimeError("ctx")
    except RuntimeError as r:
        print("context", repr(r.__context__))
    for i in range(2):
        try:
            raise IndexError(i)
        except IndexError:
            if i == 0:
                continue
            show("loop")
    show("after loop")
    def f():
        try:
            raise NameError("n")
        except NameError:
            return 1
    f()
    show("after call")
    try:
        try:
            raise ZeroDivisionError
        except ZeroDivisionError:
            raise ArithmeticError("chained")
    except ArithmeticError as a:
        print("chain", repr(a.__context__))
        show("handling chained")
    show("after chained")
    for i in range(1):
        try:
            raise LookupError
        finally:
            break  # CPython warns about this at compile time
    show("after finally break")
    try:
        raise
    except ValueError as again:
        print("bare raise", repr(again))
show("top")
try:
    try:
        raise ValueError(1)
    except ValueError:
        raise
except ValueError:
    show("reraised")
show("end")
def g():
    try:
        raise ValueError("gen")
    except ValueError:
        yield sys.exc_info()[1]
        yield sys.exc_info()[1]
it = g()
print(repr(next(it)))
show("between")
print(repr(next(it)))"#,
    });
}

// `__context__`, `__cause__`, `__suppress_context__`, and `__traceback__`
// are writable with CPython's validation and deletion errors, an assignment
// or a raise is visible through every reference to the exception (so a
// group split by except* shares the original's traceback), setting
// `__cause__` suppresses the context, and raising cuts a context cycle as
// `_PyErr_SetObject` does.
#[test]
fn cpython_exception_dunder_assignment_diff() {
    assert_cpython_output_parity(&DiffCase {
        origin: "Objects/exceptions.c BaseException getset; Python/errors.c _PyErr_SetObject",
        name: "exception-dunder-assignment",
        source: r#"e = ValueError("e")
for name, value in [("__context__", 1), ("__cause__", "x"), ("__suppress_context__", 1),
                    ("__traceback__", 1), ("__context__", KeyError("k")), ("__cause__", None),
                    ("__suppress_context__", False), ("__traceback__", None), ("__cause__", TypeError("t"))]:
    try:
        setattr(e, name, value)
        print(name, "set", repr(getattr(e, name)), e.__suppress_context__)
    except Exception as error:
        print(name, type(error).__name__, error)
for name in ["__context__", "__cause__", "__suppress_context__", "__traceback__"]:
    try:
        delattr(e, name)
    except Exception as error:
        print("del", name, type(error).__name__, error)
alias = e
print(repr(alias.__context__), repr(alias.__cause__), alias.__suppress_context__)
try:
    raise ValueError("a")
except ValueError as a:
    b = TypeError("b")
    a.__context__ = b
    try:
        raise b
    except TypeError as caught:
        print(repr(caught.__context__), repr(a.__context__), caught.__context__ is a)
orig = ValueError(1)
try:
    raise orig
except ValueError as raised:
    print(raised.__traceback__ is orig.__traceback__, orig.__traceback__ is not None)
    tb = raised.__traceback__
orig2 = KeyError(2)
orig2.__traceback__ = tb
print(orig2.__traceback__ is tb, orig2.with_traceback(None).__traceback__, orig2.__traceback__)
def chained():
    try:
        raise OSError("first")
    except OSError as first:
        second = RuntimeError("second")
        second.__cause__ = first
        raise second
try:
    chained()
except RuntimeError as r:
    print(repr(r.__cause__), r.__suppress_context__, repr(r.__context__))
try:
    try:
        raise ValueError("inner")
    except ValueError as inner:
        inner.__suppress_context__ = True
        inner.__context__ = KeyError("replaced")
        raise
except ValueError as again:
    print(repr(again.__context__), again.__suppress_context__)
x = ValueError("x"); y = ValueError("y")
x.__context__ = y; y.__context__ = x
print(repr(x.__context__), repr(x.__context__.__context__))
try:
    raise x
except ValueError as got:
    print(repr(got.__context__), repr(got.__context__.__context__))"#,
    });
    assert_cpython_output_parity(&DiffCase {
        origin: "Lib/test/test_except_star.py traceback identity of a split group",
        name: "except-star-split-traceback-identity",
        source: r#"# the subgroup bound by except* shares the original group's traceback,
# and becomes the __context__ of an exception raised inside the handler
group = ExceptionGroup("batch", [KeyError("k"), ZeroDivisionError("z"), KeyError("j")])
try:
    try:
        raise group
    except* KeyError as part:
        bound = part
        print(len(part.exceptions), part is group, part.__traceback__ is group.__traceback__, part.__traceback__ is None)
        raise LookupError("from handler")
except ExceptionGroup as outer:
    names = [type(x).__name__ for x in outer.exceptions]
    raised = [x for x in outer.exceptions if isinstance(x, LookupError) and not isinstance(x, KeyError)][0]
    context = raised.__context__
    print(names, context is bound, context.__traceback__ is group.__traceback__, context.__traceback__ is bound.__traceback__)"#,
    });
}

