#[test]
fn cpython_object_init_new_excess_arguments_diff_subset() {
    assert_cpython_output_parity(&DiffCase {
        origin: "CPython public object.__init__/object.__new__ excess-argument rules",
        name: "object-init-new-excess-arguments",
        source: r#"# object.__init__ / object.__new__ reject extra arguments unless the class overrides the other one
def attempt(label, call):
    try:
        call()
    except TypeError as error:
        print(label, 'TypeError:', error)
    else:
        print(label, 'accepted')
class Bare:
    pass
class CustomInit:
    def __init__(self, *a, **k):
        super().__init__(*a, **k)
class CustomNew:
    def __new__(cls, *a, **k):
        return super().__new__(cls)
class CustomBoth(CustomNew):
    def __init__(self, *a, **k):
        super().__init__(*a, **k)
class InheritsInit(CustomInit):
    pass
class Holder:
    class Nested:
        pass
cases = {
    'bare positional': lambda: Bare(7),
    'bare keyword': lambda: Bare(flag=True),
    'nested positional': lambda: Holder.Nested('x'),
    'init positional': lambda: CustomInit(7),
    'init nothing': lambda: CustomInit(),
    'inherited init keyword': lambda: InheritsInit(flag=True),
    'new mixed': lambda: CustomNew(7, flag=True),
    'both positional': lambda: CustomBoth(7),
    'object.__init__ on bare': lambda: object.__init__(Bare(), 7),
    'object.__init__ keyword': lambda: object.__init__(Bare(), flag=True),
    'object.__init__ nested': lambda: object.__init__(Holder.Nested(), 7),
    'Bare.__init__': lambda: Bare.__init__(Bare(), 7),
    'object.__init__ on new-only': lambda: object.__init__(CustomNew(), 7),
    'object.__init__ on init-only': lambda: object.__init__(CustomInit(), 7),
    'object.__init__ no extra': lambda: object.__init__(Bare()),
    'object.__init__ on object': lambda: object.__init__(object(), 7),
    'object.__new__ bare': lambda: object.__new__(Bare, 7),
    'object.__new__ init-only': lambda: object.__new__(CustomInit, 7, flag=True),
    'object.__new__ new-only': lambda: object.__new__(CustomNew, 7),
    'Bare.__new__ keyword': lambda: Bare.__new__(Bare, flag=True),
}
for label, call in cases.items():
    attempt(label, call)"#,
    });
}

