#[test]
fn cpython_with_exit_receives_exception_class_diff_subset() {
    assert_cpython_output_parity(&DiffCase {
        origin: "Lib/test/test_with.py public __exit__ exception type, instance, and traceback arguments",
        name: "with-exit-receives-exception-class",
        source: r#"class MyError(Exception):
    pass
class SubValue(ValueError):
    pass
class Recorder:
    def __init__(self, expected, suppress):
        self.expected = expected
        self.suppress = suppress
    def __enter__(self):
        return self
    def __exit__(self, exc_type, exc, tb):
        self.seen = (exc_type, exc, tb)
        print('exit', exc_type is self.expected, isinstance(exc_type, type), exc_type is type(exc))
        print('match', issubclass(exc_type, self.expected), isinstance(exc, self.expected), type(tb).__name__)
        return self.suppress
error = MyError('mine')
with Recorder(MyError, True) as recorder:
    raise error
print('suppressed', recorder.seen[1] is error, recorder.seen[1].args)
with Recorder(SubValue, True) as recorder:
    raise SubValue('sub')
with Recorder(ValueError, True) as recorder:
    raise SubValue('base-match')
print('base-match', recorder.seen[0] is SubValue, recorder.seen[0].__name__, recorder.seen[0].__mro__[1] is ValueError)
with Recorder(KeyError, True) as recorder:
    raise KeyError('builtin')
try:
    with Recorder(MyError, False) as recorder:
        raise MyError('propagate')
except MyError as caught:
    print('propagated', caught is recorder.seen[1])
with Recorder(MyError, True) as recorder:
    raise MyError
print('class-raise', type(recorder.seen[1]).__name__, recorder.seen[1].args)
class suppress:
    def __init__(self, *exceptions):
        self._exceptions = exceptions
    def __enter__(self):
        pass
    def __exit__(self, exctype, excinst, exctb):
        return exctype is not None and issubclass(exctype, self._exceptions)
with suppress(MyError, KeyError):
    raise MyError('quiet')
print('suppress-ok')
try:
    with suppress(KeyError):
        raise MyError('loud')
except MyError as caught:
    print('not-suppressed', caught)
class Clean:
    def __enter__(self):
        return self
    def __exit__(self, *args):
        print('clean', args)
with Clean():
    pass
class AsyncRecorder:
    async def __aenter__(self):
        return self
    async def __aexit__(self, exc_type, exc, tb):
        print('async-exit', exc_type is MyError, issubclass(exc_type, MyError), type(tb).__name__)
        return True
async def run():
    async with AsyncRecorder():
        raise MyError('async')
    return 'done'
coroutine = run()
try:
    coroutine.send(None)
except StopIteration as stop:
    print('async-result', stop.value)"#,
    });
}

