#[test]
fn cpython_format_builtin_and_custom_dunder_format_diff_subset() {
    assert_cpython_output_parity(&DiffCase {
        origin: "Lib/test/test_builtin.py::BuiltinTest::test_format and Lib/test/test_fstring.py custom format behavior",
        name: "format-builtin-custom-dunder-format",
        source: r#"print(format(42, ''), format('yz'), format(2.75, '.1f'), format(7, ''), format(True, ''))
print(format(23**17, ''), format(23**17) == str(23**17), format(-23**17) == str(-23**17))
print(format(2.0, ''), format(6.02e123, ''), format(-6.02e123, ''), format(6.02e-123, ''), format(-6.02e-123, ''))
print(format(None, ''), format(None) == str(None), format(Ellipsis, ''))
class EchoSpec:
    def __format__(self, spec):
        return '<' + spec + '>'
print(f'{EchoSpec():left}', format(EchoSpec(), 'right'), format(EchoSpec()))
# __format__ is found through inheritance, from any level of the hierarchy
class Tagged:
    def __init__(self, tag):
        self.tag = tag
    def __format__(self, spec):
        return self.tag + '/' + spec
class TaggedChild(Tagged):
    pass
class Base:
    pass
class LateFormatter(Base):
    def __init__(self, tag):
        self.tag = tag
    def __format__(self, spec):
        return spec * 2 + self.tag
class LateGrandchild(LateFormatter):
    pass
print([format(obj, 'ab') for obj in (Tagged('t1'), TaggedChild('t2'), LateFormatter('t3'), LateGrandchild('t4'))])
# each replacement field calls __format__ once
class Ticker:
    def __init__(self):
        self.calls = 0
    def __format__(self, spec):
        self.calls += 1
        return f'#{self.calls}{spec}'
x = Ticker()
print(f'{x} {x:!}')
class Y:
    def __format__(self, spec):
        return 'class:' + spec
y = Y()
y.__format__ = lambda spec: 'instance:' + spec
print(y.__format__('direct'))
print(format(y, 'real'))
print(f'{y:field}')
class FormatSub(str):
    pass
class ReturnsFormatSub:
    def __format__(self, spec):
        return FormatSub('fmt-' + spec)
def show(label, value):
    print(label, type(value).__name__, value, isinstance(value, FormatSub), type(value) is FormatSub)
show('format-builtin', format(ReturnsFormatSub(), 'x'))
show('fstring-only', f'{ReturnsFormatSub():y}')
show('fstring-literal', f'pre{ReturnsFormatSub():q}')
show('str-format-only', '{:z}'.format(ReturnsFormatSub()))
show('str-format-literal', 'pre{:q}'.format(ReturnsFormatSub()))
show('str-format-map-only', '{item:q}'.format_map({'item': ReturnsFormatSub()}))
class BadFormatResult:
    def __format__(self, spec):
        return 1.0
try:
    format(BadFormatResult(), '')
except TypeError as error:
    print(error.__class__.__name__, str(error))
for expr in [lambda: format(object(), 4), lambda: format(object(), object())]:
    try:
        expr()
    except TypeError as error:
        print(error.__class__.__name__)"#,
    });
}

