#[test]
fn cpython_from_import_submodule_error_propagation_diff_subset() {
    assert_cpython_sandbox_dir_output_parity(
        "CPython public from-import submodule error propagation",
        "from-import-submodule-error-propagation",
        &[
            ("pkg/__init__.py", r#""#),
            ("pkg/from_error.py", r#"from pkg import missing_name_q
"#),
            ("pkg/good.py", r#"VALUE = 1
"#),
            ("pkg/import_error.py", r#"import missing_dependency_xyz
"#),
            ("pkg/name_error.py", r#"print('loading name_error')
undefined_name
"#),
            ("pkg/nested_error.py", r#"from . import name_error
"#),
            ("pkg/value_error.py", r#"raise ValueError('boom')
"#),
        ],
        r#"import sys
try:
    from pkg import name_error
except NameError as error:
    print('name-error', error)
print('cached', 'pkg.name_error' in sys.modules, hasattr(sys.modules['pkg'], 'name_error'))
try:
    from pkg import name_error
except NameError as error:
    print('name-error-again', error)
try:
    from pkg import import_error
except ModuleNotFoundError as error:
    print('import-error', error)
try:
    from pkg import value_error
except ValueError as error:
    print('value-error', error)
try:
    from pkg import from_error
except ImportError as error:
    print('from-error', type(error).__name__, str(error).split(' (')[0])
try:
    from pkg import nested_error
except NameError as error:
    print('nested', error)
try:
    from pkg import good, name_error
except NameError as error:
    print('partial', error, 'pkg.good' in sys.modules)
try:
    from pkg import missing_submodule
except ImportError as error:
    print('missing', type(error).__name__, str(error).split(' (')[0])
try:
    import pkg.name_error
except NameError as error:
    print('import-statement', error)
from pkg import good
print('good', good.VALUE)"#,
    );
}

#[test]
fn cpython_dynamic_globals_module_metadata_diff_subset() {
    assert_cpython_output_parity(&DiffCase {
        origin: "CPython public __module__ from defining globals: exec(), type(), namedtuple(), metaclass namespaces",
        name: "dynamic-globals-module-metadata",
        source: r#"ns = {'__name__': 'custom'}
exec('class E:\n    def m(self):\n        pass\ndef f():\n    pass\nlam = lambda: 0', ns)
print('custom', ns['E'].__module__, ns['E'].m.__module__, ns['f'].__module__, ns['lam'].__module__)
ns = {}
exec('class E:\n    pass\ndef f():\n    pass', ns)
print('no-name', ns['E'].__module__, ns['f'].__module__)
ns = {'__name__': 42}
exec('class E:\n    pass\ndef f():\n    pass', ns)
print('non-str', repr(ns['E'].__module__), repr(ns['f'].__module__))
class Explicit:
    __module__ = 'explicit'
    def method(self):
        pass
print('explicit', Explicit.__module__, Explicit.method.__module__)
D = type('D', (), {})
print('type-call', D.__module__, type('E', (), {'__module__': 'given'}).__module__)
g = {'__name__': 'factory_globals'}
exec('def make():\n    return type("Made", (), {})', g)
print('type-in-exec', g['make']().__module__)
class Meta(type):
    def __new__(mcls, name, bases, namespace):
        print('meta-namespace', list(namespace)[0], namespace['__module__'])
        return super().__new__(mcls, name, bases, namespace)
class WithMeta(metaclass=Meta):
    pass
print('meta', WithMeta.__module__)
print('dict-order', list(Explicit.__dict__)[0])
import collections
P = collections.namedtuple('P', 'x')
print('namedtuple', P.__module__, collections.namedtuple('R', 'x', module='given').__module__)
exec("import collections\nQ = collections.namedtuple('Q', 'x')", g)
print('namedtuple-exec', g['Q'].__module__)"#,
    });
}

