fn cpython_types_union_parameter_substitution_diff_subset() {
    let probe = run_cpython(
        "import typing\nT = typing.TypeVar('T')\nx = int | T | bytes\nprint(x[str] == int | str | bytes)",
    )
    .expect("failed to probe CPython union parameter substitution support");
    if String::from_utf8_lossy(&probe.stdout).trim() != "True" {
        eprintln!(
            "skipping types union parameter substitution diff: CPython oracle lacks PEP 604 parameter substitution support"
        );
        return;
    }

    assert_cpython_output_parity(&DiffCase {
        origin: "Lib/test/test_types.py::UnionTests parameter substitution public subset",
        name: "types-union-parameter-substitution",
        source: r#"import collections.abc
import typing
K = typing.TypeVar('K')
W = typing.TypeVar('W')
UserId = typing.NewType('UserId', int)
template = float | K | complex
def describe(value):
    return getattr(value, '__name__', None) or repr(value)
substitutions = [
    ('builtin', bytes, float | bytes | complex),
    ('builtin generic', dict[str, int], float | dict[str, int] | complex),
    ('typing bare', typing.List, float | typing.List | complex),
    ('typing generic', typing.List[bytes], float | typing.List[bytes] | complex),
    ('typing abc', typing.Hashable, float | typing.Hashable | complex),
    ('abc class', collections.abc.Hashable, float | collections.abc.Hashable | complex),
    ('typing callable', typing.Callable[[str, str], bool], float | typing.Callable[[str, str], bool] | complex),
    ('abc callable', collections.abc.Callable[..., bool], float | collections.abc.Callable[..., bool] | complex),
    ('typing tuple', typing.Tuple[str, ...], float | typing.Tuple[str, ...] | complex),
    ('literal', typing.Literal[3, 4], float | typing.Literal[3, 4] | complex),
    ('newtype', UserId, float | UserId | complex),
    ('inner pep604', bytes | set, float | bytes | set | complex),
    ('inner typing union', typing.Union[bytes, set], typing.Union[float, bytes, set, complex]),
    ('duplicate pep604', bytes | float, float | bytes | complex),
    ('duplicate typing union', typing.Union[complex, bytes], typing.Union[float, complex, bytes]),
    ('another typevar', W, float | W | complex),
]
for label, argument, wanted in substitutions:
    got = template[argument]
    print(label, got == wanted, type(got) is type(wanted), [describe(a) for a in got.__args__], [p.__name__ for p in getattr(got, '__parameters__', ())])
for bad in [(bytes, set), ()]:
    try:
        template[bad]
    except TypeError:
        print('wrong number of arguments', len(bad))"#,
    });
}

