#[test]
fn cpython_list_index_bounds_index_diff_subset() {
    // CPython oracle text for non-index bounds:
    // slice indices must be integers or have an __index__ method
    assert_cpython_output_parity(&DiffCase {
        origin: "Lib/test/list_tests.py list.index start/stop __index__ subset",
        name: "list-index-bounds-index",
        source: r#"class Wrapped:
    def __init__(self, n):
        self.n = n
    def __index__(self):
        return self.n
class Huge:
    def __index__(self):
        return 7 ** 200
class HugeNegative:
    def __index__(self):
        return -7 ** 200
class NotAnInt:
    def __index__(self):
        return 2.0
class Raises:
    def __index__(self):
        raise LookupError('index refused')
letters = list('abcab')
attempts = {
    'start via __index__': lambda: letters.index('b', Wrapped(2)),
    'stop via __index__': lambda: letters.index('a', 1, Wrapped(4)),
    'stop excludes match': lambda: letters.index('b', 2, Wrapped(4)),
    'very negative start': lambda: letters.index('a', Wrapped(-50)),
    'huge start': lambda: letters.index('a', Huge()),
    'huge negative start': lambda: letters.index('c', HugeNegative()),
    'huge stop': lambda: letters.index('c', 0, Huge()),
    '__index__ returns float': lambda: letters.index('a', NotAnInt()),
    '__index__ raises': lambda: letters.index('a', Raises()),
    'str bound': lambda: letters.index('a', '1'),
    'None bound': lambda: letters.index('a', None),
    'float bound': lambda: letters.index('a', 0.0),
}
for label, attempt in attempts.items():
    try:
        print(label, attempt())
    except (TypeError, ValueError, LookupError) as error:
        print(label, type(error).__name__, error)"#,
    });
}

