#[test]
fn cpython_types_coroutine_duck_generator_wrapper_diff_subset() {
    assert_cpython_output_parity(&DiffCase {
        origin: "Lib/test/test_types.py::CoroutineTests duck-generator _GeneratorWrapper public subset",
        name: "types-coroutine-duck-generator-wrapper",
        source: r#"import types
class Relay:
    # generator look-alike (not a real generator): hands out one token, then
    # finishes with three times the value it was sent
    def __init__(self, token):
        self.token = token
        self.stage = 'fresh'
    def send(self, value):
        if self.stage == 'fresh':
            self.stage = 'waiting'
            return self.token
        if self.stage == 'waiting':
            self.stage = 'finished'
            raise StopIteration(value * 3)
        raise StopIteration
    def throw(self, kind, *rest):
        self.stage = 'finished'
        if kind is not GeneratorExit:
            raise kind
    def close(self):
        self.throw(GeneratorExit)
    # iteration is just sending None
    def __next__(self):
        return self.send(None)
    def __iter__(self):
        return self
@types.coroutine
def make_relay():
    return Relay('ticket')
wrapped = make_relay()
print('duck-wrapper', type(wrapped).__name__, isinstance(wrapped, types._GeneratorWrapper), wrapped.__await__() is wrapped, iter(wrapped) is wrapped)
print('duck-send-1', wrapped.send(None))
try:
    wrapped.send(7)
except StopIteration as stop:
    print('duck-stop', stop.value)
closing = make_relay()
next(closing)
print('duck-close', closing.close())"#,
    });
}

