#[test]
fn cpython_types_coroutine_duck_generator_proxy_diff_subset() {
    let probe = run_cpython(
        "import types\nprint(all(hasattr(types._GeneratorWrapper, n) for n in ('cr_suspended', 'gi_suspended')))",
    )
    .expect("failed to probe CPython _GeneratorWrapper duck proxy alias support");
    if String::from_utf8_lossy(&probe.stdout).trim() != "True" {
        eprintln!(
            "skipping types coroutine duck generator proxy diff: CPython oracle lacks _GeneratorWrapper cr_suspended proxy alias"
        );
        return;
    }

    assert_cpython_output_parity(&DiffCase {
        origin: "Lib/test/test_types.py::CoroutineTests duck-generator proxy public subset",
        name: "types-coroutine-duck-generator-proxy",
        source: r#"import types, collections.abc, weakref
class Recorder:
    # duck-typed generator that logs every call forwarded to it
    def __init__(self):
        self.calls = []
        self.throw_error = None
    def __iter__(self):
        return self
    def __next__(self):
        self.calls.append(('next',))
        return 'from next'
    def send(self, *args):
        self.calls.append(('send',) + args)
        return 'from send'
    def throw(self, *args):
        self.calls.append(('throw',) + args)
        if self.throw_error is not None:
            raise self.throw_error
        return 'from throw'
    def close(self, *args):
        self.calls.append(('close',) + args)
inner = Recorder()
inner.__name__ = 'inner_name'
inner.__qualname__ = 'Outer.inner_name'
print('gen', isinstance(inner, collections.abc.Generator), iter(inner) is inner)
wrapper = types.coroutine(lambda: inner)()
print('types', type(wrapper).__name__, isinstance(wrapper, types._GeneratorWrapper), isinstance(wrapper, collections.abc.Coroutine), isinstance(wrapper, collections.abc.Awaitable))
print('await-iter', wrapper.__await__() is wrapper, iter(wrapper) is wrapper)
print('names', wrapper.__name__ == inner.__name__, wrapper.__qualname__ == inner.__qualname__)
# state attributes are looked up on the wrapped object; the cr_* names alias the gi_* ones
pairs = [('gi_running', 'cr_running'), ('gi_frame', 'cr_frame'), ('gi_code', 'cr_code'), ('gi_yieldfrom', 'cr_await'), ('gi_suspended', 'cr_suspended')]
missing = []
for gi_name, cr_name in pairs:
    for name in (gi_name, cr_name):
        try:
            getattr(wrapper, name)
        except AttributeError:
            missing.append(name)
print('missing-attrs', missing)
markers = {}
for gi_name, cr_name in pairs:
    markers[gi_name] = object()
    setattr(inner, gi_name, markers[gi_name])
print('attrs', [getattr(wrapper, gi) is markers[gi] for gi, cr in pairs], [getattr(wrapper, cr) is markers[gi] for gi, cr in pairs])
results = [wrapper.close(), wrapper.send('payload'), next(wrapper), wrapper.throw('a', 'b', 'c'), wrapper.throw('a', 'b'), wrapper.throw('a')]
print('results', results)
print('forwarded', inner.calls)
inner.calls.clear()
inner.throw_error = OverflowError('from inner')
try:
    wrapper.throw('a')
except OverflowError as error:
    print('throw-prop', error is inner.throw_error, inner.calls)
inner.throw_error = None
inner.calls.clear()
for label, call in [('throw no args', lambda: wrapper.throw()), ('close with arg', lambda: wrapper.close(1)), ('send no args', lambda: wrapper.send())]:
    try:
        call()
    except TypeError:
        print(label, 'TypeError')
print('nothing forwarded', inner.calls)
print('double', types.coroutine(lambda: wrapper)() is wrapper)
ref = weakref.ref(wrapper)
print('weakref', ref() is wrapper, isinstance(ref, weakref.ReferenceType))"#,
    });
}

