#[test]
fn cpython_types_simple_namespace_new_and_invalid_replace_diff_subset() {
    let probe = run_cpython(
        "import copy, types\nprint(hasattr(copy, 'replace'), hasattr(types.SimpleNamespace, '__replace__'))",
    )
    .expect("failed to run CPython SimpleNamespace replace capability probe");
    if String::from_utf8_lossy(&probe.stdout).trim() != "True True" {
        eprintln!(
            "skipping SimpleNamespace.__replace__ diff: CPython oracle lacks copy.replace or SimpleNamespace.__replace__"
        );
        return;
    }

    assert_cpython_output_parity(&DiffCase {
        origin: "Lib/test/test_types.py::SimpleNamespaceTests::test_replace_invalid_subtype and public __new__/__replace__ behavior",
        name: "types-simple-namespace-new-invalid-replace",
        source: r#"import copy, types
Namespace = types.SimpleNamespace
bare = Namespace.__new__(Namespace)
print(type(bare).__name__, repr(bare), type(Namespace.__new__(Namespace, 'ignored', k=1)).__name__)
try:
    Namespace.__new__(dict)
except TypeError as error:
    print(type(error).__name__, 'not a subtype of types.SimpleNamespace' in str(error))
base = Namespace(a=1, b=2)
print(hasattr(Namespace, '__replace__'), Namespace.__replace__(base, c=3), base.__replace__(a=0), copy.replace(base, b=9), base)
broken = False
class Odd(Namespace):
    # __new__ can be switched to return something that is not a namespace at all
    def __new__(cls, *args, **kwargs):
        return 'not a namespace' if broken else super().__new__(cls)
item = Odd(p=1, q=2)
fresh = item.__replace__(q=20)
print(type(item).__name__, sorted(vars(item).items()), type(fresh).__name__, sorted(vars(fresh).items()))
broken = True
try:
    copy.replace(item, p=5)
except TypeError as error:
    message = str(error)
    print(type(error).__name__, 'expect types.SimpleNamespace type' in message, 'Odd()' in message, "'str' object" in message)"#,
    });
}

#[test]
fn cpython_types_simple_namespace_remaining_public_diff_subset() {
    let probe = run_cpython(
        "import types\ntry:\n    ns = types.SimpleNamespace({'x': 1}, y=2)\n    print(list(vars(ns).items()))\nexcept TypeError as error:\n    print(type(error).__name__)",
    )
    .expect("failed to run CPython SimpleNamespace positional mapping capability probe");
    if String::from_utf8_lossy(&probe.stdout).trim() != "[('x', 1), ('y', 2)]" {
        eprintln!(
            "skipping SimpleNamespace remaining public diff: CPython oracle lacks positional mapping construction"
        );
        return;
    }

    assert_cpython_output_parity(&DiffCase {
        origin: "Lib/test/test_types.py::SimpleNamespaceTests remaining public subset",
        name: "types-simple-namespace-remaining-public",
        source: r#"import pickle, types
NS = types.SimpleNamespace
# a positional mapping or iterable of pairs comes first; keywords override and extend it
print(list(vars(NS({'b': 1, 'a': 2}, b=5, c=6)).items()))
print(list(vars(NS([('b', 1), ['a', 2]], b=5, c=6)).items()))
print(list(vars(NS((), c=6)).items()), list(vars(NS({})).items()), list(vars(NS(iter([('k', 0)]))).items()))
for bad in (lambda: NS({'a': 1}, {'b': 2}), lambda: NS([('a',)]), lambda: NS({1: 'x'}), lambda: NS(5)):
    try:
        bad()
    except (TypeError, ValueError) as error:
        print(type(error).__name__)
kept = NS(on=True, off=False).__dict__
print(sorted(kept.items()))
box = NS(p=1, q=2, r=3)
for name in ('missing', 'q'):
    try:
        delattr(box, name)
        print('deleted', name, sorted(vars(box)))
    except AttributeError as error:
        print('cannot delete', name, type(error).__name__)
box.q = 'back'
print(sorted(vars(box).items()))
print(repr(NS(z=0, m=1)), repr(NS(_hidden=1, shown=NS())))
meal = NS(soup='leek', bread='rye')
restored_ok = []
for protocol in range(pickle.HIGHEST_PROTOCOL + 1):
    clone = pickle.loads(pickle.dumps(meal, protocol))
    restored_ok.append(clone == meal and clone is not meal and type(clone) is NS and list(vars(clone).items()) == list(vars(meal).items()))
print('pickle', restored_ok.count(True), len(restored_ok))
first, second = NS(a=1), NS(b=2)
for compare in (lambda: first < second, lambda: first <= second, lambda: first > second, lambda: first >= second):
    try:
        print(compare())
    except TypeError as error:
        print(type(error).__name__)
# an object that only claims to be a SimpleNamespace through __class__ is not equal to one
class Impostor(str):
    __class__ = types.SimpleNamespace
fake = Impostor()
for compare in (lambda: NS() == fake, lambda: NS() != fake, lambda: NS() < fake, lambda: NS() <= fake, lambda: NS() > fake, lambda: NS() >= fake):
    try:
        print(compare())
    except TypeError as error:
        print(type(error).__name__)"#,
    });
}

