#[test]
fn cpython_collections_counter_basics_diff_subset() {
    assert_cpython_output_parity(&DiffCase {
        origin: "Lib/test/test_collections.py TestCounter basics subset",
        name: "collections-counter-basics",
        source: r#"from collections import Counter, OrderedDict
from collections.abc import Mapping, Reversible
tally = Counter('mississippi')
print(tally == Counter({'i': 4, 's': 4, 'p': 2, 'm': 1}), tally == Counter(m=1, i=4, s=4, p=2), tally == {'m': 1, 'i': 4, 's': 4, 'p': 2})
print(isinstance(tally, dict), isinstance(tally, Mapping), issubclass(Counter, dict), issubclass(Counter, Mapping))
print(len(tally), tally.total(), list(tally), list(tally.values()), list(tally.items()))
print(tally['s'], tally['x'], 'p' in tally, 'x' in tally, tally.get('p', 0), tally.get('x', 0))
print(repr(tally), tally.most_common(), [tally.most_common(n) for n in (0, 1, 2, 9)])
print(''.join(tally.elements()))
# counts may become zero or negative; elements() skips those
tally['m'] += 2
tally['i'] -= 4
del tally['p']
del tally['p']
tally['q'] -= 1
tally['r'] = -3
tally['t'] += 2
print(dict(tally), ''.join(tally.elements()))
print(tally.pop('t'), 't' in tally)
seen = []
while len(tally) > 2:
    key, count = tally.popitem()
    seen.append((key, key in tally))
print(seen)
tally.clear()
print(tally == {}, repr(tally))
for action in (lambda: Counter.fromkeys('ab'), lambda: hash(Counter())):
    try:
        action()
    except (NotImplementedError, TypeError) as error:
        print(type(error).__name__)
fresh = Counter()
fresh.update({'x': 2, 'y': 1})
fresh.update(z=4)
fresh.update(Counter('x' * 10))
fresh.update()
fresh.__init__('y' * 7)
fresh.__init__('zw')
fresh.__init__()
print(dict(fresh), fresh.setdefault('w', 9), fresh['w'], fresh.setdefault('v', 9), fresh['v'])
print(isinstance(OrderedDict(), Reversible), isinstance(Counter(), Reversible), list(reversed(Counter('cabbc'))))"#,
    });
}

