#[test]
fn cpython_collections_counter_order_preservation_diff_subset() {
    assert_cpython_output_parity(&DiffCase {
        origin: "Lib/test/test_collections.py TestCounter order preservation subset",
        name: "collections-counter-order-preservation",
        source: r#"from collections import Counter
# insertion order of first appearance is kept by items(), elements() and every operator
print(list(Counter('banana bandana').items()))
print(list(Counter('zyxwzyxw').items()), list(Counter('hello world').elements()))
left_text = 'qqwweerrttyyuuiiop'
right_text = 'pooiiuuuytrrewqqqzz'
first_seen = {ch: i for i, ch in enumerate(dict.fromkeys(left_text + right_text))}
def in_first_seen_order(counter):
    ranks = [first_seen[ch] for ch in counter]
    return ranks == sorted(ranks)
a, b = Counter(left_text), Counter(right_text)
print([in_first_seen_order(r) for r in (+a, -a, a + b, a - b, a | b, a & b)])
def apply(name):
    x, y = Counter(left_text), Counter(right_text)
    if name == 'add':
        x += y
    elif name == 'sub':
        x -= y
    elif name == 'or':
        x |= y
    elif name == 'and':
        x &= y
    else:
        getattr(x, name)(y)
    return x
print({name: in_first_seen_order(apply(name)) for name in ('add', 'sub', 'or', 'and', 'update', 'subtract')})"#,
    });
}

