#[test]
fn cpython_collections_counter_multiset_operations_matrix_diff_subset() {
    assert_cpython_output_parity(&DiffCase {
        origin: "Lib/test/test_collections.py TestCounter multiset operations matrix subset",
        name: "collections-counter-multiset-operations-matrix",
        source: r#"from collections import Counter
seed = 8675309
def randrange(start, stop):
    global seed
    seed = (seed * 1103515245 + 12345) % 2147483648
    return start + seed % (stop - start)
def random_counter(elements, start, stop):
    c = Counter()
    for elem in elements:
        c[elem] = randrange(start, stop)
    return c
def clipped(value):
    if value > 0:
        return value
    return 0
def expected_count(name, left, right):
    if name == 'add':
        return clipped(left + right)
    if name == 'sub':
        return clipped(left - right)
    if name == 'or':
        if left > right:
            return clipped(left)
        return clipped(right)
    if left < right:
        return clipped(left)
    return clipped(right)
def all_positive(counter):
    for value in counter.values():
        if not value > 0:
            return False
    return True
failures = 0
elements = 'abcd'
ops = [('add', Counter.__add__), ('sub', Counter.__sub__), ('or', Counter.__or__), ('and', Counter.__and__)]
for i in range(1000):
    p = random_counter(elements, -2, 4)
    p.update(e=1, f=-1, g=0)
    q = random_counter(elements, -2, 4)
    q.update(h=1, i=-1, j=0)
    for name, counterop in ops:
        result = counterop(p, q)
        for x in elements:
            if expected_count(name, p[x], q[x]) != result[x]:
                failures = failures + 1
        if not all_positive(result):
            failures = failures + 1
print(failures)"#,
    });
}

#[test]
fn cpython_collections_counter_multiset_operations_equivalent_to_set_operations_diff_subset() {
    let probe = run_cpython("from collections import Counter\nprint(hasattr(Counter, '__xor__'))")
        .expect("failed to run CPython Counter xor feature probe");
    if String::from_utf8_lossy(&probe.stdout).trim() != "True" {
        eprintln!("skipping Counter set-equivalence diff: CPython oracle lacks Counter.__xor__");
        return;
    }

    assert_cpython_output_parity(&DiffCase {
        origin: "Lib/test/test_collections.py TestCounter multiset set-equivalence subset",
        name: "collections-counter-multiset-set-equivalence",
        source: r#"from collections import Counter
pairs = [('a', 0), ('a', 1), ('b', 0), ('b', 1), ('c', 0), ('c', 1)]
counters = []
for mask in range(64):
    data = {}
    for i in range(6):
        if mask & (1 << i):
            key, count = pairs[i]
            data[key] = count
    counters.append(Counter(data))
checked = 0
for cp in counters:
    for cq in counters:
        sp = set(cp.elements())
        sq = set(cq.elements())
        assert set(cp + cq) == (sp | sq)
        assert set(cp - cq) == (sp - sq)
        assert set(cp | cq) == (sp | sq)
        assert set(cp & cq) == (sp & sq)
        assert set(cp ^ cq) == (sp ^ sq)
        assert (cp == cq) == (sp == sq)
        assert (cp != cq) == (sp != sq)
        assert (cp <= cq) == (sp <= sq)
        assert (cp >= cq) == (sp >= sq)
        assert (cp < cq) == (sp < sq)
        assert (cp > cq) == (sp > sq)
        checked += 1
print(checked)"#,
    });
}

#[test]
fn cpython_collections_counter_symmetric_difference_diff_subset() {
    let probe = run_cpython("from collections import Counter\nprint(hasattr(Counter, '__xor__'))")
        .expect("failed to run CPython Counter xor feature probe");
    if String::from_utf8_lossy(&probe.stdout).trim() != "True" {
        eprintln!(
            "skipping Counter symmetric-difference diff: CPython oracle lacks Counter.__xor__"
        );
        return;
    }

    assert_cpython_output_parity(&DiffCase {
        origin: "Lib/test/test_collections.py TestCounter symmetric difference subset",
        name: "collections-counter-symmetric-difference",
        source: r#"from collections import Counter
population = (-4, -3, -2, -1, 0, 1, 2, 3, 4)
checked = 0
for a in population:
    for b1 in population:
        for b2 in population:
            for c in population:
                p = Counter(a=a, b=b1)
                q = Counter(b=b2, c=c)
                r = p ^ q
                for k in ('a', 'b', 'c'):
                    assert r[k] == max(p[k], q[k]) - min(p[k], q[k])
                    assert r[k] == abs(p[k] - q[k])
                assert r == ((p - q) | (q - p))
                if a >= 0 and b1 >= 0 and b2 >= 0 and c >= 0:
                    assert r == ((p | q) - (p & q))
                for value in r.values():
                    assert value > 0
                keys = list(p) + list(q)
                indices = []
                for k in r:
                    indices.append(keys.index(k))
                assert indices == sorted(indices)
                pp = Counter(p)
                qq = Counter(q)
                pp ^= qq
                assert pp == r
                checked += 1
print(checked)"#,
    });
}

#[test]
fn cpython_collections_counter_inplace_operations_diff_subset() {
    assert_cpython_output_parity(&DiffCase {
        origin: "Lib/test/test_collections.py TestCounter inplace operations subset",
        name: "collections-counter-inplace-operations",
        source: r#"from collections import Counter
p = Counter(a=3, b=-1, c=0, e=1, f=-1, g=0)
q = Counter(a=1, b=2, d=4, h=1, i=-1, j=0)
for op in ['+=', '-=', '|=', '&=']:
    c = p.copy()
    before = id(c)
    if op == '+=':
        expected = p + q
        result = Counter.__iadd__(c, q)
    elif op == '-=':
        expected = p - q
        result = Counter.__isub__(c, q)
    elif op == '|=':
        expected = p | q
        result = Counter.__ior__(c, q)
    else:
        expected = p & q
        result = Counter.__iand__(c, q)
    print(op, result == expected, c == expected, id(result) == before, id(c) == before)"#,
    });
}

#[test]
fn cpython_collections_counter_inplace_operations_matrix_diff_subset() {
    assert_cpython_output_parity(&DiffCase {
        origin: "Lib/test/test_collections.py TestCounter inplace operations matrix subset",
        name: "collections-counter-inplace-operations-matrix",
        source: r#"from collections import Counter
# compare each in-place operator with its binary form on deterministic pseudo-random counters
state = 20240611
def next_count(low, high):
    global state
    state = (state * 6364136223846793005 + 1442695040888963407) % 2**64
    return low + (state >> 33) % (high - low)
def sample(keys, low, high):
    return Counter({key: next_count(low, high) for key in keys})
pairs = [('+=', '__iadd__', '__add__'), ('-=', '__isub__', '__sub__'), ('|=', '__ior__', '__or__'), ('&=', '__iand__', '__and__')]
problems = {symbol: 0 for symbol, _, _ in pairs}
for _ in range(600):
    left = sample('wxyz', -3, 5)
    left.update(u=2, v=-2, s=0)
    right = sample('wxyz', -3, 5)
    right.update(m=3, n=-1, o=0)
    for symbol, inplace_name, binary_name in pairs:
        target = left.copy()
        before = id(target)
        expected = getattr(Counter, binary_name)(target, right)
        returned = getattr(Counter, inplace_name)(target, right)
        if returned != expected or target != expected or returned is not target or id(target) != before:
            problems[symbol] += 1
print(problems)"#,
    });
}

