#[test]
fn cpython_collections_namedtuple_name_conflicts_diff_subset() {
    // The field names that could clash with namedtuple's own generated code are
    // the identifiers of collections.namedtuple's source; the CPython oracle
    // extracts them at test time so the list is not pinned in this file.
    let probe = run_cpython(
        "import collections, inspect, keyword, re\nsource = inspect.getsource(collections.namedtuple)\nprint(' '.join(sorted({w for w in re.findall(r'[A-Za-z][A-Za-z0-9_]*', source) if not keyword.iskeyword(w)})))",
    )
    .expect("failed to extract identifiers from CPython's collections.namedtuple");
    assert!(
        probe.status.success(),
        "CPython could not read collections.namedtuple's source: {}",
        String::from_utf8_lossy(&probe.stderr)
    );
    let words = String::from_utf8(probe.stdout)
        .expect("CPython namedtuple identifier list is not UTF-8")
        .trim()
        .to_string();
    assert!(
        words.split(' ').count() > 50,
        "too few namedtuple identifiers: {words}"
    );
    let source = format!(
        r#"from collections import namedtuple
# a few names used by the generated class body itself
Clash = namedtuple('Clash', 'cls self tuple_new itemgetter result')
clash = Clash(1, 2, 3, 4, 5)
print(clash == (1, 2, 3, 4, 5), clash.self, clash.cls, clash._replace(cls=0, result=9))
# every identifier of namedtuple's own source used as a field name
fields = '{words}'.split()
Wide = namedtuple('Wide', fields)
numbers = tuple(range(100, 100 + len(fields)))
built = [Wide(*numbers), Wide(**dict(zip(fields, numbers))), Wide._make(numbers)]
print(len(fields) == len(set(fields)), [item == numbers for item in built])
sample = built[0]
print(repr(sample).startswith('Wide('), sample._asdict() == dict(zip(fields, numbers)), Wide._fields == tuple(fields))
scaled = tuple(n * 2 for n in numbers)
print(sample._replace(**dict(zip(fields, scaled))) == scaled, sample.__getnewargs__() == numbers)
print(all(getattr(sample, name) == value for name, value in zip(fields, numbers)))"#
    );
    assert_cpython_output_parity_source(
        "Lib/test/test_collections.py TestNamedTuple name-conflicts subset",
        "collections-namedtuple-name-conflicts",
        &source,
    );
}

