#[test]
fn cpython_operator_callable_helper_diff_subset() {
    // CPython oracle text: attribute name must be a string;
    // itemgetter expected 1 argument, got 0;
    // itemgetter expected 1 argument, got 2;
    // methodcaller expected 1 argument, got 0;
    // methodcaller expected 1 argument, got 2;
    // method name must be a string
    assert_cpython_output_parity(&DiffCase {
        origin: "Lib/test/test_operator.py::OperatorTestCase callable helper public subset stable on CPython 3.9",
        name: "operator-callable-helper",
        source: r#"import operator
class Text(str):
    pass
class Node:
    pass
a = Node()
a.name = 'root'
a.child = Node()
a.child.name = 'leaf'
a.child.child = Node()
a.child.child.name = 'deepest'
print(operator.attrgetter('name')(a), operator.attrgetter('child.child.name')(a))
print(operator.attrgetter('name', 'child.name')(a), operator.attrgetter(Text('child.name'))(a), operator.attrgetter(Text('name'), Text('child.child.name'))(a))
for attempt in [lambda: operator.attrgetter(), lambda: operator.attrgetter(7), lambda: operator.attrgetter('name')(), lambda: operator.attrgetter('name')(a, a), lambda: operator.attrgetter('name')(a, extra=1)]:
    try:
        attempt()
    except TypeError as error:
        print(type(error).__name__)
for attempt in [lambda: operator.attrgetter('missing')(a), lambda: operator.attrgetter('child.')(a), lambda: operator.attrgetter('.name')(a), lambda: operator.attrgetter('child.missing')(a)]:
    try:
        attempt()
    except AttributeError as error:
        print(type(error).__name__)
class AttrRaises:
    def __getattr__(self, name):
        raise LookupError(name)
class ItemRaises:
    def __getitem__(self, key):
        raise LookupError(key)
for attempt in (lambda: operator.attrgetter('anything')(AttrRaises()), lambda: operator.itemgetter(0)(ItemRaises())):
    try:
        attempt()
    except LookupError as error:
        print('propagated', type(error).__name__, error)
data = [chr(ord('a') + k) for k in range(12)]
table = {'pk': 'value', 3: 'three'}
print(operator.itemgetter(4)(data), operator.itemgetter(0, 11, 6)(data), operator.itemgetter('pk', 3)(table))
print(operator.itemgetter(-2)('xyzw'), operator.itemgetter(slice(1, 3))((10, 20, 30, 40)), operator.itemgetter(slice(None, None, -1))('abc'))
for attempt in [lambda: operator.itemgetter(), lambda: operator.itemgetter(1)(), lambda: operator.itemgetter(1)(data, data), lambda: operator.itemgetter(1)(data, n=1), lambda: operator.itemgetter('k')('text')]:
    try:
        attempt()
    except TypeError as error:
        print(type(error).__name__)
for attempt in [lambda: operator.itemgetter(99)('short'), lambda: operator.itemgetter('absent')(table)]:
    try:
        attempt()
    except (IndexError, KeyError) as error:
        print(type(error).__name__)
class Target:
    def add(self, *args, **kwargs):
        return args[0] * args[1]
    def option(self, value='default'):
        return value
    def raw(*args, **kwargs):
        return sorted(kwargs.items())
    def echo(self, *args, **kwargs):
        return args, kwargs
m = Target()
print(operator.methodcaller('add', 6, 7)(m), operator.methodcaller('option')(m), operator.methodcaller('option', value='given')(m))
print(operator.methodcaller(Text('option'))(m), operator.methodcaller(Text('option'), value=1)(m))
# 'self' and 'name' are accepted as keyword arguments to forward
print(operator.methodcaller('raw', self='s', name='n')(m), operator.methodcaller('echo', 'p', k='v')(m))
positional = tuple('pqrstuvwxy')
keywords = {'kw%d' % k: k for k in range(10)}
print(operator.methodcaller('echo', *positional)(m))
print(operator.methodcaller('echo', **keywords)(m))
print(operator.methodcaller('echo', *positional, **keywords)(m) == (positional, keywords))
for attempt in [lambda: operator.methodcaller(), lambda: operator.methodcaller(3.5), lambda: operator.methodcaller('add')(), lambda: operator.methodcaller('add', 1, 2)(m, m), lambda: operator.methodcaller('add', 1, 2)(m, k=1)]:
    try:
        attempt()
    except TypeError as error:
        print(type(error).__name__)
diagnostic_checks = [
    ('attr-ctor-kw', lambda: operator.attrgetter(attr='name')),
    ('attr-nonstring', lambda: operator.attrgetter(2)),
    ('attr-call-kw', lambda: operator.attrgetter('name')(a, surname='dent')),
    ('item-ctor-kw', lambda: operator.itemgetter(item=0)),
    ('item-call-noargs', lambda: operator.itemgetter(2)()),
    ('item-call-extra', lambda: operator.itemgetter(2)(data, 3)),
    ('item-call-kw', lambda: operator.itemgetter(2)(data, size=3)),
    ('method-noargs', lambda: operator.methodcaller()),
    ('method-kw', lambda: operator.methodcaller(name='foo')),
    ('method-nonstring', lambda: operator.methodcaller(12)),
    ('method-call-noargs', lambda: operator.methodcaller('foo')()),
    ('method-call-extra', lambda: operator.methodcaller('foo', 1, 2)(m, 3)),
    ('method-call-kw', lambda: operator.methodcaller('foo', 1, 2)(m, spam=3)),
]
for label, expr in diagnostic_checks:
    try:
        expr()
    except TypeError as error:
        print(label, type(error).__name__, str(error))
print(callable(operator.attrgetter('name')), callable(operator.itemgetter(0)), callable(operator.methodcaller('bar')))"#,
    });
}

#[test]
fn cpython_operator_call_helper_diff_subset() {
    let probe = run_cpython("import operator; print(hasattr(operator, 'call'))")
        .expect("failed to probe CPython operator.call support");
    if !probe.status.success() || probe.stdout.as_slice() != b"True\n" {
        eprintln!("skipping operator.call diff: CPython oracle lacks operator.call");
        return;
    }

    assert_cpython_output_parity(&DiffCase {
        origin: "Lib/test/test_operator.py newer operator.call public helper subset",
        name: "operator-call-helper",
        source: r#"import operator
def func(*args, **kwargs):
    return args, kwargs
print(operator.call(func))
print(operator.call(func, 0, 1))
print(operator.call(func, a=2, obj=3))
print(operator.call(func, 0, 1, a=2, obj=3))
for name in ['call']:
    value = getattr(operator, name)
    print(name, value.__name__, value.__qualname__, value.__module__ in ('operator', '_operator'))
    print(type(value.__doc__).__name__, bool(value.__doc__), name in operator.__all__)
print(operator.__call__ is operator.call)
for label, expected, expr in [
    ('missing', 'call expected at least 1 argument, got 0', lambda: operator.call()),
    ('noncallable', "'int' object is not callable", lambda: operator.call(42)),
    ('duplicate', "_operator.call() got multiple values for keyword argument 'unknown'", lambda: operator.call(func, unknown=1, **{'unknown': 2})),
]:
    try:
        expr()
    except TypeError as error:
        print(label, type(error).__name__, str(error), str(error) == expected)"#,
    });
}

#[test]
fn cpython_operator_inplace_helper_diff_subset() {
    // CPython oracle text: unsupported operand type(s) for *=: 'int' and 'NoneType'.
    // CPython oracle text: unsupported operand type(s) for @=: 'int' and 'int'.
    // CPython oracle text: unsupported operand type(s) for **=: 'int' and 'str'.
    // CPython oracle text: unsupported operand type(s) for >>=: 'int' and 'str'.
    assert_cpython_output_parity(&DiffCase {
        origin: "Lib/test/test_operator.py::OperatorTestCase::test_inplace and ::test_iconcat_without_getitem public subset",
        name: "operator-inplace-helper",
        source: r#"import operator
# each in-place dunder reports its own name and operand, so we can see which one ran
INPLACE = ['iadd', 'iand', 'ifloordiv', 'ilshift', 'imod', 'imul', 'imatmul', 'ior', 'ipow', 'irshift', 'isub', 'itruediv', 'ixor']
def reporter(op):
    return lambda self, other: op + ':' + repr(other)
Sink = type('Sink', (), {'__%s__' % op: reporter(op) for op in INPLACE})
Sink.__getitem__ = lambda self, key: 'item'
sink = Sink()
print([getattr(operator, op)(sink, 'v') for op in INPLACE])
# iconcat needs the target to look like a sequence (__getitem__), then uses __iadd__
print(operator.iconcat(sink, sink) == 'iadd:' + repr(sink), operator.iconcat([1], (2,)))
print([operator.iadd(6, 3), operator.isub(6, 3), operator.imul(6, 3), operator.ifloordiv(7, 3), operator.itruediv(7, 2), operator.imod(7, 3), operator.ipow(2, 10)])
print([operator.iand(0b1100, 0b1010), operator.ior(0b1100, 0b0011), operator.ixor(0b1111, 0b0101), operator.ilshift(3, 4), operator.irshift(64, 3)])
try:
    operator.imul(1, None)
except TypeError as error:
    print('imul-type', type(error).__name__, str(error))
try:
    operator.imatmul(1, 2)
except TypeError as error:
    print('imatmul-type', type(error).__name__, str(error))
try:
    operator.ipow(1, 'x')
except TypeError as error:
    print('ipow-type', type(error).__name__, str(error))
try:
    operator.irshift(1, 'x')
except TypeError as error:
    print('irshift-type', type(error).__name__, str(error))
# mutable targets are changed in place and returned
for helper in (operator.iadd, operator.iconcat):
    target = ['x']
    returned = helper(target, ['y', 'z'])
    print(helper.__name__, returned, returned is target)
print(operator.iconcat('ab', 'cd'), operator.iadd((1,), (2,)))
for expr in [lambda: operator.iadd(), lambda: operator.ifloordiv(1), lambda: operator.iconcat(1), lambda: operator.iadd(1, 2, extra=3), lambda: operator.iconcat(1, 0.5)]:
    try:
        expr()
    except TypeError as error:
        print(type(error).__name__)"#,
    });
}

