#[test]
fn cpython_functools_total_ordering_diff_subset() {
    assert_cpython_output_parity(&DiffCase {
        origin: "Lib/test/test_functools.py::TestTotalOrdering public subset",
        name: "functools-total-ordering",
        source: r#"import operator
from functools import total_ordering

NAMES = ('__lt__', '__le__', '__gt__', '__ge__')

def probe(tag, cls):
    low, high, high_again = cls(5), cls(8), cls(8)
    print(tag, low < high, high > low, low <= high, high >= low,
          high_again <= high, high_again >= high, low > high, high < low)

def build(root, fn):
    namespace = {
        '__init__': lambda self, rank: setattr(self, 'rank', rank),
        root: lambda self, other: fn(self.rank, other.rank),
        '__eq__': lambda self, other: self.rank == other.rank,
    }
    return total_ordering(type('Only' + root.strip('_').upper(), (), namespace))

for root, fn in zip(NAMES, (operator.lt, operator.le, operator.gt, operator.ge)):
    cls = build(root, fn)
    probe(root, cls)
    print(cls.__name__, [getattr(cls, name).__name__ for name in NAMES],
          [getattr(cls, name).__module__ for name in NAMES if name != root])

@total_ordering
class Preset:
    def __init__(self, weight):
        self.weight = weight
    def __eq__(self, other):
        return self.weight == other.weight
    def __gt__(self, other):
        return self.weight > other.weight
    def __ge__(self, other):
        return 'user-defined'
print('preset', Preset(1).__ge__(Preset(9)), Preset.__ge__.__qualname__,
      Preset(3) <= Preset(4), Preset(3) < Preset(4))

try:
    total_ordering(type('Bare', (), {}))
except ValueError as exc:
    print('bare', type(exc).__name__, 'ordering operation' in str(exc))

@total_ordering
class Version:
    def __init__(self, major):
        self.major = major
    def __eq__(self, other):
        return isinstance(other, Version) and self.major == other.major
    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self.major < other.major
ver = Version(3)
print('notimpl', [getattr(ver, name)('3') is NotImplemented for name in NAMES[1:]])
print('mixed', Version(2) <= Version(2), Version(4) >= Version(2), Version(1) > Version(1))
try:
    ver >= 'x'
except TypeError as exc:
    print('type', type(exc).__name__)"#,
    });
}

