// Differential smoke tests for CPython-compatible program behavior. These are
// intentionally written with syntax accepted by Python 3.9+. The oracle is
// `$MINIPYTHON_CPYTHON` (default `/opt/homebrew/bin/python3`).
#[test]
fn cpython_comparison_helper_rules_diff_subset() {
    assert_cpython_output_parity(&DiffCase {
        origin: "Grammar/python.gram compare_op_bitwise_or_pair and comparison operator helper public execution subset",
        name: "comparison-helper-rules",
        source: r#"print(1 == 1 | 0, 1 != 2 | 0)
print(1 <= 2 | 1, 1 < 2 | 1, 3 >= 2 | 1, 4 > 1 | 2)
print(1 in [0 | 1], 2 not in [1 | 0])
print(None is None, None is not 1 | 0)
seq = [5]
probe = 5
# every comparison operator in one chain; the first link is false so the
# remaining links (including the ill-typed membership tests) never run
chained = 3 > 4 < 2 != 9 == 9 <= 0 >= 1 in probe not in seq is probe is not seq
print("chain", chained)
print(1 < 2 <= 2 == 2 != 3 >= 3 > 0, 5 in seq is not None, probe not in [] is not False)
print("done")"#,
    });
}

