#[test]
fn cpython_bytes_join_diff_subset() {
    assert_cpython_output_parity(&DiffCase {
        origin: "Lib/test/test_bytes.py::BaseBytesTest::test_join public subset",
        name: "bytes-join",
        source: r#"for ctor in [bytes, bytearray]:
    empty = ctor(b'')
    print(empty.join([]))
    print(empty.join([b'']))
    word = b'join'
    for cut in range(len(word) + 1):
        pieces = [ctor(word[:cut]), ctor(word[cut:])]
        print(cut, empty.join(pieces), empty.join(tuple(pieces)), empty.join(p for p in pieces))
    singles = [ctor(bytes([byte])) for byte in word]
    print(empty.join(singles), empty.join(iter(singles)))
    dot_join = ctor(b'.:').join
    print(dot_join([b'ab', b'cd']))
    print(dot_join([memoryview(b'ab'), b'cd']))
    print(dot_join([b'ab', memoryview(b'cd')]))
    print(dot_join([bytearray(b'ab'), b'cd']))
    print(dot_join([b'ab', bytearray(b'cd')]))
    for label, item in [
        ('join-slice-mid', memoryview(bytearray(b'abcdef'))[2:5]),
        ('join-slice-step', memoryview(bytearray(b'abcdef'))[::2]),
        ('join-slice-rev', memoryview(bytearray(b'abcdef'))[::-1]),
    ]:
        try:
            result = dot_join([item])
            print(label, type(result).__name__, result)
        except TypeError as error:
            print(label, error.__class__.__name__, str(error), 'memoryview found' in str(error))
    seq = [b'abc'] * 100
    joined = dot_join(seq)
    expected = b'abc' + b'.:abc' * 99
    print(joined == ctor(expected), len(joined))
    joined = empty.join(seq)
    expected = b'abc' * 100
    print(joined == ctor(expected), len(joined))
    for expr in [
        lambda: ctor(b' ').join(None),
        lambda: dot_join([bytearray(b'ab'), 'cd', b'ef']),
        lambda: dot_join([memoryview(b'ab'), 'cd', b'ef']),
    ]:
        try:
            expr()
        except TypeError as error:
            print(error.__class__.__name__)"#,
    });
}

