#[test]
fn cpython_bytearray_extended_slice_assignment_diff_subset() {
    assert_cpython_output_parity(&DiffCase {
        origin: "Lib/test/test_bytes.py::ByteArrayTest::test_extended_set_del_slice and ::test_setslice_trap",
        name: "bytearray-extended-slice-assignment",
        source: r#"import sys
edges = [None, 0, 2, 21, 2 ** 200, sys.maxsize, -1, -4, -27, -200]
failures = []
pattern = [(5 * k + 1) % 256 for k in range(130)]
for lo in edges:
    for hi in edges:
        for st in edges:
            if st == 0:
                continue
            model = pattern[:]
            actual = bytearray(pattern)
            # assign a same-length replacement (rotated selection) through the slice
            picked = model[lo:hi:st]
            replacement = picked[1:] + picked[:1]
            model[lo:hi:st] = replacement
            actual[lo:hi:st] = replacement
            same_after_set = actual == bytearray(model)
            del model[lo:hi:st]
            del actual[lo:hi:st]
            if not (same_after_set and actual == bytearray(model)):
                failures.append((lo, hi, st))
print('extended set/del', failures)
for rhs in [(65, 66), range(65, 68), [65, True, False], [65, 'x'], [256], [-1]]:
    b = bytearray(b'abc')
    try:
        b[1:2] = rhs
        print(type(rhs).__name__, b)
    except (TypeError, ValueError) as error:
        print(type(rhs).__name__, error.__class__.__name__)
b = bytearray(b'abcdef')
print(b.__setitem__(slice(1, 3), [88, 89]), b)
print(b.__delitem__(slice(None, None, 2)), b)
b = bytearray(range(10))
b[8:] = b
print(len(b), b[:5], b[8:13])
print('__setitem__' in dir(bytearray), '__delitem__' in dir(bytearray))"#,
    });
}

