fn cpython_bytearray_search_reentrancy_buffererror_diff_subset() {
    let probe = run_cpython("print(hasattr(bytearray(), '__buffer__'))")
        .expect("failed to probe CPython bytearray __buffer__ support");
    if !probe.status.success() || probe.stdout.as_slice() != b"True\n" {
        eprintln!("skipping bytearray search reentrancy diff: CPython oracle lacks __buffer__");
        return;
    }

    assert_cpython_output_parity(&DiffCase {
        origin: "Lib/test/test_bytes.py::ByteArrayTest::test_search_methods_reentrancy_raises_buffererror public subset",
        name: "bytearray-search-reentrancy-buffererror",
        source: r#"class Saboteur:
    # both the buffer export and the index conversion empty the haystack first
    def __init__(self, target):
        self.target = target
    def __buffer__(self, flags):
        del self.target[:]
        return memoryview(self.target)
    def __release_buffer__(self, view):
        view.release()
    def __index__(self):
        del self.target[:]
        return 0x5a
operations = {
    'find': lambda hay, needle: hay.find(needle),
    'count': lambda hay, needle: hay.count(needle),
    'index': lambda hay, needle: hay.index(needle),
    'rindex': lambda hay, needle: hay.rindex(needle),
    'rfind': lambda hay, needle: hay.rfind(needle),
    'contains': lambda hay, needle: needle in hay,
    'split': lambda hay, needle: hay.split(needle),
    'rsplit': lambda hay, needle: hay.rsplit(needle),
}
for label, operation in operations.items():
    haystack = bytearray(b'ZZ')
    try:
        outcome = operation(haystack, Saboteur(haystack))
    except BufferError as error:
        print(label, type(error).__name__, haystack)
    else:
        print(label, 'accepted', outcome, haystack)"#,
    });
}

