#[test]
fn cpython_float_short_repr_diff_subset() {
    assert_cpython_output_parity(&DiffCase {
        origin: "Lib/test/test_float.py::ReprTestCase::test_short_repr",
        name: "float-short-repr",
        source: r#"import sys
# repr must pick the shortest string that round-trips; the switch to exponent
# notation happens below 1e-4 and at 1e16.
mantissas = ['1', '2', '5', '9', '25', '123456789', '999999999999999', '100000000000001', '4.000000000000001']
mismatches = []
for exponent in range(-8, 24):
    row = []
    for mantissa in mantissas:
        value = float(mantissa + 'e' + str(exponent))
        for signed in (value, -value):
            text = repr(signed)
            if str(signed) != text or float(text) != signed or eval(text) != signed:
                mismatches.append(text)
            row.append(text)
    print(exponent, ' '.join(row))
state = 2024
for _ in range(40):
    state = (state * 6364136223846793005 + 1442695040888963407) % 2 ** 64
    value = float('%.15g' % ((state >> 11) / 2.0 ** 53 * 10.0 ** ((state % 60) - 30)))
    print(repr(value), repr(-value), repr(value) == str(value))
extras = [0.0, 1 / 3, 2 / 3, 0.1 + 0.2, 1e16 - 2, 2.0 ** 53, 2.0 ** -1074, sys.float_info.max, sys.float_info.min]
print([repr(value) for value in extras])
print('style', sys.float_repr_style, 'mismatches', mismatches)"#,
    });
}

// The shortest repr can tie: `-71321097208477.125` lies exactly between the
// 16-digit candidates `...477.12` and `...477.13`, which both round-trip.
// CPython (`_Py_dg_dtoa` mode 0) takes the even one; the release gate's
// datetime corpus found it through `timedelta.total_seconds()`.
#[test]
fn cpython_float_repr_shortest_tie_to_even_diff() {
    assert_cpython_output_parity(&DiffCase {
        origin: "float_repr shortest digits, exactly halfway cases",
        name: "float-repr-shortest-tie-to-even",
        source: r#"from datetime import timedelta
print(timedelta(-825475663, 74722, 873546).total_seconds())
print(-71321097208477.125, 71321097208477.125, 71321097208477.375)
for scale in (3, 4, 5, 7, 9, 11):
    for i in range(40):
        n = (1 << 52) + i * 7919 * 104729 + scale * 31
        for shift in (0, 1, 3, 6):
            x = (n >> shift) * 2.0 ** -scale
            row = (x, -x, x * 2.0 ** 30, x * 2.0 ** -40, x * 2.0 ** 80, x * 2.0 ** -80)
            print(' '.join(repr(y) for y in row), str(-x), f'{x}', '%r' % x)"#,
    });
}

// Several starred items are a display, not an assignment: `[*x, *y]` as an
// expression statement, in tuples, sets, calls, and returned values is
// accepted, while every assignment-like target (`=`, `for`, comprehension
// `for`, `with ... as`) rejects them in the compiler as CPython does.
#[test]
fn cpython_multiple_starred_display_vs_target_diff() {
    assert_cpython_output_parity(&DiffCase {
        origin: "Python/codegen.c unpack_helper; Grammar/python.gram star_targets",
        name: "multiple-starred-display-vs-target",
        source: r#"sources = [
    "[*x, *y]", "(*x, *y)", "*x, *y", "{*x, *y}", "f(*x, *y)", "print(*x, *y, sep='')",
    "[*x, *y] = z", "*x, *y = z", "(*x, *y) = z", "a, *x, b, *y = z", "[a, [*x, *y]] = z",
    "x = [*a, *b] = c", "[*a, *b] += c",
    "for *x, *y in z: pass", "for [*x, *y] in z: pass", "for (*x, *y) in z: pass",
    "[q for *x, *y in z]", "with a as (*x, *y): pass", "*x = y", "*x", "[*x] = y",
    "x = *a, *b", "def f():\n    return *a, *b", "def g():\n    yield *a, *b",
    "[*x, *y][0]", "[*x, *y].append(1)", "x = 1; [*x, *y]",
]
for source in sources:
    try:
        compile(source, "<case>", "exec")
        print(repr(source), "accepted")
    except SyntaxError as error:
        print(repr(source), type(error).__name__, error.args[0])
x = [1]; y = (2, 3)
print([*x, *y], (*x, *y), {*x, *y}, [*x, *y][1:])
[*x, *y]
*x, *y
print(*x, *y, sep='-')
a, *b = [*x, *y]; print(a, b)
for p, *q in [[*x, *y]]: print(p, q)
def f():
    return *x, *y
def g():
    yield *x, *y
print(f(), list(g()), [*range(2), *'ab'])"#,
    });
}

