#[test]
fn cpython_float_round_matches_format_diff_subset() {
    assert_cpython_output_parity(&DiffCase {
        origin: "Lib/test/test_float.py::RoundTestCase::test_matches_float_format",
        name: "float-round-matches-format",
        source: r#"def check(label, values):
    checked = 0
    for x in values:
        for ndigits in range(4):
            formatted = float(format(x, '.' + str(ndigits) + 'f'))
            rounded = round(x, ndigits)
            if formatted != rounded:
                print('mismatch', label, repr(x), ndigits, repr(formatted), repr(rounded))
            checked += 1
    print(label, checked)

check('thousandths', [i / 1000.0 for i in range(500)])
check('half-cent-grid', [i / 1000.0 for i in range(5, 5000, 10)])
check('deterministic-random-like', [((i * 1103515245 + 12345) % 1000000) / 1000000.0 for i in range(500)])"#,
    });
}

#[test]
fn cpython_float_format_specials_diff_subset() {
    assert_cpython_output_parity(&DiffCase {
        origin: "Lib/test/test_float.py::RoundTestCase::test_format_specials",
        name: "float-format-specials",
        source: r#"# Non-finite values ignore precision and the alternate flag; only the sign
# options change the output, and NaN never shows a minus sign.
specials = [('inf', float('inf')), ('-inf', float('-inf')), ('nan', float('nan')), ('-nan', -float('nan'))]
bodies = []
for kind in 'efgEFG':
    for precision in ('', '.0', '.4', '.25'):
        for alt in ('', '#'):
            bodies.append(alt + precision + kind)
seen = {}
for body in bodies:
    for sign in ('', '+', ' ', '-'):
        for label, value in specials:
            via_percent = ('%' + sign + body) % value
            via_format = format(value, sign + body)
            key = (sign, label, via_percent == via_format)
            seen.setdefault(key, set()).add(via_percent)
for key in sorted(seen):
    print(key, sorted(seen[key]))
print('checked', len(bodies) * 4 * len(specials))"#,
    });
}

#[test]
fn cpython_float_inf_nan_string_diff_subset() {
    assert_cpython_output_parity(&DiffCase {
        origin: "Lib/test/test_float.py::InfNanTest",
        name: "float-inf-nan-string",
        source: r#"import math
def show_float(label, expr):
    try:
        value = expr()
        print(label, math.isinf(value), math.isnan(value), repr(value), str(value), math.copysign(1.0, value))
    except BaseException as error:
        print(label, type(error).__name__, error.args[0])

for text in ['inf', '+inf', '-inf', 'infinity', '+infinity', '-infinity', 'INF', '+Inf', '-iNF', 'Infinity', '+iNfInItY', '-INFINITY']:
    show_float('parse-inf ' + text, lambda text=text: float(text))
for text in ['info', '+info', '-info', 'in', '+in', '-in', 'infinit', '+Infin', '-INFI', 'infinitys', '++Inf', '-+inf', '+-infinity', '--Infinity']:
    show_float('bad-inf ' + text, lambda text=text: float(text))
for text in ['nan', '+nan', '-nan', 'NAN', '+NAn', '-NaN']:
    show_float('parse-nan ' + text, lambda text=text: float(text))
for text in ['nana', '+nana', '-nana', 'na', '+na', '-na', '++nan', '-+NAN', '+-NaN', '--nAn']:
    show_float('bad-nan ' + text, lambda text=text: float(text))
for label, value in [
    ('inf-as-repr', 1e300 * 1e300),
    ('ninf-as-repr', -1e300 * 1e300),
]:
    print(label, repr(value), str(value), math.isinf(value), math.isnan(value), math.copysign(1.0, value))
# The sign of a NaN that arithmetic produced is not defined by Python: it
# depends on the hardware and on the build of the interpreter, so the two
# cases below print no sign. The sign of a parsed NaN and of an infinity is
# defined, and the cases above and below hold it exactly.
for label, value in [
    ('nan-as-repr', 1e300 * 1e300 * 0),
    ('neg-nan-as-repr', -1e300 * 1e300 * 0),
]:
    print(label, repr(value), str(value), math.isinf(value), math.isnan(value))
print('sign-inf', math.copysign(1.0, float('inf')), math.copysign(1.0, float('-inf')))
print('sign-nan', math.copysign(1.0, float('nan')), math.copysign(1.0, float('-nan')))"#,
    });
}

#[test]
fn cpython_float_from_number_diff_subset() {
    let oracle_probe = run_cpython("print(hasattr(float, 'from_number'))")
        .expect("failed to run CPython float.from_number capability probe");
    let oracle_stdout = String::from_utf8(oracle_probe.stdout)
        .expect("CPython float.from_number probe emitted non-UTF-8 output");
    if oracle_stdout.trim() != "True" {
        eprintln!("skipping float.from_number diff: CPython oracle lacks float.from_number");
        return;
    }

    assert_cpython_output_parity(&DiffCase {
        origin: "Lib/test/test_float.py::GeneralFloatCases::test_from_number and ::test_from_number_subclass",
        name: "float-from-number",
        source: r#"class Sub(float):
    pass
class OtherSub(float):
    pass
class Floaty:
    def __init__(self, payload):
        self.payload = payload
    def __float__(self):
        return self.payload
class Indexy:
    def __init__(self, payload):
        self.payload = payload
    def __index__(self):
        return self.payload
class Inty:
    # __int__ alone is not enough for from_number
    def __int__(self):
        return 5

def report(label, result, expected_type):
    print(label, result, type(result) is expected_type)

report('float', float.from_number(-0.75), float)
report('int', float.from_number(-12), float)
report('subclass-in', float.from_number(OtherSub(6.5)), float)
report('floaty', float.from_number(Floaty(1.25)), float)
report('floaty-sub-result', float.from_number(Floaty(OtherSub(8.5))), float)
report('indexy', float.from_number(Indexy(77)), float)
report('sub-from-float', Sub.from_number(0.5), Sub)
report('sub-from-index', Sub.from_number(Indexy(-3)), Sub)
print('dir', all('from_number' in dir(obj) for obj in (float, 2.0, Sub, Sub(2.0))))
print('via-instance', type((9.0).from_number(1)) is float, type(Sub(9.0).from_number(1)) is Sub)
nan = float('nan')
plain = float.from_number(nan)
child = Sub.from_number(nan)
print('nan', plain != plain, plain is nan, type(plain).__name__, child != child, type(child).__name__)
for label, thunk in [
    ('text', lambda: float.from_number('1.5')),
    ('raw', lambda: float.from_number(b'1.5')),
    ('imaginary', lambda: float.from_number(2j)),
    ('inty', lambda: float.from_number(Inty())),
    ('list', lambda: float.from_number([])),
    ('no-args', lambda: float.from_number()),
    ('two-args', lambda: float.from_number(1.0, 2.0)),
    ('keyword', lambda: float.from_number(number=1)),
]:
    try:
        thunk()
    except TypeError as error:
        print(label, type(error).__name__)
try:
    float.from_number(Indexy(10 ** 400))
except OverflowError as error:
    print('huge-index', type(error).__name__)"#,
    });
}

