#[test]
fn cpython_dict_view_membership_rich_compare_diff_subset() {
    assert_cpython_output_parity(&DiffCase {
        origin: "Lib/test/test_dict.py dict view membership rich equality subset",
        name: "dict-view-membership-rich-compare",
        source: r#"class Probe:
    def __init__(self, tag):
        self.tag = tag
    def __eq__(self, other):
        print("eq", self.tag, getattr(other, "tag", other))
        return self.tag == getattr(other, "tag", other)

d = {"a": Probe("a"), "b": Probe("b")}
print("values", Probe("b") in d.values())
print("items-tuple", ("b", Probe("b")) in d.items())
print("items-list", ["b", Probe("b")] in d.items())

class Boom:
    def __eq__(self, other):
        raise ValueError("boom")

def show(label, fn):
    try:
        print(label, fn())
    except Exception as error:
        print(label, type(error).__name__, str(error), error.args)

show("values-error", lambda: 1 in {"x": Boom()}.values())
show("items-error", lambda: ("x", 1) in {"x": Boom()}.items())"#,
    });
}

#[test]
fn cpython_dict_values_view_identity_equality_diff_subset() {
    assert_cpython_output_parity(&DiffCase {
        origin: "Lib/test/test_dict.py dict values-view identity equality subset",
        name: "dict-values-view-identity-equality",
        source: r#"from collections import OrderedDict

d = {1: 2}
values = d.values()
same = values
print('values-same', values == same, values != same)
print('values-is', values is same, d.values() is d.values())
print('values-fresh', d.values() == d.values(), d.values() != d.values())
other = {1: 2}
print('values-other', d.values() == other.values(), d.values() != other.values())
left = d.values()
right = d.values()
d[3] = 4
print('values-live-identity', left == right, left == left, list(left))
od = OrderedDict([('a', 1)])
od_values = od.values()
print('ordered-values-same', od_values == od_values, od.values() == od.values())
print('setlike', d.keys() == d.keys(), d.items() == d.items(), {}.keys() == {}.items())
print('setlike-is', d.keys() is d.keys(), d.items() is d.items())"#,
    });
}

