#[test]
fn cpython_future_statement_error_messages_diff_subset() {
    assert_cpython_output_parity_source(
        "Python/future.c and Python/codegen.c future statement diagnostics",
        "future-statement-errors",
        r##"cases = [
    "from __future__ import braces",
    "from __future__ import nonsense",
    "from __future__ import annotations, nonsense",
    "from __future__ import nonsense, braces",
    "from __future__ import braces, nonsense",
    "from __future__ import nonsense as alias",
    "from __future__ import *",
    "from __future__ import (\n    annotations,\n    nonsense)",
    "from __future__ import (annotations as a)",
    "from __future__ import annotations as a, division as d",
    "import os\nfrom __future__ import annotations",
    "x = 1\nfrom __future__ import annotations",
    "'''doc'''\nfrom __future__ import annotations",
    "'''doc'''\n'''doc2'''\nfrom __future__ import annotations",
    "'doc'\nfrom __future__ import annotations\nfrom __future__ import division",
    "from __future__ import annotations\nimport os\nfrom __future__ import division",
    "from __future__ import annotations\n'doc'\nfrom __future__ import division",
    "def f():\n    from __future__ import annotations",
    "class C:\n    from __future__ import annotations",
    "if 1:\n    from __future__ import annotations",
    "try:\n    from __future__ import annotations\nexcept: pass",
    "async def f():\n    from __future__ import annotations",
    "from __future__ import annotations; from __future__ import division",
    "from __future__ import annotations; x = 1",
    "x = 1; from __future__ import annotations",
    "from . __future__ import annotations",
    "from .__future__ import annotations",
    "import __future__",
    "b'doc'\nfrom __future__ import annotations",
    "f'doc'\nfrom __future__ import annotations",
    "1\nfrom __future__ import annotations",
    "r'doc'\nfrom __future__ import annotations",
    "'a' 'b'\nfrom __future__ import annotations",
    "('doc')\nfrom __future__ import annotations",
    "# comment\n\n'doc'\n\nfrom __future__ import annotations",
    "from __future__ import annotations\nfrom __future__ import braces",
    "from __future__ import braces\nfrom __future__ import nonsense",
    "x = 1\nfrom __future__ import nonsense",
    "x = 1\nfrom __future__ import braces",
    "x = 1\nfrom __future__ import *",
    "def f():\n    from __future__ import nonsense",
    "from __future__ import (annotations, division,)",
    "from __future__ import annotations\nfrom __future__ import annotations",
    "\n\n\nx=1\n\nfrom __future__ import annotations",
    "from __future__ import generators, nested_scopes, division, absolute_import, with_statement, print_function, unicode_literals, generator_stop, annotations",
    "'doc'\n'doc'\nfrom __future__ import nonsense",
]
for source in cases:
    for mode in ['exec', 'single']:
        if mode == 'single' and '\n' in source:
            continue
        try:
            compile(source, '<future>', mode)
        except SyntaxError as error:
            print(mode, repr(source), type(error).__name__, error.args[0])
        else:
            print(mode, repr(source), 'compiled')
for source in ["from __future__ import braces", "from __future__ import annotations\nimport os\nfrom __future__ import division"]:
    try:
        exec(source, {})
    except SyntaxError as error:
        print('exec', type(error).__name__, error.args[0])
"##,
    );
}

#[test]
fn cpython_future_statement_error_location_diff_subset() {
    use minipython::{source_compile_error_diagnostic, source_parse_error_diagnostic};

    let cases = [
        "from __future__ import braces",
        "from __future__ import nonsense",
        "from __future__ import annotations, nonsense",
        "from __future__ import nonsense as n",
        "from __future__ import *",
        "from __future__ import (annotations,\n    braces as b)",
        "import os\nfrom __future__ import annotations",
        "x = 1; from __future__ import annotations",
        "'''doc'''\n'''doc2'''\nfrom __future__ import annotations",
        "from __future__ import annotations\nimport os\nfrom __future__ import division",
        "def f():\n    from __future__ import annotations",
        "x=1\nfrom __future__ import (a,\n  b)",
        "x=1\nfrom __future__ import a ;y=2",
        "from __future__ import annotations\ndef f(x: (yield y)): pass",
        "from __future__ import annotations\ndef f(x: (yield)): pass",
        "from __future__ import annotations\ndef f(x: (z := 1 + 2)): pass",
        "from __future__ import annotations\nx: (yield from y) = 1",
        "from __future__ import annotations\nasync def f(x: (await (y))): pass",
        "from __future__ import barry_as_FLUFL\nprint(1 != 2)",
        "print(1 <> 2)",
        "x = 1 <> 2",
    ];
    let mut source = String::from("cases = [\n");
    for case in cases {
        source.push_str(&format!("    {case:?},\n"));
    }
    source.push_str(
        "]\nfor case in cases:\n    try:\n        compile(case, '<future>', 'exec')\n    except SyntaxError as error:\n        print(error.msg, error.lineno, error.offset, error.end_lineno, error.end_offset, sep='|')\n",
    );
    let output = run_cpython(&source).expect("run CPython future diagnostics");
    assert!(output.status.success(), "{}", String::from_utf8_lossy(&output.stderr));
    let stdout = String::from_utf8(output.stdout).expect("CPython emits UTF-8");
    let lines = stdout.lines().collect::<Vec<_>>();
    assert_eq!(lines.len(), cases.len(), "CPython output:\n{stdout}");

    for (case, expected) in cases.iter().zip(lines) {
        let diagnostic = match source_compile_error_diagnostic(case) {
            Ok(Some(diagnostic)) => diagnostic,
            Ok(None) => panic!("MiniPython compiled {case:?}"),
            Err(_) => source_parse_error_diagnostic(case)
                .expect("lexes")
                .unwrap_or_else(|| panic!("MiniPython parsed {case:?}")),
        };
        let actual = format!(
            "{}|{}|{}|{}|{}",
            diagnostic.message,
            diagnostic.line,
            diagnostic.column,
            diagnostic.end_line,
            diagnostic.end_column
        );
        assert_eq!(actual, expected, "diagnostic differs for {case:?}");
    }
}

