#[test]
fn cpython_instance_arithmetic_special_methods_diff() {
    assert_cpython_output_parity(&DiffCase {
        origin: "Python data model: numeric special methods of user classes (CPython 3.14.6 oracle)",
        name: "instance_arithmetic_special_methods",
        source: r#"import operator


class V:
    def __init__(self, x):
        self.x = x

    def __repr__(self):
        return f'V({self.x!r})'

    def __add__(self, other):
        return V(self.x + (other.x if isinstance(other, V) else other))

    def __mul__(self, other):
        return V(self.x * (other.x if isinstance(other, V) else other))

    def __rmul__(self, other):
        return ('rmul', other)

    def __truediv__(self, other):
        return ('truediv', other)

    def __rtruediv__(self, other):
        return ('rtruediv', other)

    def __floordiv__(self, other):
        return ('floordiv', other)

    def __rfloordiv__(self, other):
        return ('rfloordiv', other)

    def __mod__(self, other):
        return ('mod', other)

    def __rmod__(self, other):
        return ('rmod', other)

    def __divmod__(self, other):
        return ('divmod', other)

    def __rdivmod__(self, other):
        return ('rdivmod', other)

    def __neg__(self):
        return V(-self.x)

    def __pos__(self):
        return ('pos', self.x)


class Refuses:
    def __mul__(self, other):
        return NotImplemented

    def __rmul__(self, other):
        return NotImplemented

    def __truediv__(self, other):
        return NotImplemented

    def __mod__(self, other):
        return NotImplemented

    def __divmod__(self, other):
        return NotImplemented


class Answers:
    def __rmul__(self, other):
        return 'Answers.rmul'

    def __rtruediv__(self, other):
        return 'Answers.rtruediv'

    def __rmod__(self, other):
        return 'Answers.rmod'

    def __rdivmod__(self, other):
        return 'Answers.rdivmod'


def attempt(label, func):
    try:
        print(label, repr(func()))
    except Exception as exc:
        print(label, 'raise', type(exc).__name__, exc)


attempt('mul', lambda: V(2) * 3)
attempt('rmul', lambda: 3 * V(2))
attempt('mul same', lambda: V(2) * V(5))
attempt('truediv', lambda: (V(1) / 2, 2 / V(1)))
attempt('floordiv', lambda: (V(1) // 2, 2 // V(1)))
attempt('mod', lambda: (V(1) % 2, 2 % V(1)))
attempt('divmod', lambda: (divmod(V(1), 2), divmod(2, V(1))))
attempt('neg pos', lambda: ' '.join(map(repr, (-V(3), +V(3)))))
attempt('format percent', lambda: '%s|%r' % (V(1), V(2)))
attempt('percent single', lambda: '%s' % V(7))
attempt('operator', lambda: ' '.join(map(repr, (
    operator.mul(V(2), 3), operator.truediv(V(1), 2), operator.neg(V(3)),
    operator.pos(V(3)), operator.mod(V(1), 2), operator.floordiv(2, V(1))))))
attempt('refuses mul', lambda: Refuses() * 2)
attempt('refuses same', lambda: Refuses() * Refuses())
attempt('refuses truediv', lambda: Refuses() / 2)
attempt('refuses mod', lambda: Refuses() % 2)
attempt('refuses divmod', lambda: divmod(Refuses(), 2))
attempt('answers', lambda: (Refuses() * Answers(), Refuses() / Answers(), Refuses() % Answers(),
                            divmod(Refuses(), Answers())))
attempt('int answers', lambda: (2 * Answers(), 2 / Answers(), 2 % Answers(), divmod(2, Answers())))
attempt('unary refuses', lambda: -Refuses())
v = V(1)
v += 2
v *= 3
attempt('in place', lambda: v)
w = Answers()
attempt('in place reflected', lambda: (lambda x: x)(2) * w)
x = 5
x *= Answers()
attempt('in place int', lambda: x)
items = [1]
items *= 2
attempt('list repeat', lambda: items)
"#,
    });
}

// --------------------
// io.StringIO: native class diffed against CPython 3.14.6.
//
// Every program starts with STRINGIO_DIFF_PRELUDE: `attempt` prints a result or
// the raised exception's type and message.
// --------------------

const STRINGIO_DIFF_PRELUDE: &str = r#"import io, sys


def attempt(label, func):
    try:
        print(label, 'ok', repr(func()))
    except Exception as exc:
        print(label, 'raise', type(exc).__name__, str(exc))

"#;

fn assert_cpython_stringio_parity(name: &str, body: &str) {
    let origin = "Lib/io StringIO public behavior (CPython 3.14.6 oracle)";
    let source = format!("{STRINGIO_DIFF_PRELUDE}{body}");
    let cpython_output = run_cpython(&source).unwrap_or_else(|message| {
        panic!("failed to run CPython for {origin}::{name}\nsource:\n{source}\n\n{message}")
    });
    assert!(
        cpython_output.status.success(),
        "expected CPython to accept {origin}::{name}\nsource:\n{source}\n\nstderr:\n{}",
        String::from_utf8_lossy(&cpython_output.stderr)
    );
    let cpython_stdout = String::from_utf8(cpython_output.stdout)
        .unwrap_or_else(|error| panic!("CPython emitted non-UTF-8 output: {error}"));
    let cpython_lines: Vec<String> = cpython_stdout.lines().map(str::to_string).collect();
    assert!(
        cpython_lines.len() > 1,
        "StringIO diff {name} must produce output to compare"
    );
    assert_eq!(
        run_minipython_source(&source),
        Ok(cpython_lines),
        "MiniPython output differs from CPython for {origin}::{name}\nsource:\n{source}"
    );
}

/// Constructor argument errors, every newline mode on write and read, the newlines property, re-initialization, and the type surface.
