fn cpython_stringio_constructor_and_newline_modes_diff() {
    assert_cpython_stringio_parity(
        "constructor-newline-modes",
        r#"_doc = lambda value: '<doc>' if isinstance(value, str) and value else value
S = io.StringIO
attempt('ctor int', lambda: S(1))
attempt('ctor bytes', lambda: S(b'x'))
attempt('ctor none', lambda: S(None).getvalue())
attempt('ctor nl bad', lambda: S('', 'x'))
attempt('ctor nl int', lambda: S('', 1))
attempt('ctor nl bytes', lambda: S('', b'\n'))
attempt('ctor 3', lambda: S('', None, 1))
attempt('ctor kw', lambda: S(initial_value='a', newline=None).getvalue())
attempt('ctor kw bad', lambda: S(foo=1))
attempt('ctor str subclass', lambda: S(type('T', (str,), {})('ab\n')).readline())
for nl in [None, '', '\n', '\r', '\r\n']:
    s = S('a\rb\r\nc\nd', newline=nl)
    print(repr(nl), repr(s.getvalue()), repr(s.newlines), s.readlines(), s.tell())
    s = S(newline=nl)
    s.write('x\r')
    print(repr(nl), repr(s.getvalue()), repr(s.newlines))
    s.write('\ny\r\n')
    print(repr(nl), repr(s.getvalue()), repr(s.newlines))
    s.write('z\n')
    s.seek(0)
    print(repr(nl), list(s), repr(s.newlines))
print(repr(S('abc', None).newlines), repr(S('a\n', '').newlines), repr(S('a\n').newlines))
s = S('xyz')
attempt('reinit', lambda: (s.__init__('new\nvalue'), s.readline(), s.tell()))
attempt('reinit bad', lambda: s.__init__(1))
print(repr(s.getvalue()), s.tell())
print(type(s).__name__, type(s).__module__, type(s).__qualname__, repr(type(s)), _doc(io.StringIO.__doc__))
print(repr(s)[:24], isinstance(s, io.StringIO), isinstance(s, object))
"#,
    );
}

