// --------------------
// csv: native module diffed against CPython 3.14.6.
//
// Every program starts with CSV_DIFF_PRELUDE: `attempt` prints a result or the
// raised exception's type and message, `rows` reads lines and records each
// row with its line_num (or the csv.Error), and `written` writes rows to a
// StringIO and returns the text with each writerow result.
// --------------------

const CSV_DIFF_PRELUDE: &str = r#"import csv, io, sys


def attempt(label, func):
    try:
        print(label, 'ok', repr(func()))
    except Exception as exc:
        print(label, 'raise', type(exc).__name__, str(exc))


def rows(lines, **kw):
    reader = csv.reader(lines, **kw)
    out = []
    try:
        for row in reader:
            out.append((reader.line_num, row))
    except csv.Error as exc:
        out.append(('Error', reader.line_num, str(exc)))
    return out


def written(rows, **kw):
    stream = io.StringIO()
    writer = csv.writer(stream, **kw)
    results = []
    for row in rows:
        try:
            results.append(writer.writerow(row))
        except Exception as exc:
            results.append((type(exc).__name__, str(exc)))
    return stream.getvalue(), results

"#;

fn assert_cpython_csv_parity(name: &str, body: &str) {
    let origin = "Lib/csv public behavior (CPython 3.14.6 oracle)";
    let source = format!("{CSV_DIFF_PRELUDE}{body}");
    let cpython_output = run_cpython(&source).unwrap_or_else(|message| {
        panic!("failed to run CPython for {origin}::{name}\nsource:\n{source}\n\n{message}")
    });
    assert!(
        cpython_output.status.success(),
        "expected CPython to accept {origin}::{name}\nsource:\n{source}\n\nstderr:\n{}",
        String::from_utf8_lossy(&cpython_output.stderr)
    );
    let cpython_stdout = String::from_utf8(cpython_output.stdout)
        .unwrap_or_else(|error| panic!("CPython emitted non-UTF-8 output: {error}"));
    let cpython_lines: Vec<String> = cpython_stdout.lines().map(str::to_string).collect();
    assert!(
        cpython_lines.len() > 1,
        "csv diff {name} must produce output to compare"
    );
    assert_eq!(
        run_minipython_source(&source),
        Ok(cpython_lines),
        "MiniPython output differs from CPython for {origin}::{name}\nsource:\n{source}"
    );
}

