// --------------------
// datetime: native module diffed against CPython 3.14.6.
//
// CPython runs with TZ=UTC because the sandbox's local time zone is always
// UTC. Every program starts with DATETIME_DIFF_PRELUDE, whose `t(label,
// func)` prints the repr of a result or the exception type and message.
// --------------------

const DATETIME_DIFF_PRELUDE: &str = r#"import copy
import datetime
from datetime import date, time, datetime as dt, timedelta, timezone, tzinfo, UTC, MINYEAR, MAXYEAR


def t(label, func):
    try:
        print(label, '->', repr(func()))
    except Exception as exc:
        print(label, '!!', type(exc).__name__, exc)

"#;

fn run_cpython_with_utc_local_zone(source: &str) -> Result<Output, String> {
    let executable = crate::cpython_sources::executable();
    Command::new(&executable)
        .arg("-I")
        .arg("-c")
        .arg(source)
        .env("TZ", "UTC")
        .output()
        .map_err(|error| format!("could not execute {executable:?}: {error}"))
}

fn assert_cpython_datetime_parity(name: &str, body: &str) {
    let origin = "Lib/datetime.py public behavior (CPython 3.14.6 oracle, TZ=UTC)";
    let source = format!("{DATETIME_DIFF_PRELUDE}{body}");
    let cpython_output = run_cpython_with_utc_local_zone(&source).unwrap_or_else(|message| {
        panic!("failed to run CPython for {origin}::{name}\nsource:\n{source}\n\n{message}")
    });
    assert!(
        cpython_output.status.success(),
        "expected CPython to accept {origin}::{name}\nsource:\n{source}\n\nstderr:\n{}",
        String::from_utf8_lossy(&cpython_output.stderr)
    );
    let cpython_stdout = String::from_utf8(cpython_output.stdout)
        .unwrap_or_else(|error| panic!("CPython emitted non-UTF-8 output: {error}"));
    let cpython_lines: Vec<String> = cpython_stdout.lines().map(str::to_string).collect();
    assert!(
        cpython_lines.len() > 1,
        "datetime diff {name} must produce output to compare"
    );
    assert_eq!(
        run_minipython_source(&source),
        Ok(cpython_lines),
        "MiniPython output differs from CPython for {origin}::{name}\nsource:\n{source}"
    );
}


/// The module surface: __all__, constants, classes, MROs, class constants, IsoCalendarDate, struct_time, read-only attributes, no instance __dict__, and the final timezone.
