/// Constructor and method argument binding: ranges, C-int conversion and overflow, keyword errors with suggestions, pickle-state constructors, and replace().
/// Equal datetime values must hash alike: aware datetimes and times by
/// their UTC instant, naive values ignoring `fold`, and timedeltas and
/// timezones by their normalized fields. Only the consistency is compared;
/// the hash values themselves are MiniPython's own.
#[test]
fn cpython_datetime_hash_equality_consistency_diff() {
    assert_cpython_output_parity(&DiffCase {
        origin: "CPython datetime hash/equality consistency",
        name: "datetime-hash-equality-consistency",
        source: r#"from datetime import date, datetime, time, timedelta, timezone
utc = timezone.utc
plus2 = timezone(timedelta(hours=2), 'plus2')
minus5 = timezone(timedelta(hours=-5, minutes=-30))
groups = [
    [timedelta(days=1), timedelta(hours=24), timedelta(seconds=86400), timedelta(microseconds=86400 * 10**6)],
    [timedelta(0), timedelta(), timedelta(hours=1, minutes=-60)],
    [timedelta(days=-1, seconds=86399), timedelta(seconds=-1)],
    [date(2024, 2, 29), date.fromordinal(date(2024, 2, 29).toordinal())],
    [datetime(2024, 1, 1, 12, tzinfo=utc), datetime(2024, 1, 1, 14, tzinfo=plus2), datetime(2024, 1, 1, 6, 30, tzinfo=minus5)],
    [datetime(2021, 11, 7, 1, 30), datetime(2021, 11, 7, 1, 30, fold=1)],
    [datetime(2000, 1, 1, tzinfo=plus2), datetime(2000, 1, 1, tzinfo=plus2, fold=1), datetime(1999, 12, 31, 22, tzinfo=utc)],
    [time(12, 0, tzinfo=utc), time(14, 0, tzinfo=plus2), time(6, 30, tzinfo=minus5)],
    [time(1, 2, 3, 4), time(1, 2, 3, 4, fold=1)],
    [timezone(timedelta(hours=2)), timezone(timedelta(minutes=120), 'other')],
]
for index, group in enumerate(groups):
    equal = all(a == b for a in group for b in group)
    same_hash = len({hash(value) for value in group}) == 1
    table = {group[0]: index}
    print(index, equal, same_hash, all(table.get(value) == index for value in group), all(hash(v) != -1 for v in group))
distinct = [datetime(2024, 1, 1, 12), datetime(2024, 1, 1, 12, tzinfo=utc), date(2024, 1, 1), time(12), timedelta(hours=12)]
print('distinct', len(set(distinct)), [type(v).__name__ for v in distinct])"#,
    });
}

