/// The strftime cases the platform decides: the year-bearing directives of a
/// year below 1000, which glibc does not zero-pad the way macOS does, and
/// the `timetuple()` override that returns something else than a tuple,
/// which CPython rejects with a different message on Linux than on macOS.
/// They are compared apart and are a documented, Linux-scoped exclusion
/// (tests/README.md, "Platform-dependent behavior").
fn assert_cpython_strftime_platform_parity(name: &str, body: &str) {
    if cfg!(target_os = "linux") {
        use std::io::Write;
        let _ = writeln!(
            std::io::stderr(),
            "\n*** EXCLUDED platform strftime (Linux): the datetime strftime cases of a year below 1000 and the timetuple type case are not compared on Linux ***"
        );
        return;
    }
    assert_cpython_datetime_parity(name, body);
}


/// Strftime directives with C-locale output, padding flags, E/O modifiers, %f %z %:z %Z, __format__, ctime, user tzinfo names, and timetuple overrides.
#[test]
fn cpython_datetime_strftime_and_format_diff() {
    assert_cpython_datetime_parity(
        "strftime_and_format",
        r#"directives = 'aAbBcCdDeFgGhHIjklmMnprRStTuUVwWxXyYzZf%'
values = [dt(2020, 1, 5, 13, 4, 5, 123456), dt(2021, 12, 31, 0, 0, 0), dt(1000, 1, 1), dt(9999, 12, 31, 23, 59, 59, 999999), dt(2008, 12, 29, 12, 30), dt(2010, 1, 3, 11, 0, tzinfo=timezone(timedelta(hours=5, minutes=30), 'IST')), dt(2015, 6, 15, 6, 7, 8, tzinfo=timezone(timedelta(hours=-3, seconds=-5, microseconds=-6)))]
for value in values:
    print(repr(value), [value.strftime('%' + c) for c in directives])
for value in [date(2020, 1, 5), date(999, 1, 1), date(12, 1, 1), date(1, 1, 1)]:
    # The year-bearing directives of a year below 1000 are rendered by the
    # platform C library; they are compared in the platform part below.
    print(repr(value), [value.strftime('%' + c) for c in directives if value.year >= 1000 or c not in 'YGCFcx'])
for value in [time(13, 4, 5, 6), time(0, 0, tzinfo=UTC), time(23, 1, tzinfo=timezone(timedelta(hours=-1), 'm1'))]:
    print(repr(value), [value.strftime('%' + c) for c in directives])
print([dt(2020, 1, 5, 3, 4, 5).strftime('%' + flag + c) for flag in '-_0' for c in 'deHIjklmMSUVW'])
print([dt(2020, 1, 5).strftime(f) for f in ['%Ey', '%EY', '%EC', '%Ec', '%Ex', '%EX', '%Od', '%Oe', '%OH', '%OI', '%Om', '%OM', '%OS', '%Ou', '%OU', '%OV', '%Ow', '%OW', '%Oy']])
for fmt in ['', 'plain', '%', 'abc%', '%%', '%%f', '%%%f', '%Y-%m-%dT%H:%M:%S.%f%z', '%A, %B %d, %Y', '%I:%M %p', '%H:%M:%S %Z %z %:z', 'é%Y€', '100%% %Y', '%x %X', '%c']:
    t('fmt ' + repr(fmt), lambda: (values[5].strftime(fmt), values[0].strftime(fmt), date(2020, 2, 29).strftime(fmt), time(9, 5).strftime(fmt)))
t('format spec', lambda: (format(values[0], '%Y'), f'{values[0]:%d/%m/%Y %H:%M}', '{:%B}'.format(date(2020, 3, 1)), f'{time(1, 2):%H%M}', format(values[0], '')))
t('strftime errors', lambda: values[0].strftime(1))
t('strftime none', lambda: values[0].strftime())
t('format error', lambda: values[0].__format__(1))
t('ctime', lambda: [v.ctime() for v in values] + [date(2020, 1, 5).ctime()])
class TZ(tzinfo):
    def utcoffset(self, dt):
        return timedelta(hours=2)
    def tzname(self, dt):
        return 'TWO%Y'
    def dst(self, dt):
        return timedelta(0)
t('tzname with percent', lambda: (dt(2020, 1, 1, tzinfo=TZ()).strftime('%Z|%z'), time(1, tzinfo=TZ()).strftime('%Z')))
class Str(str):
    def replace(self, *args):
        return None
class BadName(TZ):
    def tzname(self, dt):
        return Str('name')
t('bad tzname replace', lambda: dt(2020, 1, 1, tzinfo=BadName()).strftime('%Z'))
class NoneTZ(tzinfo):
    def utcoffset(self, dt):
        return None
    def tzname(self, dt):
        return None
    def dst(self, dt):
        return None
t('none tz', lambda: (dt(2020, 1, 1, tzinfo=NoneTZ()).strftime('[%z|%Z|%:z]'), time(1, tzinfo=NoneTZ()).strftime('[%z|%Z]')))
class D(date):
    def timetuple(self):
        return (2001, 2, 3, 4, 5, 6, 0, 34, 0)
t('subclass timetuple', lambda: D(2020, 1, 1).strftime('%Y-%m-%d %H:%M:%S %a %j'))
class D2(date):
    def timetuple(self):
        return (2001, 13, 3, 4, 5, 6, 0, 34, 0)
t('bad timetuple', lambda: D2(2020, 1, 1).strftime('%Y'))
"#,
    );
    assert_cpython_strftime_platform_parity(
        "strftime_and_format_platform_cases",
        r#"directives = 'aAbBcCdDeFgGhHIjklmMnprRStTuUVwWxXyYzZf%'
for value in [date(999, 1, 1), date(12, 1, 1), date(1, 1, 1)]:
    print(repr(value), [value.strftime('%' + c) for c in directives if c in 'YGCFcx'])
class D3(date):
    def timetuple(self):
        return 5
t('timetuple type', lambda: D3(2020, 1, 1).strftime('%Y'))
"#,
    );
}


/// The oracle corpora's platform-scoped strftime exclusion: the datetime
/// corpus generator marks only the scenarios that really call an affected
/// format, and the corpus runner skips the marked scenarios on Linux and
/// counts every one of them as a documented exclusion, never as a pass.
/// These are the regression tests of tests/oracles/test_platform_exclusions.py.
#[test]
fn cpython_datetime_strftime_platform_exclusion_diff() {
    let executable = crate::cpython_sources::executable();
    let script = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("oracles")
        .join("test_platform_exclusions.py");
    let output = Command::new(&executable)
        .arg("-I")
        .arg(&script)
        .output()
        .unwrap_or_else(|error| panic!("could not execute {executable:?}: {error}"));
    assert!(
        output.status.success(),
        "the oracle runner's platform-exclusion regression tests failed\nstdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
}


