#[test]
fn cpython_argparse_type_conversion_diff() {
    assert_cpython_argparse_parity(
        "type-conversion",
        r#"
calls = []

def positive(text):
    calls.append(text)
    value = int(text)
    if value <= 0:
        raise argparse.ArgumentTypeError('%r is not a positive integer' % text)
    return value

def raises_type_error(text):
    raise TypeError('nope')

def raises_key_error(text):
    raise KeyError(text)

class Weird:
    def __call__(self, text):
        raise ValueError('bad')
    def __repr__(self):
        return 'Weird()'

t = argparse.ArgumentParser(prog='types')
t.add_argument('--pos', type=positive)
t.add_argument('--te', type=raises_type_error)
t.add_argument('--w', type=Weird())
t.add_argument('--f', type=float)
t.add_argument('--c', type=complex)
t.add_argument('--l', type=lambda s: s.split(','))
t.add_argument('--d', type=int, default='7')
t.add_argument('--e', type=int, default=7)
t.add_argument('--s', type=str.upper, default='low')
t.add_argument('--many', type=int, nargs='+')
t.add_argument('--opt', type=int, nargs='?', const='11', default='12')
t.add_argument('pos_default', type=int, nargs='?', default='5')
for args in [['--pos', '-3'], ['--pos', 'abc'], ['--pos', '4'], ['--te', 'x'], ['--w', 'x'],
             ['--f', 'nan?'], ['--f', '1e3'], ['--c', '1+2j', '--l', 'a,b'], [], ['--d', '1'],
             ['--many', '1', 'x'], ['--opt'], ['--opt', '3'], ['9'], ['nine'], ['--s', 'up']]:
    run(t, args)
print(calls)
k = argparse.ArgumentParser(prog='keyerr')
k.add_argument('--k', type=raises_key_error)
run(k, ['--k', 'z'])
nc = argparse.ArgumentParser(prog='notcallable')
attempt('not callable', lambda: nc.add_argument('--x', type='int'))
attempt('filetype class', lambda: nc.add_argument('--y', type=argparse.FileType))
nc.register('type', 'hex', lambda s: int(s, 16))
nc.add_argument('--h', type='hex')
run(nc, ['--h', 'ff'])
run(nc, ['--h', 'zz'])
"#,
    );
}

