#[test]
fn cpython_argparse_namespace_semantics_diff() {
    assert_cpython_argparse_parity(
        "namespace-semantics",
        r#"
ns = argparse.Namespace(a=1, b='x')
print(ns, repr(ns), 'a' in ns, 'z' in ns, vars(ns))
print(ns == argparse.Namespace(a=1, b='x'), ns == argparse.Namespace(a=1), ns != argparse.Namespace(a=2, b='x'))
print(ns == 1, ns != 'x', argparse.Namespace() == argparse.Namespace())
weird = argparse.Namespace(**{'not valid': 1, 'ok': 2, 'class': 3, '9x': 4})
print(weird)
print(argparse.Namespace())
attempt('hash', lambda: hash(ns))
ns.c = [1]
del ns.a
print(ns, sorted(vars(ns)), list(vars(ns)))
setattr(ns, 'with-dash', 5)
print(ns, getattr(ns, 'with-dash'))
class Sub(argparse.Namespace):
    def total(self):
        return len(vars(self))
s = Sub(x=1, y=2)
print(s, s.total(), s == argparse.Namespace(x=1, y=2), isinstance(s, argparse.Namespace))
p = argparse.ArgumentParser(prog='ns')
p.add_argument('--z', default=0)
p.add_argument('w')
r = p.parse_args(['q'], namespace=Sub())
print(type(r).__name__, r, r.total())
class Plain:
    pass
target = Plain()
target.z = 'kept'
print(p.parse_args(['q'], namespace=target) is target, sorted(vars(target).items()))
"#,
    );
}

