#[test]
fn cpython_argparse_help_formatter_classes_diff() {
    assert_cpython_argparse_parity(
        "help-formatter-classes",
        r#"
desc = """This is a long description that should be wrapped by the default
formatter because it is much longer than the available width of the terminal, which
is eighty columns minus two.

A second paragraph   with   irregular    spacing.
"""
class Combined(argparse.ArgumentDefaultsHelpFormatter, argparse.RawDescriptionHelpFormatter):
    pass
for fmt in [argparse.HelpFormatter, argparse.RawDescriptionHelpFormatter, argparse.RawTextHelpFormatter,
            argparse.ArgumentDefaultsHelpFormatter, argparse.MetavarTypeHelpFormatter, Combined]:
    p = argparse.ArgumentParser(prog='fmt-demo', description=desc, epilog='Epilog\n  with indent', formatter_class=fmt)
    p.add_argument('input', type=str, help='the input file to process; it can be a path or a dash for standard input')
    p.add_argument('--output', '-o', type=str, default='out.txt', help='where to write\nthe results')
    p.add_argument('--level', type=int, default=3, choices=[1, 2, 3], help='compression level')
    p.add_argument('--ratio', type=float, help='a ratio')
    p.add_argument('--quiet', action='store_true', help=argparse.SUPPRESS)
    p.add_argument('--tags', nargs='*', type=str, default=[], help='tags (%(type)s) default=%(default)r')
    p.add_argument('--pair', nargs=2, type=str, metavar=('KEY', 'VALUE'), help='a pair')
    p.add_argument('--opt', nargs='?', const='C', type=str, help='optional value, const=%(const)s')
    p.add_argument('--req', type=int, required=True, help='required option')
    p.add_argument('--nohelp', type=int, default=4)
    p.add_argument('maybe', nargs='?', type=str, default='m', help='optional positional')
    g = p.add_argument_group('advanced', 'Advanced options for experts only.')
    g.add_argument('--threads', type=int, default=4, help='number of worker threads to use when processing very large inputs that would otherwise take forever')
    print(fmt.__name__)
    print(p.format_help())
"#,
    );
}

