#[test]
fn cpython_argparse_custom_actions_diff() {
    assert_cpython_argparse_parity(
        "custom-actions",
        r#"
class Upper(argparse.Action):
    def __init__(self, option_strings, dest, nargs=None, **kwargs):
        if nargs is not None:
            raise ValueError('nargs not allowed')
        super().__init__(option_strings, dest, **kwargs)

    def __call__(self, parser, namespace, values, option_string=None):
        print('Upper called', repr(option_string), repr(values))
        setattr(namespace, self.dest, values.upper())

class KeyValue(argparse.Action):
    def __call__(self, parser, namespace, values, option_string=None):
        d = getattr(namespace, self.dest) or {}
        for item in values:
            if '=' not in item:
                raise argparse.ArgumentError(self, 'expected KEY=VALUE, got %r' % item)
            k, v = item.split('=', 1)
            d[k] = v
        setattr(namespace, self.dest, d)

class Flag(argparse.Action):
    def __init__(self, option_strings, dest, **kwargs):
        super().__init__(option_strings, dest, nargs=0, **kwargs)
    def __call__(self, parser, namespace, values, option_string=None):
        setattr(namespace, self.dest, option_string)
    def format_usage(self):
        return '<' + self.option_strings[0] + '>'

class Extending(argparse._AppendAction):
    def __call__(self, parser, namespace, values, option_string=None):
        super().__call__(parser, namespace, values.upper(), option_string)

p = argparse.ArgumentParser(prog='custom')
p.add_argument('--name', action=Upper, default='none')
p.add_argument('--set', nargs='+', action=KeyValue, metavar='KEY=VALUE')
p.add_argument('--flag', '-F', action=Flag, help='custom flag')
p.add_argument('--app', action=Extending)
p.add_argument('pos', action=Upper)
for args in [['--name', 'bob', 'xyz'], ['xyz', '--set', 'a=1', 'b=2'], ['xyz', '--set', 'oops'], ['-h'],
             ['-F', 'q'], ['--app', 'a', '--app', 'b', 'z']]:
    run(p, args)
attempt('bad nargs', lambda: p.add_argument('--z', action=Upper, nargs=2))
a = p._option_string_actions['--name']
print(type(a).__name__, isinstance(a, argparse.Action), a.dest, a.default, a.container is p._optionals)
print(repr(p._option_string_actions['--flag']))
"#,
    );
}

