#[test]
fn cpython_argparse_formatter_subclass_overrides_diff() {
    assert_cpython_argparse_parity(
        "formatter-subclass-overrides",
        r#"
class SmartFormatter(argparse.HelpFormatter):
    def _split_lines(self, text, width):
        if text.startswith('R|'):
            return text[2:].splitlines()
        return super()._split_lines(text, width)

class InvocationFormatter(argparse.HelpFormatter):
    def _format_action_invocation(self, action):
        if not action.option_strings or action.nargs == 0:
            return super()._format_action_invocation(action)
        default = self._get_default_metavar_for_optional(action)
        args_string = self._format_args(action, default)
        return ', '.join(action.option_strings) + ' ' + args_string

class HelpStringFormatter(argparse.HelpFormatter):
    def _get_help_string(self, action):
        return (action.help or '') + ' [custom]'
    def _fill_text(self, text, width, indent):
        return indent + text.upper()

class MetavarFormatter(argparse.HelpFormatter):
    def _get_default_metavar_for_optional(self, action):
        return '<' + action.dest + '>'
    def _metavar_formatter(self, action, default_metavar):
        base = super()._metavar_formatter(action, default_metavar)
        return lambda size: tuple(str(item).lower() for item in base(size))

class Sections(argparse.HelpFormatter):
    def start_section(self, heading):
        super().start_section(heading.upper() if heading else heading)
    def add_usage(self, usage, actions, groups, prefix=None):
        super().add_usage(usage, actions, groups, 'Usage -> ')

for fmt in [SmartFormatter, InvocationFormatter, HelpStringFormatter, MetavarFormatter, Sections,
            lambda prog: argparse.HelpFormatter(prog, max_help_position=40, width=60),
            lambda prog: argparse.RawTextHelpFormatter(prog, indent_increment=4, max_help_position=10, width=50)]:
    p = argparse.ArgumentParser(prog='fmt', description='Desc of %(prog)s\n  indented line', formatter_class=fmt)
    p.add_argument('-i', '--input', metavar='FILE', default='-', help='R|first line\nsecond line\n  indented third')
    p.add_argument('-n', '--count', type=int, default=5, help='repeat %(default)r times')
    p.add_argument('--mode', choices=['a', 'b'], default='a', help='mode')
    p.add_argument('pos', nargs='?', default='dflt', help='positional with default %(default)s')
    print(p.format_help())
f = argparse.HelpFormatter('direct-prog')
print(f._prog, f._width, f._max_help_position, f._indent_increment, f._current_indent, f._level)
f.add_usage(None, [], [], 'go: ')
f.start_section('section')
f.add_text('some text that gets filled')
f.end_section()
print(repr(f.format_help()))
print(f._split_lines('  many   words   to   split  ', 10), repr(f._fill_text('a  b   c', 5, '> ')))
print(argparse.RawDescriptionHelpFormatter('x')._fill_text('a\n b\n', 5, '..'))
print(argparse.RawTextHelpFormatter('x')._split_lines('a\n b\n', 5))
"#,
    );
}

