#[test]
fn cpython_argparse_skill_shaped_scripts_diff() {
    assert_cpython_argparse_parity(
        "skill-shaped-scripts",
        r#"
import json

def build_parser():
    parser = argparse.ArgumentParser(
        prog='summarize.py',
        description='Summarize JSON records passed on the command line and print totals per group.',
        epilog='Example: summarize.py --group-by kind \'[{"kind": "a", "n": 1}]\'',
    )
    parser.add_argument('records', help='JSON array of objects')
    parser.add_argument('--group-by', '-g', default='kind', help='field to group by (default: %(default)s)')
    parser.add_argument('--field', '-f', default='n', help='numeric field to sum')
    parser.add_argument('--top', type=int, default=0, help='only show the N largest groups')
    parser.add_argument('--format', choices=['text', 'json'], default='text', help='output format')
    parser.add_argument('--verbose', '-v', action='store_true', help='print diagnostics to stderr')
    return parser

def main(argv):
    parser = build_parser()
    args = parser.parse_args(argv)
    try:
        records = json.loads(args.records)
    except ValueError as exc:
        parser.error(f'records is not valid JSON: {exc}')
    totals = {}
    for record in records:
        key = record.get(args.group_by, '?')
        totals[key] = totals.get(key, 0) + record.get(args.field, 0)
    items = sorted(totals.items(), key=lambda item: (-item[1], item[0]))
    if args.top:
        items = items[: args.top]
    if args.verbose:
        print(f'{len(records)} records, {len(totals)} groups', file=sys.stderr)
    if args.format == 'json':
        print(json.dumps(dict(items), indent=2))
    else:
        for key, total in items:
            print(f'{key}\t{total}')
    return 0

class Script:
    def parse_args(self, argv):
        return main(argv)

records = json.dumps([{'kind': 'a', 'n': 2}, {'kind': 'b', 'n': 5}, {'kind': 'a', 'n': 4}, {'n': 1}])
for argv in [['--help'], [], [records], [records, '-v', '--format', 'json'], [records, '--top', '1', '-g', 'kind'],
             ['not json'], [records, '--top', 'x'], [records, '--format', 'xml', '--bogus']]:
    run(Script(), argv)

def tool_parser():
    parser = argparse.ArgumentParser(prog='kv-tool', description='Manage a small JSON key-value store kept in memory.')
    parser.add_argument('--store', default='{}', help='initial store as JSON')
    commands = parser.add_subparsers(dest='command', required=True, metavar='COMMAND')
    get = commands.add_parser('get', help='read a key')
    get.add_argument('key')
    put = commands.add_parser('put', help='write a key')
    put.add_argument('key')
    put.add_argument('value', type=json.loads, help='JSON value')
    lst = commands.add_parser('list', aliases=['ls'], help='list keys')
    lst.add_argument('--prefix', default='')
    return parser

class Tool:
    def parse_args(self, argv):
        args = tool_parser().parse_args(argv)
        store = json.loads(args.store)
        if args.command == 'get':
            if args.key not in store:
                print(f'missing key {args.key!r}', file=sys.stderr)
                sys.exit(1)
            print(json.dumps(store[args.key]))
        elif args.command == 'put':
            store[args.key] = args.value
            print(json.dumps(store, sort_keys=True))
        else:
            print('\n'.join(sorted(k for k in store if k.startswith(args.prefix))))
        return args

for argv in [['-h'], ['put', '-h'], [], ['get'], ['--store', '{"a": 1}', 'get', 'a'], ['--store', '{"a": 1}', 'get', 'b'],
             ['put', 'k', '[1, 2]'], ['put', 'k', '{bad'], ['ls', '--prefix', 'a'], ['remove', 'x']]:
    run(Tool(), argv)
"#,
    );
}

// Every builtin that consumes an iterable is fed a generator expression, a
// user class whose __iter__ returns an iterator, a user class whose __iter__
// is a generator, and a generator that raises midway. The containers that
// CPython fills item by item keep what was produced before the exception;
// slice assignment materializes first and stays unchanged; short-circuiting
// predicates stop before the exception.
#[test]
fn cpython_iterable_consumers_accept_any_iterable_diff() {
    assert_cpython_output_parity_source(
        "Objects/listobject.c list_extend and abstract iteration consumers",
        "iterable-consumers-any-iterable",
        r#"import array, collections, itertools

class Iterable:
    def __init__(self, values):
        self.values = values
    def __iter__(self):
        return iter(self.values)

class IterableGen:
    def __init__(self, values):
        self.values = values
    def __iter__(self):
        for value in self.values:
            yield value

def boom(values):
    for value in values:
        yield value
    raise ValueError('boom midway')

def run(label, values, fn, state=None):
    for kind, make in [('genexpr', lambda: (v for v in values)), ('iterclass', lambda: Iterable(values)),
                       ('itergen', lambda: IterableGen(values)), ('raising', lambda: boom(values))]:
        try:
            result = fn(make())
        except Exception as error:
            result = f'{type(error).__name__}: {error}'
        extra = '' if state is None else f' state={state()!r}'
        print(f'{label}/{kind}: {result!r}{extra}')

box = {}
def fresh(key, value):
    box[key] = value
    return value

def list_iadd(it):
    l = fresh('l', [0])
    l += it
    return l

def list_slice(it):
    l = fresh('l', [0, 9])
    l[1:] = it
    return l

def set_op(name):
    def op(it):
        s = fresh('s', {0, 1})
        result = getattr(s, name)(it)
        return (sorted(result) if isinstance(result, (set, frozenset)) else result, sorted(s))
    return op

run('list.extend', [1, 2], lambda it: (fresh('l', [0]).extend(it), box['l'])[1], lambda: box['l'])
run('list+=', [1, 2], list_iadd, lambda: box['l'])
run('list[1:]=', [1, 2], list_slice, lambda: box['l'])
run('[*it]', [1, 2], lambda it: [0, *it])
run('(*it,)', [1, 2], lambda it: (0, *it))
run('in', [1, 2], lambda it: 2 in it)
run('not in', [1, 2], lambda it: 3 not in it)
run('list()', [1, 2], list)
run('tuple()', [1, 2], tuple)
run('dict()', [('a', 1), ('b', 2)], dict)
run('dict.update', [('a', 1), ('b', 2)], lambda it: fresh('d', {'z': 0}).update(it), lambda: box['d'])
run('set.update', [1, 2], lambda it: fresh('s', {0}).update(it), lambda: sorted(box['s']))
for name in ['union', 'intersection', 'difference', 'symmetric_difference', 'intersection_update',
             'difference_update', 'symmetric_difference_update', 'issubset', 'issuperset', 'isdisjoint']:
    run('set.' + name, [1, 2], set_op(name))
run('frozenset.isdisjoint', [1, 2], lambda it: frozenset({0, 1}).isdisjoint(it))
run('frozenset.issuperset', [1, 2], lambda it: frozenset({0, 1}).issuperset(it))
run('str.join', ['a', 'b'], '-'.join)
run('bytes.join', [b'a', b'b'], b'-'.join)
run('bytearray.extend', [65, 66], lambda it: fresh('b', bytearray(b'x')).extend(it), lambda: box['b'])
run('deque.extend', [1, 2], lambda it: fresh('q', collections.deque([0])).extend(it), lambda: list(box['q']))
run('deque.extendleft', [1, 2], lambda it: fresh('q', collections.deque([0])).extendleft(it), lambda: list(box['q']))
run('deque(maxlen)', [1, 2, 3], lambda it: list(collections.deque(it, maxlen=2)))
run('Counter.update', ['a', 'b', 'a'], lambda it: fresh('c', collections.Counter('a')).update(it), lambda: sorted(box['c'].items()))
run('Counter.subtract', ['a', 'b'], lambda it: fresh('c', collections.Counter('a')).subtract(it), lambda: sorted(box['c'].items()))
run('min/max/sum', [3, 1, 2], lambda it: (lambda v: (min(v), max(v), sum(v)))(list(it)))
run('sorted', [3, 1, 2], lambda it: sorted(it, reverse=True))
run('any', [0, 1], any)
run('all', [1, 1], all)
run('zip', [1, 2], lambda it: list(zip(it, 'ab', strict=True)))
run('enumerate', [1, 2], lambda it: list(enumerate(it, 5)))
run('map/filter', [0, 1, 2], lambda it: list(filter(None, map(abs, it))))
run('array.extend', [1, 2], lambda it: fresh('a', array.array('i', [0])).extend(it), lambda: box['a'].tolist())
run('itertools.chain', [1, 2], lambda it: list(itertools.chain(it, [9])))
run('itertools.islice', [1, 2, 3], lambda it: list(itertools.islice(it, 2)))
run('itertools.cycle', [1, 2], lambda it: list(itertools.islice(itertools.cycle(it), 5)))
run('itertools.accumulate', [1, 2, 3], lambda it: list(itertools.accumulate(it)))
run('itertools.compress', [1, 2, 3], lambda it: list(itertools.compress(it, [1, 0, 1])))
run('itertools.dropwhile', [1, 2, 3], lambda it: list(itertools.dropwhile(lambda v: v < 2, it)))
run('itertools.takewhile', [1, 2, 3], lambda it: list(itertools.takewhile(lambda v: v < 3, it)))
run('itertools.filterfalse', [0, 1], lambda it: list(itertools.filterfalse(None, it)))
run('itertools.groupby', [1, 1, 2], lambda it: [(k, list(g)) for k, g in itertools.groupby(it)])
run('itertools.starmap', [(1, 2)], lambda it: list(itertools.starmap(pow, it)))
run('itertools.tee', [1, 2], lambda it: [list(t) for t in itertools.tee(it)])
run('itertools.zip_longest', [1, 2], lambda it: list(itertools.zip_longest(it, 'a')))
run('itertools.pairwise', [1, 2, 3], lambda it: list(itertools.pairwise(it)))
run('itertools.batched', [1, 2, 3], lambda it: list(itertools.batched(it, 2)))
run('itertools.product', [1, 2], lambda it: list(itertools.product(it, 'a')))
"#,
    );
}

// json.loads raises json.JSONDecodeError, a ValueError subclass defined in
// json.decoder that carries msg, doc, pos, lineno, and colno, for every
// decoder failure; errors raised by hooks pass through unchanged.
#[test]
fn cpython_json_decode_error_type_and_attributes_diff() {
    assert_cpython_output_parity_source(
        "Lib/json/decoder.py JSONDecodeError public behavior",
        "json-decode-error",
        r#"import json

for doc in ['{', '{"a": 1,}', '[1, 2', '', 'x', '{"a" 1}', '﻿[]', '[1]x', '"\\x"', '{"a":\n  nul}', b'{"a": }']:
    try:
        json.loads(doc)
    except json.JSONDecodeError as error:
        print(type(error).__name__, type(error).__module__, repr(error.msg), error.pos, error.lineno, error.colno)
        print(repr(error.doc), error.args, str(error), repr(error))
        print(isinstance(error, ValueError), isinstance(error, json.JSONDecodeError))
cls = json.JSONDecodeError
print(cls.__name__, cls.__module__, cls.__qualname__, issubclass(cls, ValueError), [c.__name__ for c in cls.__mro__])
try:
    json.loads('[')
except ValueError as error:
    print('caught as ValueError', type(error).__name__)

def hook(pairs):
    raise ValueError('hook: line 1 column 1 (char 0)')
try:
    json.loads('{"a": 1}', object_hook=hook)
except Exception as error:
    print(type(error).__name__, error)
"#,
    );
}

// Iterable consumers report CPython's errors for non-iterables, keep the
// identity and context of exceptions raised by __iter__ or by the iterator,
// and copy a list or deque before extending it with itself.
#[test]
fn cpython_iterable_consumer_errors_and_exception_identity_diff() {
    assert_cpython_output_parity_source(
        "Objects/listobject.c list_extend error paths",
        "iterable-consumer-errors",
        r#"import collections, itertools

for source in ['[].extend(5)', 'x = []; x += 5', '[*5]', '(*5,)', 'x = [1]; x[1:] = 5', 'x = [1]; x[::2] = 5',
               '2 in 5', 'set().update(5)', '{}.update(5)', 'collections.deque().extend(5)',
               'list(itertools.chain([1], 5))']:
    try:
        exec(source)
    except TypeError as error:
        print(source, '->', error)

class Boom(Exception):
    pass

class Bad:
    def __iter__(self):
        raise Boom('iter')

def raising():
    yield ('k', 1)
    raise Boom('next')

for label, fn in [('extend', lambda it: [].extend(it)), ('unpack', lambda it: [*it]), ('in', lambda it: 3 in it),
                  ('slice', lambda it: [1].__setitem__(slice(0, 1), it)), ('set.update', lambda it: set().update(it)),
                  ('dict.update', lambda it: {}.update(it)), ('deque', lambda it: collections.deque().extend(it)),
                  ('islice', lambda it: list(itertools.islice(it, 5)))]:
    for source in (Bad, raising):
        try:
            fn(source())
        except Boom as error:
            print(label, source.__name__, type(error).__name__, error, error.__context__)

try:
    raise KeyError('outer')
except KeyError:
    try:
        [].extend(raising())
    except Boom as error:
        print('context', repr(error.__context__))

l = [1, 2]
l.extend(l)
l += l
l[1:3] = l
print(l)
d = collections.deque([1, 2], maxlen=3)
d.extend(d)
d.extendleft(d)
print(d)

class Eq:
    def __eq__(self, other):
        return other == 3
print(Eq() in (x for x in [1, 2, 3]))
g = (x for x in [1, 2, 3, 4])
print(2 in g, list(g))
"#,
    );
}

// The recursion limit counts Python frames, the module frame included:
// functions, methods, lambdas, keyword calls, `finally` unwinding, and
// `exec` all stop at the same depth with a catchable RecursionError.
#[test]
fn cpython_recursion_limit_counts_python_frames_diff() {
    assert_cpython_output_parity_source(
        "Python/ceval.c _Py_CheckRecursiveCallPy and sys.getrecursionlimit",
        "recursion-limit-python-frames",
        r#"import sys

def depth():
    count = 0
    frame = sys._getframe()
    while frame is not None:
        count += 1
        frame = frame.f_back
    return count

print('default', sys.getrecursionlimit(), type(sys.getrecursionlimit()).__name__)

deepest = [0]
def dive(n):
    deepest[0] = n
    if n == 3:
        deepest.append(depth())
    dive(n + 1)

for limit in [1000, 50, 7]:
    sys.setrecursionlimit(limit)
    del deepest[:]
    deepest.append(0)
    try:
        dive(1)
    except RecursionError as error:
        print('limit', limit, 'deepest', deepest, type(error).__name__, str(error),
              error.args, isinstance(error, RuntimeError))
sys.setrecursionlimit(1000)

def countdown(n):
    return 0 if n == 0 else 1 + countdown(n - 1)
print('within limit', countdown(990))
try:
    countdown(1000)
except RecursionError as error:
    print('over limit', error)

class Walker:
    def visit(self, n):
        return n if n == 0 else self.visit(n - 1) + 1
    @staticmethod
    def static(n):
        return n if n == 0 else Walker.static(n - 1) + 1
    @classmethod
    def klass(cls, n):
        return n if n == 0 else cls.klass(n - 1) + 1
print('methods', Walker().visit(900), Walker.static(900), Walker.klass(900))

even = lambda n: True if n == 0 else odd(n - 1)
odd = lambda n: False if n == 0 else even(n - 1)
print('mutual', even(950), odd(951))
try:
    even(5000)
except RecursionError as error:
    print('mutual overflow', error)

def keyword_recursion(n, *, step=1, **extra):
    return n if n <= 0 else keyword_recursion(n - step, step=step, **extra)
print('keywords', keyword_recursion(800, step=1, tag='x'))
try:
    keyword_recursion(10**6, tag='x')
except RecursionError as error:
    print('keyword overflow', error)

def through_finally(n, log):
    try:
        return through_finally(n + 1, log)
    finally:
        if n % 250 == 0:
            log.append(n)
log = []
try:
    through_finally(0, log)
except RecursionError as error:
    print('finally', error, log)

def exec_recursion(n):
    if n:
        exec('exec_recursion(n - 1)', {'exec_recursion': exec_recursion, 'n': n})
try:
    exec_recursion(10**6)
except RecursionError as error:
    print('exec', error)
print('after', countdown(500), sys.getrecursionlimit())
"#,
    );
}

// sys.setrecursionlimit argument conversion, range checks, the
// "limit is too low" RecursionError at the current depth, and the
// argument-count errors of both functions.
#[test]
fn cpython_setrecursionlimit_validation_diff() {
    assert_cpython_output_parity_source(
        "Python/sysmodule.c sys_setrecursionlimit_impl",
        "setrecursionlimit-validation",
        r#"import sys

def as_index(number):
    # an object accepted only through the __index__ protocol
    return type('AsIndex', (), {'__index__': lambda self: number})()

for label, value in [
    ('zero', 0), ('negative', -1), ('float', 1.5), ('str', 'x'), ('none', None),
    ('big', 2**40), ('negative-big', -2**40), ('int-max+1', 2**31),
    ('index', as_index(77)), ('index-big', as_index(2**40)), ('true', True), ('false', False),
]:
    try:
        result = sys.setrecursionlimit(value)
        print(label, 'ok', result, sys.getrecursionlimit())
    except BaseException as error:
        print(label, type(error).__name__, error)
    sys.setrecursionlimit(1000)

sys.setrecursionlimit(2**31 - 1)
print('int-max', sys.getrecursionlimit())
sys.setrecursionlimit(1000)

for label, call in [
    ('set-none', lambda: sys.setrecursionlimit()),
    ('set-two', lambda: sys.setrecursionlimit(1, 2)),
    ('set-keyword', lambda: sys.setrecursionlimit(limit=5)),
    ('set-keyword-and-arg', lambda: sys.setrecursionlimit(5, x=1)),
    ('get-arg', lambda: sys.getrecursionlimit(1)),
    ('get-two', lambda: sys.getrecursionlimit(1, 2)),
    ('get-keyword', lambda: sys.getrecursionlimit(x=1)),
]:
    try:
        call()
    except TypeError as error:
        print(label, error)

def at_depth(n, callback):
    return callback() if n == 0 else at_depth(n - 1, callback)

def frames():
    count = 0
    frame = sys._getframe(1)
    while frame is not None:
        count += 1
        frame = frame.f_back
    return count

def lower_too_far():
    here = frames()
    for limit in [here - 5, here, here + 1]:
        try:
            sys.setrecursionlimit(limit)
            print('set', limit - here, 'ok', sys.getrecursionlimit() - here)
        except RecursionError as error:
            print('set', limit - here, type(error).__name__,
                  str(error).replace(str(limit), 'LIMIT').replace(str(here), 'DEPTH'))
        sys.setrecursionlimit(1000)
at_depth(20, lower_too_far)
print('final', sys.getrecursionlimit())
"#,
    );
}

// CPython 3.14 grants no extra frames to code handling a RecursionError:
// a call from the handler at the limit fails again, catch-and-recurse
// stays bounded, and generators, class bodies, and exception chains
// report the error in the frame that tried to go deeper.
#[test]
fn cpython_recursion_error_handlers_get_no_headroom_diff() {
    assert_cpython_output_parity_source(
        "Python/ceval.c recursion_headroom",
        "recursion-error-handlers",
        r#"import sys

hits = []
def g(n):
    return n

def f(n):
    try:
        return f(n + 1)
    except RecursionError:
        try:
            hits.append((n, g(n)))
        except RecursionError as inner:
            hits.append((n, 'handler call', str(inner)))
        return n
print('deepest', f(0), hits)

sys.setrecursionlimit(40)
count = [0]
def retry(n):
    count[0] += 1
    if count[0] > 3000:
        return
    try:
        retry(n + 1)
    except RecursionError:
        retry(n + 1)
retry(0)
print('catch-and-recurse', count[0])
sys.setrecursionlimit(1000)

def loop_forever():
    return loop_forever()
for attempt in range(3):
    try:
        loop_forever()
    except RecursionError as error:
        print('attempt', attempt, error)

def raise_from(n):
    try:
        return raise_from(n + 1)
    except RecursionError as error:
        if n == 0:
            raise ValueError('top') from error
        raise
try:
    raise_from(0)
except ValueError as error:
    cause = error.__cause__
    print('chained', type(cause).__name__, cause, error.__context__ is cause)

def generator_recursion(n):
    yield n
    yield from generator_recursion(n + 1)
sys.setrecursionlimit(200)
values = []
try:
    for value in generator_recursion(0):
        values.append(value)
except RecursionError as error:
    print('generator', error, len(values) > 100, values[:3])
sys.setrecursionlimit(1000)

class Meta(type):
    pass
def class_bodies(n):
    class Inner(metaclass=Meta):
        value = class_bodies(n + 1) if n < 10**6 else 0
    return Inner
try:
    class_bodies(0)
except RecursionError as error:
    print('class bodies', error)

def chain(n):
    if n == 0:
        raise ValueError(0)
    try:
        chain(n - 1)
    except ValueError:
        raise ValueError(n)
try:
    chain(150)
except ValueError as error:
    links = 0
    while error is not None:
        links += 1
        error = error.__context__
    print('chained contexts', links)
"#,
    );
}

// Unbounded recursion through special methods reaches the Python
// recursion limit; the limit is lowered so the native stack guard never
// trips first even in debug builds.
#[test]
fn cpython_dunder_recursion_raises_recursion_error_diff() {
    assert_cpython_output_parity_source(
        "Objects/typeobject.c slot recursion",
        "dunder-recursion",
        r#"import sys

sys.setrecursionlimit(120)

class Repr:
    def __repr__(self):
        return repr(self)
class Str:
    def __str__(self):
        return str(self)
class Format:
    def __format__(self, spec):
        return format(self, spec)
class Eq:
    def __eq__(self, other):
        return self == other
class Lt:
    def __lt__(self, other):
        return self < other
class Hash:
    def __hash__(self):
        return hash(self)
class GetAttr:
    def __getattr__(self, name):
        return getattr(self, name)
class Prop:
    @property
    def value(self):
        return self.value
class Init:
    def __init__(self):
        Init()
class Add:
    def __add__(self, other):
        return self + other
class Iter:
    def __iter__(self):
        return iter(self)
class Len:
    def __len__(self):
        return len(self)
class Bool:
    def __bool__(self):
        return bool(self)
class GetItem:
    def __getitem__(self, key):
        return self[key]
class Call:
    def __call__(self):
        return self()
class Contains:
    def __contains__(self, item):
        return item in self
class SetAttr:
    def __setattr__(self, name, value):
        setattr(self, name, value)

cases = [
    ('repr', lambda: repr(Repr())),
    ('str', lambda: str(Str())),
    ('fstring', lambda: f'{Str()!s}'),
    ('format', lambda: format(Format(), '')),
    ('eq', lambda: Eq() == Eq()),
    ('lt', lambda: Lt() < Lt()),
    ('sorted', lambda: sorted([Lt(), Lt()])),
    ('hash', lambda: hash(Hash())),
    ('getattr', lambda: GetAttr().missing),
    ('property', lambda: Prop().value),
    ('init', lambda: Init()),
    ('add', lambda: Add() + Add()),
    ('iter', lambda: iter(Iter())),
    ('len', lambda: len(Len())),
    ('bool', lambda: bool(Bool())),
    ('getitem', lambda: GetItem()[0]),
    ('call', lambda: Call()()),
    ('contains', lambda: 1 in Contains()),
    ('setattr', lambda: setattr(SetAttr(), 'x', 1)),
]
for label, call in cases:
    try:
        call()
        print(label, 'no error')
    except RecursionError as error:
        print(label, type(error).__name__, error)
print('limit', sys.getrecursionlimit())
"#,
    );
}

// Nested containers within native limits repr, compare, hash, sort,
// round-trip through JSON (beyond MiniPython's former 250-level cap),
// and copy; copy.deepcopy spends CPython's Python frames per level, so
// it fails between 450 and 600 levels in both; cycles print [...].
#[test]
fn cpython_nested_containers_within_limits_diff() {
    assert_cpython_output_parity_source(
        "Objects/listobject.c list_repr and Lib/copy.py deepcopy",
        "nested-containers-within-limits",
        r#"import copy, json, sys

def nested_list(n):
    value = []
    for _ in range(n):
        value = [value]
    return value

def nested_dict(n):
    value = {}
    for _ in range(n):
        value = {'k': value}
    return value

def nested_tuple(n):
    value = ()
    for _ in range(n):
        value = (value,)
    return value

for n in [300, 480]:
    a, b = nested_list(n), nested_list(n)
    d, e = nested_dict(n), nested_dict(n)
    t, u = nested_tuple(n), nested_tuple(n)
    print(n, 'repr', len(repr(a)), repr(a)[:5], len(str(d)), len(repr(t)), len(f'{a}'), len(format(t)))
    print(n, 'compare', a == b, a != b, a < b, a <= b, d == e, t == u, t < u, a in [b], t in {u: 1})
    print(n, 'hash', hash(t) == hash(u))
    print(n, 'sorted', sorted([b, a]) == [a, b], max([t, u]) == t)
    print(n, 'json', json.dumps(a) == '[' * (n + 1) + ']' * (n + 1), json.loads(json.dumps(d)) == d,
          json.loads(json.dumps(a, indent=1)) == a)
    print(n, 'copy', copy.copy(a) == a, copy.deepcopy(a) == a, copy.deepcopy(d) == d, copy.deepcopy(t) == t)

for n in [450, 600]:
    for label, value in [('list', nested_list(n)), ('dict', nested_dict(n)), ('tuple', nested_tuple(n))]:
        try:
            copy.deepcopy(value)
            print('deepcopy', label, n, 'ok')
        except RecursionError as error:
            print('deepcopy', label, n, type(error).__name__, error)

class Node:
    def __init__(self, nxt):
        self.nxt = nxt
for n in [200, 300]:
    head = None
    for _ in range(n):
        head = Node(head)
    try:
        copy.deepcopy(head)
        print('deepcopy objects', n, 'ok')
    except RecursionError as error:
        print('deepcopy objects', n, error)

cycle = [1]
cycle.append(cycle)
mapping = {'a': 1}
mapping['self'] = mapping
mixed = [mapping, (cycle,)]
print(repr(cycle), str(cycle), f'{cycle}', format(cycle))
print(repr(mapping), repr(mixed))
print(copy.deepcopy(cycle)[1][1][0], json.dumps([[1, [2]], {'a': [3]}]))
for label, value in [('list', cycle), ('dict', mapping)]:
    try:
        json.dumps(value)
    except ValueError as error:
        print('json cycle', label, error)
"#,
    );
}

// Nesting too deep for the native stack: JSON decoding raises
// RecursionError with CPython's context, the parser's nesting cap
// raises MemoryError at CPython's depth, and brackets past 200 are a
// SyntaxError.
#[test]
fn cpython_deep_native_nesting_errors_diff() {
    assert_cpython_output_parity_source(
        "Modules/_json.c and Parser/parser.c MAXSTACK",
        "deep-native-nesting-errors",
        r#"import json

def overflow(label, call, context):
    try:
        call()
        print(label, 'no error')
    except RecursionError as error:
        text = str(error)
        print(label, type(error).__name__, text.startswith('Stack overflow (used '),
              text.endswith(' kB)' + context))

n = 10**6
overflow('json-array', lambda: json.loads('[' * n + ']' * n),
         ' while decoding a JSON array from a unicode string')
overflow('json-object', lambda: json.loads('{"a":' * n + '1' + '}' * n),
         ' while decoding a JSON object from a unicode string')

for count in [1000, 4000, 10000, 10**5]:
    for label, source in [('not', 'not ' * count + '1'), ('lambda', 'lambda: ' * count + '1')]:
        try:
            eval(source)
            print('parse', label, count, 'ok')
        except MemoryError as error:
            print('parse', label, count, type(error).__name__, error)
for source in ['(' * 201 + ')' * 201, '[' * 201 + ']' * 201, '{' * 201 + '}' * 201]:
    try:
        compile(source, '<nested>', 'eval')
    except SyntaxError as error:
        print('nested brackets', type(error).__name__, error.msg)
print('compile', len(eval('[' + '[' * 150 + ']' * 150 + ']')), eval('1' + ' + 1' * 2000))
"#,
    );
}

// Under the defaults the limit is CPython's 1000: recursion to 990 works and
// 1000 raises. Any positive int is accepted, a raised limit admits deeper
// recursion, and recursion that exhausts the interpreter stack reports
// CPython's C-stack message with the context of the guarded operation.
#[test]
fn cpython_recursion_defaults_and_raised_limits_diff() {
    assert_cpython_output_parity_source(
        "Python/ceval.c _Py_CheckRecursiveCall and Objects/object.c PyObject_Repr",
        "recursion-defaults-raised-limits",
        r#"import sys

print('default', sys.getrecursionlimit())

def down(n):
    return 0 if n == 0 else 1 + down(n - 1)
print('990 under the default', down(990))
try:
    down(1000)
except RecursionError as error:
    print('1000 under the default', type(error).__name__, error)

for limit in [5000, 100000, 2**31 - 1]:
    sys.setrecursionlimit(limit)
    print('accepted', sys.getrecursionlimit() == limit)
sys.setrecursionlimit(3000)
print('raised', down(2500))
sys.setrecursionlimit(100000)

def stack_overflow(label, call, context):
    try:
        call()
        print(label, 'no error')
    except RecursionError as error:
        text = str(error)
        # CPython reports whichever recursion check crosses its C-stack limit
        # first, so the context may also be the frame-entry one (empty).
        print(label, text.startswith('Stack overflow (used '),
              text.endswith(' kB)' + context) or text.endswith(' kB)'))

class Eq:
    def __eq__(self, other):
        return self == other
class Repr:
    def __repr__(self):
        return repr(self)
class Str:
    def __str__(self):
        return str(self)
class GetAttr:
    def __getattr__(self, name):
        return getattr(self, name)
stack_overflow('eq', lambda: Eq() == Eq(), ' in comparison')
stack_overflow('repr', lambda: repr(Repr()), ' while getting the repr of an object')
stack_overflow('str', lambda: str(Str()), ' while getting the str of an object')
stack_overflow('getattr', lambda: GetAttr().missing, '')
sys.setrecursionlimit(1000)
print('restored', sys.getrecursionlimit(), down(990))
"#,
    );
}

// Unicode names are looked up only when they are made of the characters
