    fn source_section(start: &str, end: Option<&str>) -> &'static str {
        let start = PARITY_SOURCE
            .find(start)
            .unwrap_or_else(|| panic!("missing parity section start: {start}"));
        let tail = &PARITY_SOURCE[start..];
        match end {
            Some(end) => {
                let length = tail
                    .find(end)
                    .unwrap_or_else(|| panic!("missing parity section end: {end}"));
                &tail[..length]
            }
            None => tail,
        }
    }

