/// `datetime` reads the clock through `RuntimeOptions::clock`; a pinned
/// clock makes `now()`/`today()` deterministic, and the local zone is UTC.
#[test]
fn cpython_datetime_pinned_clock_subset() {
    // 2024-03-10T12:34:56.789012Z
    let options = RuntimeOptions::default()
        .with_clock(minipython::HostClock::fixed_unix_micros(1_710_074_096_789_012));
    let expected = [
        "2024-03-10 12:34:56.789012",
        "2024-03-10 2024-03-10 12:34:56.789012",
        "datetime.datetime(2024, 3, 10, 12, 34, 56, 789012, tzinfo=datetime.timezone.utc)",
        "2024-03-10T07:34:56.789012-05:00",
        "2024-03-10 12:34:56.789012 1 DeprecationWarning",
        "1710074096.789012 2024-03-10 12:34:56.789012+00:00",
        "UTC 1970-01-01 00:00:00",
    ];
    let source = "import datetime\nimport warnings\nprint(datetime.datetime.now())\nprint(datetime.date.today(), datetime.datetime.today())\nprint(repr(datetime.datetime.now(datetime.UTC)))\nprint(datetime.datetime.now(datetime.timezone(datetime.timedelta(hours=-5), 'EST')).isoformat())\nwith warnings.catch_warnings(record=True) as caught:\n    warnings.simplefilter('always')\n    print(datetime.datetime.utcnow(), len(caught), caught[0].category.__name__)\nprint(datetime.datetime.now().timestamp(), datetime.datetime.now().astimezone())\nprint(datetime.datetime.now().astimezone().tzname(), datetime.datetime.fromtimestamp(0))";
    assert_output_with_runtime_options(source, &expected, options);

    // Before the epoch, and the default (real) clock.
    let early = RuntimeOptions::default()
        .with_clock(minipython::HostClock::fixed_unix_micros(-1));
    assert_output_with_runtime_options(
        "import datetime\nprint(repr(datetime.datetime.now()), datetime.date.today())",
        &["datetime.datetime(1969, 12, 31, 23, 59, 59, 999999) 1969-12-31"],
        early,
    );
    assert_eq!(RuntimeOptions::default().clock, minipython::HostClock::System);
    assert_output(
        "import datetime\nprint(datetime.datetime.now().year >= 2024, datetime.datetime.now().astimezone().utcoffset())",
        &["True 0:00:00"],
    );
}

/// Native `datetime` values in containers compare and display by value.
#[test]
fn cpython_datetime_containers_subset() {
    assert_output(
        "from datetime import date, datetime, timedelta, timezone\nd = {date(2020, 1, 1): 'a'}\nprint(d[date(2020, 1, 1)], (date(2020, 1, 1), 1) in {(date(2020, 1, 1), 1)})\nprint([date(2020, 1, 2), timedelta(hours=1), datetime(2020, 1, 2, 3, tzinfo=timezone.utc)])\nprint({datetime(2020, 1, 1, 5, tzinfo=timezone(timedelta(hours=5))): 1}.get(datetime(2020, 1, 1, tzinfo=timezone.utc)))",
        &[
            "a True",
            "[datetime.date(2020, 1, 2), datetime.timedelta(seconds=3600), datetime.datetime(2020, 1, 2, 3, 0, tzinfo=datetime.timezone.utc)]",
            "1",
        ],
    );
}

fn cpython_formatfloat_testfile_source() -> Option<String> {
    let data = crate::cpython_sources::read_lib_file("test/mathdata/formatfloat_testcases.txt");
    Some(format!(
        r#"data = {data:?}
cases = []
for line in data.splitlines():
    line = line.strip()
    if not line or line.startswith('--'):
        continue
    lhs, expected = [part.strip() for part in line.split('->')]
    fmt, arg = lhs.split()
    cases.append((fmt, arg, expected))

checks = 0
failures = 0
for fmt, arg, expected in cases:
    value = float(arg)
    for label, got, wanted in [
        ('percent', fmt % value, expected),
        ('percent-neg', fmt % -value, '-' + expected),
    ]:
        checks += 1
        if got != wanted:
            print('mismatch', label, fmt, arg, repr(got), repr(wanted))
            failures += 1
    if fmt != '%r':
        spec = fmt[1:]
        for label, got, wanted in [
            ('format', format(value, spec), expected),
            ('format-neg', format(-value, spec), '-' + expected),
        ]:
            checks += 1
            if got != wanted:
                print('mismatch', label, fmt, arg, repr(got), repr(wanted))
                failures += 1
print('checked', len(cases), checks, 'failures', failures)"#
    ))
}

fn cpython_floating_points_repr_source() -> Option<String> {
    let data = crate::cpython_sources::read_lib_file("test/mathdata/floating_points.txt");
    Some(format!(
        r#"import math
data = {data:?}
checked = 0
failures = 0
for line in data.splitlines():
    text = line.strip()
    if not text or text.startswith('#'):
        continue
    value = eval(text)
    rendered = repr(value)
    roundtrip = eval(rendered)
    if value != roundtrip:
        print('mismatch', text, rendered, roundtrip)
        failures += 1
    if value == 0.0 and math.copysign(1.0, value) != math.copysign(1.0, roundtrip):
        print('zero-sign-mismatch', text, rendered)
        failures += 1
    checked += 1
print('checked', checked, 'failures', failures)"#
    ))
}

fn assert_output(source: &str, expected: &[&str]) {
    let expected = expected.iter().map(|line| line.to_string()).collect();
    assert_eq!(run_source(source), Ok(expected), "source:\n{source}");
}

fn assert_output_with_runtime_options(source: &str, expected: &[&str], options: RuntimeOptions) {
    let expected = expected.iter().map(|line| line.to_string()).collect();
    assert_eq!(
        run_source_with_runtime_options(source, options),
        Ok(expected),
        "source:\n{source}"
    );
}

fn assert_output_with_stack(source: &str, expected: &[&str], stack_size: usize) {
    let expected = expected.iter().map(|line| line.to_string()).collect();
    let source_for_thread = source.to_string();
    let actual = std::thread::Builder::new()
        .stack_size(stack_size)
        .spawn(move || run_source(&source_for_thread))
        .expect("failed to spawn MiniPython test thread")
        .join()
        .expect("MiniPython test thread panicked");
    assert_eq!(actual, Ok(expected), "source:\n{source}");
}

fn run_test_with_stack<F>(stack_size: usize, test: F)
where
    F: FnOnce() + Send + 'static,
{
    let handle = std::thread::Builder::new()
        .stack_size(stack_size)
        .spawn(test)
        .expect("failed to spawn MiniPython test thread");
    if let Err(payload) = handle.join() {
        std::panic::resume_unwind(payload);
    }
}

