// Adapted from CPython's shared `VALID_UNDERSCORE_LITERALS` table in
// Lib/test/support/numbers.py. CPython checks that each literal evaluates the
// same as the same spelling with underscores removed.
#[test]
fn cpython_valid_underscore_number_literals_subset() {
    let (valid, _) = cpython_underscore_literal_tables();
    assert_eq!(valid.len(), 21);
    for literal in &valid {
        let normalized = literal.replace('_', "");
        assert_output(&format!("print({literal} == {normalized})"), &["True"]);
    }
}

/// `VALID_UNDERSCORE_LITERALS` and `INVALID_UNDERSCORE_LITERALS` of the
/// pinned CPython's `test/support/numbers.py`, loaded at test time by CPython
/// itself (the tables are not copied into this file).
fn cpython_underscore_literal_tables() -> (Vec<String>, Vec<String>) {
    let numbers = crate::cpython_sources::lib_file("test/support/numbers.py");
    let script = r#"
import runpy
import sys

tables = runpy.run_path(sys.argv[1])
for tag in ("VALID", "INVALID"):
    for literal in tables[tag + "_UNDERSCORE_LITERALS"]:
        print(tag, literal.encode("utf-8").hex())
"#;
    let executable = crate::cpython_sources::executable();
    let output = std::process::Command::new(&executable)
        .arg("-I")
        .arg("-c")
        .arg(script)
        .arg(&numbers)
        .output()
        .expect("failed to run python3 for CPython underscore literal tables");
    assert!(
        output.status.success(),
        "failed to load CPython numbers.py: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    let mut valid = Vec::new();
    let mut invalid = Vec::new();
    for line in String::from_utf8(output.stdout)
        .expect("CPython numbers.py output should be UTF-8")
        .lines()
    {
        let (tag, hex) = line.split_once(' ').expect("tagged literal line");
        let literal = hex_utf8_line(hex);
        match tag {
            "VALID" => valid.push(literal),
            "INVALID" => invalid.push(literal),
            other => panic!("unexpected table tag {other:?}"),
        }
    }
    (valid, invalid)
}

