// Adapted from CPython Lib/test/test_float.py::GeneralFloatCases::
// test_floatconversion. The warning assertions around float-subclass
// `__float__` results are represented here by the public result type/value.
#[test]
fn cpython_float_conversion_protocol_subset() {
    assert_output_with_stack(
        r#"class Sub(float):
    pass
class OtherSub(float):
    pass
class Convertible:
    def __init__(self, payload):
        self.payload = payload
    def __float__(self):
        return self.payload
class HookOnSubclass(float):
    def __float__(self):
        return -1.5
class SelfReturning(float):
    def __new__(cls, x=0.0):
        return super().__new__(cls, x + 0.5)
    def __float__(self):
        return self
class IntResult(float):
    def __float__(self):
        return 7
class NumericText(str):
    def __float__(self):
        return float(str(self)) * 10

def show(label, thunk):
    try:
        result = thunk()
    except Exception as error:
        print(label, type(error).__name__, error)
    else:
        print(label, result, type(result).__name__, type(result) is float, type(result) is Sub)

show('convertible', lambda: float(Convertible(2.5)))
show('hook-on-subclass', lambda: float(HookOnSubclass(3.0)))
show('self-returning', lambda: float(SelfReturning(1)))
show('str-subclass', lambda: float(NumericText('0.25')))
show('returns-subclass', lambda: float(Convertible(OtherSub(9.0))))
show('ctor-subclass', lambda: Sub(Convertible(OtherSub(9.0))))
show('int-result', lambda: float(IntResult(1.0)))
show('text-result', lambda: float(Convertible('text')))"#,
        &[
            "convertible 2.5 float True False",
            "hook-on-subclass -1.5 float True False",
            "self-returning 1.5 float True False",
            "str-subclass 2.5 float True False",
            "returns-subclass 9.0 float True False",
            "ctor-subclass 9.0 Sub False True",
            "int-result TypeError IntResult.__float__ returned non-float (type int)",
            "text-result TypeError Convertible.__float__ returned non-float (type str)",
        ],
        64 * 1024 * 1024,
    );
}

// Adapted from CPython Lib/test/test_float.py::GeneralFloatCases::
