// Adapted from CPython Lib/test/test_float.py::GeneralFloatCases::
// test_keywords_in_subclass. This covers float subclass construction,
// keyword forwarding to user `__init__` / `__new__`, and inherited
// `float.__new__` lookup through `super()`.
#[test]
fn cpython_float_keywords_in_subclass_subset() {
    assert_output(
        r#"class Bare(float):
    pass
value = Bare(-4.0)
print('plain', type(value) is Bare, float(value), repr(value))
try:
    Bare(tag=1)
except TypeError as error:
    print('keyword', type(error).__name__, str(error))

class InitKw(float):
    # float.__new__ ignores extra keywords when the subclass overrides __init__
    def __init__(self, number, *, tag='none'):
        self.tag = tag
value = InitKw('1.5', tag='init')
print('init', type(value) is InitKw, float(value), value.tag)

class NewKw(float):
    def __new__(cls, number, label=None):
        made = float.__new__(cls, number)
        made.label = label
        return made
value = NewKw(9, label='new')
print('new', type(value) is NewKw, float(value), value.label)"#,
        &[
            "plain True -4.0 -4.0",
            "keyword TypeError float() takes no keyword arguments",
            "init True 1.5 init",
            "new True 9.0 new",
        ],
    );
}

