// Adapted from CPython Lib/test/test_float.py::HexFloatTestCase::test_ends
// and ::test_whitespace.
#[test]
fn cpython_float_hex_fromhex_ends_whitespace_subset() {
    assert_output(
        concat!(
            "import math\n",
            "INF = float('inf')\n",
            "NAN = float('nan')\n",
            "MAX = float.fromhex('0x.fffffffffffff8p+1024')\n",
            "MIN = float.fromhex('0x1p-1022')\n",
            "TINY = float.fromhex('0x0.0000000000001p-1022')\n",
            "EPS = float.fromhex('0x0.0000000000001p0')\n",
            "def identical(x, y):\n",
            "    if x != x or y != y:\n",
            "        return x != x and y != y\n",
            "    if x == y:\n",
            "        if x != 0.0:\n",
            "            return True\n",
            "        return math.copysign(1.0, x) == math.copysign(1.0, y)\n",
            "    return False\n",
            "ends = [\n",
            "    ('MIN', MIN, math.ldexp(1.0, -1022)),\n",
            "    ('TINY', TINY, math.ldexp(1.0, -1074)),\n",
            "    ('EPS', EPS, math.ldexp(1.0, -52)),\n",
            "    ('MAX', MAX, 2.0 * (math.ldexp(1.0, 1023) - math.ldexp(1.0, 970))),\n",
            "]\n",
            "for name, actual, expected in ends:\n",
            "    print(name, actual.hex(), expected.hex(), identical(actual, expected))\n",
            "specials = {'inf': INF, '-Infinity': -INF, 'NaN': NAN, '+0x1p0': 1.0, '-0x.4': -0.25, '-0x0p0': -0.0, '0x1.8': 1.5}\n",
            "pads = [' ', '\\t', '\\n', '\\r', '\\f', '\\v', '\\n\\t ', '']\n",
            "bad = [(lead, body, tail) for body, want in specials.items() for lead in pads for tail in pads\n",
            "       if not identical(float.fromhex(lead + body + tail), want)]\n",
            "print('whitespace', bad, len(specials) * len(pads) ** 2)\n",
            "for text in ['\\f-0.0\\v', '\\rnan\\n', '\\n \\t-0x.2\\f']:\n",
            "    value = float.fromhex(text)\n",
            "    if value != value:\n",
            "        print(repr(text), 'nan')\n",
            "    else:\n",
            "        print(repr(text), value.hex(), math.copysign(1.0, value))",
        ),
        &[
            "MIN 0x1.0000000000000p-1022 0x1.0000000000000p-1022 True",
            "TINY 0x0.0000000000001p-1022 0x0.0000000000001p-1022 True",
            "EPS 0x1.0000000000000p-52 0x1.0000000000000p-52 True",
            "MAX 0x1.fffffffffffffp+1023 0x1.fffffffffffffp+1023 True",
            "whitespace [] 448",
            "'\\x0c-0.0\\x0b' -0x0.0p+0 -1.0",
            "'\\rnan\\n' nan",
            "'\\n \\t-0x.2\\x0c' -0x1.0000000000000p-3 -1.0",
        ],
    );
}

// Adapted from CPython Lib/test/test_float.py::HexFloatTestCase::test_roundtrip.
// CPython uses randomized exponent/mantissa samples here; MiniPython keeps the
// same public invariant but uses a 10,000-row deterministic sweep so the Rust
// test is repeatable.
#[test]
fn cpython_float_hex_fromhex_roundtrip_matrix_subset() {
    assert_output(
        concat!(
            "import math\n",
            "NAN = float('nan')\n",
            "INF = float('inf')\n",
            "MAX = float.fromhex('0x1.fffffffffffffp+1023')\n",
            "MIN = float.fromhex('0x1p-1022')\n",
            "TINY = float.fromhex('0x0.0000000000001p-1022')\n",
            "def identical(x, y):\n",
            "    if x != x or y != y:\n",
            "        return x != x and y != y\n",
            "    if x == y:\n",
            "        if x != 0.0:\n",
            "            return True\n",
            "        return math.copysign(1.0, x) == math.copysign(1.0, y)\n",
            "    return False\n",
            "def roundtrip(x):\n",
            "    return float.fromhex(x.hex())\n",
            "for x in [NAN, INF, MAX, MIN, MIN - TINY, TINY, 0.0]:\n",
            "    print(x.hex(), identical(x, roundtrip(x)), (-x).hex(), identical(-x, roundtrip(-x)))\n",
            "ok = True\n",
            "count = 0\n",
            "skipped = 0\n",
            "for i in range(10000):\n",
            "    exponent = ((i * 1543 + 17) % 2400) - 1200\n",
            "    mantissa_bits = (i * 6364136223846793005 + 1442695040888963407) % (2 ** 53)\n",
            "    mantissa = mantissa_bits / float(2 ** 53)\n",
            "    sign = -1.0 if ((i * 1103515245 + 12345) % 2) else 1.0\n",
            "    try:\n",
            "        x = sign * math.ldexp(mantissa, exponent)\n",
            "    except OverflowError:\n",
            "        skipped += 1\n",
            "    else:\n",
            "        count += 1\n",
            "        if not identical(x, roundtrip(x)):\n",
            "            print('mismatch', i, exponent, mantissa_bits, x.hex(), roundtrip(x).hex())\n",
            "            ok = False\n",
            "print('deterministic-sweep', ok, count, skipped)\n",
            "print(roundtrip(-0.0).hex(), identical(-0.0, roundtrip(-0.0)))",
        ),
        &[
            "nan True nan True",
            "inf True -inf True",
            "0x1.fffffffffffffp+1023 True -0x1.fffffffffffffp+1023 True",
            "0x1.0000000000000p-1022 True -0x1.0000000000000p-1022 True",
            "0x0.fffffffffffffp-1022 True -0x0.fffffffffffffp-1022 True",
            "0x0.0000000000001p-1022 True -0x0.0000000000001p-1022 True",
            "0x0.0p+0 True -0x0.0p+0 True",
            "deterministic-sweep True 9275 725",
            "-0x0.0p+0 True",
        ],
    );
}

// Adapted from CPython Lib/test/test_float.py::HexFloatTestCase::test_subclass.
#[test]
fn cpython_float_hex_fromhex_subclass_subset() {
    assert_output(
        r#"class Doubled(float):
    def __new__(cls, x):
        return super().__new__(cls, x * 2)
h = Doubled.fromhex('0x1.4p+1')
print(type(h).__name__, h, h == 5.0, isinstance(h, float), issubclass(Doubled, float), h.hex())
raw = float.__new__(Doubled, 0.75)
print(raw, type(raw) is Doubled)
class Tagged(float):
    def __init__(self, x):
        self.tag = 'init-ran'
t = Tagged.fromhex('-0x1p-2')
print(type(t) is Tagged, t, t == -0.25, getattr(t, 'tag', 'missing'), bool(Tagged(0.0)), bool(Tagged('1e-9')))"#,
        &[
            "Doubled 5.0 True True True 0x1.4000000000000p+2",
            "0.75 True",
            "True -0.25 True init-ran False True",
        ],
    );
}

// Adapted from CPython Lib/test/test_math.py public pure-memory smoke coverage.
#[test]
fn cpython_math_core_subset() {
    assert_output(
        concat!(
            "import math\n",
            "print(math.__name__, repr(math.__package__))\n",
            "print(repr(object.__getattribute__(math, '__package__')))\n",
            "print('__package__' in dir(math), repr(math.__dict__['__package__']))\n",
            "print(math.sqrt.__qualname__, math.gcd.__qualname__, math.isfinite.__qualname__)\n",
            "print(type(math.sqrt.__doc__).__name__, bool(math.sqrt.__doc__))\n",
            "print(type(math.gcd.__doc__).__name__, bool(math.gcd.__doc__))\n",
            "print(type(math.isfinite.__doc__).__name__, bool(math.isfinite.__doc__))\n",
            "print(round(math.pi, 3), round(math.e, 3), round(math.tau, 3))\n",
            "print(math.isfinite(1.0), math.isfinite(math.inf), math.isinf(-math.inf), math.isnan(math.nan))\n",
            "print(math.sqrt(9), math.gcd(12, 18), math.lcm(4, 6), math.factorial(5), math.isqrt(17))\n",
            "print(math.comb(5, 2), math.perm(5, 2), math.prod([2, 3, 4]), math.isclose(1.0, 1.0 + 1e-10))\n",
            "print(math.fabs(-3.5), math.trunc(3.9), math.floor(-1.2), math.ceil(-1.2))\n",
            "for expr in [lambda: math.sqrt(-1), lambda: math.factorial(-1), lambda: math.gcd(1.2), lambda: math.isclose(1.0, 1.1, rel_tol=-1.0)]:\n",
            "    try:\n",
            "        expr()\n",
            "    except (TypeError, ValueError) as error:\n",
            "        print(error.__class__.__name__)"
        ),
        &[
            "math ''",
            "''",
            "True ''",
            "sqrt gcd isfinite",
            "str True",
            "str True",
            "str True",
            "3.142 2.718 6.283",
            "True False True True",
            "3.0 6 12 120 4",
            "10 20 24 True",
            "3.5 3 -2 -1",
            "ValueError",
            "ValueError",
            "TypeError",
            "ValueError",
        ],
    );
}

