// Adapted from CPython Lib/test/test_math.py::MathTests::test_prod. MiniPython
// ports the public iterable product, keyword-only `start`, integer/float,
// sequence-repetition, zero, NaN/inf, type-preservation, and error-class
// behavior supported by the current runtime.
#[test]
fn cpython_math_prod_subset() {
    assert_output(
        r#"import math
from math import prod
print(prod([]), prod((), start=-2), prod(list(range(3, 9))))
print(prod(iter(range(3, 9))), prod(range(2, 7), start=3))
ints, floats = [2, 3, 5, 7], [2.0, 3.0, 5.0, 7.0]
print(prod(ints), prod(floats), prod([2, 3, 5.0, 7.0]), prod([2.0, 3.0, 5, 7]))
print(prod([1, 2**40, 1]), prod([1.0, 2**40, 1]))
# start may be any object supporting multiplication by the items
print(prod([3, 2], start='xy'), prod([2, 2], start=(0,)), prod([], start={'k': 1}))
print([prod(row) for row in ([0, 4, 5], [4, 0, 5], [4, 5, 0])])
nan, inf = float('nan'), float('inf')
print(math.isnan(prod([4, nan, 5])), math.isnan(prod([4, 0, nan])), math.isnan(prod([nan, 0, 4])))
signed = [prod([2, inf, -1]), prod([2, -inf, -1]), prod([-inf, -inf])]
print([(math.isinf(v), v > 0) for v in signed])
print(math.isnan(prod([3, 0, inf])), math.isnan(prod([3, 0, -inf])))
print(type(prod(range(1, 6))).__name__, type(prod([1, 2, 3.5])).__name__)"#,
        &[
            "1 -2 20160",
            "20160 2160",
            "210 210.0 210.0 210.0",
            "1099511627776 1099511627776.0",
            "xyxyxyxyxyxy (0, 0, 0, 0) {'k': 1}",
            "[0, 0, 0]",
            "True True True",
            "[(True, False), (True, True), (True, True)]",
            "True True",
            "int float",
        ],
    );
    assert_output(
        concat!(
            "import math\n",
            "prod = math.prod\n",
            "values = [bytearray(b'a'), bytearray(b'b')]\n",
            "for expr in [lambda: prod(), lambda: prod(42), lambda: prod(['a', 'b', 'c']), lambda: prod(['a', 'b', 'c'], start=''), lambda: prod([b'a', b'c'], start=b''), lambda: prod(values, start=bytearray(b'')), lambda: prod([[1], [2], [3]]), lambda: prod([{2: 3}]), lambda: prod([{2: 3}] * 2, start={2: 3}), lambda: prod([[1], [2], [3]], start=[]), lambda: prod([10, 20], 1), lambda: prod([1], missing=2)]:\n",
            "    try:\n",
            "        expr()\n",
            "    except Exception as error:\n",
            "        print(error.__class__.__name__)"
        ),
        &[
            "TypeError",
            "TypeError",
            "TypeError",
            "TypeError",
            "TypeError",
            "TypeError",
            "TypeError",
            "TypeError",
            "TypeError",
            "TypeError",
            "TypeError",
            "TypeError",
        ],
    );
    assert_output(
        "import math\nprod = math.prod\nfor label, expr in [('missing', lambda: prod()), ('keyword-iterable', lambda: prod(iterable=[1, 2])), ('positional-start', lambda: prod([10, 20], 1)), ('too-many', lambda: prod([1], 2, 3))]:\n    try:\n        expr()\n    except TypeError as error:\n        print(label, str(error))",
        &[
            "missing prod() takes exactly 1 positional argument (0 given)",
            "keyword-iterable prod() takes exactly 1 positional argument (0 given)",
            "positional-start prod() takes exactly 1 positional argument (2 given)",
            "too-many prod() takes at most 2 arguments (3 given)",
        ],
    );
}

// Adapted from CPython float numeric-protocol coverage in
// Lib/test/test_float.py::test_is_integer and ::test_floatasratio, plus the
