// Adapted from CPython Lib/test/test_grammar.py::GrammarTests.test_matrix_mul.
// This is the method-level grammar smoke slice for `@` and `@=` dispatch.
#[test]
fn cpython_grammar_matrix_mul_method_subset() {
    let source = r#"class Grid:
    def __init__(self, cells):
        self.cells = cells
    def __matmul__(self, other):
        return sum(a * b for a, b in zip(self.cells, other.cells))
    def __imatmul__(self, other):
        self.cells = [value * other for value in self.cells]
        return self
row = Grid([1, 2, 3])
print(row @ Grid([4, 5, 6]))
row @= 10
print(row.cells)"#;
    assert_output(source, &[
            "32",
            "[10, 20, 30]",
        ]);
}

// Adapted from CPython's invalid arithmetic/factor grammar rules. MiniPython
// rejects the same unparenthesized `not` forms after arithmetic operators.
#[test]
fn cpython_invalid_arithmetic_and_factor_syntax_subset() {
    for source in [
        "print(1 + not 2)",
        "print(1 - not 2)",
        "print(1 * not 2)",
        "print(1 / not 2)",
        "print(1 % not 2)",
        "print(1 // not 2)",
        "print(1 @ not 2)",
        "print(+not 2)",
        "print(-not 2)",
        "print(~not 2)",
    ] {
        assert_error(
            source,
            "parse error: 'not' after an operator must be parenthesized",
        );
    }

    assert_output("print(not 0)", &["True"]);
    assert_output("print((not 0))", &["True"]);
}

// Adapted from CPython expression grammar for bitwise and shift expressions.
// MiniPython currently supports integer-only bitwise operators.
#[test]
fn cpython_grammar_bitwise_and_shift_subset() {
    assert_output("x = 1 & 1", &[]);
    assert_output("x = 1 ^ 1", &[]);
    assert_output("x = 1 | 1", &[]);
    assert_output("x = 1 << 1", &[]);
    assert_output("x = 1 >> 1", &[]);
    assert_output("x = 1 << 1 >> 1", &[]);
    assert_output("print(1 | 2, 3 ^ 1, 6 & 3)", &["3 2 2"]);
    assert_output("print(1 << 3, 8 >> 1)", &["8 4"]);
    assert_output("print(1 + 2 << 2, 8 >> 1 + 1)", &["12 2"]);
    assert_output("print(1 & 1, 1 ^ 1, 1 | 1)", &["1 0 1"]);
    assert_output("print(1 << 1, 1 >> 1, 1 << 1 >> 1)", &["2 0 1"]);
}

// Adapted from CPython expression grammar for conditional expressions:
// `disjunction 'if' disjunction 'else' expression`. The last case verifies
// right associativity and branch short-circuiting in MiniPython.
#[test]
fn cpython_grammar_conditional_expression_subset() {
    assert_output("print(1 if True else 2)", &["1"]);
    assert_output("print(1 if False else 2)", &["2"]);
    assert_output("print(\"yes\" if 1 < 2 else \"no\")", &["yes"]);
    assert_output("print(1 if True else unknown)", &["1"]);
    assert_output("print(1 if False else 2 if True else 3)", &["2"]);
}

// Adapted from CPython Lib/test/test_grammar.py::GrammarTests.test_if_else_expr.
// This keeps the method-level conditional-expression precedence and
// short-circuiting cases together, including lambdas inside comprehensions.
#[test]
fn cpython_grammar_if_else_expr_method_subset() {
    let source = r#"def noisy(tag, value):
    print('evaluated', tag)
    return value

print([f() for f in (lambda: 'yes', lambda: '') if f()])
print([g(1) for g in (lambda v: 0 if v else 9, lambda v: 7 if v else 0) if g(1)])
# only the selected branch is evaluated
print('picked' if 2 > 1 else noisy('A', 'never'))
print(noisy('B', 'never') if [] else 'fallback')
# the conditional binds looser than and/or/not and arithmetic/comparison
print(3 and 4 if None else 8)
print((3 and 4) if 1 else 8)
print(3 and (4 if '' else 9))
print('' or noisy('C', 'c') if 1 else 'unused')
print('first' or noisy('D', 'd') if 1 else noisy('E', 'e'))
print(0 or 7 if 0 else noisy('F', 'f'))
print(not 2 if 'x' else 'y', not 2 if '' else 'y')
print(10 + 5 if 1 else 0, 10 - 5 if 1 else 0, 10 * 5 if 1 else 0, 10 / 5 if 1 else 0, 1 < 0 if 1 else 'n')"#;
    assert_output(
        source,
        &[
            "['yes']",
            "[7]",
            "picked",
            "fallback",
            "8",
            "4",
            "9",
            "evaluated C",
            "c",
            "first",
            "evaluated F",
            "f",
            "False y",
            "15 5 50 2.0 False",
        ],
    );
}

