// First structural migration step for
// Lib/test/test_ast/test_ast.py::AST_Tests::test_snippets. CPython compares
// `to_tuple(ast_tree)` for every snippet; MiniPython does not yet expose a
// public CPython-compatible `ast` module, so this pins representative internal
// parser AST shapes instead of only checking parse success.
#[test]
fn cpython_ast_snippets_structural_dump_subset() {
    assert_ast_dump_contains(
        "'module docstring'",
        &["Program { statements: [Expr(String(\"module docstring\"))] }"],
    );
    assert_ast_dump_contains(
        "def f(a=0): pass",
        &[
            "FunctionDef { name: \"f\"",
            "Param { name: \"a\", annotation: None, default: Some(Number(0)), type_comment: None }",
            "body: [Pass]",
        ],
    );
    assert_ast_dump_contains(
        "class C(A, B): pass",
        &[
            "ClassDef { name: \"C\"",
            "bases: [Expr(Name(\"A\")), Expr(Name(\"B\"))]",
            "body: [Pass]",
        ],
    );
    assert_ast_dump_contains(
        "a,b = c",
        &[
            "Assign { targets: [Tuple([Name(\"a\"), Name(\"b\")])], value: Name(\"c\"), type_comment: None }",
        ],
    );
    assert_ast_dump_contains(
        "if a:\n  pass\nelse:\n  pass",
        &[
            "If { condition: Name(\"a\")",
            "then_body: [Pass]",
            "else_body: [Pass]",
        ],
    );
    assert_ast_dump_contains(
        "for a,b in c: pass",
        &[
            "For { target: Tuple([Name(\"a\"), Name(\"b\")])",
            "iter: Name(\"c\")",
            "body: [Pass]",
        ],
    );
    assert_ast_dump_contains(
        "with x as y: pass",
        &[
            "With { items: [WithItem { context_expr: Name(\"x\"), optional_vars: Some(Name(\"y\")) }]",
            "body: [Pass]",
        ],
    );
    assert_ast_dump_contains(
        "try:\n  pass\nexcept Exception as exc:\n  pass\nelse:  pass\nfinally:\n  pass",
        &[
            "Try { body: [Pass]",
            "ExceptHandler { type_expr: Some(Name(\"Exception\")), name: Some(\"exc\"), body: [Pass] }",
            "else_body: [Pass]",
            "finally_body: [Pass]",
        ],
    );
    assert_ast_dump_contains(
        "match x:\n\tcase 1:\n\t\tpass",
        &[
            "Match { subject: Name(\"x\")",
            "MatchCase { pattern: Literal(Number(1)), guard: None, body: [Pass] }",
        ],
    );

    assert_interactive_ast_dump_contains(
        "1+2",
        &["Expr(Binary { left: Number(1), op: Add, right: Number(2) })"],
    );
    assert_eval_ast_dump_contains(
        "foo() if x else bar()",
        &[
            "IfExpression",
            "condition: Name(\"x\")",
            "then_branch: Call { callee: Name(\"foo\"), args: [] }",
            "else_branch: Call { callee: Name(\"bar\"), args: [] }",
        ],
    );
    assert_eval_ast_dump_contains(
        "f(1,2,c=3,*d,**e)",
        &[
            "UnpackCall",
            "args: [Expr(Number(1)), Expr(Number(2)), Unpack(Name(\"d\"))]",
            "keywords: [Named(\"c\", Number(3)), Unpack(Name(\"e\"))]",
        ],
    );
    assert_eval_ast_dump_contains(
        "[a for b in c if d]",
        &[
            "ListComp",
            "element: Name(\"a\")",
            "ComprehensionClause { is_async: false, target: Name(\"b\"), iter: Name(\"c\"), ifs: [Name(\"d\")] }",
        ],
    );
    assert_eval_ast_dump_contains(
        "t'{a!r:.2f}'",
        &[
            "TemplateString",
            "Interpolation",
            "conversion: Some(Repr)",
            "format_spec: Some([Literal(\".2f\")])",
        ],
    );
}

/// Every case of the pinned CPython's `test/test_ast/snippets.py`, read at
/// test time: `(mode, source, expected)` for `exec_tests`, `single_tests`
/// and `eval_tests`, where `expected` is the repr of the `to_tuple()` result
/// that CPython's test expects (`exec_results`, ...). The file imports
/// `to_tuple` from `test/test_ast/utils.py`, so both come from the install.
fn cpython_ast_snippet_cases() -> Vec<(String, String, String)> {
    let snippets = crate::cpython_sources::lib_file("test/test_ast/snippets.py");
    let utils = crate::cpython_sources::lib_file("test/test_ast/utils.py");
    let script = r#"
import runpy
import sys
import types

utils = runpy.run_path(sys.argv[2])
for name in ("test", "test.test_ast", "test.test_ast.utils"):
    sys.modules[name] = types.ModuleType(name)
sys.modules["test.test_ast.utils"].to_tuple = utils["to_tuple"]
snippets = runpy.run_path(sys.argv[1])
for mode in ("exec", "single", "eval"):
    for source, result in zip(snippets[mode + "_tests"], snippets[mode + "_results"], strict=True):
        print(mode, source.encode("utf-8").hex(), repr(result).encode("utf-8").hex())
"#;
    let executable = crate::cpython_sources::executable();
    let output = std::process::Command::new(&executable)
        .arg("-I")
        .arg("-c")
        .arg(script)
        .arg(&snippets)
        .arg(&utils)
        .output()
        .expect("failed to run python3 for CPython AST snippets");
    assert!(
        output.status.success(),
        "failed to load CPython snippets.py: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    String::from_utf8(output.stdout)
        .expect("CPython snippets output should be UTF-8")
        .lines()
        .map(|line| {
            let mut fields = line.split(' ');
            let mode = fields.next().expect("mode").to_string();
            let source = hex_utf8_line(fields.next().expect("source"));
            let expected = hex_utf8_line(fields.next().expect("expected"));
            (mode, source, expected)
        })
        .collect()
}

/// A Python list literal of `(mode, source)` pairs.
fn ast_snippet_case_list(cases: &[(String, String, String)]) -> String {
    let mut list = String::from("[\n");
    for (mode, source, _) in cases {
        list.push_str(&format!("    ({mode:?}, {source:?}),\n"));
    }
    list.push(']');
    list
}

/// CPython's `AST_Tests.test_snippets` comparison on the pinned snippet
/// inventory: each source is compiled to an AST with `PyCF_ONLY_AST`, its
/// `to_tuple()` (the pinned `utils.py` helper, run inside MiniPython) must
/// equal the result `snippets.py` records, and the tree must compile back.
#[test]
fn cpython_ast_snippets_to_tuple_from_cpython_source_subset() {
    let cases = cpython_ast_snippet_cases();
    assert_eq!(cases.len(), 215);
    let to_tuple = crate::cpython_sources::read_lib_file("test/test_ast/utils.py");
    let program = format!(
        "{to_tuple}\nimport ast\nfor mode, source in {}:\n    tree = compile(source, '?', mode, ast.PyCF_ONLY_AST, optimize=False)\n    print(repr(to_tuple(tree)))\n    compile(tree, '?', mode)\n",
        ast_snippet_case_list(&cases)
    );
    let actual = run_test_with_stack_result(32 * 1024 * 1024, move || run_source(&program));
    let actual = actual.unwrap_or_else(|error| panic!("{error}"));
    assert_eq!(actual.len(), cases.len());
    for ((mode, source, expected), actual) in cases.iter().zip(&actual) {
        assert_eq!(actual, expected, "{mode} snippet {source:?}");
    }
}

/// Every pinned snippet parses in its mode.
#[test]
fn cpython_ast_snippets_parse_from_cpython_source_subset() {
    for (mode, source, _) in cpython_ast_snippet_cases() {
        match mode.as_str() {
            "exec" => assert_parse_ok(&source),
            "single" => assert_interactive_parse_ok(&source),
            "eval" => assert_eval_parse_ok(&source),
            other => panic!("unexpected snippet mode {other}"),
        }
    }
}

/// `ast.compare()` finds two parses of each pinned snippet equal.
#[test]
fn cpython_ast_snippets_compare_modes_from_cpython_source_subset() {
    for (mode, source, _) in cpython_ast_snippet_cases() {
        assert_ast_compare_mode_source(&mode, &source);
    }
}

/// Source positions of every pinned snippet's tree: no statement,
/// expression or except handler starts before the node that contains it
/// (decorators, which precede their definition, excepted), list items do
/// not go backwards, and `__match_args__` equals `_fields` on every node.
/// Each tree also compiles back, and the exec-mode parse compiles. CPython
/// runs the same program for the expected output.
#[test]
fn cpython_ast_snippets_position_order_from_cpython_source_subset() {
    let cases = cpython_ast_snippet_cases();
    let program = format!(
        r#"import ast
positioned = (ast.stmt, ast.expr, ast.excepthandler)

def start(node):
    return (node.lineno, node.col_offset)

def check(node, floor, path):
    problems = []
    if isinstance(node, positioned):
        if start(node) < floor:
            problems.append(('before-parent', path, type(node).__name__))
        floor = start(node)
    if tuple(node._fields) != tuple(node.__match_args__):
        problems.append(('match-args', type(node).__name__))
    for field in node._fields:
        value = getattr(node, field, None)
        children = value if isinstance(value, list) else [value]
        previous = floor
        for child in children:
            if not isinstance(child, ast.AST):
                continue
            child_floor = (0, 0) if field == 'decorator_list' else floor
            problems += check(child, child_floor, path + '.' + field)
            if isinstance(child, positioned) and field != 'decorator_list':
                if start(child) < previous:
                    problems.append(('list-order', path + '.' + field))
                previous = start(child)
    return problems

checked = 0
for mode, source in {cases}:
    tree = compile(source, '?', mode, ast.PyCF_ONLY_AST, optimize=False)
    for problem in check(tree, (0, 0), type(tree).__name__):
        print(mode, repr(source), problem)
    compile(tree, '?', mode)
    if mode == 'exec':
        compile(ast.parse(source, optimize=False), '<string>', 'exec')
    checked += 1
print('checked', checked)"#,
        cases = ast_snippet_case_list(&cases)
    );
    let cpython = std::process::Command::new(crate::cpython_sources::executable())
        .arg("-I")
        .arg("-c")
        .arg(&program)
        .output()
        .expect("failed to run CPython");
    assert!(
        cpython.status.success(),
        "{}",
        String::from_utf8_lossy(&cpython.stderr)
    );
    let expected: Vec<String> = String::from_utf8(cpython.stdout)
        .expect("CPython output should be UTF-8")
        .lines()
        .map(str::to_string)
        .collect();
    assert_eq!(expected.last().map(String::as_str), Some("checked 215"));
    let actual = run_test_with_stack_result(32 * 1024 * 1024, move || run_source(&program));
    assert_eq!(actual, Ok(expected));
}

fn run_test_with_stack_result<T, F>(stack_size: usize, test: F) -> T
where
    T: Send + 'static,
    F: FnOnce() -> T + Send + 'static,
{
    std::thread::Builder::new()
        .stack_size(stack_size)
        .spawn(test)
        .expect("failed to spawn MiniPython test thread")
        .join()
        .unwrap_or_else(|payload| std::panic::resume_unwind(payload))
}

/// The repr of an empty module, which the snippet inventory does not cover.
#[test]
fn cpython_ast_empty_module_repr_subset() {
    assert_output(
        "import ast\nprint(repr(ast.parse('')))\nprint(ast.dump(ast.parse('')))",
        &["Module(body=[], type_ignores=[])", "Module()"],
    );
}

// Focused public-AST start-mode coverage: `eval` produces `Expression`,
// `single` produces `Interactive`, and `func_type` is exposed through
// `ast.parse(..., mode='func_type')` as a `FunctionType` root. The tuples
// come from `to_tuple()` of the pinned CPython's `test/test_ast/utils.py`.
#[test]
fn cpython_ast_start_modes_public_to_tuple_subset() {
    let program = format!(
        "{}\nimport ast\n{}",
        crate::cpython_sources::read_lib_file("test/test_ast/utils.py"),
        r#"def show(source, mode):
    if mode == "func_type":
        tree = ast.parse(source, mode=mode)
    else:
        tree = compile(source, "<modes>", mode, flags=ast.PyCF_ONLY_AST, optimize=False)
        compile(tree, "<modes>", mode)
    print(mode, to_tuple(tree))

show("3 * 4", "eval")
show("lambda a, b=1: a", "eval")
show("3 * 4", "single")
show("total = 9", "single")
show("(bytes, float) -> list", "func_type")
show("(set[str], *list[int], **dict[int, str]) -> dict[int, bytes]", "func_type")"#
    );
    // The `eval` and `single` tuples are CPython 3.14.6 output. MiniPython does
    // not record positions on `func_type` nodes yet, so those two lines pin its
    // position-free tuples (CPython also prints the location tuples there).
    assert_output_with_stack(
        &program,
        &[
            "eval ('Expression', ('BinOp', (1, 0, 1, 5), ('Constant', (1, 0, 1, 1), 3, None), ('Mult',), ('Constant', (1, 4, 1, 5), 4, None)))",
            "eval ('Expression', ('Lambda', (1, 0, 1, 16), ('arguments', [], [('arg', (1, 7, 1, 8), 'a', None, None), ('arg', (1, 10, 1, 11), 'b', None, None)], None, [], [], None, [('Constant', (1, 12, 1, 13), 1, None)]), ('Name', (1, 15, 1, 16), 'a', ('Load',))))",
            "single ('Interactive', [('Expr', (1, 0, 1, 5), ('BinOp', (1, 0, 1, 5), ('Constant', (1, 0, 1, 1), 3, None), ('Mult',), ('Constant', (1, 4, 1, 5), 4, None)))])",
            "single ('Interactive', [('Assign', (1, 0, 1, 9), [('Name', (1, 0, 1, 5), 'total', ('Store',))], ('Constant', (1, 8, 1, 9), 9, None), None)])",
            "func_type ('FunctionType', [('Name', 'bytes', ('Load',)), ('Name', 'float', ('Load',))], ('Name', 'list', ('Load',)))",
            "func_type ('FunctionType', [('Subscript', ('Name', 'set', ('Load',)), ('Name', 'str', ('Load',)), ('Load',)), ('Subscript', ('Name', 'list', ('Load',)), ('Name', 'int', ('Load',)), ('Load',)), ('Subscript', ('Name', 'dict', ('Load',)), ('Tuple', [('Name', 'int', ('Load',)), ('Name', 'str', ('Load',))], ('Load',)), ('Load',))], ('Subscript', ('Name', 'dict', ('Load',)), ('Tuple', [('Name', 'int', ('Load',)), ('Name', 'bytes', ('Load',))], ('Load',)), ('Load',)))",
        ],
        32 * 1024 * 1024,
    );
}

// First public `ast` module slice. CPython's Lib/ast.py routes parse() through
// compile(..., PyCF_ONLY_AST); MiniPython now exposes the same entry point, but
// ast.dump() still returns the internal parser dump while the public AST node
// tree is being built out.
#[test]
fn cpython_ast_module_parse_dump_first_pass_subset() {
    assert_output(
        "import ast\nnode = ast.parse('x = 1')\nprint(type(node).__name__, type(node) == ast.Module)\nassign = node.body[0]\ntarget = assign.targets[0]\nprint(node._fields, assign._fields)\nprint(type(assign).__name__, isinstance(assign, ast.Assign), isinstance(node, ast.AST))\nprint(target.id, type(target.ctx).__name__, assign.value.value)\ndump = ast.dump(node)\nprint('Assign' in dump, 'Name' in dump, 'Constant' in dump)\nexpr = ast.parse('1 + 2', mode='eval')\nprint(type(expr).__name__)\nprint(type(expr.body).__name__, type(expr.body.op).__name__, 'BinOp' in ast.dump(expr), 'Add' in ast.dump(expr))\nsingle = ast.parse('1 + 2', mode='single')\nprint(type(single).__name__)\nfunc_type = ast.parse('(int, str) -> bool', mode='func_type')\nprint(type(func_type).__name__, 'FunctionType' in ast.dump(func_type))\nprint(ast.parse(node) is node)\nprint(ast.PyCF_ONLY_AST)",
        &[
            "Module True",
            "('body', 'type_ignores') ('targets', 'value', 'type_comment')",
            "Assign True True",
            "x Store 1",
            "True True True",
            "Expression",
            "BinOp Add True True",
            "Interactive",
            "FunctionType True",
            "True",
            "1024",
        ],
    );
    assert_output(
        "import ast\nfor call in [lambda: ast.parse(123), lambda: ast.parse('1', 123), lambda: ast.parse('1', mode='bad'), lambda: ast.dump('x')]:\n    try:\n        call()\n    except (TypeError, ValueError) as error:\n        print(error.__class__.__name__)",
        &["TypeError", "TypeError", "ValueError", "TypeError"],
    );
    assert_output(
        "import ast\nclass S(str):\n    pass\nclass B(bytes):\n    pass\nclass BA(bytearray):\n    pass\nfor source in [S('x = 1'), B(b'x = 2'), BA(b'x = 3')]:\n    node = ast.parse(source)\n    print(type(source).__name__, type(node).__name__, type(node.body[0]).__name__)",
        &["S Module Assign", "B Module Assign", "BA Module Assign"],
    );
    assert_output(
        "import ast\nclass S(str):\n    pass\nnode = ast.parse('1 + 2', mode=S('eval'))\nprint(type(node).__name__, type(node.body).__name__)",
        &["Expression BinOp"],
    );
    assert_output(
        "import ast\nclass S(str):\n    pass\nclass B(bytes):\n    pass\nclass FakePath:\n    def __init__(self, path):\n        self.path = path\n    def __fspath__(self):\n        return self.path\nfor filename in [S('<afile>'), B(b'<bfile>'), FakePath(S('<apath>')), FakePath(B(b'<bpath>'))]:\n    node = ast.parse('x = 1', filename=filename)\n    print(type(filename).__name__, type(node).__name__, type(node.body[0]).__name__)\nclass BadPath:\n    def __fspath__(self):\n        return 123\ntry:\n    ast.parse('x = 1', filename=BadPath())\nexcept TypeError as error:\n    print(error.__class__.__name__, 'BadPath.__fspath__' in str(error), str(error).endswith('not int'))",
        &[
            "S Module Assign",
            "B Module Assign",
            "FakePath Module Assign",
            "FakePath Module Assign",
            "TypeError True True",
        ],
    );
    assert_output(
        "import ast\nclass S(str):\n    pass\nclass FakePath:\n    def __init__(self, path):\n        self.path = path\n    def __fspath__(self):\n        return self.path\nfor label, filename in [('str-subclass', S('<sfile>')), ('path-str-subclass', FakePath(S('<psfile>')),)]:\n    try:\n        ast.parse('x =', filename=filename)\n    except SyntaxError as error:\n        print(label, repr(error.filename), type(error.filename).__name__, error.args[1][0] is error.filename)",
        &[
            "str-subclass '<sfile>' S True",
            "path-str-subclass '<psfile>' S True",
        ],
    );
}

