// Adapted from CPython Lib/test/test_ast/test_ast.py::ASTOptimizationTests::
// test_folding_match_case_allowed_expressions and
// test_match_case_not_folded_in_unoptimized_ast. Match literal patterns keep
// their expression shape at optimize=0, but optimize > 0 folds signed numbers
// and real-plus-imaginary forms to Constant nodes.
#[test]
fn cpython_ast_optimization_match_case_folding_subset() {
    assert_output(
        r#"import ast

def case_pattern(literal, level):
    tree = ast.parse('match subject:\n    case ' + literal + ':\n        pass', optimize=level)
    return tree.body[0].cases[0].pattern

def plain(value):
    # Adding 0 drops the sign of zero parts, which this check does not pin.
    if isinstance(value, complex):
        return complex(value.real + 0, value.imag + 0)
    return value + 0

def report(literal):
    pattern = case_pattern(literal, 1)
    leftover = sorted({type(n).__name__ for n in ast.walk(pattern) if isinstance(n, (ast.UnaryOp, ast.BinOp))})
    values = [plain(n.value) for n in ast.walk(pattern) if isinstance(n, ast.Constant)]
    print(literal, '=>', values, leftover or 'folded')

signed = ['-7', '-2.5', '-7j', '-2.5j', '-0', '-0.0', '-0j',
          '3 + 4j', '3 - 4j', '0.5 + 1.5j', '0.5 - 1.5j',
          '-3 + 2j', '-3 - 2j', '-0 + 5j', '-0 - 5j', '-0.5 + 0.25j', '-0.5 - 0.25j']
for literal in signed:
    report(literal)
for literal in signed:
    report('{' + literal + ': 0}')
report('{-1: 0, 2 + 3j: 1, -0.5 - 1j: 2}')
for shape in ['[-7, -2.5, -7j, -2.5j]', '[[-7], [[-2.5]], -7j, [-2.5j]]',
              '(-7, (-2.5, (-7j, -2.5j)))', '((-7, -2.5), [-7j, -2.5j])',
              '(((-7))) | [-2.5, *_]', '{-7: [-2.5, (-7j,)], 1: -2.5j}']:
    report(shape)
for level in (0, 1, 2):
    node = case_pattern('-2 - 6j', level).value
    print(level, type(node).__name__, getattr(node, 'value', None))"#,
        &[
            "-7 => [-7] folded",
            "-2.5 => [-2.5] folded",
            "-7j => [-7j] folded",
            "-2.5j => [-2.5j] folded",
            "-0 => [0] folded",
            "-0.0 => [0.0] folded",
            "-0j => [0j] folded",
            "3 + 4j => [(3+4j)] folded",
            "3 - 4j => [(3-4j)] folded",
            "0.5 + 1.5j => [(0.5+1.5j)] folded",
            "0.5 - 1.5j => [(0.5-1.5j)] folded",
            "-3 + 2j => [(-3+2j)] folded",
            "-3 - 2j => [(-3-2j)] folded",
            "-0 + 5j => [5j] folded",
            "-0 - 5j => [-5j] folded",
            "-0.5 + 0.25j => [(-0.5+0.25j)] folded",
            "-0.5 - 0.25j => [(-0.5-0.25j)] folded",
            "{-7: 0} => [-7, 0] folded",
            "{-2.5: 0} => [-2.5, 0] folded",
            "{-7j: 0} => [-7j, 0] folded",
            "{-2.5j: 0} => [-2.5j, 0] folded",
            "{-0: 0} => [0, 0] folded",
            "{-0.0: 0} => [0.0, 0] folded",
            "{-0j: 0} => [0j, 0] folded",
            "{3 + 4j: 0} => [(3+4j), 0] folded",
            "{3 - 4j: 0} => [(3-4j), 0] folded",
            "{0.5 + 1.5j: 0} => [(0.5+1.5j), 0] folded",
            "{0.5 - 1.5j: 0} => [(0.5-1.5j), 0] folded",
            "{-3 + 2j: 0} => [(-3+2j), 0] folded",
            "{-3 - 2j: 0} => [(-3-2j), 0] folded",
            "{-0 + 5j: 0} => [5j, 0] folded",
            "{-0 - 5j: 0} => [-5j, 0] folded",
            "{-0.5 + 0.25j: 0} => [(-0.5+0.25j), 0] folded",
            "{-0.5 - 0.25j: 0} => [(-0.5-0.25j), 0] folded",
            "{-1: 0, 2 + 3j: 1, -0.5 - 1j: 2} => [-1, (2+3j), (-0.5-1j), 0, 1, 2] folded",
            "[-7, -2.5, -7j, -2.5j] => [-7, -2.5, -7j, -2.5j] folded",
            "[[-7], [[-2.5]], -7j, [-2.5j]] => [-7j, -7, -2.5j, -2.5] folded",
            "(-7, (-2.5, (-7j, -2.5j))) => [-7, -2.5, -7j, -2.5j] folded",
            "((-7, -2.5), [-7j, -2.5j]) => [-7, -2.5, -7j, -2.5j] folded",
            "(((-7))) | [-2.5, *_] => [-7, -2.5] folded",
            "{-7: [-2.5, (-7j,)], 1: -2.5j} => [-7, 1, -2.5j, -2.5, -7j] folded",
            "0 BinOp None",
            "1 Constant (-2-6j)",
            "2 Constant (-2-6j)",
        ],
    );
}

