// Shared harness for the AST validator subsets below: `ld`/`st`/`num` build
// Load/Store names and constants, and `verdict(tag, node, want, mode)` wraps a
// node in the right root, compiles it, and prints the exception type when the
// message contains `want` (or `accepted` when `want` is None).
fn ast_validator_probe(cases: &str) -> String {
    let mut program = String::from(
        r#"import ast

LOAD = 'must have Load context but has Store instead'
STORE = 'must have Store context but has Load instead'

def ld(ident='v'):
    return ast.Name(id=ident, ctx=ast.Load())

def st(ident='v'):
    return ast.Name(id=ident, ctx=ast.Store())

def num(n=0):
    return ast.Constant(value=n)

def verdict(tag, node, want=None, mode='exec'):
    if isinstance(node, ast.mod):
        root = node
    elif isinstance(node, ast.stmt):
        root = ast.Module(body=[node], type_ignores=[])
    elif mode == 'eval':
        root = ast.Expression(body=node)
    elif mode == 'single':
        root = ast.Interactive(body=[ast.Expr(value=node)])
    else:
        root = ast.Module(body=[ast.Expr(value=node)], type_ignores=[])
    ast.fix_missing_locations(root)
    try:
        compile(root, '<validator>', mode)
    except (TypeError, ValueError) as exc:
        if want is not None and want in str(exc):
            print(tag + ':', type(exc).__name__)
        else:
            print(tag + ':', type(exc).__name__, 'unexpected', repr(str(exc)))
    else:
        print(tag + ':', 'accepted' if want is None else 'missing error')
"#,
    );
    program.push_str(cases);
    program
}

