fn cpython_ast_validator_simple_comp_source(factory: &str) -> String {
    format!(
        r#"import ast

kind = ast.{factory}

def ref(ident, ctx):
    return ast.Name(id=ident, ctx=ctx())

def clause(target, source, *conditions):
    return ast.comprehension(target=target, iter=source, ifs=list(conditions), is_async=0)

good = clause(ref('n', ast.Store), ref('numbers', ast.Load))
checks = [
    (kind(elt=ref('n', ast.Store), generators=[good]), 'must have Load context'),
    (kind(elt=ref('n', ast.Store), generators=[]), 'comprehension with no generators'),
    (kind(elt=ref('n', ast.Store), generators=[clause(ref('n', ast.Load), ref('numbers', ast.Load))]), 'must have Store context'),
    (kind(elt=ref('n', ast.Load), generators=[clause(ref('n', ast.Store), ref('numbers', ast.Store))]), 'must have Load context'),
    (kind(elt=ref('n', ast.Load), generators=[clause(ref('n', ast.Store), ref('numbers', ast.Load), None)]), 'None disallowed'),
    (kind(elt=ref('n', ast.Load), generators=[clause(ref('n', ast.Store), ref('numbers', ast.Load), ref('odd', ast.Store))]), 'must have Load context'),
]
for node, fragment in checks:
    tree = ast.fix_missing_locations(ast.Module(body=[ast.Expr(value=node)], type_ignores=[]))
    try:
        compile(tree, '<comprehension>', 'exec')
    except ValueError as exc:
        print(type(exc).__name__, fragment in str(exc))
    else:
        print('compiled')"#
    )
}

