#[test]
fn cpython_ast_validator_match_pattern_subset() {
    assert_output(
        r#"import ast

def name(ident, ctx=ast.Load):
    return ast.Name(id=ident, ctx=ctx())

def dotted(base, *attrs, last_ctx=ast.Load):
    node = base
    for i, attr in enumerate(attrs):
        node = ast.Attribute(value=node, attr=attr, ctx=(last_ctx if i == 0 else ast.Load)())
    return node

one = ast.Constant(value=1)
word = ast.Constant(value='w')
yes = ast.Constant(value=True)
match_one = ast.MatchValue(value=one)
match_word = ast.MatchValue(value=word)
bad_singleton = ast.MatchSingleton(value='text')
Point = name('Point')

def cls(target, patterns=(), attrs=(), kw=()):
    return ast.MatchClass(cls=target, patterns=list(patterns), kwd_attrs=list(attrs), kwd_patterns=list(kw))

patterns = {
    'value-store-base': ast.MatchValue(value=dotted(name('pkg', ast.Store), 'mod', 'attr')),
    'value-store-attr': ast.MatchValue(value=dotted(name('pkg'), 'mod', 'attr', last_ctx=ast.Store)),
    'value-ellipsis': ast.MatchValue(value=ast.Constant(value=...)),
    'value-bool': ast.MatchValue(value=ast.Constant(value=False)),
    'value-tuple': ast.MatchValue(value=ast.Constant(value=(4, 5))),
    'singleton-str': bad_singleton,
    'sequence-bad-item': ast.MatchSequence(patterns=[bad_singleton]),
    'nested-sequence-bad-item': ast.MatchSequence(patterns=[ast.MatchSequence(patterns=[bad_singleton])]),
    'mapping-length-mismatch': ast.MatchMapping(keys=[one, yes], patterns=[match_word]),
    'mapping-rest-keyword': ast.MatchMapping(keys=[yes, one], patterns=[match_word, match_one], rest='None'),
    'mapping-starred-key': ast.MatchMapping(keys=[yes, ast.Starred(value=name('extra'), ctx=ast.Load())], patterns=[match_word, match_one], rest='more'),
    'class-constant-base': cls(dotted(word, 'a', 'b')),
    'class-keyword-attr-name': cls(Point, attrs=['False'], kw=[match_one]),
    'class-attr-pattern-mismatch': cls(Point, kw=[match_one]),
    'class-bad-positional': cls(Point, patterns=[bad_singleton]),
    'class-star-positional': cls(Point, patterns=[ast.MatchStar()]),
    'class-star-keyword': cls(Point, kw=[ast.MatchStar()]),
    'class-constant-cls': cls(yes, attrs=['False'], kw=[match_one]),
    'star-keyword-name': ast.MatchSequence(patterns=[ast.MatchStar(name='None')]),
    'as-keyword-name': ast.MatchAs(name='True'),
    'or-empty': ast.MatchOr(patterns=[]),
    'or-single': ast.MatchOr(patterns=[match_one]),
    'or-bad-alternative': ast.MatchOr(patterns=[match_one, match_word, ast.MatchSingleton(value='zz')]),
    'as-underscore': ast.MatchAs(name='_'),
    'star-top-level': ast.MatchStar(name='tail'),
    'star-underscore': ast.MatchSequence(patterns=[ast.MatchStar(name='_')]),
    'mapping-rest-underscore': ast.MatchMapping(keys=[], patterns=[], rest='_'),
}

for tag, pattern in patterns.items():
    stmt = ast.Match(subject=name('subject'), cases=[ast.match_case(pattern=pattern, body=[ast.Pass()])])
    tree = ast.fix_missing_locations(ast.Module(body=[stmt], type_ignores=[]))
    try:
        compile(tree, '<patterns>', 'exec')
    except ValueError as exc:
        print(tag, type(exc).__name__)
    else:
        print(tag, 'compiled')"#,
        &[
            "value-store-base ValueError",
            "value-store-attr ValueError",
            "value-ellipsis ValueError",
            "value-bool ValueError",
            "value-tuple ValueError",
            "singleton-str ValueError",
            "sequence-bad-item ValueError",
            "nested-sequence-bad-item ValueError",
            "mapping-length-mismatch ValueError",
            "mapping-rest-keyword ValueError",
            "mapping-starred-key ValueError",
            "class-constant-base ValueError",
            "class-keyword-attr-name ValueError",
            "class-attr-pattern-mismatch ValueError",
            "class-bad-positional ValueError",
            "class-star-positional ValueError",
            "class-star-keyword ValueError",
            "class-constant-cls ValueError",
            "star-keyword-name ValueError",
            "as-keyword-name ValueError",
            "or-empty ValueError",
            "or-single ValueError",
            "or-bad-alternative ValueError",
            "as-underscore ValueError",
            "star-top-level ValueError",
            "star-underscore ValueError",
            "mapping-rest-underscore ValueError",
        ],
    );
}

