// Adapted from CPython `ASTValidatorTests.test_funcdef`.
#[test]
fn cpython_ast_validator_funcdef_exact_subset() {
    assert_output(
        &ast_validator_probe(r#"
nothing = ast.Pass()
blank = ast.arguments()
def function(sig=blank, **extra):
    extra.setdefault('body', [nothing])
    return ast.FunctionDef(name='handler', args=sig, **extra)
store_ann = [ast.arg(arg='item', annotation=st('Kind'))]
verdict('def-empty-body', function(body=[]), 'empty body on FunctionDef')
verdict('def-store-decorator', function(decorator_list=[st('wrap')]), LOAD)
verdict('def-store-returns', function(returns=st('Result')), LOAD)
verdict('def-positional-minimal', ast.FunctionDef('handler', ast.arguments(), [ast.Pass()]))
verdict('def-arg-annotation', function(ast.arguments(args=store_ann)), LOAD)
verdict('def-posonly-annotation', function(ast.arguments(posonlyargs=store_ann)), LOAD)
verdict('def-kwonly-annotation', function(ast.arguments(kwonlyargs=store_ann)), LOAD)
verdict('def-default-without-arg', function(ast.arguments(defaults=[num(1)])), 'more positional defaults than args')
verdict('def-kwdefault-without-kwonly', function(ast.arguments(kw_defaults=[num(2)])), 'length of kwonlyargs is not the same as kw_defaults')
verdict('def-store-default', function(ast.arguments(args=[ast.arg('item', ld('int'))], defaults=[st('fallback')])), LOAD)
pair = [ast.arg('left', ld('int')), ast.arg('right', ld('int'))]
verdict('def-store-kwdefault', function(ast.arguments(kwonlyargs=pair, kw_defaults=[None, st('fallback')])), LOAD)"#),
        &[
            "def-empty-body: ValueError",
            "def-store-decorator: ValueError",
            "def-store-returns: ValueError",
            "def-positional-minimal: accepted",
            "def-arg-annotation: ValueError",
            "def-posonly-annotation: ValueError",
            "def-kwonly-annotation: ValueError",
            "def-default-without-arg: ValueError",
            "def-kwdefault-without-kwonly: ValueError",
            "def-store-default: ValueError",
            "def-store-kwdefault: ValueError",
        ],
    );
}

