// Adapted from CPython `ASTValidatorTests.test_try`.
#[test]
fn cpython_ast_validator_try_exact_subset() {
    assert_output(
        &ast_validator_probe(r#"
def try_family(kind):
    label = kind.__name__
    ok = ast.Pass()
    bad = ast.Expr(value=st('oops'))
    catch_all = [ast.ExceptHandler(type=None, name='err', body=[ok])]
    def build(body, handlers=(), orelse=(), final=()):
        return kind(body=body, handlers=list(handlers), orelse=list(orelse), finalbody=list(final))
    verdict(label + '-empty-body', build([], final=[ok]), 'empty body on ' + label)
    verdict(label + '-store-in-body', build([bad], final=[ok]), LOAD)
    verdict(label + '-no-handlers-no-finally', build([ok]), label + ' has neither except handlers nor finalbody')
    verdict(label + '-orelse-without-handlers', build([ok], orelse=[ok], final=[ok]), label + ' has orelse but no except handlers')
    verdict(label + '-empty-handler', build([ok], [ast.ExceptHandler(type=None, name='err', body=[])]), 'empty body on ExceptHandler')
    verdict(label + '-store-handler-type', build([ok], [ast.ExceptHandler(type=st('Failure'), name='err', body=[ok])]), LOAD)
    verdict(label + '-store-in-orelse', build([ok], catch_all, [bad], [ok]), LOAD)
    verdict(label + '-store-in-finally', build([ok], catch_all, [ok], [bad]), LOAD)

try_family(ast.Try)"#),
        &[
            "Try-empty-body: ValueError",
            "Try-store-in-body: ValueError",
            "Try-no-handlers-no-finally: ValueError",
            "Try-orelse-without-handlers: ValueError",
            "Try-empty-handler: ValueError",
            "Try-store-handler-type: ValueError",
            "Try-store-in-orelse: ValueError",
            "Try-store-in-finally: ValueError",
        ],
    );
}

