// Adapted from CPython `CopyTests` in Lib/test/test_ast/test_ast.py. This
// ports the first shallow `copy.replace()` / `__replace__()` AST-node behavior
// without the larger pickle/deepcopy surface.
#[test]
fn cpython_ast_copy_replace_first_pass_subset() {
    assert_output(
        r#"import ast
import copy

node = ast.Name(id="x", ctx=ast.Load())
ctx = node.ctx
repl = copy.replace(node, id="y")
print(node.id, repl.id, repl.ctx is ctx, repl is node)

node.extra = object()
repl = copy.replace(node)
print(repl.id, repl.ctx is ctx, hasattr(repl, "extra"), hasattr(node, "extra"))

try:
    copy.replace(node, extra=1)
except TypeError as error:
    print(error.__class__.__name__, error)

del node.id
try:
    copy.replace(node)
except TypeError as error:
    print(error.__class__.__name__, error)
repl = copy.replace(node, id="z")
print(hasattr(node, "id"), repl.id, repl.ctx is ctx)

fn = ast.FunctionDef(name="foo", args=ast.arguments())
fn2 = copy.replace(fn, name="bar")
print(fn.name, fn2.name, fn2.returns, fn2.decorator_list)

parsed = ast.parse("x").body[0].value
lineno = object()
parsed2 = copy.replace(parsed, lineno=lineno)
print(parsed.lineno, parsed2.lineno is lineno, parsed2.id == parsed.id, parsed2.ctx is parsed.ctx)

class MyNode(ast.AST):
    _fields = ("name", "data")
    __match_args__ = ("name", "data")
name = "name"
data = object()
node = MyNode(name, data)
repl = copy.replace(node)
print(repl.name == name, repl.data is data, repl is node)
new_data = object()
repl = copy.replace(node, data=new_data)
print(repl.name == name, repl.data is new_data, node.data is data)

class MyAttrs(ast.AST):
    x = 0
    y = 1
    _attributes = ("x", "y")
node = MyAttrs()
marker = object()
repl = copy.replace(node, y=marker)
print(repl.x, repl.y is marker, node.y)

try:
    ast.Name(id="x").__replace__(1)
except TypeError as error:
    print(error.__class__.__name__, "positional" in str(error))
try:
    ast.Name(id="x").__replace__(**{object(): "y"})
except TypeError as error:
    print(error.__class__.__name__, "unexpected keyword argument <object object at 0x" in str(error))"#,
        &[
            "x y True False",
            "x True False True",
            "TypeError Name.__replace__ got an unexpected keyword argument 'extra'.",
            "TypeError Name.__replace__ missing 1 keyword argument: 'id'.",
            "False z True",
            "foo bar None []",
            "1 True True True",
            "True True False",
            "True True True",
            "0 True 1",
            "TypeError True",
            "TypeError True",
        ],
    );
}

// Adapted from CPython `CopyTests.test_copy_with_parents`. This focuses on
// the cyclic AST-object graph that matters for parent links without pulling in
// CPython's stack-limit support helpers.
#[test]
fn cpython_ast_deepcopy_parent_links_first_pass_subset() {
    assert_output_with_stack(
        r#"import ast
import copy

program = '''
def tally(rows, limit):
    seen = {}
    for index, row in enumerate(rows):
        if row is None:
            continue
        while index < limit:
            try:
                key = row[index] if index % 2 else -row[index]
                with guard(key) as slot:
                    if key not in seen and slot:
                        seen[key] = [k for k in range(key) if k > 0]
                    elif key:
                        seen[key] += (key, lambda v=key: v * 2)
                    else:
                        raise ValueError(f"bad {key!r}")
            except (KeyError, IndexError):
                break
            index += 1
    return {k: len(v) for k, v in seen.items()}
'''

original = ast.parse(program)
links = 0
for parent in ast.walk(original):
    for child in ast.iter_child_nodes(parent):
        child.parent = parent
        links += 1

duplicate = copy.deepcopy(original)
for node in ast.walk(original):
    if 'parent' in node.__dict__:
        del node.parent

shared_singletons = (ast.expr_context, ast.boolop, ast.operator, ast.unaryop, ast.cmpop)
own_links = 0
for parent in ast.walk(duplicate):
    for child in ast.iter_child_nodes(parent):
        if isinstance(child, shared_singletons):
            continue
        assert child.parent is parent, ast.dump(child)
        assert ast.compare(child.parent, parent)
        own_links += 1

print(duplicate is not original, links > 100, own_links > 80)
print(ast.compare(original, duplicate))
print(any('parent' in node.__dict__ for node in ast.walk(original)))
print([issubclass(kind, ast.AST) for kind in shared_singletons])"#,
        &[
            "True True True",
            "True",
            "False",
            "[True, True, True, True, True]",
        ],
        16 * 1024 * 1024,
    );
}

// Adapted from CPython `CopyTests.test_pickling`. MiniPython does not expose
// CPython's binary pickle protocol yet; this ports the observable AST
// round-trip semantics through the minimal `pickle.dumps()` / `pickle.loads()`
// surface over public AST trees.
#[test]
fn cpython_ast_pickle_roundtrip_first_pass_subset() {
    assert_output(
        r#"import ast
import pickle

samples = [
    "count = 0\n",
    "def mix(x, /, y=3, *more, flag, **opts):\n    return x * y\n",
    "match point:\n    case (0, other) if other:\n        found = other\n",
    "async def pump(q):\n    async with lock:\n        await q.put([i async for i in feed()])\n",
    "class Box[T](Base, meta=Meta):\n    size: int = 1\n",
]
matches = []
for protocol in range(pickle.HIGHEST_PROTOCOL + 1):
    for text in samples:
        tree = ast.parse(text)
        clone = pickle.loads(pickle.dumps(tree, protocol))
        matches.append(clone is not tree and ast.compare(clone, tree, compare_attributes=True))
print(len(matches) == len(samples) * (pickle.HIGHEST_PROTOCOL + 1), all(matches))

tree = ast.parse("total = price * qty\n")
blob = pickle.dumps(tree)
tree.body.clear()
restored = pickle.loads(blob)
print(len(restored.body), len(tree.body), ast.compare(restored, tree))
print(type(restored.body[0].value.op).__name__, restored.body[0].targets[0].id)"#,
        &["True True", "1 0 False", "Mult total"],
    );
}

// Adapted from CPython `CopyTests.test_replace_interface` and
// `CopyTests.test_replace_native`. This walks the native
// `ast.AST.__subclasses__()` tree and checks the class-level `__replace__`
// surface plus shallow field/location-attribute replacement across every
// exposed native AST class.
#[test]
fn cpython_ast_replace_native_class_iteration_first_pass_subset() {
    assert_output_with_stack(
        r#"import ast
import copy

def native_node_classes():
    found, pending = [], [ast.AST]
    while pending:
        cls = pending.pop()
        if cls.__module__ != 'ast' or cls.__name__ == 'Index':
            continue
        found.append(cls)
        pending.extend(reversed(cls.__subclasses__()))
    return found

classes = native_node_classes()
print(len(classes) > 50, all(k in classes for k in (ast.AST, ast.expr, ast.Name, ast.Add, ast.MatchClass)))
print(issubclass(ast.Name, ast.expr), isinstance(ast.Name('n'), ast.expr), ast.Name.__bases__ == (ast.expr,))
print(ast.stmt in ast.AST.__subclasses__(), ast.If in ast.stmt.__subclasses__(), ast.Store in ast.expr_context.__subclasses__())
replace_methods = sum(callable(getattr(cls, '__replace__', None)) for cls in classes)
rejected = {'copy.replace': 0, '__replace__': 0}
for cls in classes:
    node = cls(**{name: None for name in cls._fields})
    for label, call in [('copy.replace', lambda: copy.replace(node, 'positional')),
                        ('__replace__', lambda: node.__replace__('positional'))]:
        try:
            call()
        except TypeError:
            rejected[label] += 1
print(len(classes) > 50, replace_methods == len(classes), rejected == dict.fromkeys(rejected, len(classes)))
def expect(flag, label):
    if not flag:
        print('failed:', label)
    return flag

same, fields_changed, attrs_changed, field_total, attr_total = 0, 0, 0, 0, 0
for cls in classes:
    names, attrs = cls._fields, cls._attributes
    field_total += len(names)
    attr_total += len(attrs)
    field_values = {name: 'field:' + name for name in names}
    attr_values = {name: 'attr:' + name for name in attrs}
    for extra in ({}, attr_values):
        node = cls(**field_values, **extra)
        twin = copy.replace(node)
        same += expect(twin is not node and ast.compare(node, twin, compare_attributes=True), cls.__name__)
    for name in names:
        for extra in ({}, attr_values):
            node = cls(**field_values, **extra)
            before = getattr(node, name)
            marker = object()
            twin = copy.replace(node, **{name: marker})
            fields_changed += expect(getattr(node, name) is before and getattr(twin, name) is marker
                                     and not ast.compare(node, twin, compare_attributes=True), cls.__name__ + '.' + name)
    for name in attrs:
        node = cls(**field_values, **attr_values)
        before = getattr(node, name)
        marker = object()
        twin = copy.replace(node, **{name: marker})
        attrs_changed += expect(getattr(node, name) is before and getattr(twin, name) is marker
                                and not ast.compare(node, twin, compare_attributes=True), cls.__name__ + '.' + name)
print(same == 2 * len(classes), fields_changed == 2 * field_total, attrs_changed == attr_total)
print(field_total > 100, attr_total > 0)"#,
        &[
            "True True",
            "True True True",
            "True True True",
            "True True True",
            "True True True",
            "True True",
        ],
        8 * 1024 * 1024,
    );
}

#[test]
fn cpython_ast_copy_pickling_exact_subset() {
    assert_output(
        r#"import ast
import pickle

sources = [
    "flag = not ready\n",
    "for i, (a, *b) in pairs:\n    del a[i:]\nelse:\n    pass\n",
    "try:\n    run()\nexcept* (OSError, ValueError) as group:\n    log(group)\n",
    "@cached\ndef area(r: float) -> float:\n    return 3.14 * r ** 2\n",
]
results = {}
for protocol in range(pickle.HIGHEST_PROTOCOL + 1):
    for text in sources:
        tree = compile(text, "<pickle>", "exec", ast.PyCF_ONLY_AST)
        again = pickle.loads(pickle.dumps(tree, protocol=protocol))
        results[protocol, text] = ast.compare(again, tree, compare_attributes=True)
print(len(results), sum(results.values()), pickle.HIGHEST_PROTOCOL >= 5)"#,
        &["24 24 True"],
    );
}

