// Adapted from CPython `AST_Tests.test_filter_syntax_warnings_by_module`.
// MiniPython keeps the same warning-producing source rows and checks that
// `ast.parse()` emits tokenizer SyntaxWarnings through the public `warnings`
// capture surface.
#[test]
fn cpython_ast_filter_syntax_warnings_by_module_subset() {
    assert_output(
        r##"import ast
import warnings

source = r"""# Syntax warnings emitted in different parts of the Python compiler.

# Parser/lexer/lexer.c
x = 1or 0  # line 4

# Parser/tokenizer/helpers.c
'\z'  # line 7

# Parser/string_parser.c
'\400'  # line 10

# _PyCompile_Warn() in Python/codegen.c
assert(x, 'message')  # line 13
x is 1  # line 14

# _PyErr_EmitSyntaxWarning() in Python/ast_preprocess.c
def f():
    try:
        pass
    finally:
        return 42  # line 21
"""

def show(wlog):
    print(sorted([wm.lineno for wm in wlog]))
    for wm in wlog:
        print(wm.filename, wm.category is SyntaxWarning)

with warnings.catch_warnings(record=True) as wlog:
    warnings.simplefilter("error")
    warnings.filterwarnings("always", module=r"<unknown>\z")
    ast.parse(source)
show(wlog)

with warnings.catch_warnings(record=True) as wlog:
    warnings.simplefilter("error")
    warnings.filterwarnings("always", module=r"package\.module\z")
    warnings.filterwarnings("error", module=r"<unknown>")
    ast.parse(source, "syntax_warnings.py", module="package.module")
show(wlog)"##,
        &[
            "[4, 7, 10]",
            "<unknown> True",
            "<unknown> True",
            "<unknown> True",
            "[4, 7, 10]",
            "syntax_warnings.py True",
            "syntax_warnings.py True",
            "syntax_warnings.py True",
        ],
    );
}

// Adapted from CPython `AST_Tests.test_AST_objects` and
// `test_AST_fields_NULL_check`. This covers base `ast.AST` instances with
// custom attributes plus the CPython crash-regression path where deleting the
// class-level `_fields` descriptor makes AST construction raise AttributeError.
#[test]
fn cpython_ast_base_object_and_missing_fields_subset() {
    assert_output(
        r#"import ast

def show_error(fn, expected_type, fragment):
    try:
        fn()
    except Exception as error:
        print(error.__class__.__name__ == expected_type, fragment in str(error))
    else:
        print(False, False)

x = ast.AST()
print(x._fields == ())
x.foobar = 42
print(x.foobar)
print(x.__dict__["foobar"])
show_error(lambda: x.vararg, "AttributeError", "vararg")
show_error(lambda: ast.AST(2), "TypeError", "0 positional")

old_value = ast.AST._fields
try:
    del ast.AST._fields
    msg = "type object 'ast.AST' has no attribute '_fields'"
    show_error(lambda: ast.AST(arg1=123), "AttributeError", msg)
    show_error(lambda: ast.AST(), "AttributeError", msg)
finally:
    ast.AST._fields = old_value
print(ast.AST._fields == old_value)"#,
        &[
            "True",
            "42",
            "42",
            "True True",
            "True True",
            "True True",
            "True True",
            "True",
        ],
    );
}

// Adapted from CPython `AST_Tests.test_none_checks`. This mutates parser-built
// public AST nodes by replacing required fields with `None`, then checks that
// compile-from-AST rejects the tree with the CPython-style required-field
// `ValueError` instead of a generic type error or panic.
#[test]
fn cpython_ast_none_required_fields_subset() {
    assert_output(
        r#"import ast

cases = [
    ("import os.path as p", ast.alias, "name"),
    ("def g(q): return q", ast.arg, "arg"),
    ("[v for v in w]", ast.comprehension, "target"),
    ("{v for v in w}", ast.comprehension, "iter"),
    ("g(**w)", ast.keyword, "value"),
    ("match w:\n    case 1: pass", ast.match_case, "pattern"),
    ("with w as v: pass", ast.withitem, "context_expr"),
]
for src, kind, field in cases:
    mod = ast.parse(src)
    hits = [n for n in ast.walk(mod) if type(n) is kind]
    for n in hits:
        setattr(n, field, None)
    try:
        compile(mod, "<none-check>", "exec")
        outcome = "compiled"
    except ValueError as exc:
        outcome = "ValueError: " + str(exc)
    print(kind.__name__, field, len(hits), outcome)"#,
        &[
            "alias name 1 ValueError: field 'name' is required for alias",
            "arg arg 1 ValueError: field 'arg' is required for arg",
            "comprehension target 1 ValueError: field 'target' is required for comprehension",
            "comprehension iter 1 ValueError: field 'iter' is required for comprehension",
            "keyword value 1 ValueError: field 'value' is required for keyword",
            "match_case pattern 1 ValueError: field 'pattern' is required for match_case",
            "withitem context_expr 1 ValueError: field 'context_expr' is required for withitem",
        ],
    );
}

// Adapted from CPython `AST_Tests.test_field_attr_existence`. This walks the
// public `ast.__dict__` class surface and constructs each public AST class from
// its generated `__annotations__` shape, proving constructed AST nodes expose
// tuple-valued `_fields`.
#[test]
fn cpython_ast_field_attr_existence_subset() {
    assert_output(
        r#"import ast

def build(cls):
    values = {}
    for field, ann in cls.__annotations__.items():
        if ann is int:
            values[field] = 7
        elif ann is str:
            values[field] = "w"
        elif ann is object:
            values[field] = 2.5
        elif isinstance(ann, type) and issubclass(ann, ast.AST):
            values[field] = build(ann)
    return cls(**values)

names = []
for key in dir(ast):
    obj = getattr(ast, key)
    if key == "Index" or key == "AST" or not key[:1].isupper():
        continue
    if isinstance(obj, type) and issubclass(obj, ast.AST):
        names.append(key)

bad = [key for key in names if type(build(getattr(ast, key))._fields) is not tuple]
print(len(names) > 50, bad, "Constant" in names, "NodeVisitor" in names)
for cls in (ast.Name, ast.BinOp, ast.Assert):
    node = build(cls)
    print(cls.__name__, isinstance(node, ast.AST), type(node._fields).__name__, node._fields)"#,
        &[
            "True [] True False",
            "Name True tuple ('id', 'ctx')",
            "BinOp True tuple ('left', 'op', 'right')",
            "Assert True tuple ('test', 'msg')",
        ],
    );
}

// Adapted from CPython `AST_Tests` compare methods in
// Lib/test/test_ast/test_ast.py. This ports the public `ast.compare()` behavior
// for structural equality, runtime `_fields` / `_attributes` mutation, exact
// primitive type checks, fieldless operator nodes, and missing fields/attrs.
#[test]
fn cpython_ast_compare_first_pass_subset() {
    assert_output(
        r#"import ast

P = ast.parse
pairs = [("a.b = 3", "a.b = 3"), ("a.b = 3", "pass"), ("a.b = 3", "a.b"), ("def f(): pass", "if q: pass")]
print([ast.compare(P(x), P(y)) for x, y in pairs])

left = P("f(k) - 4", mode="eval")
right = P("f(k) - 4", mode="eval")
print(ast.compare(left, right))
left._fields += ("extra",)
left.extra = 11
print(ast.compare(left, right), ast.compare(right, left))
right._fields = left._fields
right.extra = 11
print(ast.compare(left, right), ast.compare(right, left))
right._attributes += ("note",)
right.note = "n"
print(ast.compare(left, right, compare_attributes=True), ast.compare(right, left, compare_attributes=True))
left._attributes = right._attributes
left.note = "n"
print(ast.compare(left, right, compare_attributes=True), ast.compare(right, left, compare_attributes=True))

C = ast.Constant
values = [(5, 5), (5, 5.0), (5, True), (0, False), ("s", "s"), ((), ()), (frozenset(), frozenset())]
print([ast.compare(C(x), C(y)) for x, y in values])

print(ast.compare(ast.Mult(), ast.Mult()), ast.compare(ast.Mult(), ast.Div()))
n1 = ast.Name("v")
n2 = ast.Name("v")
print(ast.compare(n1, n2))
del n1.id
print(ast.compare(n1, n2), ast.compare(n2, n1))
del n2.id
print(ast.compare(n1, n2))

spaced, packed = P("k * 3"), P("k*3")
print(ast.compare(spaced, packed), ast.compare(spaced, packed, compare_attributes=False), ast.compare(spaced, packed, compare_attributes=True))
n1 = ast.Name("v", lineno=4)
n2 = ast.Name("v", lineno=4)
print(ast.compare(n1, n2), ast.compare(n1, n2, compare_attributes=True))
del n2.lineno
print(ast.compare(n1, n2, compare_attributes=True), ast.compare(n1, n2))
del n1.lineno
print(ast.compare(n1, n2, compare_attributes=True))"#,
        &[
            "[True, False, False, False]",
            "True",
            "False False",
            "True True",
            "False False",
            "True True",
            "[True, False, False, False, True, True, True]",
            "True False",
            "True",
            "False False",
            "True",
            "True True False",
            "True True",
            "False True",
            "True",
        ],
    );
}

// Adapted from CPython `AST_Tests.test_compare_literals`. This pins
// `ast.compare()` literal equality to both value equality and exact public
// constant type, so bool/int/float/complex values that compare equal at runtime
// still compare unequal as AST constants.
#[test]
fn cpython_ast_compare_literals_exact_subset() {
    assert_output(
        r#"import ast

def same(x, y):
    return ast.compare(ast.Constant(value=x), ast.Constant(value=y))

samples = [3, -3, 3.0, 3j, True, False, 0, 0.0, "q", "Q", "été", b"q", (), (1,), frozenset({2}), None, ..., float("inf"), -float("inf")]
self_equal = sum(same(v, v) for v in samples)
distinct = sum(not same(samples[i], samples[j]) for i in range(len(samples)) for j in range(len(samples)) if i != j)
print(self_equal, len(samples), distinct, len(samples) * (len(samples) - 1))

numeric = [1, 1.0, 1 + 0j, True]
zeros = [0, 0.0, 0j, False]
for group in (numeric, zeros):
    print(all(a == b for a in group for b in group), [same(a, b) for a in group for b in group if a is not b].count(True))"#,
        &[
            "19 19 342 342",
            "True 0",
            "True 0",
        ],
    );
}

fn assert_ast_compare_mode_source(mode: &str, source: &str) {
    let program = format!(
        "import ast\nsource = {source:?}\nmode = {mode:?}\na = ast.parse(source, mode=mode)\nb = ast.parse(source, mode=mode)\nprint(ast.compare(a, b))"
    );
    assert_output(&program, &["True"]);
}

