#[test]
fn cpython_ast_node_transformer_first_pass_subset() {
    assert_output_with_stack(
        r#"import ast
print(ast.NodeVisitor.__module__, ast.NodeTransformer.__module__)
print(issubclass(ast.NodeTransformer, ast.NodeVisitor), isinstance(ast.NodeTransformer(), ast.NodeVisitor))

class Collect(ast.NodeVisitor):
    def __init__(self):
        self.seen = []
    def visit_Constant(self, node):
        self.seen.append(node.value)
    def visit_Name(self, node):
        self.seen.append(node.id)

c = Collect()
print(c.visit(ast.parse("total = a * 2 - 'z'")), c.seen)

class DropAnnotation(ast.NodeTransformer):
    def visit_Name(self, node):
        return None if node.id.startswith("Hint") else node

func_def = DropAnnotation().visit(ast.parse("def g(p) -> HintT:\n    return p")).body[0]
print(getattr(func_def, "returns", None) is None, func_def.args.args[0].arg)

class DropPass(ast.NodeTransformer):
    def visit_Pass(self, node):
        return None

body = DropPass().visit(ast.parse("if c:\n    pass\n    go()\n    pass")).body[0].body
print(len(body), type(body[0]).__name__)

class Fanout(ast.NodeTransformer):
    def visit_keyword(self, node):
        if node.arg != "seed":
            return node
        extra = ast.keyword(arg="seed2", value=ast.Constant(value=0))
        return [extra, node]

call = Fanout().visit(ast.parse("make(a, seed=9, size=3)")).body[0].value
print([(k.arg, k.value.value) for k in call.keywords])

class Rename(ast.NodeTransformer):
    def visit_Name(self, node):
        if node.id == "old":
            node.id = "new"
        return node

tree = Rename().visit(ast.parse("old(old.x)"))
print([n.id for n in ast.walk(tree) if isinstance(n, ast.Name)], tree.body[0].value.args[0].attr)

class Rewrap(ast.NodeTransformer):
    def visit_Call(self, node):
        node = self.generic_visit(node)
        callee = node.func
        if not (isinstance(callee, ast.Name) and callee.id == "show"):
            return node
        target = ast.Attribute(value=ast.Name(id="out", ctx=ast.Load()), attr="write", ctx=ast.Load())
        return ast.Call(func=target, args=node.args, keywords=[ast.keyword(arg="flush", value=ast.Constant(value=True))])

expr = Rewrap().visit(ast.parse("def h(v):\n    show(v)")).body[0].body[0].value
print(type(expr.func).__name__, expr.func.value.id, expr.func.attr, expr.args[0].id, expr.keywords[0].arg, expr.keywords[0].value.value)"#,
        &[
            "ast ast",
            "True True",
            "None ['total', 'a', 2, 'z']",
            "True p",
            "1 Expr",
            "[('seed2', 0), ('seed', 9), ('size', 3)]",
            "['new', 'new'] x",
            "Attribute out write v flush True",
        ],
        8 * 1024 * 1024,
    );
}

