#[test]
fn cpython_ast_literal_eval_diagnostics_first_pass_subset() {
    assert_output(
        r#"import ast

def attempt(arg):
    try:
        result = ast.literal_eval(arg)
    except Exception as exc:
        if isinstance(exc, SyntaxError):
            return type(exc).__name__ + ": " + exc.msg
        return type(exc).__name__ + ": " + str(exc).split("\n")[0]
    return "value " + repr(result)

one, two, three = (ast.Constant(value=v) for v in (10, 20, 30))
print(attempt(ast.Dict(keys=[one], values=[two, three])))
print(attempt(ast.Dict(keys=[one, two], values=[three])))
for text in ("  7.5", "\t[8]", "\t \t{9}"):
    print(attempt(text))
print(attempt("\n    (5,)"))
print(attempt("\n   \\\n   [\\\n  \\ "))
print(attempt("[\n 1,\n 2,\n f(3)]"))
bare = ast.UnaryOp(op=ast.USub(), operand=ast.UnaryOp(op=ast.USub(), operand=ast.Constant(value=4)))
print(hasattr(bare, "lineno"), attempt(bare).split(":")[:2])"#,
        &[
            "ValueError: malformed node or string: Dict(keys=[Constant(value=10, kind=None)], values=[Constant(value=20, kind=None), Constant(value=30, kind=None)])",
            "ValueError: malformed node or string: Dict(keys=[Constant(value=10, kind=None), Constant(value=20, kind=None)], values=[Constant(value=30, kind=None)])",
            "value 7.5",
            "value [8]",
            "value {9}",
            "IndentationError: unexpected indent",
            "IndentationError: unexpected indent",
            "ValueError: malformed node or string on line 4: Call(func=Name(id='f', ctx=Load()), args=[Constant(value=3, kind=None)], keywords=[])",
            "False ['ValueError', ' malformed node or string']",
        ],
    );
}

