fn cpython_ast_location_helpers_first_pass_subset() {
    assert_output(
        r#"import ast
keys = ("lineno", "col_offset", "end_lineno", "end_col_offset")
origin = ast.Constant("q", lineno=7, col_offset=2, end_lineno=8, end_col_offset=11)
target = ast.Constant("r")
print(ast.copy_location(target, origin) is target, [getattr(target, k) for k in keys])
print(ast.dump(target, include_attributes=True))
blank = ast.Name("q", ast.Load(), lineno=None, col_offset=None, end_lineno=None, end_col_offset=None)
kept = ast.Name("r", ast.Load(), lineno=5, col_offset=6, end_lineno=5, end_col_offset=7)
ast.copy_location(kept, blank)
print([getattr(kept, k) for k in keys])
stmt = ast.Return(ast.BinOp(ast.Constant(1.5), ast.Mult(), ast.Constant(3)))
print(ast.fix_missing_locations(stmt) is stmt)
print([(type(n).__name__, n.lineno, n.col_offset, n.end_lineno, n.end_col_offset) for n in ast.walk(stmt) if "lineno" in n._attributes])
tree = ast.Compare(ast.Constant(1, lineno=20, col_offset=0, end_lineno=21, end_col_offset=4), [ast.Lt()], [ast.Constant(2)])
print(ast.increment_lineno(tree, n=5) is tree)
print([(n.lineno, n.end_lineno) for n in ast.walk(tree) if "lineno" in n._attributes])
attr = ast.Attribute(ast.Name("m", ast.Load()), "x", ast.Load(), lineno=3)
ast.increment_lineno(attr)
print(attr.lineno, attr.end_lineno, attr.value.lineno)"#,
        &[
            "True [7, 2, 8, 11]",
            "Constant(value='r', lineno=7, col_offset=2, end_lineno=8, end_col_offset=11)",
            "[5, 6, None, None]",
            "True",
            "[('Return', 1, 0, 1, 0), ('BinOp', 1, 0, 1, 0), ('Constant', 1, 0, 1, 0), ('Constant', 1, 0, 1, 0)]",
            "True",
            "[(5, None), (25, 26), (5, None)]",
            "4 None 1",
        ],
    );
}

