#[test]
fn cpython_ast_recursion_detection_subset() {
    assert_output(
        r#"import ast
at = {"lineno": 1, "col_offset": 0}

def try_compile(expr, label):
    try:
        compile(ast.Expression(body=expr), "<cycle>", "eval")
        print(label, "compiled")
    except RecursionError as exc:
        print(label, type(exc).__name__)

seq = ast.List(elts=[], ctx=ast.Load(), **at)
seq.elts.append(seq)
try_compile(seq, "self")

first = ast.BinOp(left=ast.Constant(1, **at), op=ast.Add(), right=ast.Constant(2, **at), **at)
second = ast.BinOp(left=ast.Constant(3, **at), op=ast.Sub(), right=first, **at)
third = ast.UnaryOp(op=ast.Invert(), operand=second, **at)
first.left = third
try_compile(third, "ring")"#,
        &[
            "self RecursionError",
            "ring RecursionError",
        ],
    );
}

