#[test]
fn cpython_ast_function_class_end_positions_first_pass_subset() {
    assert_output(
        r#"import ast
seg = ast.get_source_segment
code = "def area(w: float,\n         h: float = 1.0,\n         *more: int,\n         **opts: dict) -> float:\n    return w * h"
fn = ast.parse(code).body[0]
print(fn.end_lineno, fn.end_col_offset)
a = fn.args
print([seg(code, n) for n in (fn.body[0], a.args[1], a.args[1].annotation, a.defaults[0], a.vararg, a.vararg.annotation, a.kwarg, a.kwarg.annotation, fn.returns)])
code = "class Pair(Base, Mixin):\n    left: int = 0\n    right: str"
cls = ast.parse(code).body[0]
print(cls.end_lineno, cls.end_col_offset, [seg(code, b) for b in cls.bases], [seg(code, s) for s in cls.body])
code = "class Meta(metaclass=registry.Kind, flag=True): ..."
cls = ast.parse(code).body[0]
print([seg(code, k.value) for k in cls.keywords], [seg(code, k) for k in cls.keywords])
code = "class Holder:\n    def size(self) -> int:\n        return 3"
method = ast.parse(code).body[0].body[0]
print(repr(seg(code, method, padded=True)), repr(seg(code, method)))"#,
        &[
            "5 16",
            "['return w * h', 'h: float', 'float', '1.0', 'more: int', 'int', 'opts: dict', 'dict', 'float']",
            "3 14 ['Base', 'Mixin'] ['left: int = 0', 'right: str']",
            "['registry.Kind', 'True'] ['metaclass=registry.Kind', 'flag=True']",
            "'    def size(self) -> int:\\n        return 3' 'def size(self) -> int:\\n        return 3'",
        ],
    );
}

