// Adapted from CPython `EndPositionTests.test_redundant_parenthesis` and
// `test_trailers_with_redundant_parenthesis`.
#[test]
fn cpython_ast_redundant_parentheses_source_segment_subset() {
    assert_output(
        r#"import ast

def segment_of(text, prefix=""):
    full = prefix + text
    node = ast.parse(full).body[0].value
    if prefix:
        node = node.value
    return type(node).__name__, ast.get_source_segment(full, node)

for text in ["(( (x * y) ))", "((( f ))) (1, 2)", "( (seq) ) [ 0 ]", "((obj)).attr", "(( g ))()"]:
    for prefix in ("", "await "):
        print(repr(prefix), segment_of(text, prefix))"#,
        &[
            "'' ('BinOp', 'x * y')",
            "'await ' ('BinOp', 'x * y')",
            "'' ('Call', '((( f ))) (1, 2)')",
            "'await ' ('Call', '((( f ))) (1, 2)')",
            "'' ('Subscript', '( (seq) ) [ 0 ]')",
            "'await ' ('Subscript', '( (seq) ) [ 0 ]')",
            "'' ('Attribute', '((obj)).attr')",
            "'await ' ('Attribute', '((obj)).attr')",
            "'' ('Call', '(( g ))()')",
            "'await ' ('Call', '(( g ))()')",
        ],
    );
}

