#[test]
fn cpython_ast_suite_end_positions_first_pass_subset() {
    assert_output(
        r#"import ast
code = "\n".join([
    "with open(p) as fh, lock:",
    "    data = fh.read()",
    "",
    "if a > 1:",
    "    r = 'big'",
    "elif a < 0:",
    "    r = 'neg'",
    "else:",
    "    r = 'small'",
    "",
    "async def walk():",
    "    async for k, v in items():",
    "        await k",
    "",
    "try:",
    "    risky()",
    "except (KeyError, ValueError) as err:",
    "    handle(err)",
    "finally:",
    "    done = 1",
    "",
    "del r",
])
tree = ast.parse(code)
for stmt in tree.body:
    print(type(stmt).__name__, stmt.lineno, stmt.end_lineno, stmt.end_col_offset)
seg = lambda node: ast.get_source_segment(code, node)
w, cond, fn, tr, last = tree.body
print(repr(seg(w.items[0].context_expr)), repr(seg(w.items[0].optional_vars)), repr(seg(w.body[0])))
print(repr(seg(cond.orelse[0].test)), repr(seg(cond.orelse[0].orelse[0])))
loop = fn.body[0]
print(type(loop).__name__, repr(seg(loop.target)), loop.end_lineno, loop.end_col_offset)
print(repr(seg(tr.handlers[0].type)), repr(seg(tr.finalbody[0])), tr.handlers[0].end_lineno)
print([seg(s).count("\n") for s in tree.body])
print(seg(cond).splitlines()[-1], seg(tr).endswith("done = 1"))"#,
        &[
            "With 1 2 20",
            "If 4 9 15",
            "AsyncFunctionDef 11 13 15",
            "Try 15 20 12",
            "Delete 22 22 5",
            "'open(p)' 'fh' 'data = fh.read()'",
            "'a < 0' \"r = 'small'\"",
            "AsyncFor 'k, v' 13 15",
            "'(KeyError, ValueError)' 'done = 1' 18",
            "[1, 5, 2, 5, 0]",
            "    r = 'small' True",
        ],
    );
}

