fn cpython_ast_suites_end_positions_exact_subset() {
    assert_output(
        r#"import ast
lines = [
    "for i in range(3):",
    "    total += i",
    "else:",
    "    total = -total",
    "while not ready:",
    "    wait(0.5)",
    "match cmd:",
    "    case 'go':",
    "        go()",
    "    case _:",
    "        stop()",
    "try:",
    "    pass",
    "except* OSError:",
    "    pass",
    "x = 0",
]
code = "\n".join(lines)
tree = ast.parse(code)
for stmt in tree.body:
    print(type(stmt).__name__, stmt.end_lineno, stmt.end_col_offset)
loop, spin, choice, guarded, _ = tree.body
print(ast.get_source_segment(code, loop.target), ast.get_source_segment(code, loop.orelse[0]))
print(ast.get_source_segment(code, spin.test), ast.get_source_segment(code, choice.cases[0].pattern))
print(choice.cases[1].body[0].end_lineno, ast.get_source_segment(code, guarded.handlers[0].type))"#,
        &[
            "For 4 18",
            "While 6 13",
            "Match 11 14",
            "TryStar 15 8",
            "Assign 16 5",
            "i total = -total",
            "not ready 'go'",
            "11 OSError",
        ],
    );
}

