// Adapted from CPython Lib/test/test_compile.py::TestSpecifics::test_compile_warning_in_finally.
// CPython compiles finally bodies through multiple internal paths; the
// Python-visible behavior is that each source warning is captured once.
#[test]
fn cpython_compile_specifics_warning_in_finally_subset() {
    assert_output(
        r#"import warnings

def lines_warned(text):
    with warnings.catch_warnings(record=True) as log:
        warnings.simplefilter("always")
        compile(text, "<fin>", "exec")
    return [(w.lineno, w.category.__name__, str(w.message)) for w in log]

plain = "try:\n    a = 1\nfinally:\n    a is 'x'\n    try:\n        b = 2\n    finally:\n        b is 3.5\n"
grouped = "try:\n    a = 1\nexcept* ValueError:\n    a = 2\nfinally:\n    a is 'x'\n    try:\n        pass\n    except* KeyError:\n        pass\n    finally:\n        a is 3.5\n"
for text in (plain, grouped):
    for item in sorted(lines_warned(text)):
        print(*item)"#,
        &[
            "4 SyntaxWarning \"is\" with 'str' literal. Did you mean \"==\"?",
            "8 SyntaxWarning \"is\" with 'float' literal. Did you mean \"==\"?",
            "6 SyntaxWarning \"is\" with 'str' literal. Did you mean \"==\"?",
            "12 SyntaxWarning \"is\" with 'float' literal. Did you mean \"==\"?",
        ],
    );
}

