// Adapted from CPython Lib/test/test_compile.py::TestSpecifics::
// test_docstring and test_docstring_interactive_mode. This checks public
// function/class/module `__doc__` behavior under compile optimize levels
// without depending on CPython bytecode or constant-table internals.
#[test]
fn cpython_compile_specifics_docstring_optimize_subset() {
    assert_output(
        r#"import ast
module_text = '''
def one():
    "first doc"
    return 1

def two():
    "first"
    "second"

def fmt():
    f"{1} formatted"

def joined():
    "left " "right"

def added():
    "a" + "b"

def repeated():
    "ab" * 2

def raw_bytes():
    b"raw"

class Holder:
    "holder doc"
    x = 1
'''
names = ["one", "two", "fmt", "joined", "added", "repeated", "raw_bytes", "Holder"]
for via_ast in (False, True):
    for level in (0, 1, 2):
        source = ast.parse(module_text, optimize=False) if via_ast else module_text
        scope = {}
        exec(compile(source, "<docs>", "exec", optimize=level), scope)
        print("ast" if via_ast else "text", level, [scope[n].__doc__ for n in names])
for level in (0, 1, 2):
    found = []
    for text in ('def item():\n    "item doc"\n', 'class item:\n    "item doc"\n'):
        scope = {}
        exec(compile(text, "<one>", "single", optimize=level), scope)
        found.append(scope["item"].__doc__)
    print("single", level, found)
for level in (-1, 0, 1, 2):
    scope = {}
    exec(compile("'top doc'\nvalue = 2", "<mod>", "exec", optimize=level), scope)
    dbg = eval(compile("__debug__", "<dbg>", "eval", optimize=level))
    print("module", level, scope.get("__doc__", "<absent>"), "__doc__" in scope, dbg)

def changeable():
    "changeable doc"

print(changeable.__doc__, changeable.__dict__)
changeable.__doc__ = ("tuple", "doc")
print(changeable.__doc__, changeable.__dict__)
del changeable.__doc__
print(changeable.__doc__, changeable.__dict__)"#,
        &[
            "text 0 ['first doc', 'first', None, 'left right', None, None, None, 'holder doc']",
            "text 1 ['first doc', 'first', None, 'left right', None, None, None, 'holder doc']",
            "text 2 [None, None, None, None, None, None, None, None]",
            "ast 0 ['first doc', 'first', None, 'left right', None, None, None, 'holder doc']",
            "ast 1 ['first doc', 'first', None, 'left right', None, None, None, 'holder doc']",
            "ast 2 [None, None, None, None, None, None, None, None]",
            "single 0 ['item doc', 'item doc']",
            "single 1 ['item doc', 'item doc']",
            "single 2 [None, None]",
            "module -1 top doc True True",
            "module 0 top doc True True",
            "module 1 top doc True False",
            "module 2 <absent> False False",
            "changeable doc {}",
            "('tuple', 'doc') {}",
            "None {}",
        ],
    );
}

// Adapted from CPython Lib/test/test_compile.py::TestSpecifics::
// test_none_assignment. CPython rejects `None` as a binding target across
// assignment, augmented assignment, definitions, loops, parameters, and import
// aliases in both `single` and `exec` compile modes.
#[test]
fn cpython_compile_specifics_none_assignment_subset() {
    assert_output(
        r#"templates = [
    "{t} = 1",
    "{t} -= 1",
    "box.{t} = 1",
    "def {t}(): pass",
    "class {t}: pass",
    "[first, {t}] = 1, 2",
    "for {t} in (): pass",
    "def f(a, {t}=2): pass",
    "def f(*, {t}): pass",
    "lambda {t}: 0",
    "import {t}",
    "import pkg as {t}",
    "from pkg import {t}",
    "from pkg import thing as {t}",
    "with ctx as {t}: pass",
    "try:\n    pass\nexcept E as {t}:\n    pass",
    "({t} := 3)",
    "del {t}",
]
targets = ["None", "True", "False", "plain"]
for template in templates:
    verdicts = []
    for target in targets:
        stmt = template.replace("{t}", target)
        results = set()
        for mode in ("single", "exec"):
            try:
                compile(stmt + "\n", "<none>", mode)
                results.add("ok")
            except SyntaxError:
                results.add("SyntaxError")
        verdicts.append(target + "=" + "/".join(sorted(results)))
    print(repr(template), " ".join(verdicts))"#,
        &[
            "'{t} = 1' None=SyntaxError True=SyntaxError False=SyntaxError plain=ok",
            "'{t} -= 1' None=SyntaxError True=SyntaxError False=SyntaxError plain=ok",
            "'box.{t} = 1' None=SyntaxError True=SyntaxError False=SyntaxError plain=ok",
            "'def {t}(): pass' None=SyntaxError True=SyntaxError False=SyntaxError plain=ok",
            "'class {t}: pass' None=SyntaxError True=SyntaxError False=SyntaxError plain=ok",
            "'[first, {t}] = 1, 2' None=SyntaxError True=SyntaxError False=SyntaxError plain=ok",
            "'for {t} in (): pass' None=SyntaxError True=SyntaxError False=SyntaxError plain=ok",
            "'def f(a, {t}=2): pass' None=SyntaxError True=SyntaxError False=SyntaxError plain=ok",
            "'def f(*, {t}): pass' None=SyntaxError True=SyntaxError False=SyntaxError plain=ok",
            "'lambda {t}: 0' None=SyntaxError True=SyntaxError False=SyntaxError plain=ok",
            "'import {t}' None=SyntaxError True=SyntaxError False=SyntaxError plain=ok",
            "'import pkg as {t}' None=SyntaxError True=SyntaxError False=SyntaxError plain=ok",
            "'from pkg import {t}' None=SyntaxError True=SyntaxError False=SyntaxError plain=ok",
            "'from pkg import thing as {t}' None=SyntaxError True=SyntaxError False=SyntaxError plain=ok",
            "'with ctx as {t}: pass' None=SyntaxError True=SyntaxError False=SyntaxError plain=ok",
            "'try:\\n    pass\\nexcept E as {t}:\\n    pass' None=SyntaxError True=SyntaxError False=SyntaxError plain=ok",
            "'({t} := 3)' None=SyntaxError True=SyntaxError False=SyntaxError plain=ok",
            "'del {t}' None=SyntaxError True=SyntaxError False=SyntaxError plain=ok",
        ],
    );
}

// Adapted from CPython Lib/test/test_compile.py::TestSpecifics::test_import.
// This checks the compile-time grammar boundary for ordinary and parenthesized
// import/from-import forms without requiring the imported modules to execute.
#[test]
fn cpython_compile_specifics_import_syntax_subset() {
    assert_output(
        r#"templates = [
    "import {m}", "import {m}, {n}", "import {m} as alias", "import {m}.{s} as alias",
    "import ({m}, {n})", "import ({m}), ({n})", "import (({m}), ({n}))", "import ({m}",
    "import {m})", "import ({m},)", "import {m} AS alias", "import {m}.{s} az alias",
    "from {m} import {s}, {t}", "from {m} import ({s},\n{t})", "from {m} import ({s},\n{t},)",
    "from {m} import ({s}\n, {t})", "from {m} import ({s}\n, {t},)",
    "from {m} import {s} as x, {t} as y", "from {m} import ({s} as x, {t} as y)",
    "from {m} import ({s} as x, {t} as y,)", "from {m} import {s} As x", "from {m} import {s} az x",
    "from ({m}) import {s}", "from {m} import ({s}", "from {m} import {s})",
    "from {m} import {s},\n{t}", "from {m} import {s}, {t},\n{n}", "from {m} import {s} x",
    "from {m} import {s},", "from {m} import (*)", "from {m} import ({s},, {t})",
    "from {m} import ({s}, {t}),", "from {m} import *", "from . import {s}", "from ..{m} import ({s})",
]
groups = [("json", "re", "dumps", "loads"), ("__future__", "sys", "annotations", "division")]
for m, n, s, t in groups:
    for template in templates:
        stmt = template.replace("{m}", m).replace("{n}", n).replace("{s}", s).replace("{t}", t)
        try:
            compile(stmt, "<imp>", "exec")
            verdict = "ok"
        except SyntaxError:
            verdict = "SyntaxError"
        print(verdict, repr(stmt))"#,
        &[
            "ok 'import json'",
            "ok 'import json, re'",
            "ok 'import json as alias'",
            "ok 'import json.dumps as alias'",
            "SyntaxError 'import (json, re)'",
            "SyntaxError 'import (json), (re)'",
            "SyntaxError 'import ((json), (re))'",
            "SyntaxError 'import (json'",
            "SyntaxError 'import json)'",
            "SyntaxError 'import (json,)'",
            "SyntaxError 'import json AS alias'",
            "SyntaxError 'import json.dumps az alias'",
            "ok 'from json import dumps, loads'",
            "ok 'from json import (dumps,\\nloads)'",
            "ok 'from json import (dumps,\\nloads,)'",
            "ok 'from json import (dumps\\n, loads)'",
            "ok 'from json import (dumps\\n, loads,)'",
            "ok 'from json import dumps as x, loads as y'",
            "ok 'from json import (dumps as x, loads as y)'",
            "ok 'from json import (dumps as x, loads as y,)'",
            "SyntaxError 'from json import dumps As x'",
            "SyntaxError 'from json import dumps az x'",
            "SyntaxError 'from (json) import dumps'",
            "SyntaxError 'from json import (dumps'",
            "SyntaxError 'from json import dumps)'",
            "SyntaxError 'from json import dumps,\\nloads'",
            "SyntaxError 'from json import dumps, loads,\\nre'",
            "SyntaxError 'from json import dumps x'",
            "SyntaxError 'from json import dumps,'",
            "SyntaxError 'from json import (*)'",
            "SyntaxError 'from json import (dumps,, loads)'",
            "SyntaxError 'from json import (dumps, loads),'",
            "ok 'from json import *'",
            "ok 'from . import dumps'",
            "ok 'from ..json import (dumps)'",
            "ok 'import __future__'",
            "ok 'import __future__, sys'",
            "ok 'import __future__ as alias'",
            "ok 'import __future__.annotations as alias'",
            "SyntaxError 'import (__future__, sys)'",
            "SyntaxError 'import (__future__), (sys)'",
            "SyntaxError 'import ((__future__), (sys))'",
            "SyntaxError 'import (__future__'",
            "SyntaxError 'import __future__)'",
            "SyntaxError 'import (__future__,)'",
            "SyntaxError 'import __future__ AS alias'",
            "SyntaxError 'import __future__.annotations az alias'",
            "ok 'from __future__ import annotations, division'",
            "ok 'from __future__ import (annotations,\\ndivision)'",
            "ok 'from __future__ import (annotations,\\ndivision,)'",
            "ok 'from __future__ import (annotations\\n, division)'",
            "ok 'from __future__ import (annotations\\n, division,)'",
            "ok 'from __future__ import annotations as x, division as y'",
            "ok 'from __future__ import (annotations as x, division as y)'",
            "ok 'from __future__ import (annotations as x, division as y,)'",
            "SyntaxError 'from __future__ import annotations As x'",
            "SyntaxError 'from __future__ import annotations az x'",
            "SyntaxError 'from (__future__) import annotations'",
            "SyntaxError 'from __future__ import (annotations'",
            "SyntaxError 'from __future__ import annotations)'",
            "SyntaxError 'from __future__ import annotations,\\ndivision'",
            "SyntaxError 'from __future__ import annotations, division,\\nsys'",
            "SyntaxError 'from __future__ import annotations x'",
            "SyntaxError 'from __future__ import annotations,'",
            "SyntaxError 'from __future__ import (*)'",
            "SyntaxError 'from __future__ import (annotations,, division)'",
            "SyntaxError 'from __future__ import (annotations, division),'",
            "SyntaxError 'from __future__ import *'",
            "ok 'from . import annotations'",
            "ok 'from ..__future__ import (annotations)'",
        ],
    );
}

// Adapted from CPython Lib/test/test_compile.py::TestSpecifics successful
// compile/runtime regression methods that do not require code-object metadata:
// `test_extended_arg`, `test_sequence_unpacking_error`, `test_annotation_limit`,
// `test_condition_expression_with_dead_blocks_compiles`,
// `test_condition_expression_with_redundant_comparisons_compiles`,
// `test_dead_code_with_except_handler_compiles`, and
// `test_try_except_in_while_with_chained_condition_compiles`.
#[test]
fn cpython_compile_specifics_compile_stability_subset() {
    let longexpr = format!("x = x or {}", "-x".repeat(100));
    assert_output(
        &format!(
            "def f(x):\n    {}\n    {}\n    {}\n    {}\n    {}\n    {}\n    {}\n    {}\n    {}\n    {}\n    while x:\n        x -= 1\n    return x\nprint(f(5))",
            longexpr,
            longexpr,
            longexpr,
            longexpr,
            longexpr,
            longexpr,
            longexpr,
            longexpr,
            longexpr,
            longexpr
        ),
        &["0"],
    );

    assert_output("i, j = (1, -1) or (-1, 1)\nprint(i, j)", &["1 -1"]);

    let params = (0..300)
        .map(|index| format!("a{index}:{index}"))
        .collect::<Vec<_>>()
        .join(", ");
    assert_output(
        &format!("compile('def f({params}): pass', '?', 'exec')\nprint('annotation-limit-ok')"),
        &["annotation-limit-ok"],
    );

    assert_output(
        r#"import warnings
chains = ["if 3<4<5and 6" + "or 7" * k + ":pass" for k in range(1, 6)]
chains += ["while 1>2>3or 4" + "and 5" * k + ":break" for k in range(1, 4)]
constant_tests = [
    "if (1 if 0 else Q): pass",
    "while (0 if 1 else R): pass",
    "z = (A if 7 else B) or C",
]
dead_blocks = [
    "if 0:\n    with ctx as c:\n        y = c\nelse:\n    y = 2\n",
    "if False:\n    try:\n        y = 1\n    except Exception:\n        y = 3\n",
]
loops = [
    "p, q, r = 3, 2, 1\nwhile p >= q < r:\n    try:\n        raise\n    except:\n        continue\n    finally:\n        break\n",
    "p, q = 1, 2\nwhile p < q < 5 and p:\n    try:\n        p += 1\n    except ValueError:\n        pass\n",
]
with warnings.catch_warnings():
    warnings.simplefilter("ignore")
    for text in chains + constant_tests + dead_blocks + loops:
        compile(text, "<stable>", "exec")
scope = {"ctx": None}
exec(dead_blocks[0], scope)
exec(loops[1], scope)
print(len(chains + constant_tests + dead_blocks + loops), scope["y"], scope["p"])"#,
        &[
            "15 2 2",
        ],
    );
}

// Adapted from CPython Lib/test/test_compile.py::TestSpecifics::
// test_compile_invalid_namedexpr and test_compile_invalid_typealias.
// These validate public AST-to-code rejection messages rather than parser
// syntax errors.
#[test]
fn cpython_compile_specifics_invalid_public_ast_subset() {
    assert_output(
        r#"import ast

def build_and_compile(stmt):
    tree = ast.fix_missing_locations(ast.Module(body=[stmt], type_ignores=[]))
    try:
        compile(tree, "<built>", "exec")
        return "compiled"
    except (TypeError, ValueError) as exc:
        return type(exc).__name__ + ": " + str(exc)

load, store = ast.Load(), ast.Store()
slot = ast.Attribute(value=ast.Name("obj", load), attr="slot", ctx=store)
walrus = ast.NamedExpr(target=slot, value=ast.Constant(7))
print(build_and_compile(ast.If(test=walrus, body=[ast.Pass()], orelse=[])))
loop = ast.comprehension(target=ast.Name("i", store), iter=ast.Name("data", load), ifs=[], is_async=0)
inside = ast.SetComp(elt=ast.NamedExpr(target=ast.Constant("k"), value=ast.Constant(0)), generators=[loop])
print(build_and_compile(ast.Expr(inside)))
fine = ast.NamedExpr(target=ast.Name("k", store), value=ast.Constant(0))
print(build_and_compile(ast.Expr(fine)))
dotted = ast.Attribute(value=ast.Name("mod", load), attr="Alias", ctx=store)
print(build_and_compile(ast.TypeAlias(name=dotted, type_params=[], value=ast.Name("int", load))))
print(build_and_compile(ast.TypeAlias(name=ast.Name("Alias", store), type_params=[], value=ast.Name("int", load))))"#,
        &[
            "TypeError: NamedExpr target must be a Name",
            "TypeError: NamedExpr target must be a Name",
            "compiled",
            "TypeError: TypeAlias with non-Name name",
            "compiled",
        ],
    );
}

// Adapted from CPython Lib/test/test_compile.py::TestSpecifics::
// test_compile_ast. This covers the public source -> AST -> code path for the
// small sample matrix plus the public TypeError boundaries for mismatched
// start nodes and invalid AST children.
#[test]
fn cpython_compile_specifics_compile_ast_public_subset() {
    assert_output(
        r#"import ast
sample_code = [
    ["<assign>", "x = 5"],
    ["<ifblock>", "if True:\n    pass\n"],
    ["<forblock>", "for n in [1, 2, 3]:\n    print(n)\n"],
    ["<deffunc>", "def foo():\n    pass\nfoo()\n"],
]
for fname, code in sample_code:
    co1 = compile(code, fname + "1", "exec")
    tree = compile(code, fname + "2", "exec", ast.PyCF_ONLY_AST)
    print(type(tree).__name__, co1 == compile(tree, fname + "3", "exec"), compile(tree, fname + "3", "exec").co_filename)

tree = compile("print(1)", "<string>", "exec", ast.PyCF_ONLY_AST)
try:
    compile(tree, "<ast>", "eval")
except TypeError as error:
    print("mode", error.__class__.__name__)

try:
    compile(ast.If(test=ast.Name(id="x", ctx=ast.Load())), "<ast>", "exec")
except TypeError as error:
    print("start", error.__class__.__name__)

bad = ast.Module()
bad.body = [ast.BoolOp(op=ast.Or())]
try:
    compile(bad, "<ast>", "exec")
except TypeError as error:
    print("children", error.__class__.__name__)"#,
        &[
            "Module True <assign>3",
            "Module True <ifblock>3",
            "Module True <forblock>3",
            "Module True <deffunc>3",
            "mode TypeError",
            "start TypeError",
            "children TypeError",
        ],
    );
}

