// Adapted from CPython Lib/test/test_compile.py::TestSpecifics::
// test_unary_minus and the 64-bit-platform test_32_63_bit_values branch.
// MiniPython does not promise CPython's exact constant-folding table shape;
// this pins the public int semantics and code-object constants exposed today.
#[test]
fn cpython_compile_specifics_integer_constant_edges_subset() {
    assert_output(
        r#"print(eval("0xffffffffffffffff") == 18446744073709551615)
print(eval("-0xffffffffffffffff") == -18446744073709551615)
print(isinstance(eval("-9223372036854775808"), int))
print(isinstance(eval("-9223372036854775809"), int))
def constants():
    a = +4294967296
    b = -4294967296
    c = +281474976710656
    d = -281474976710656
    e = +4611686018427387904
    f = -4611686018427387904
    g = +9223372036854775807
    h = -9223372036854775807
consts = constants.__code__.co_consts
print(4294967296 in consts)
print(281474976710656 in consts)
print(4611686018427387904 in consts)
print(9223372036854775807 in consts)
all_ints = True
for variable in consts:
    if variable is not None and not isinstance(variable, int):
        all_ints = False
print(all_ints)"#,
        &[
            "True", "True", "True", "True", "True", "True", "True", "True", "True",
        ],
    );
}

// Adapted from CPython Lib/test/test_compile.py::TestSpecifics::
// test_int_literals_too_long. Decimal integer source literals must honor
// sys.set_int_max_str_digits() during compile(), report the source line of the
// offending literal, and keep hexadecimal literals outside the decimal
// conversion limit.
#[test]
fn cpython_compile_specifics_int_literals_too_long_subset() {
    assert_output(
        r#"import sys
old_limit = sys.get_int_max_str_digits()
n = 3000
source = "a = 1\nb = 2\nc = " + "3" * n + "\nd = 4"
sys.set_int_max_str_digits(n)
try:
    compile(source, "<long_int_pass>", "exec")
    print("pass-ok")
finally:
    sys.set_int_max_str_digits(old_limit)
sys.set_int_max_str_digits(n - 1)
try:
    compile(source, "<long_int_fail>", "exec")
except SyntaxError as error:
    print(error.lineno)
    text = str(error)
    print("Exceeds the limit " in text, " Consider hexadecimal " in text)
finally:
    sys.set_int_max_str_digits(old_limit)
sys.set_int_max_str_digits(640)
try:
    compile("value = 0x" + "f" * 1000, "<hex_int_pass>", "exec")
    print("hex-ok")
finally:
    sys.set_int_max_str_digits(old_limit)"#,
        &["pass-ok", "3", "True True", "hex-ok"],
    );
}

// Adapted from CPython Lib/test/test_compile.py::TestSpecifics public compile
// and execution regressions around conditional expressions, multiline lambda
// arguments, duplicate assignment targets, dependent stores, and control-flow
// compile stability. These pin observable MiniPython behavior rather than
// CPython opcode layout.
#[test]
fn cpython_compile_specifics_public_regression_shapes_subset() {
    assert_output(
        r#"shapes = [
    "assert not (0 if 7 else 1)",
    "def g():\n\tif (1 if 0 else 0): raise ValueError",
    "def g():\n\tif not (0 if 3 else 1):\n\t\treturn 'yes'",
    "def call(a, fn):\n    return fn()\n\ncall(a=1,\n     fn=lambda:\n     2)\n",
    "def g(items, flag):\n    while items and flag:\n        try:\n            return items.pop()\n        except IndexError:\n            pass\n",
    "def g(n):\n    while n:\n        try:\n            break\n        except Exception:\n            pass\n    else:\n        0 if n else 1\n",
    "def g(n):\n    while n:\n        n if 0 else n\n        n -= 1\n",
    "def g(p, q, r, s):\n    return p if (q if r else s) else 0\n",
    "async def g(src):\n    match src:\n        case 0:\n            pass\n        case [*rest] if f'{rest}':\n            return {k: v async for k, v in src}\n        case {}:\n            pass\n    ()\n",
]
for text in shapes:
    compile(text, "<shape>", "exec")
print(len(shapes), "shapes compiled")

def last_wins(p, q, r):
    s, t, s = p, q, r
    u, u = s, t
    return s, t, u

print(last_wins(1, 2, 3))

def rebind():
    n = 7; m = n * 2; n = 0
    return n, m

print(rebind())
glob = {"counter": 11}
loc = {}
for handler in ("except ValueError:", "except* ValueError:"):
    text = "def h():\n    try:\n        pass\n    " + handler + "\n        global counter\n    else:\n        return counter\n"
    exec(text, glob, loc)
    print(handler, loc["h"]())

class SubDict(dict):
    pass

space = {}
exec("def read():\n    return hidden_name", SubDict(), space)
try:
    space["read"]()
except NameError as exc:
    print(type(exc).__name__, exc)"#,
        &[
            "9 shapes compiled",
            "(3, 2, 2)",
            "(0, 14)",
            "except ValueError: 11",
            "except* ValueError: 11",
            "NameError name 'hidden_name' is not defined",
        ],
    );
}

// Adapted from CPython Lib/test/test_compile.py::TestSpecifics::
// test_single_statement and test_bad_single_statement. `single` mode accepts
// one interactive statement, including semicolon-separated simple statements
// and newline-terminated compound statements, while rejecting multiple
// physical statements and unterminated inline compound statements.
#[test]
fn cpython_compile_specifics_single_statement_subset() {
    assert_output(
        r#"accepted = [
    '1 + 2',
    '\n1 + 2',
    '1 + 2\n',
    '1 + 2\n\n',
    '1 + 2\t\t\n',
    '1 + 2\t\t\n        ',
    '1 + 2 # one plus two',
    '1; 2',
    'import sys; sys',
    'def f():\n   pass',
    'while False:\n   pass',
    'if x:\n   f(x)',
    'if x:\n   f(x)\nelse:\n   g(x)',
    'class T:\n   pass',
    "c = '''\na=1\nb=2\nc=3\n'''",
]
for source in accepted:
    compile(source, '<single>', 'single')
print('single-accepted-ok')
invalid = [
    '1\n2',
    'def f(): pass',
    'a = 13\nb = 187',
    'del x\ndel y',
    'f()\ng()',
    'f()\n# blah\nblah()',
    'f()\nxy # blah\nblah()',
    'x = 5 # comment\nx = 6\n',
    "c = '''\nd=1\n'''\na = 1\n\nb = 2\n",
]
for source in invalid:
    try:
        compile(source, '<single>', 'single')
    except SyntaxError:
        pass
    else:
        print('accepted-invalid', repr(source))
print('single-invalid-ok')"#,
        &["single-accepted-ok", "single-invalid-ok"],
    );
}

// Adapted from CPython Lib/test/test_compile.py::TestSpecifics::
// test_dict_evaluation_order. Dict displays must evaluate each key before its
// corresponding value and proceed left to right.
#[test]
fn cpython_compile_specifics_dict_evaluation_order_subset() {
    assert_output(
        r#"calls = []

def mark(tag):
    calls.append(tag)
    return tag

table = {mark("k1"): mark("v1"), mark("k2"): mark("v2"), **{mark("k3"): mark("v3")}}
print(calls)
print(table)"#,
        &[
            "['k1', 'v1', 'k2', 'v2', 'k3', 'v3']",
            "{'k1': 'v1', 'k2': 'v2', 'k3': 'v3'}",
        ],
    );
}

// Adapted from CPython Lib/test/test_compile.py::TestSpecifics::
// test_compile_filename. MiniPython now exposes the public `co_filename`
// attribute for compiled code objects, accepts str/bytes filenames, and
// supports the path-like `__fspath__` protocol for filename objects.
#[test]
fn cpython_compile_specifics_compile_filename_subset() {
    assert_output(
        "class S(str):\n    pass\nclass B(bytes):\n    pass\nfor filename in ['file.py', b'file.py']:\n    code = compile('pass', filename, 'exec')\n    print(code.co_filename)\ncode = compile('pass', S('str_subclass.py'), 'exec')\nprint(code.co_filename, type(code.co_filename).__name__)\ncode = compile('pass', B(b'bytes_subclass.py'), 'exec')\nprint(code.co_filename, type(code.co_filename).__name__)\nfor label, expr in [('bytearray', lambda: compile('pass', bytearray(b'file.py'), 'exec')), ('memoryview', lambda: compile('pass', memoryview(b'file.py'), 'exec')), ('list', lambda: compile('pass', [102, 105, 108, 101], 'exec'))]:\n    try:\n        expr()\n    except TypeError as error:\n        print(label, error.__class__.__name__, str(error))",
        &[
            "file.py",
            "file.py",
            "str_subclass.py S",
            "bytes_subclass.py str",
            "bytearray TypeError expected str, bytes or os.PathLike object, not bytearray",
            "memoryview TypeError expected str, bytes or os.PathLike object, not memoryview",
            "list TypeError expected str, bytes or os.PathLike object, not list",
        ],
    );
    assert_output(
        "class S(str):\n    pass\nclass B(bytes):\n    pass\nclass FakePath:\n    def __init__(self, path):\n        self.path = path\n    def __fspath__(self):\n        return self.path\nclass EvilPath:\n    def __fspath__(self):\n        raise ValueError('bad path')\nfor filename in [FakePath('test_compile_pathlike'), FakePath(S('path_str_subclass.py')), FakePath(b'bytes_path.py'), FakePath(B(b'path_subclass.py'))]:\n    code = compile('42', filename, 'single')\n    print(code.co_filename, type(code.co_filename).__name__)\nfor label, expr in [('object', lambda: compile('42', object(), 'single')), ('path-result', lambda: compile('42', FakePath(bytearray(b'bad.py')), 'single'))]:\n    try:\n        expr()\n    except TypeError as error:\n        print(label, error.__class__.__name__, str(error))\ntry:\n    compile('42', EvilPath(), 'single')\nexcept ValueError as error:\n    print(error.__class__.__name__, error)",
        &[
            "test_compile_pathlike str",
            "path_str_subclass.py S",
            "bytes_path.py str",
            "path_subclass.py str",
            "object TypeError expected str, bytes or os.PathLike object, not object",
            "path-result TypeError expected FakePath.__fspath__() to return str or bytes, not bytearray",
            "ValueError bad path",
        ],
    );
}

// Adapted from CPython Lib/test/test_compile.py::TestSpecifics::
// test_compile_filename_refleak. The original CPython test targets reference
// leaks in filename decoding, but these public error paths are observable:
// invalid mode conversion, oversized optimize conversion, and dont_inherit
// truth-value conversion errors.
#[test]
fn cpython_compile_specifics_compile_argument_conversion_subset() {
    assert_output(
        "mortal_str = 'this is a mortal string'\nfor expr in [\n    lambda: compile(b'', mortal_str, mode=1234),\n    lambda: compile(b'', mortal_str, 'exec', optimize=1 << 1000),\n]:\n    try:\n        expr()\n    except (TypeError, OverflowError) as error:\n        print(error.__class__.__name__)\nclass EvilBool:\n    def __bool__(self):\n        print('bool-called')\n        raise ValueError('bad bool')\ntry:\n    compile(b'', mortal_str, 'exec', dont_inherit=EvilBool())\nexcept ValueError as error:\n    print(error.__class__.__name__, error)",
        &[
            "TypeError",
            "OverflowError",
            "bool-called",
            "ValueError bad bool",
        ],
    );
}

// Adapted from CPython Lib/test/test_compile.py::TestSpecifics::
