// Adapted from CPython Lib/test/test_memoryview.py constructor, equality, hash,
// attribute, method, context-manager, release, and reversed-iteration checks.
// MiniPython only models one-dimensional bytes-like memoryviews.
#[test]
fn cpython_memoryview_minimal_runtime_subset() {
    assert_output(
        "for source in [b'x', bytearray(b'x'), memoryview(b'x')]:\n    print(type(source).__name__, bool(memoryview(source)), bool(memoryview(object=source)), memoryview(source).tolist())\nprint(list(memoryview(b'abc')))\nprint(memoryview(b'abcdef') == b'abcdef', memoryview(bytearray(b'abcdef')) == bytearray(b'abcdef'))\nprint(memoryview(b'abcde') == b'abcdef', memoryview(b'abcdef') != b'abcde')\nprint(hash(memoryview(b'abcdef')) == hash(b'abcdef'))\ntry:\n    hash(memoryview(bytearray(b'abcdef')))\nexcept ValueError as error:\n    print(error.__class__.__name__)\nfor label, expr in [('missing', lambda: memoryview()), ('two-pos', lambda: memoryview(b'x', b'y')), ('bad-kw', lambda: memoryview(argument=b'x')), ('two-kw', lambda: memoryview(object=b'x', argument=True)), ('pos-object-kw', lambda: memoryview(b'x', object=b'y')), ('pos-bad-kw', lambda: memoryview(b'x', argument=True))]:\n    try:\n        expr()\n    except TypeError as error:\n        print(label, error.__class__.__name__, str(error))",
        &[
            "bytes True True [120]",
            "bytearray True True [120]",
            "memoryview True True [120]",
            "[97, 98, 99]",
            "True True",
            "False True",
            "True",
            "ValueError",
            "missing TypeError memoryview() missing required argument 'object' (pos 1)",
            "two-pos TypeError memoryview() takes at most 1 argument (2 given)",
            "bad-kw TypeError memoryview() missing required argument 'object' (pos 1)",
            "two-kw TypeError memoryview() takes at most 1 keyword argument (2 given)",
            "pos-object-kw TypeError memoryview() takes at most 1 argument (2 given)",
            "pos-bad-kw TypeError memoryview() takes at most 1 argument (2 given)",
        ],
    );
    assert_output(
        "for source in [b'abcdef', bytearray(b'abcdef'), memoryview(b'abcdef')[1:5]]:\n    m = memoryview(source)\n    print(m.tobytes(), m.tolist(), m.hex(), m.hex(':', 2))\n    print(m.format, m.itemsize, m.ndim, m.shape, m.strides, m.suboffsets, m.readonly, m.nbytes)\n    print(m.count(ord('a')), m.count(ord('c')), m.count(ord('x')))\n    try:\n        print(m.index(ord('c')), m.index(ord('c'), -10, 99))\n    except ValueError as error:\n        print(error.__class__.__name__)\n    print(m.toreadonly().readonly, m.toreadonly().tolist() == m.tolist())\ntry:\n    memoryview(b'abcdef').index(ord('x'))\nexcept ValueError as error:\n    print(error.__class__.__name__, str(error))\nfor expr in [lambda: memoryview(b'abc').tobytes(1), lambda: memoryview(b'abc').tolist(1), lambda: memoryview(b'abc').count(), lambda: memoryview(b'abc').index(), lambda: memoryview(b'abc').index(97, 0, 1, 2)]:\n    try:\n        expr()\n    except TypeError as error:\n        print(error.__class__.__name__)",
        &[
            "b'abcdef' [97, 98, 99, 100, 101, 102] 616263646566 6162:6364:6566",
            "B 1 1 (6,) (1,) () True 6",
            "1 1 0",
            "2 2",
            "True True",
            "b'abcdef' [97, 98, 99, 100, 101, 102] 616263646566 6162:6364:6566",
            "B 1 1 (6,) (1,) () False 6",
            "1 1 0",
            "2 2",
            "True True",
            "b'bcde' [98, 99, 100, 101] 62636465 6263:6465",
            "B 1 1 (4,) (1,) () True 4",
            "0 1 0",
            "1 1",
            "True True",
            "ValueError memoryview.index(x): x not found",
            "TypeError",
            "TypeError",
            "TypeError",
            "TypeError",
            "TypeError",
        ],
    );
    assert_output(
        "m = memoryview(b'abcdef')\nprint(list(reversed(m)), list(m[::-1]))\nwith m as cm:\n    print(cm is m)\nfor expr in [lambda: bytes(m), lambda: m.tobytes(), lambda: m.tolist(), lambda: m[0], lambda: len(m), lambda: m.format, lambda: m.itemsize, lambda: m.ndim, lambda: m.readonly, lambda: m.shape, lambda: m.strides, lambda: hash(m)]:\n    try:\n        expr()\n    except ValueError as error:\n        print(error.__class__.__name__, 'released' in str(error))\nprint('released memory' in str(m), 'released memory' in repr(m))\nprint(m == m, m != memoryview(b'abcdef'), m != b'abcdef')\nm.release()\nprint('released memory' in str(m))\nm = memoryview(b'abcdef')\nwith m:\n    m.release()\ntry:\n    with m:\n        pass\nexcept ValueError as error:\n    print(error.__class__.__name__, 'released' in str(error))\nbase = memoryview(b'abcdef')\nreadonly = base.toreadonly()\nreadonly.release()\nprint(base.tolist())",
        &[
            "[102, 101, 100, 99, 98, 97] [102, 101, 100, 99, 98, 97]",
            "True",
            "ValueError True",
            "ValueError True",
            "ValueError True",
            "ValueError True",
            "ValueError True",
            "ValueError True",
            "ValueError True",
            "ValueError True",
            "ValueError True",
            "ValueError True",
            "ValueError True",
            "ValueError True",
            "True True",
            "True True True",
            "True",
            "ValueError True",
            "[97, 98, 99, 100, 101, 102]",
        ],
    );
}

// Adapted from CPython Lib/test/test_memoryview.py::AbstractMemoryTests::
// test_tobytes, test_tolist, test_attributes_readonly,
// test_attributes_writable, test_contextmanager, test_release, and
