// Adapted from CPython Lib/test/test_memoryview.py::AbstractMemoryTests::
// test_setitem_readonly, test_setitem_writable, and test_delitem for the
// supported one-dimensional bytearray-backed memoryview subset.
#[test]
fn cpython_memoryview_writable_setitem_subset() {
    assert_output(
        "base = bytearray(b'abcdef')\nalias = base\nalias[0] = ord('z')\nprint(base)\nbase[0] = ord('a')\nm = memoryview(base)\nm[0] = ord('1')\nprint(base, m.tolist())\nm[0:1] = bytearray(b'0')\nprint(base)\nm[1:3] = bytearray(b'12')\nprint(base)\nm[1:1] = bytearray(b'')\nprint(base)\nm[:] = bytearray(b'abcdef')\nprint(base)\nm[0:3] = m[2:5]\nprint(base)\nm[:] = bytearray(b'abcdef')\nm[2:5] = m[0:3]\nprint(base)",
        &[
            "bytearray(b'zbcdef')",
            "bytearray(b'1bcdef') [49, 98, 99, 100, 101, 102]",
            "bytearray(b'0bcdef')",
            "bytearray(b'012def')",
            "bytearray(b'012def')",
            "bytearray(b'abcdef')",
            "bytearray(b'cdedef')",
            "bytearray(b'ababcf')",
        ],
    );
    assert_output(
        "readonly = memoryview(b'abcdef')\nfor expr in [lambda: readonly.__setitem__(0, ord('1')), lambda: readonly.__setitem__(0, b'1'), lambda: readonly.__setitem__(0, memoryview(b'1'))]:\n    try:\n        expr()\n    except TypeError as error:\n        print(error.__class__.__name__)\nfor source in [memoryview(b'abcdef'), memoryview(bytearray(b'abcdef'))]:\n    for expr in [lambda source=source: source.__delitem__(1), lambda source=source: source.__delitem__(slice(1, 4))]:\n        try:\n            expr()\n        except TypeError as error:\n            print(error.__class__.__name__)\nbase = bytearray(b'abcdef')\nm = memoryview(base)\nfor expr in [lambda: m.__setitem__(6, b'a'), lambda: m.__setitem__(-7, b'a'), lambda: m.__setitem__(0, b''), lambda: m.__setitem__(0, b'ab'), lambda: m.__setitem__(slice(1, 1), b'a'), lambda: m.__setitem__(slice(0, 2), b'a')]:\n    try:\n        expr()\n    except (IndexError, ValueError, TypeError) as error:\n        print(error.__class__.__name__)\nprint(base)",
        &[
            "TypeError",
            "TypeError",
            "TypeError",
            "TypeError",
            "TypeError",
            "TypeError",
            "TypeError",
            "IndexError",
            "IndexError",
            "TypeError",
            "TypeError",
            "ValueError",
            "ValueError",
            "bytearray(b'abcdef')",
        ],
    );
    assert_output(
        "base = bytearray(b'abcdef')\nm = memoryview(base)\nfor label, key in [('get-empty', ()), ('get-scalar', (0,)), ('get-bool', (True,)), ('get-oob', (99,)), ('get-one-slice', (slice(0, 1, 1),)), ('get-two-slice', (slice(0, 1, 1), slice(0, 1, 1))), ('get-slice-int', (slice(0, 1, 1), 0)), ('get-int-slice', (0, slice(0, 1, 1))), ('get-two-int', (0, 0)), ('get-float', (0.0,))]:\n    try:\n        result = m.__getitem__(key)\n        print(label, result)\n    except (TypeError, IndexError, NotImplementedError) as error:\n        print(label, error.__class__.__name__)\nbase = bytearray(b'abcdef')\nm = memoryview(base)\nfor label, key, value in [('set-scalar', (0,), 90), ('set-empty', (), 90), ('set-one-slice', (slice(0, 1, 1),), b'Z'), ('set-two-slice', (slice(0, 1, 1), slice(0, 1, 1)), b'Z'), ('set-slice-int', (slice(0, 1, 1), 0), b'Z'), ('set-int-slice', (0, slice(0, 1, 1)), b'Z'), ('set-two-int', (0, 0), 90), ('set-float', (0.0,), 90), ('set-bytes-scalar', (0,), b'Z')]:\n    try:\n        result = m.__setitem__(key, value)\n        print(label, result, base)\n    except (TypeError, IndexError, NotImplementedError) as error:\n        print(label, error.__class__.__name__, base)",
        &[
            "get-empty NotImplementedError",
            "get-scalar 97",
            "get-bool 98",
            "get-oob IndexError",
            "get-one-slice NotImplementedError",
            "get-two-slice NotImplementedError",
            "get-slice-int TypeError",
            "get-int-slice TypeError",
            "get-two-int TypeError",
            "get-float TypeError",
            "set-scalar None bytearray(b'Zbcdef')",
            "set-empty NotImplementedError bytearray(b'Zbcdef')",
            "set-one-slice NotImplementedError bytearray(b'Zbcdef')",
            "set-two-slice NotImplementedError bytearray(b'Zbcdef')",
            "set-slice-int TypeError bytearray(b'Zbcdef')",
            "set-int-slice TypeError bytearray(b'Zbcdef')",
            "set-two-int TypeError bytearray(b'Zbcdef')",
            "set-float TypeError bytearray(b'Zbcdef')",
            "set-bytes-scalar TypeError bytearray(b'Zbcdef')",
        ],
    );
}

// Adapted from CPython Lib/test/test_memoryview.py::BaseMemorySliceTests and
// BaseMemorySliceSliceTests. This pins true one-dimensional subview behavior:
// slices keep sharing the original buffer instead of copying bytes.
#[test]
fn cpython_memoryview_slice_reference_subset() {
    assert_output(
        "base = bytearray(b'XabcdefY')\nm = memoryview(base)[1:7]\nprint(m.tobytes(), m.tolist(), m.readonly, m.nbytes)\nm[0] = ord('1')\nprint(base, m.tobytes())\nbase[2] = ord('2')\nprint(base, m.tobytes())\nm[2:4] = b'34'\nprint(base, m.tobytes())\nbase = bytearray(b'XabcdefY')\ns = memoryview(base)[:7][1:]\ns[5] = ord('!')\nprint(base, s.tobytes())\nrev_base = bytearray(b'abcdef')\nrev = memoryview(rev_base)[::-1]\nprint(rev.tolist(), rev.tobytes())\nrev[0] = ord('Z')\nrev[5] = ord('A')\nprint(rev_base, rev.tobytes())\nreadonly = memoryview(b'XabcdefY')[1:7]\ntry:\n    readonly[0] = ord('x')\nexcept TypeError as error:\n    print(error.__class__.__name__)",
        &[
            "b'abcdef' [97, 98, 99, 100, 101, 102] False 6",
            "bytearray(b'X1bcdefY') b'1bcdef'",
            "bytearray(b'X12cdefY') b'12cdef'",
            "bytearray(b'X1234efY') b'1234ef'",
            "bytearray(b'Xabcde!Y') b'abcde!'",
            "[102, 101, 100, 99, 98, 97] b'fedcba'",
            "bytearray(b'AbcdeZ') b'ZedcbA'",
            "TypeError",
        ],
    );
}

// Adapted from CPython Lib/test/test_memoryview.py attribute tests and the
// one-dimensional public attribute checks in Lib/test/test_buffer.py. This
// keeps the supported bytes-like memoryview object model tied to the original
// exporter and CPython's one-dimensional contiguity rules.
#[test]
fn cpython_memoryview_public_buffer_attributes_subset() {
    assert_output(
        "base = bytearray(b'ab')\nview = memoryview(base)\ncopy = memoryview(view)\nreadonly = view.toreadonly()\nprint(view.obj is base, copy.obj is base, readonly.obj is base, readonly.readonly)\nfor name, m in [('full', view), ('empty', view[0:0]), ('empty-step', view[0:0:2]), ('empty-neg', view[0:0:-1]), ('skip', view[::2]), ('reverse', view[::-1]), ('one-reverse', view[:0:-1])]:\n    print(name, m.tolist(), m.strides, m.c_contiguous, m.f_contiguous, m.contiguous, m.obj is base)\nbytes_view = memoryview(b'abcdef')[1:5]\nprint(bytes_view.obj == b'abcdef', bytes_view.obj, bytes_view.strides, bytes_view.c_contiguous)\nreleased = memoryview(base)\nreleased.release()\nfor expr in [lambda: released.obj, lambda: released.c_contiguous, lambda: released.f_contiguous, lambda: released.contiguous]:\n    try:\n        expr()\n    except ValueError as error:\n        print(error.__class__.__name__, 'released' in str(error))",
        &[
            "True True True True",
            "full [97, 98] (1,) True True True True",
            "empty [] (1,) True True True True",
            "empty-step [] (2,) False False False True",
            "empty-neg [] (-1,) False False False True",
            "skip [97] (2,) True True True True",
            "reverse [98, 97] (-1,) False False False True",
            "one-reverse [98] (-1,) True True True True",
            "True b'abcdef' (1,) True",
            "ValueError True",
            "ValueError True",
            "ValueError True",
            "ValueError True",
        ],
    );
}

// Adapted from CPython Lib/test/test_memoryview.py array-backed exporter
// coverage. MiniPython currently supports the array('B') one-byte writable
// buffer surface; non-byte array formats remain classified as migration gaps.
#[test]
fn cpython_memoryview_array_b_buffer_subset() {
    assert_output(
        "import array\narr = array.array('B', [97, 98, 99])\nm = memoryview(arr)\nprint(m.format, m.itemsize, m.ndim, m.shape, m.strides, m.readonly, m.tolist(), m.tobytes(), m.obj is arr)\nm[0] = ord('z')\nprint(arr, repr(arr), bytes(arr), m.tolist())\nm[1:3] = b'XY'\nprint(arr, bytes(arr), m.tobytes())\nsub = m[::2]\nprint(sub.tolist(), sub.strides, sub.obj is arr)\nreadonly = m.toreadonly()\nprint(readonly.readonly, readonly.obj is arr, readonly.tolist())",
        &[
            "B 1 1 (3,) (1,) False [97, 98, 99] b'abc' True",
            "array('B', [122, 98, 99]) array('B', [122, 98, 99]) b'zbc' [122, 98, 99]",
            "array('B', [122, 88, 89]) b'zXY' b'zXY'",
            "[122, 89] (2,) True",
            "True True [122, 88, 89]",
        ],
    );
}

// Adapted from CPython Lib/test/test_memoryview.py array-backed exporter
// coverage for the signed one-byte array format.
#[test]
fn cpython_memoryview_array_signed_byte_buffer_subset() {
    assert_output(
        "import array\n\ndef show(label, expr):\n    try:\n        value = expr()\n        print(label, value)\n    except Exception as error:\n        print(label, error.__class__.__name__, str(error))\n\nfor source in [b'\\xff\\x00\\x7f', bytearray(b'\\xff\\x00\\x7f'), [-1, 0, 127], memoryview(array.array('b', [-1, 2])), memoryview(b'\\xff')]:\n    show('init-' + type(source).__name__, lambda source=source: (repr(array.array('b', source)), bytes(array.array('b', source)), list(array.array('b', source))))\narr = array.array('b', [-1, 0, 127])\nm = memoryview(arr)\nprint('view', m.format, m.itemsize, m.ndim, m.shape, m.strides, m.readonly, m.tolist(), m.tobytes(), m.obj is arr, m[0])\nm[0] = -2\nprint('set', repr(arr), m.tolist(), m.tobytes())\nshow('set-high', lambda: m.__setitem__(1, 128))\nshow('set-type', lambda: m.__setitem__(1, b'X'))\nm[1:3] = memoryview(array.array('b', [3, -4]))\nprint('slice-ok', repr(arr), m.tolist(), m.tobytes())\nfor label, rhs in [('bytes', b'\\x01\\x02'), ('B-view', memoryview(array.array('B', [1, 2]))), ('list', [1, 2])]:\n    show('slice-' + label, lambda rhs=rhs: m.__setitem__(slice(0, 2), rhs))",
        &[
            "init-bytes (\"array('b', [-1, 0, 127])\", b'\\xff\\x00\\x7f', [-1, 0, 127])",
            "init-bytearray (\"array('b', [-1, 0, 127])\", b'\\xff\\x00\\x7f', [-1, 0, 127])",
            "init-list (\"array('b', [-1, 0, 127])\", b'\\xff\\x00\\x7f', [-1, 0, 127])",
            "init-memoryview (\"array('b', [-1, 2])\", b'\\xff\\x02', [-1, 2])",
            "init-memoryview OverflowError signed char is greater than maximum",
            "view b 1 1 (3,) (1,) False [-1, 0, 127] b'\\xff\\x00\\x7f' True -1",
            "set array('b', [-2, 0, 127]) [-2, 0, 127] b'\\xfe\\x00\\x7f'",
            "set-high ValueError memoryview: invalid value for format 'b'",
            "set-type TypeError memoryview: invalid type for format 'b'",
            "slice-ok array('b', [-2, 3, -4]) [-2, 3, -4] b'\\xfe\\x03\\xfc'",
            "slice-bytes ValueError memoryview assignment: lvalue and rvalue have different structures",
            "slice-B-view ValueError memoryview assignment: lvalue and rvalue have different structures",
            "slice-list TypeError a bytes-like object is required, not 'list'",
        ],
    );
}

// Adapted from CPython Lib/test/test_memoryview.py array-backed exporter
// coverage for non-byte numeric formats. Writable non-byte item assignment
// remains out of scope until full typed buffer writeback is implemented.
#[test]
fn cpython_memoryview_array_non_byte_public_read_subset() {
    assert_output(
        "import array\n\ncases = [\n    ('h', [-2, 0, 258]),\n    ('H', [0, 258, 65535]),\n    ('i', [-123456, 0, 123456]),\n    ('I', [0, 123456, 3000000000]),\n    ('f', [1.25, -0.5]),\n    ('d', [1.25, -0.5]),\n]\n\nfor typecode, values in cases:\n    arr = array.array(typecode, values)\n    view = memoryview(arr)\n    print('view', typecode, view.format, view.itemsize, len(view), view.shape, view.strides, view.nbytes, view.c_contiguous, view.tolist())\n    print('index', typecode, view[0], view[-1], view.tobytes() == arr.tobytes())\n    sub = view[1:]\n    print('slice', typecode, sub.format, len(sub), sub.shape, sub.strides, sub.nbytes, sub.c_contiguous, sub.tolist(), sub.tobytes() == arr[1:].tobytes())\n    cast = view.cast('B')\n    print('cast', typecode, cast.format, len(cast), cast.shape, cast.nbytes, cast.tobytes() == arr.tobytes())",
        &[
            "view h h 2 3 (3,) (2,) 6 True [-2, 0, 258]",
            "index h -2 258 True",
            "slice h h 2 (2,) (2,) 4 True [0, 258] True",
            "cast h B 6 (6,) 6 True",
            "view H H 2 3 (3,) (2,) 6 True [0, 258, 65535]",
            "index H 0 65535 True",
            "slice H H 2 (2,) (2,) 4 True [258, 65535] True",
            "cast H B 6 (6,) 6 True",
            "view i i 4 3 (3,) (4,) 12 True [-123456, 0, 123456]",
            "index i -123456 123456 True",
            "slice i i 2 (2,) (4,) 8 True [0, 123456] True",
            "cast i B 12 (12,) 12 True",
            "view I I 4 3 (3,) (4,) 12 True [0, 123456, 3000000000]",
            "index I 0 3000000000 True",
            "slice I I 2 (2,) (4,) 8 True [123456, 3000000000] True",
            "cast I B 12 (12,) 12 True",
            "view f f 4 2 (2,) (4,) 8 True [1.25, -0.5]",
            "index f 1.25 -0.5 True",
            "slice f f 1 (1,) (4,) 4 True [-0.5] True",
            "cast f B 8 (8,) 8 True",
            "view d d 8 2 (2,) (8,) 16 True [1.25, -0.5]",
            "index d 1.25 -0.5 True",
            "slice d d 1 (1,) (8,) 8 True [-0.5] True",
            "cast d B 16 (16,) 16 True",
        ],
    );
}

// Adapted from CPython Lib/test/test_memoryview.py array-backed exporter
// coverage for one-dimensional non-byte writeback through memoryview.
#[test]
fn cpython_memoryview_array_non_byte_writeback_subset() {
    assert_output(
        "import array\n\nclass I:\n    def __index__(self):\n        return 7\n\ndef show(label, callback):\n    try:\n        callback()\n    except Exception as error:\n        print(label, type(error).__name__, isinstance(error, (TypeError, ValueError, OverflowError)))\n    else:\n        print(label, 'OK')\n\nfor typecode, values, scalar, replacement in [\n    ('h', [1, 2, 3, 4], -7, [8, 9]),\n    ('H', [1, 2, 3, 4], 65535, [8, 9]),\n    ('i', [1, 2, 3, 4], -70000, [80000, 90000]),\n    ('f', [1.0, 2.0, 3.0, 4.0], 1.25, [8.5, 9.5]),\n    ('d', [1.0, 2.0, 3.0, 4.0], 1.25, [8.5, 9.5]),\n]:\n    arr = array.array(typecode, values)\n    view = memoryview(arr)\n    view[1] = scalar\n    print('scalar', typecode, arr.tolist(), view.tolist(), view.tobytes() == arr.tobytes())\n    view[1:3] = memoryview(array.array(typecode, replacement))\n    print('slice', typecode, arr.tolist(), view.tolist(), view.tobytes() == arr.tobytes())\n    view[::2] = memoryview(array.array(typecode, replacement))\n    print('extended', typecode, arr.tolist(), view.tolist(), view.tobytes() == arr.tobytes())\n    show('mismatch-' + typecode, lambda view=view: view.__setitem__(slice(0, 2), memoryview(array.array('B', [1, 2]))))\n    show('bytes-' + typecode, lambda view=view: view.__setitem__(slice(0, 2), b'ab'))\n    show('bad-scalar-' + typecode, lambda view=view: view.__setitem__(0, object()))\n\narr = array.array('h', [1, 2])\nview = memoryview(arr)\nview[0] = I()\nprint('index-object', arr.tolist(), view.tolist())",
        &[
            "scalar h [1, -7, 3, 4] [1, -7, 3, 4] True",
            "slice h [1, 8, 9, 4] [1, 8, 9, 4] True",
            "extended h [8, 8, 9, 4] [8, 8, 9, 4] True",
            "mismatch-h ValueError True",
            "bytes-h ValueError True",
            "bad-scalar-h TypeError True",
            "scalar H [1, 65535, 3, 4] [1, 65535, 3, 4] True",
            "slice H [1, 8, 9, 4] [1, 8, 9, 4] True",
            "extended H [8, 8, 9, 4] [8, 8, 9, 4] True",
            "mismatch-H ValueError True",
            "bytes-H ValueError True",
            "bad-scalar-H TypeError True",
            "scalar i [1, -70000, 3, 4] [1, -70000, 3, 4] True",
            "slice i [1, 80000, 90000, 4] [1, 80000, 90000, 4] True",
            "extended i [80000, 80000, 90000, 4] [80000, 80000, 90000, 4] True",
            "mismatch-i ValueError True",
            "bytes-i ValueError True",
            "bad-scalar-i TypeError True",
            "scalar f [1.0, 1.25, 3.0, 4.0] [1.0, 1.25, 3.0, 4.0] True",
            "slice f [1.0, 8.5, 9.5, 4.0] [1.0, 8.5, 9.5, 4.0] True",
            "extended f [8.5, 8.5, 9.5, 4.0] [8.5, 8.5, 9.5, 4.0] True",
            "mismatch-f ValueError True",
            "bytes-f ValueError True",
            "bad-scalar-f TypeError True",
            "scalar d [1.0, 1.25, 3.0, 4.0] [1.0, 1.25, 3.0, 4.0] True",
            "slice d [1.0, 8.5, 9.5, 4.0] [1.0, 8.5, 9.5, 4.0] True",
            "extended d [8.5, 8.5, 9.5, 4.0] [8.5, 8.5, 9.5, 4.0] True",
            "mismatch-d ValueError True",
            "bytes-d ValueError True",
            "bad-scalar-d TypeError True",
            "index-object [7, 2] [7, 2]",
        ],
    );
}

// Mirrors CPython's public `array` module `__package__` metadata while keeping
// the supported sandbox surface pure-memory.
#[test]
fn cpython_array_module_package_metadata_subset() {
    assert_output(
        r#"import array
print(array.__name__, repr(array.__package__))
print(repr(object.__getattribute__(array, '__package__')))
print('__package__' in dir(array), repr(array.__dict__['__package__']))"#,
        &["array ''", "''", "True ''"],
    );
}

// Mirrors CPython's public `array` module `__doc__` metadata while keeping the
