// Adapted from CPython Lib/copy.py public pure-memory behavior.
#[test]
fn cpython_copy_public_subset() {
    assert_output(
        concat!(
            "import copy\n",
            "import io\n",
            "from collections import UserDict, UserList, deque\n",
            "print(copy.Error is copy.error)\n",
            "print(copy.Error.__name__, copy.Error.__qualname__, copy.Error.__module__)\n",
            "try:\n",
            "    raise copy.Error('boom')\n",
            "except copy.Error as error:\n",
            "    print(type(error).__name__, isinstance(error, Exception), str(error))\n",
            "print(type(copy.dispatch_table).__name__, copy.dispatch_table is copy.dispatch_table)\n",
            "class CustomCopy:\n",
            "    def __copy__(self):\n",
            "        print('copy-hook')\n",
            "        return 'copied'\n",
            "class CustomDeep:\n",
            "    def __deepcopy__(self, memo):\n",
            "        print('deep-hook', isinstance(memo, dict))\n",
            "        memo[id(self)] = 'seen'\n",
            "        return 'deeped'\n",
            "class BadDeep:\n",
            "    def __deepcopy__(self):\n",
            "        return 'bad'\n",
            "class MemoDeep:\n",
            "    calls = 0\n",
            "    def __deepcopy__(self, memo):\n",
            "        type(self).calls += 1\n",
            "        return ['memo-copy', type(self).calls]\n",
            "print('custom-copy', copy.copy(CustomCopy()))\n",
            "print('custom-deep', copy.deepcopy(CustomDeep()))\n",
            "try:\n",
            "    copy.deepcopy(BadDeep())\n",
            "except TypeError as error:\n",
            "    print('bad-deep', type(error).__name__)\n",
            "memo_obj = MemoDeep()\n",
            "memo_cloned = copy.deepcopy([memo_obj, memo_obj])\n",
            "print('custom-deep-memo', MemoDeep.calls, memo_cloned[0] is memo_cloned[1], memo_cloned)\n",
            "nested = [1, [2], {'a': [3]}]\n",
            "shallow = copy.copy(nested)\n",
            "deep = copy.deepcopy(nested)\n",
            "nested[1].append(4)\n",
            "nested[2]['a'].append(5)\n",
            "print(shallow is nested, deep is nested)\n",
            "print(shallow[1] is nested[1], deep[1] is nested[1], shallow[1], deep[1])\n",
            "print(shallow[2] is nested[2], deep[2] is nested[2], shallow[2], deep[2])\n",
            "for value in [None, True, 42, 'abc', b'abc', (1, 2)]:\n",
            "    print(type(value).__name__, copy.copy(value) == value, copy.copy(value) is value, copy.deepcopy(value) == value, copy.deepcopy(value) is value)\n",
            "ba = bytearray(b'ab')\n",
            "ba_shallow = copy.copy(ba)\n",
            "ba_deep = copy.deepcopy(ba)\n",
            "ba.append(ord('c'))\n",
            "print(type(ba_shallow).__name__, ba_shallow == bytearray(b'ab'), ba_shallow is ba)\n",
            "print(type(ba_deep).__name__, ba_deep == bytearray(b'ab'), ba_deep is ba)\n",
            "d = {'x': [1]}\n",
            "ds = copy.copy(d)\n",
            "dd = copy.deepcopy(d)\n",
            "d['x'].append(2)\n",
            "print(ds is d, dd is d, ds['x'], dd['x'])\n",
            "shared = [1]\n",
            "outer = [shared, shared]\n",
            "cloned = copy.deepcopy(outer)\n",
            "print('list-alias', cloned is outer, cloned[0] is shared, cloned[0] is cloned[1], cloned)\n",
            "d = {'a': shared, 'b': shared}\n",
            "cd = copy.deepcopy(d)\n",
            "print('dict-alias', cd is d, cd['a'] is shared, cd['a'] is cd['b'], cd)\n",
            "t = (shared, shared)\n",
            "ct = copy.deepcopy(t)\n",
            "print('tuple-alias', ct is t, ct[0] is shared, ct[0] is ct[1], ct)\n",
            "cycle = []\n",
            "cycle.append(cycle)\n",
            "cc = copy.deepcopy(cycle)\n",
            "print('list-cycle', cc is cycle, cc[0] is cc, len(cc))\n",
            "class Box:\n",
            "    pass\n",
            "box = Box()\n",
            "box.a = shared\n",
            "box.b = shared\n",
            "cbox = copy.deepcopy(box)\n",
            "print('instance-alias', cbox is box, cbox.a is shared, cbox.a is cbox.b)\n",
            "box.self = box\n",
            "cbox = copy.deepcopy(box)\n",
            "print('instance-cycle', cbox is box, cbox.self is cbox)\n",
            "ul = UserList([shared, shared])\n",
            "cul = copy.deepcopy(ul)\n",
            "print('userlist-alias', cul is ul, cul.data is ul.data, cul[0] is shared, cul[0] is cul[1], cul)\n",
            "ul_cycle = UserList([])\n",
            "ul_cycle.append(ul_cycle)\n",
            "cul_cycle = copy.deepcopy(ul_cycle)\n",
            "print('userlist-cycle', cul_cycle is ul_cycle, cul_cycle[0] is cul_cycle, len(cul_cycle))\n",
            "ud = UserDict({'a': shared, 'b': shared})\n",
            "cud = copy.deepcopy(ud)\n",
            "print('userdict-alias', cud is ud, cud.data is ud.data, cud['a'] is shared, cud['a'] is cud['b'], list(cud.items()))\n",
            "dq = deque([shared, shared])\n",
            "cdq = copy.deepcopy(dq)\n",
            "print('deque-alias', cdq is dq, cdq[0] is shared, cdq[0] is cdq[1], list(cdq))\n",
            "memo = {}\n",
            "memo_result = copy.deepcopy(outer, memo)\n",
            "print('memo-populated', memo_result[0] is memo_result[1], id(outer) in memo, id(shared) in memo)\n",
            "memo = {id(shared): ['sentinel']}\n",
            "memo_result = copy.deepcopy(outer, memo)\n",
            "print('memo-preseed-shared', memo_result, memo_result[0] is memo_result[1], id(outer) in memo, id(shared) in memo)\n",
            "memo = {id(outer): ['outer-sentinel']}\n",
            "memo_result = copy.deepcopy(outer, memo)\n",
            "print('memo-preseed-outer', memo_result, id(outer) in memo)\n",
            "obj = [1]\n",
            "nil = []\n",
            "memo = {id(obj): nil}\n",
            "nil_result = copy.deepcopy(obj, memo, nil)\n",
            "print('memo-nil-sentinel', nil_result is nil, nil_result, memo[id(obj)] is nil, memo[id(obj)] is nil_result)\n",
            "print('nil-keyword', copy.deepcopy([1], _nil=[]))\n",
            "for memo_arg in [None, [], {1: 2}]:\n",
            "    try:\n",
            "        print('memo-arg', type(memo_arg).__name__, copy.deepcopy([1], memo_arg))\n",
            "    except Exception as error:\n",
            "        print('memo-arg', type(memo_arg).__name__, type(error).__name__)\n",
            "marker = [1]\n",
            "bio = io.BytesIO(b'abc')\n",
            "bio.seek(1)\n",
            "bio.tag = marker\n",
            "bio.self = bio\n",
            "bio_shallow = copy.copy(bio)\n",
            "bio_deep = copy.deepcopy(bio)\n",
            "print('bytesio-copy', bio_shallow is bio, bio_shallow.getvalue(), bio_shallow.tell(), bio_shallow.tag is marker, bio_shallow.self is bio)\n",
            "print('bytesio-deepcopy', bio_deep is bio, bio_deep.getvalue(), bio_deep.tell(), bio_deep.tag is marker, bio_deep.self is bio_deep)\n",
            "bio.write(b'Z')\n",
            "bio_shallow.write(b'Y')\n",
            "bio_deep.write(b'X')\n",
            "print('bytesio-independent', bio.getvalue(), bio_shallow.getvalue(), bio_deep.getvalue())\n",
            "for fn in [copy.copy, copy.deepcopy]:\n",
            "    closed = io.BytesIO(b'abc')\n",
            "    closed.close()\n",
            "    try:\n",
            "        fn(closed)\n",
            "    except ValueError as error:\n",
            "        print('bytesio-closed', fn.__name__, type(error).__name__)\n",
            "for expr in [lambda: copy.copy(), lambda: copy.copy(1, 2), lambda: copy.deepcopy(), lambda: copy.replace()]:\n",
            "    try:\n",
            "        expr()\n",
            "    except TypeError as error:\n",
            "        print(error.__class__.__name__, str(error))"
        ),
        &[
            "True",
            "Error Error copy",
            "Error True boom",
            "dict True",
            "copy-hook",
            "custom-copy copied",
            "deep-hook True",
            "custom-deep deeped",
            "bad-deep TypeError",
            "custom-deep-memo 1 True [['memo-copy', 1], ['memo-copy', 1]]",
            "False False",
            "True False [2, 4] [2]",
            "True False {'a': [3, 5]} {'a': [3]}",
            "NoneType True True True True",
            "bool True True True True",
            "int True True True True",
            "str True True True True",
            "bytes True True True True",
            "tuple True True True True",
            "bytearray True False",
            "bytearray True False",
            "False False [1, 2] [1]",
            "list-alias False False True [[1], [1]]",
            "dict-alias False False True {'a': [1], 'b': [1]}",
            "tuple-alias False False True ([1], [1])",
            "list-cycle False True 1",
            "instance-alias False False True",
            "instance-cycle False True",
            "userlist-alias False False False True [[1], [1]]",
            "userlist-cycle False True 1",
            "userdict-alias False False False True [('a', [1]), ('b', [1])]",
            "deque-alias False False True [[1], [1]]",
            "memo-populated True True True",
            "memo-preseed-shared [['sentinel'], ['sentinel']] True True True",
            "memo-preseed-outer ['outer-sentinel'] True",
            "memo-nil-sentinel False [1] False True",
            "nil-keyword [1]",
            "memo-arg NoneType [1]",
            "memo-arg list AttributeError",
            "memo-arg dict [1]",
            "bytesio-copy False b'abc' 1 True True",
            "bytesio-deepcopy False b'abc' 1 False True",
            "bytesio-independent b'aZc' b'aYc' b'aXc'",
            "bytesio-closed copy ValueError",
            "bytesio-closed deepcopy ValueError",
            "TypeError copy() missing 1 required positional argument: 'x'",
            "TypeError copy() takes 1 positional argument but 2 were given",
            "TypeError deepcopy() missing 1 required positional argument: 'x'",
            "TypeError replace() missing 1 required positional argument: 'obj'",
        ],
    );
}

// Adapted from CPython Lib/copy.py public copy.replace() hook behavior.
#[test]
fn cpython_copy_replace_custom_hook_subset() {
    assert_output(
        r#"import copy
class CustomReplace:
    def __replace__(self, **changes):
        return ('custom', sorted(changes.items()))
class StaticReplace:
    __replace__ = staticmethod(lambda obj, **changes: ('static', type(obj).__name__, sorted(changes.items())))
class ClassReplace:
    @classmethod
    def __replace__(cls, obj, **changes):
        return ('class', cls.__name__, type(obj).__name__, sorted(changes.items()))
class ShadowReplace:
    def __init__(self):
        self.__replace__ = lambda **changes: ('instance', sorted(changes.items()))
    def __replace__(self, **changes):
        return ('class-shadow', sorted(changes.items()))
print(copy.replace(CustomReplace(), y=2, x=1))
print(copy.replace(StaticReplace(), x=3))
print(copy.replace(ClassReplace(), x=4))
print(copy.replace(ShadowReplace(), x=5))"#,
        &[
            "('custom', [('x', 1), ('y', 2)])",
            "('static', 'StaticReplace', [('x', 3)])",
            "('class', 'ClassReplace', 'ClassReplace', [('x', 4)])",
            "('class-shadow', [('x', 5)])",
        ],
    );
}

