// Adapted from CPython Lib/test/test_weakref.py::ReferencesTestCase
// live proxy behavior. Dead proxy ReferenceError, reuse, registries, and
// callback invocation remain tied to future GC weakref support.
#[test]
fn cpython_weakref_proxy_live_forwarding_subset() {
    assert_output(
        r#"import weakref, _weakref, operator

class Target:
    def __init__(self, n):
        self.n = n
    def twice(self):
        return self.n * 2
    def __hash__(self):
        return 7

class Box:
    last = None
    def __getitem__(self, key):
        return key * 3
    def __setitem__(self, key, value):
        self.last = ("set", key, value)
    def __delitem__(self, key):
        self.last = ("del", key)
    def __index__(self):
        return 6

class Textual:
    def __str__(self):
        return "text-form"
    def __bytes__(self):
        return b"byte-form"

class Ops:
    def __floordiv__(self, other):
        return "floor"
    def __ifloordiv__(self, other):
        return "ifloor"
    def __matmul__(self, other):
        return "mat"
    def __rmatmul__(self, other):
        return "rmat"
    def __imatmul__(self, other):
        return "imat"

class Seq:
    def __iter__(self):
        yield from "pq"
    def __len__(self):
        return 2
    def __reversed__(self):
        return iter("qp")
    def __bool__(self):
        return False

class Fn:
    def __call__(self, a=1, *, b=2):
        self.seen = (a, b)
        return a + b

t = Target(5)
pt = weakref.proxy(t)
print("type", type(pt) is weakref.ProxyType, isinstance(pt, weakref.ProxyTypes), isinstance(pt, weakref.CallableProxyType), pt.__class__ is Target)
print("attr", pt.n, pt.twice())
pt.tag = "t"
print("set", t.tag, pt.tag)
del pt.tag
print("del", hasattr(t, "tag"))
try:
    hash(pt)
except TypeError as exc:
    print("hash", type(exc).__name__)
print("no-callback", weakref.proxy(t, None).n, type(_weakref.proxy(t)) is weakref.ProxyType)
b = Box()
pb = weakref.proxy(b)
print("getitem", pb[2])
pb["k"] = 1
print("setitem", b.last, pb.last)
del pb["k"]
print("delitem", b.last)
print("index", operator.index(pb), [10, 11, 12, 13, 14, 15, 16][pb])
x = Textual()
px = weakref.proxy(x)
print("str-bytes", str(px), bytes(px), "__bytes__" in dir(px), px.__dir__() == x.__dir__())
o = Ops()
po = weakref.proxy(o)
print("binary", po // 1, po @ 1, 1 @ po)
po //= 2
print("inplace-floor", po)
po = weakref.proxy(o)
po @= 2
print("inplace-mat", po)
s = Seq()
ps = weakref.proxy(s)
print("seq", list(ps), len(ps), list(reversed(ps)), bool(ps))
f = Fn()
pf = weakref.proxy(f)
print("callable", type(pf) is weakref.CallableProxyType, isinstance(pf, weakref.ProxyTypes), pf.__class__ is Fn)
print("call", pf(), pf(4), pf(b=9), f.seen)
for attempt in (lambda: weakref.proxy(object=t), lambda: weakref.proxy(t, callback=None), lambda: weakref.proxy(object=t, callback=None)):
    try:
        attempt()
    except TypeError as exc:
        print("keyword", type(exc).__name__)"#,
        &[
            "type True True False True",
            "attr 5 10",
            "set t t",
            "del False",
            "hash TypeError",
            "no-callback 5 True",
            "getitem 6",
            "setitem ('set', 'k', 1) ('set', 'k', 1)",
            "delitem ('del', 'k')",
            "index 6 16",
            "str-bytes text-form b'byte-form' True True",
            "binary floor mat rmat",
            "inplace-floor ifloor",
            "inplace-mat imat",
            "seq ['p', 'q'] 2 ['q', 'p'] False",
            "callable True True True",
            "call 3 6 10 (1, 9)",
            "keyword TypeError",
            "keyword TypeError",
            "keyword TypeError",
        ],
    );
    assert_output(
        concat!(
            "import weakref\n",
            "class ListSubclass(list):\n",
            "    pass\n",
            "items = ListSubclass()\n",
            "proxy = weakref.proxy(items)\n",
            "print('list-type', proxy.__class__ is ListSubclass, isinstance(proxy, weakref.ProxyType))\n",
            "print('list-empty', bool(proxy), len(proxy), list(proxy))\n",
            "proxy.append(12)\n",
            "print('list-append', bool(proxy), len(items), len(proxy), 12 in proxy, proxy[0], list(proxy))\n",
            "proxy[:] = [2, 3]\n",
            "print('list-slice-set', len(items), len(proxy), proxy[:], 3 in proxy)\n",
            "proxy[1] = 5\n",
            "print('list-item-set', items[1], proxy[1], list(proxy))\n",
            "print('list-reversed', list(reversed(proxy)))",
        ),
        &[
            "list-type True True",
            "list-empty False 0 []",
            "list-append True 1 1 True 12 [12]",
            "list-slice-set 2 2 [2, 3] True",
            "list-item-set 5 5 [2, 5]",
            "list-reversed [5, 2]",
        ],
    );
}

