// Adapted from CPython Lib/test/test_builtin.py::BuiltinTest::
// test_compile_top_level_await. Top-level async code must require the public
// flag, compile to a coroutine code object, and execute through FunctionType
// and eval() with module-code globals semantics.
#[test]
fn cpython_builtin_compile_top_level_await_subset() {
    let source = r#"import ast, inspect, types

class Tick:
    def __init__(self, value):
        self.value = value
    def __await__(self):
        yield "tick"
        return self.value

async def pause(value):
    return await Tick(value)

async def count_up(limit):
    for k in range(limit):
        yield k

class Guard:
    flag = 1
    async def __aenter__(self):
        return self
    async def __aexit__(self, *details):
        return False

def run(coro):
    try:
        while True:
            coro.send(None)
    except StopIteration:
        pass

samples = [
    "done = await pause(1)",
    "async for v in count_up(1):\n    done = v + 1",
    "async with Guard() as g:\n    done = g.flag",
    "done = [v async for v in count_up(3)][1]",
    "done = len({v async for v in count_up(1)})",
    "done = {v: v + 1 async for v in count_up(1)}[0]",
    "done = [p * q async for p in count_up(2) async for q in count_up(2)][3]",
    "done = [v async for v in (w async for w in count_up(4))][1]",
    "done, = [1 for _ in {v async for v in count_up(1)}]",
    "done = [await pause(v) async for v in count_up(2)][-1]",
    "assert not await pause(0); done = 1",
    "assert [v async for v in count_up(1)]; done = 1",
    "assert {v async for v in count_up(1)}; done = 1",
    "assert {v: 0 async for v in count_up(1)}; done = 1",
    "if (done := 1) and __debug__:\n    async with Guard():\n        pass",
    "if (done := 1) and __debug__:\n    async for _ in count_up(2):\n        pass",
    "while not done:\n    done = await pause(1)",
    "try:\n    done = await pause(1)\nfinally:\n    pass",
]
flag = ast.PyCF_ALLOW_TOP_LEVEL_AWAIT
ok = 0
problems = []
for mode in ("exec", "single"):
    for index, text in enumerate(samples):
        for level in (-1, 0, 1, 2):
            try:
                compile(text, "<tla>", mode, optimize=level)
                problems.append(("no-error", mode, index))
            except SyntaxError:
                ok += 1
            code = compile(text, "<tla>", mode, flags=flag, optimize=level)
            if code.co_flags & inspect.CO_COROUTINE:
                ok += 1
            else:
                problems.append(("no-coro", mode, index))
            for how in ("function", "eval"):
                env = {"done": 0, "pause": pause, "count_up": count_up, "Guard": Guard}
                run(types.FunctionType(code, env)() if how == "function" else eval(code, env))
                if env["done"] == 1:
                    ok += 1
                else:
                    problems.append((how, mode, index, env["done"]))
print(ok, len(samples) * 2 * 4 * 4, problems)"#;

    assert_output_with_stack(source, &[
            "576 576 []",
        ], 64 * 1024 * 1024);
}

// Adapted from CPython Lib/test/test_builtin.py::BuiltinTest::
// test_compile_top_level_await_invalid_cases. The public top-level-await flag
// must not make nested ordinary functions accept async-only constructs.
#[test]
fn cpython_builtin_compile_top_level_await_invalid_cases_subset() {
    assert_output(
        r#"import ast
bodies = [
    "def plain():\n    return await job()\n",
    "def plain():\n    return [v async for v in feed()]\n",
    "def plain():\n    return [await v async for v in feed()]\n",
    "def plain():\n    async for v in feed():\n        pass\n",
    "def plain():\n    async with ctx() as c:\n        pass\n",
    "g = lambda: await job()\n",
    "class K:\n    def m(self):\n        await job()\n",
]
for mode in ("exec", "single"):
    for flags in (0, ast.PyCF_ALLOW_TOP_LEVEL_AWAIT):
        verdicts = []
        for text in bodies:
            try:
                compile(text, "<bad>", mode, flags=flags)
                verdicts.append("ok")
            except SyntaxError as exc:
                verdicts.append("SyntaxError")
        print(mode, flags, verdicts)"#,
        &[
            "exec 0 ['SyntaxError', 'SyntaxError', 'SyntaxError', 'SyntaxError', 'SyntaxError', 'SyntaxError', 'SyntaxError']",
            "exec 8192 ['SyntaxError', 'SyntaxError', 'SyntaxError', 'SyntaxError', 'SyntaxError', 'SyntaxError', 'SyntaxError']",
            "single 0 ['SyntaxError', 'SyntaxError', 'SyntaxError', 'SyntaxError', 'SyntaxError', 'SyntaxError', 'SyntaxError']",
            "single 8192 ['SyntaxError', 'SyntaxError', 'SyntaxError', 'SyntaxError', 'SyntaxError', 'SyntaxError', 'SyntaxError']",
        ],
    );
}

// Adapted from CPython Lib/test/test_builtin.py::BuiltinTest::
// test_compile_async_generator. The top-level-await flag must not turn an async
// generator function into a coroutine.
#[test]
fn cpython_builtin_compile_async_generator_flag_subset() {
    assert_output(
        r#"import ast, inspect, types
text = "async def stream(n):\n    while n:\n        n -= 1\n        await nap()\n        yield n\n"
code = compile(text, "<agen>", "exec", flags=ast.PyCF_ALLOW_TOP_LEVEL_AWAIT)
print(bool(code.co_flags & inspect.CO_COROUTINE))
env = {}
exec(code, env)
fn = env["stream"]
print(bool(fn.__code__.co_flags & inspect.CO_ASYNC_GENERATOR), bool(fn.__code__.co_flags & inspect.CO_COROUTINE))
gen = fn(3)
print(type(gen).__name__, isinstance(gen, types.AsyncGeneratorType))"#,
        &[
            "False",
            "True False",
            "async_generator True",
        ],
    );
}

// Adapted from CPython's `interactive` starting rule and
// Lib/test/test_compile.py::test_single_statement / test_bad_single_statement.
// MiniPython models the same one-input boundary and displays expression
// statements through its REPL-style output.
#[test]
fn cpython_interactive_input_subset() {
    assert_interactive("1 + 2", &["3"]);
    assert_interactive("\n1 + 2", &["3"]);
    assert_interactive("1 + 2\n\n", &["3"]);
    assert_interactive("1; 2", &["1", "2"]);
    assert_interactive("import sys; sys.__name__", &["sys"]);
    assert_interactive("if True:\n   print(\"then\")", &["then"]);
    assert_interactive("class T:\n   pass", &[]);
    assert_interactive("\n", &[]);
    assert_interactive_error(
        "1\n2",
        "parse error: expected end of input, found Number(2)",
    );
    assert_interactive_error(
        "x = 5 # comment\nx = 6\n",
        "parse error: expected end of input, found Identifier(\"x\")",
    );
    assert_interactive_error("f{}", "parse error: invalid syntax");
}

// Adapted from CPython's `statement_newline` interactive-input rule. The rule
// accepts one compound statement, one simple-statement line, a blank line, or
// end-of-input.
#[test]
fn cpython_statement_newline_subset() {
    assert_interactive("", &[]);
    assert_interactive("\n", &[]);
    assert_interactive("1 + 2\n", &["3"]);
    assert_interactive("1; 2;\n", &["1", "2"]);
    assert_interactive("if True:\n    print(\"ok\")\n", &["ok"]);
}

// Adapted from CPython's `func_type` starting rule and
// Lib/test/test_type_comments.py::test_func_type_input. The CPython AST
// FunctionType mode ignores `*` and `**` markers and keeps the underlying type
// expressions.
#[test]
fn cpython_func_type_input_subset() {
    assert_func_type("() -> int", &["arg_types: []", "returns: Name(\"int\")"]);
    assert_func_type(
        "(int) -> List[str]",
        &[
            "Name(\"int\")",
            "Subscript",
            "Name(\"List\")",
            "Name(\"str\")",
        ],
    );
    assert_func_type(
        "(int, *str, **Any) -> float",
        &[
            "Name(\"int\")",
            "Name(\"str\")",
            "Name(\"Any\")",
            "returns: Name(\"float\")",
        ],
    );
    assert_func_type(
        "(int, str, *tuple, **dict) -> float\n\n",
        &[
            "Name(\"int\")",
            "Name(\"str\")",
            "Name(\"tuple\")",
            "Name(\"dict\")",
            "returns: Name(\"float\")",
        ],
    );
    assert_func_type("(*int) -> None", &["Name(\"int\")", "returns: None"]);
    assert_func_type("(**int) -> None", &["Name(\"int\")", "returns: None"]);
    assert_func_type(
        "(*int, **str) -> None",
        &["Name(\"int\")", "Name(\"str\")", "returns: None"],
    );
    assert_eq!(
        parse_func_type_source("(int, *str, *Any) -> float"),
        Err("parse error: multiple '*' type expressions are not allowed".to_string())
    );
    assert_eq!(
        parse_func_type_source("(int, **str, Any) -> float"),
        Err("parse error: '**' type expression must be last".to_string())
    );
    assert_eq!(
        parse_func_type_source("(**int, **str) -> float"),
        Err("parse error: '**' type expression must be last".to_string())
    );
}

// Adapted from CPython's `type_expressions` helper rule in
// Grammar/python.gram and Lib/test/test_type_comments.py::test_func_type_input.
// FunctionType mode ignores `*` and `**` markers but still enforces their
// ordering and rejects trailing commas.
#[test]
fn cpython_type_expression_helper_rules_subset() {
    assert_func_type(
        "(int, str) -> None",
        &["Name(\"int\")", "Name(\"str\")", "returns: None"],
    );
    assert_func_type(
        "(int, *str) -> None",
        &["Name(\"int\")", "Name(\"str\")", "returns: None"],
    );
    assert_func_type(
        "(int, **Any) -> None",
        &["Name(\"int\")", "Name(\"Any\")", "returns: None"],
    );
    assert_func_type(
        "(int, str, **dict) -> None",
        &[
            "Name(\"int\")",
            "Name(\"str\")",
            "Name(\"dict\")",
            "returns: None",
        ],
    );
    assert_func_type(
        "(*str, **Any) -> None",
        &["Name(\"str\")", "Name(\"Any\")", "returns: None"],
    );
    assert_func_type(
        "(int, str, *tuple, **dict) -> None",
        &[
            "Name(\"int\")",
            "Name(\"str\")",
            "Name(\"tuple\")",
            "Name(\"dict\")",
            "returns: None",
        ],
    );
    assert_func_type(
        "(list[int], dict[str, int]) -> tuple[str, int]",
        &[
            "Subscript",
            "Name(\"list\")",
            "Name(\"dict\")",
            "Name(\"tuple\")",
        ],
    );
    assert_eq!(
        parse_func_type_source("(int,) -> None"),
        Err("parse error: trailing comma in type expressions is not allowed".to_string())
    );
    assert_eq!(
        parse_func_type_source("(*int,) -> None"),
        Err("parse error: trailing comma in type expressions is not allowed".to_string())
    );
    assert_eq!(
        parse_func_type_source("(**int,) -> None"),
        Err("parse error: trailing comma in type expressions is not allowed".to_string())
    );
    assert_eq!(
        parse_func_type_source("(*int, str) -> None"),
        Err("parse error: plain type expression cannot follow '*' or '**'".to_string())
    );
}

// Pins '# type: ignore' comments inside multi-line signatures, calls, lambdas,
// and displays: normal parsing ignores them, while ast.parse(...,
// type_comments=True) records def-header ignores in type_ignores.
#[test]
fn cpython_type_ignore_comments_inside_brackets_subset() {
    assert_output(
        r#"import ast
def signature(
    first,  # type: ignore
    second=2,  # type: ignore[assignment]
    *args,  # type: ignore
    keyword=3,  # type: ignore[misc]
    **kwargs  # type: ignore
):  # type: ignore
    return first + second + keyword + len(args) + len(kwargs)
print('signature', signature(1))
def opened(  # type: ignore
    value,
    /,  # type: ignore
    other,
):
    return value - other
print('opened', opened(5, 2))
def own_line(
    # type: ignore
    value,
):
    return value
print('own-line', own_line(7))
total = signature(  # type: ignore
    10,  # type: ignore[arg-type]
)
print('call', total)
items = [
    1,  # type: ignore
    2,
]
print('list', items)
pick = (lambda a,  # type: ignore
        b: a + b)
print('lambda', pick(1, 2))
def with_default(
    value=(1,  # type: ignore
           2),
):
    return value
print('default', with_default())
namespace = {}
exec(compile('def compiled(\n    a,  # type: ignore\n):\n    return a * 2\n', '<type-ignore>', 'exec'), namespace)
print('compiled', namespace['compiled'](4))
sources = {
    'after-comma': 'def f(\n    a,  # type: ignore\n    b,  # type: ignore[assignment]\n):\n    pass\n',
    'last-no-comma': 'def f(\n    a  # type: ignore\n):\n    pass\n',
    'after-open': 'def f(  # type: ignore\n    a,\n):\n    pass\n',
    'then-comment': 'def f(\n    a,  # type: ignore\n    b,  # type: int\n):\n    pass\n',
    'star': 'def f(\n    *args,  # type: ignore\n    **kwargs  # type: ignore[misc]\n):\n    pass\n',
    'keyword-only': 'def f(\n    *,\n    a=1,  # type: ignore\n):\n    pass\n',
    'slash': 'def f(\n    a,\n    /,  # type: ignore\n    b,\n):\n    pass\n',
}
for label, source in sources.items():
    plain = ast.parse(source)
    typed = ast.parse(source, type_comments=True)
    arguments = typed.body[0].args
    params = arguments.posonlyargs + arguments.args + arguments.kwonlyargs + [arg for arg in (arguments.vararg, arguments.kwarg) if arg]
    print(label, len(plain.type_ignores), [(node.lineno, node.tag) for node in typed.type_ignores], [param.type_comment for param in params])"#,
        &[
            "signature 6",
            "opened 3",
            "own-line 7",
            "call 15",
            "list [1, 2]",
            "lambda 3",
            "default (1, 2)",
            "compiled 8",
            "after-comma 0 [(2, ''), (3, '[assignment]')] [None, None]",
            "last-no-comma 0 [(2, '')] [None]",
            "after-open 0 [(1, '')] [None]",
            "then-comment 0 [(2, '')] [None, 'int']",
            "star 0 [(2, ''), (3, '[misc]')] [None, None]",
            "keyword-only 0 [(3, '')] [None]",
            "slash 0 [(3, '')] [None, None]",
        ],
    );
}

// Adapted from Lib/test/test_type_comments.py. MiniPython currently preserves
// TYPE_COMMENT and TYPE_IGNORE at the lexer boundary, then treats them as
// parser trivia so executable behavior matches the supported syntax subset.
#[test]
fn cpython_type_comments_and_ignores_subset() {
    assert_output("x = 1  # type: int\nprint(x)", &["1"]);
    assert_output(
        "def foo():  # type: () -> int\n    return 1\nprint(foo())",
        &["1"],
    );
    assert_output("for item in [1]:  # type: int\n    print(item)", &["1"]);
    assert_output(
        "pass  # type: ignore\nx = 1  # type: ignore[assignment]\nprint(x)",
        &["1"],
    );
    assert_output("pass  # type: ignorewhatever\nprint(\"ok\")", &["ok"]);
}

// Adapted from CPython's `func_type_comment` helper rule and
// Lib/test/test_type_comments.py function-definition coverage. MiniPython
// accepts the same inline and own-line function type-comment shapes, exposes
// statement-level `type_comment` metadata through `ast.parse(...,
// type_comments=True)`, and rejects duplicate comments.
#[test]
fn cpython_func_type_comment_helper_rules_subset() {
    assert_output(
        "def foo():\n    # type: () -> int\n    return 1\nprint(foo())",
        &["1"],
    );
    assert_output(
        "def bar():  # type: () -> None\n    pass\nprint(bar())",
        &["None"],
    );
    assert_output(
        "async def foo():\n    # type: () -> int\n    return 1\nvalue = foo()\nprint(value)",
        &["<coroutine object foo>"],
    );
    assert_output(
        "async def bar():  # type: () -> int\n    return 2\nvalue = bar()\nprint(value)",
        &["<coroutine object bar>"],
    );
    assert_error(
        "def redundant():  # type: () -> int\n    # type: () -> str\n    return 1",
        "parse error: Cannot have two type comments on def",
    );
    assert_error(
        "async def redundant():  # type: () -> int\n    # type: () -> str\n    return 1",
        "parse error: Cannot have two type comments on def",
    );
}

// Adapted from CPython Lib/test/test_type_comments.py. `ast.parse(...,
// type_comments=True)` preserves statement-level type comments for functions,
// async functions, assignments, for-loops, async for-loops, with-statements,
// and async with-statements; ordinary
// `ast.parse()` keeps the same fields as `None`.
#[test]
fn cpython_type_comment_public_ast_metadata_subset() {
    assert_output(
        r#"import ast
text = "\n".join([
    "def first(a):",
    "    # type: (int) -> str",
    "    return str(a)",
    "def second():  # type: () -> float",
    "    return 1.0",
    "async def third():",
    "    # type: () -> list",
    "    return []",
    "async def fourth():  # type: () -> dict",
    "    async for row in rows:  # type: Row",
    "        pass",
    "    async with lock() as held:  # type: Held",
    "        pass",
    "count = 3  # type: int",
    "for key in data:  # type: bytes",
    "    pass",
    "with opener() as handle:  # type: IO",
    "    pass",
    "with (opener() as handle):  # type: IOParen",
    "    pass",
    "",
])
for typed in (True, False):
    tree = ast.parse(text, type_comments=typed)
    rows = []
    for node in ast.walk(tree):
        if "type_comment" in node._fields and not isinstance(node, ast.arg):
            rows.append((type(node).__name__, node.lineno, node.type_comment))
    print(typed, len(rows))
    for row in rows:
        print("-", *row)
compile(ast.parse(text, type_comments=True), "<tc>", "exec")
print("compiled")"#,
        &[
            "True 10",
            "- FunctionDef 1 (int) -> str",
            "- FunctionDef 4 () -> float",
            "- AsyncFunctionDef 6 () -> list",
            "- AsyncFunctionDef 9 () -> dict",
            "- Assign 14 int",
            "- For 15 bytes",
            "- With 17 IO",
            "- With 19 IOParen",
            "- AsyncFor 10 Row",
            "- AsyncWith 12 Held",
            "False 10",
            "- FunctionDef 1 None",
            "- FunctionDef 4 None",
            "- AsyncFunctionDef 6 None",
            "- AsyncFunctionDef 9 None",
            "- Assign 14 None",
            "- For 15 None",
            "- With 17 None",
            "- With 19 None",
            "- AsyncFor 10 None",
            "- AsyncWith 12 None",
            "compiled",
        ],
    );
}

// Adapted from CPython Lib/test/test_type_comments.py. Function parameter
// comments are exposed on public `ast.arg.type_comment` nodes only when
// `ast.parse(..., type_comments=True)` is requested.
#[test]
fn cpython_type_comment_argument_ast_metadata_subset() {
    assert_output(
        r#"import ast
source = """\
def typed(
    pos,  # type: pos
    only=1,  # type: only
    /,
    normal=2,  # type: normal
    *args,  # type: args
    kw,  # type: kw
    default_kw=3,  # type: default-kw
    **kwargs  # type: kwargs
):
    pass

def annotated(
    value: int,  # type: annotated
):
    pass
"""
module = ast.parse(source, type_comments=True)
typed = module.body[0]
args = typed.args
for group_name, group in (
    ("posonly", args.posonlyargs),
    ("args", args.args),
    ("kwonly", args.kwonlyargs),
):
    for arg in group:
        print(group_name, arg.arg, arg.type_comment)
print("vararg", args.vararg.arg, args.vararg.type_comment)
print("kwarg", args.kwarg.arg, args.kwarg.type_comment)
annotated = module.body[1].args.args[0]
print("annotated", annotated.arg, type(annotated.annotation).__name__, annotated.type_comment)
classic = ast.parse(source).body[0].args
for arg in classic.posonlyargs + classic.args + classic.kwonlyargs:
    print("classic", arg.arg, arg.type_comment)
print("classic vararg", classic.vararg.type_comment)
print("classic kwarg", classic.kwarg.type_comment)
compile(module, "<ast>", "exec")"#,
        &[
            "posonly pos pos",
            "posonly only only",
            "args normal normal",
            "kwonly kw kw",
            "kwonly default_kw default-kw",
            "vararg args args",
            "kwarg kwargs kwargs",
            "annotated value Name annotated",
            "classic pos None",
            "classic only None",
            "classic normal None",
            "classic kw None",
            "classic default_kw None",
            "classic vararg None",
            "classic kwarg None",
        ],
    );
}

// Adapted from CPython Lib/test/test_type_comments.py::
// TypeCommentTests.test_inappropriate_type_comments. These comments are
// ordinary comments when type comment parsing is off, but become SyntaxError
// when `ast.parse(..., type_comments=True)` asks the frontend to interpret
// them as type comments.
#[test]
fn cpython_inappropriate_type_comments_subset() {
    assert_output(
        r#"import ast
bad_sources = [
    "pass  # type: int\n",
    "foo()  # type: int\n",
    "x += 1  # type: int\n",
    "while True:  # type: int\n  continue\n",
    "while True:\n  continue  # type: int\n",
    "try:  # type: int\n  pass\nfinally:\n  pass\n",
    "try:\n  pass\nfinally:  # type: int\n  pass\n",
    "pass  # type: ignorewhatever\n",
    "pass  # type: ignoreé\n",
]
for source in bad_sources:
    ast.parse(source, type_comments=False)
    try:
        ast.parse(source, type_comments=True)
    except SyntaxError:
        print("strict-error", source.splitlines()[0])
    else:
        print("missing-error", source.splitlines()[0])

good_sources = [
    "x = 1  # type: int\n",
    "x = foo(y=1)  # type: int\n",
    "def f():  # type: () -> int\n  pass\n",
    "def f():\n  # type: () -> int\n  pass\n",
    "def f(a,  # type: A\n):\n  pass\n",
    "for a in []:  # type: int\n  pass\n",
    "with context() as a:  # type: int\n  pass\n",
]
for source in good_sources:
    ast.parse(source, type_comments=True)
print("legal-ok")"#,
        &[
            "strict-error pass  # type: int",
            "strict-error foo()  # type: int",
            "strict-error x += 1  # type: int",
            "strict-error while True:  # type: int",
            "strict-error while True:",
            "strict-error try:  # type: int",
            "strict-error try:",
            "strict-error pass  # type: ignorewhatever",
            "strict-error pass  # type: ignoreé",
            "legal-ok",
        ],
    );
}

// Adapted from CPython Lib/test/test_type_comments.py. These method-level
// smoke checks prove that enabling `type_comments=True` does not regress newer
// syntax forms, keeps non-ASCII function type comments intact, preserves the
// exact public `TypeIgnore.tag` strings, and still rejects `async` / `await` as
// ordinary assignment targets in the default parser mode.
#[test]
fn cpython_type_comment_modern_syntax_and_ignores_subset() {
    assert_output(
        r#"import ast
modern = {
    "async-comp": "async def collect(rows):\n    return {r async for r in rows}\n",
    "matrix": "m = left @ right\nm @= other\n",
    "f-string": "n = 5\ntext = f'{n!r:>4}'\n",
    "digits": "big = 1_000_000 + 0x_ff\n",
    "walrus": "if (size := 3) > 2:\n    pass\n",
}
for label, text in modern.items():
    tree = ast.parse(text, type_comments=True)
    print("parsed", label, len(tree.body))
for word in ("async", "await"):
    try:
        ast.parse(word + " = 1\n")
        print(word, "accepted")
    except SyntaxError:
        print(word, "SyntaxError")
accents = "def g():\n    # type: () -> déjà_vu\n    pass\n"
print(ast.parse(accents, type_comments=True).body[0].type_comment, ast.parse(accents).body[0].type_comment)
grouped = "with (x as y):  # type: str\n    pass\nwith (x, y):  # type: bytes\n    pass\n"
for typed in (True, False):
    print([(type(s).__name__, s.type_comment) for s in ast.parse(grouped, type_comments=typed).body])
marks = "\n".join([
    "x = 1  # type: ignore",
    "def h():",
    "    y = 2  # type: ignore[attr]",
    "    return y  # type: ignore =reason",
    "z = 3  # type: ignore  extra words",
    "w = 4  # type: ignore[a, b]",
    "",
])
tree = ast.parse(marks, type_comments=True)
print([(t.lineno, t.tag) for t in tree.type_ignores])
print(len(ast.parse(marks).type_ignores))"#,
        &[
            "parsed async-comp 1",
            "parsed matrix 2",
            "parsed f-string 2",
            "parsed digits 1",
            "parsed walrus 1",
            "async SyntaxError",
            "await SyntaxError",
            "() -> déjà_vu None",
            "[('With', 'str'), ('With', 'bytes')]",
            "[('With', None), ('With', None)]",
            "[(1, ''), (3, '[attr]'), (4, ' =reason'), (5, '  extra words'), (6, '[a, b]')]",
            "0",
        ],
    );
}

// Adapted from CPython's `invalid_def_raw` grammar rule and
// Lib/test/test_syntax.py function-definition header diagnostics. MiniPython
// preserves the same rejected source shapes before VM execution, with its own
// Rust parser wording.
#[test]
fn cpython_invalid_function_def_raw_subset() {
    assert_error("def f:\n    pass", "parse error: expected '(', found Colon");
    assert_error(
        "async def f:\n    pass",
        "parse error: expected '(', found Colon",
    );
    assert_error(
        "def f -> int:\n    pass",
        "parse error: expected '(', found Arrow",
    );
    assert_error(
        "async def f -> int:  # type: int\n    pass",
        "parse error: expected '(', found Arrow",
    );
    assert_error(
        "async def f[T]:\n    pass",
        "parse error: expected '(', found Colon",
    );
    assert_error(
        "def f[T] -> str:\n    pass",
        "parse error: expected '(', found Arrow",
    );
    assert_error(
        "def foo(x, /, y, *, z=2):\npass",
        "parse error: expected an indented block",
    );
    assert_error(
        "async def foo(x, /, y, *, z=2):\npass",
        "parse error: expected an indented block",
    );
    assert_error(
        "def foo[T](x, /, y, *, z=2):\npass",
        "parse error: expected an indented block",
    );
    assert_error(
        "async def foo[T](x) -> int:\npass",
        "parse error: expected an indented block",
    );
    assert_error(
        "def foo(x)\n    pass",
        "parse error: expected ':', found Newline",
    );
    assert_error(
        "def foo[T](x)\n    pass",
        "parse error: expected ':', found Newline",
    );
    assert_error(
        "async def foo(x)\n    pass",
        "parse error: expected ':', found Newline",
    );
    for source in [
        "def f() ->:\n    pass",
        "def f() ->\n    pass",
        "def f() ->",
        "def f() ->; pass",
        "async def f() ->:\n    pass",
        "async def f() ->\n    pass",
    ] {
        assert_error(source, "parse error: expected ':'");
    }
    for source in [
        "def f[*Ts]() -> *Ts:\n    pass",
        "def f() -> *:\n    pass",
        "def f() -> *\n    pass",
        "def f[*Ts]() -> *Ts, int:\n    pass",
        "def f() -> **Ts:\n    pass",
        "def f() -> **:\n    pass",
        "async def f[*Ts]() -> *Ts:\n    pass",
    ] {
        assert_error(source, "parse error: expected ':'");
    }

    assert_parse_error_diagnostic("def f:\n    pass", "expected '(', found Colon", 1, 6, 1, 7);
    assert_parse_error_diagnostic(
        "async def f:\n    pass",
        "expected '(', found Colon",
        1,
        12,
        1,
        13,
    );
    assert_parse_error_diagnostic(
        "def f -> int:\n    pass",
        "expected '(', found Arrow",
        1,
        7,
        1,
        9,
    );
    assert_parse_error_diagnostic(
        "def foo(x, /, y, *, z=2):\npass",
        "expected an indented block",
        2,
        1,
        2,
        5,
    );
    assert_parse_error_diagnostic(
        "def foo(x)\n    pass",
        "expected ':', found Newline",
        1,
        11,
        2,
        1,
    );
}

