// Adapted from CPython `ConstantTests` in Lib/test/test_ast/test_ast.py.
// This first pass covers Constant compile validation, singleton/value
// preservation, invalid assignment targets, literal_eval replacement, and
// string-prefix `kind` metadata for supported public AST nodes.
#[test]
fn cpython_ast_constant_compile_first_pass_subset() {
    assert_output(
        r#"import ast
import dis

def via_constant(value):
    mod = ast.parse("result = 0")
    stmt = mod.body[0]
    stmt.value = ast.copy_location(ast.Constant(value=value), stmt.value)
    env = {}
    exec(compile(mod, "<const>", "exec"), env)
    return env["result"]

singletons = [None, True, False, ...]
print([via_constant(v) is v for v in singletons])
plain = [0, -7, 2 ** 70, 2.5, 1e300, 4j, complex(0, -1.5), "text", "", "ü", b"", b"\x00\xff"]
print([via_constant(v) for v in plain])
deep_tuple = (1, (2.0, ("three", (b"4",))))
deep_set = frozenset({frozenset({frozenset({0}), "x"}), 9})
mixed = (frozenset({1, 2}), (None, ...))
for value in (deep_tuple, deep_set, mixed, tuple("abc"), frozenset("abc")):
    got = via_constant(value)
    print(type(got).__name__, got == value)
for bad in ([1], {2: 3}, {4}, bytearray(b"z")):
    try:
        via_constant(bad)
    except TypeError as exc:
        print("TypeError", exc)

loop = ast.parse("for item in data:\n    pass")
target = loop.body[0].target
loop.body[0].target = ast.copy_location(ast.Constant(value="lit"), target)
try:
    compile(loop, "<store>", "exec")
except ValueError as exc:
    print("ValueError", exc)

expr = ast.parse("0 - 0", mode="eval").body
expr.left = ast.copy_location(ast.Constant(value=5), expr.left)
expr.right = ast.copy_location(ast.Constant(value=2j), expr.right)
print(ast.literal_eval(expr))
print([ast.parse(text, mode="eval").body.kind for text in ("'q'", "u'q'", "r'q'", "b'q'", "rb'q'")])
print(ast.get_docstring(ast.parse("'''module text'''\nvalue = 1", optimize=False)))

def loaded_constants(tree):
    code = compile(tree, "<consts>", "exec")
    return [ins.argval for ins in dis.get_instructions(code) if ins.opcode in dis.hasconst]

values = [None, False, 5000, 0.25, 2j, "s", b"b", (4, 5), ...]
tree = ast.parse("\n".join("v = " + ("..." if v is ... else repr(v)) for v in values))
before = loaded_constants(tree)
for stmt, value in zip(tree.body, values):
    stmt.value = ast.copy_location(ast.Constant(value=value), stmt.value)
after = loaded_constants(tree)
print(before[:len(values)] == values, after == before)"#,
        &[
            "[True, True, True, True]",
            "[0, -7, 1180591620717411303424, 2.5, 1e+300, 4j, -1.5j, 'text', '', 'ü', b'', b'\\x00\\xff']",
            "tuple True",
            "frozenset True",
            "tuple True",
            "tuple True",
            "frozenset True",
            "TypeError got an invalid type in Constant: list",
            "TypeError got an invalid type in Constant: dict",
            "TypeError got an invalid type in Constant: set",
            "TypeError got an invalid type in Constant: bytearray",
            "ValueError expression which can't be assigned to in Store context",
            "(5-2j)",
            "[None, 'u', None, None, None]",
            "module text",
            "True True",
        ],
    );
}

