// Adapted from CPython grammar `assignment`, whose alternatives cover
// annotated name targets, annotated parenthesized/subscript/attribute targets,
// one-or-more chained `star_targets =` groups, augmented assignment, and the
// delegated `invalid_assignment` rules.
#[test]
fn cpython_assignment_rule_alternatives_subset() {
    assert_output(
        "class Box:\n    pass\nbox = Box()\nitems = [0, 1]\nx: int\ny: str = \"ok\"\n(box.value): int = 4\n(items[0]): int = 5\na = b = *[1, 2], 3\np, *middle, q = [1, 2, 3, 4]\nbox.value += 6\nitems[0] += 2\nprint(__annotations__[\"x\"].__name__, __annotations__['y'].__name__, y)\nprint(box.value, items, a, b, p, middle, q)",
        &["int str ok", "10 [7, 1] (1, 2, 3) (1, 2, 3) 1 [2, 3] 4"],
    );
    assert_error(
        "a + b = 1",
        "parse error: cannot assign to expression here. Maybe you meant '==' instead of '='?",
    );
    assert_error(
        "f() += 1",
        "parse error: 'function call' is an illegal expression for augmented assignment",
    );
    assert_error(
        "a, b: int",
        "parse error: only single target (not tuple) can be annotated",
    );
}

// Adapted from CPython invalid assignment-target coverage in
// Lib/test/test_syntax.py. MiniPython should reject these forms before VM
// execution even when its exact diagnostic text is intentionally simpler.
#[test]
fn cpython_invalid_assignment_target_subset() {
    assert_parse_error("None = 1");
    assert_parse_error("True = 1");
    assert_parse_error("__debug__ = 1");
    assert_parse_error("obj.__debug__ = 1");
    assert_parse_error("def __debug__():\n    pass");
    assert_parse_error("async def __debug__():\n    pass");
    assert_parse_error("class __debug__:\n    pass");
    assert_parse_error("del __debug__");
    assert_parse_error("f() = 1");
    assert_parse_error("del f()");
    assert_parse_error("a + 1 = 2");
    assert_parse_error("(x for x in x) = 1");
    assert_parse_error("1 = 1");
    assert_parse_error("\"abc\" = 1");
    assert_parse_error("... = 1");
    assert_parse_error("a, b += 1, 2");
    assert_parse_error("(a, b) += 1, 2");
    assert_parse_error("[a, b] += 1, 2");
    assert_parse_error("for __debug__ in [1]:\n    pass");
    assert_parse_error("with manager as __debug__:\n    pass");
    assert_parse_error("[x for __debug__ in [1]]");
    assert_parse_error("del (*x,)");
    assert_parse_error("del [*x,]");
    assert_parse_error("del x, *y");
    assert_error("a[b:=0:] = 1", "parse error: invalid syntax");
    assert_parse_error("a[:b:=0] = 1");
    assert_parse_error("a[::b:=0] = 1");
    assert_parse_error("del a[b:=0:]");
    assert_parse_error("a[b:=0:] += 1");

    assert_parse_error_diagnostic(
        "None = 1",
        "cannot assign to None here. Maybe you meant '==' instead of '='?",
        1,
        1,
        1,
        5,
    );
    assert_parse_error_diagnostic(
        "True = 1",
        "cannot assign to True here. Maybe you meant '==' instead of '='?",
        1,
        1,
        1,
        5,
    );
    assert_parse_error_diagnostic("__debug__ = 1", "cannot assign to __debug__", 1, 1, 1, 10);
    assert_parse_error_diagnostic(
        "1 = 1",
        "cannot assign to literal here. Maybe you meant '==' instead of '='?",
        1,
        1,
        1,
        2,
    );
    assert_parse_error_diagnostic(
        "\"abc\" = 1",
        "cannot assign to literal here. Maybe you meant '==' instead of '='?",
        1,
        1,
        1,
        6,
    );
}

// Adapted from CPython's `invalid_assignment` and `invalid_ann_assign_target`
// grammar rules, with examples from Lib/test/test_syntax.py. MiniPython reports
// the same high-level target category for the supported invalid forms.
#[test]
fn cpython_invalid_assignment_and_annotation_subset() {
    assert_error(
        "f() = 1",
        "parse error: cannot assign to function call here. Maybe you meant '==' instead of '='?",
    );
    assert_error(
        "x = f() = 1",
        "parse error: cannot assign to function call here. Maybe you meant '==' instead of '='?",
    );
    assert_error(
        "x = 1 = 2",
        "parse error: cannot assign to literal here. Maybe you meant '==' instead of '='?",
    );
    assert_error(
        "x = a + 1 = 2",
        "parse error: cannot assign to expression here. Maybe you meant '==' instead of '='?",
    );
    assert_error(
        "yield = 1",
        "parse error: assignment to yield expression not possible",
    );
    assert_error(
        "x = y = yield = 1",
        "parse error: assignment to yield expression not possible",
    );
    assert_error(
        "yield value = 1",
        "parse error: assignment to yield expression not possible",
    );
    assert_error(
        "yield from values = 1",
        "parse error: assignment to yield expression not possible",
    );
    assert_error(
        "1 = 2",
        "parse error: cannot assign to literal here. Maybe you meant '==' instead of '='?",
    );
    assert_error(
        "a + 1 = 2",
        "parse error: cannot assign to expression here. Maybe you meant '==' instead of '='?",
    );
    assert_error(
        "a, b: int",
        "parse error: only single target (not tuple) can be annotated",
    );
    assert_error(
        "(a, b): int",
        "parse error: only single target (not tuple) can be annotated",
    );
    assert_error(
        "((a, b)): int",
        "parse error: only single target (not tuple) can be annotated",
    );
    assert_error(
        "[a, b]: int",
        "parse error: only single target (not list) can be annotated",
    );
    assert_error(
        "([a, b]): int",
        "parse error: only single target (not list) can be annotated",
    );
    assert_error(
        "(([a, b])): int",
        "parse error: only single target (not list) can be annotated",
    );
    assert_error("a + 1: int", "parse error: illegal target for annotation");
    assert_error("f(): int", "parse error: illegal target for annotation");
    for source in [
        "x:\n    pass",
        "x:",
        "x: # missing annotation expression\n",
        "obj.attr:\n    pass",
        "arr[0]:\n    pass",
        "x:; pass",
    ] {
        assert_error(source, "parse error: invalid syntax");
    }
    assert_error(
        "a, b += 1, 2",
        "parse error: 'tuple' is an illegal expression for augmented assignment",
    );
    assert_error(
        "[a, b] += [1, 2]",
        "parse error: 'list' is an illegal expression for augmented assignment",
    );
    assert_error(
        "f() += 1",
        "parse error: 'function call' is an illegal expression for augmented assignment",
    );
    assert_error(
        "1 += 2",
        "parse error: 'literal' is an illegal expression for augmented assignment",
    );
    assert_error(
        "a + b += 1",
        "parse error: 'expression' is an illegal expression for augmented assignment",
    );

    assert_parse_error_diagnostic(
        "f() = 1",
        "cannot assign to function call here. Maybe you meant '==' instead of '='?",
        1,
        1,
        1,
        4,
    );
    assert_parse_error_diagnostic(
        "x = f() = 1",
        "cannot assign to function call here. Maybe you meant '==' instead of '='?",
        1,
        5,
        1,
        8,
    );
    assert_parse_error_diagnostic(
        "x = 1 = 2",
        "cannot assign to literal here. Maybe you meant '==' instead of '='?",
        1,
        5,
        1,
        6,
    );
    assert_parse_error_diagnostic(
        "x = a + 1 = 2",
        "cannot assign to expression here. Maybe you meant '==' instead of '='?",
        1,
        5,
        1,
        10,
    );
}

// Adapted from CPython AST augmented assignment snippets in
