// Adapted from CPython `Lib/test/test_builtin.py::TestBreakpoint` public hook
// dispatch rows. MiniPython covers custom `sys.breakpointhook` dispatch and
// hook-loss errors. The default hook is a sandbox no-op stub; pdb integration
// and `PYTHONBREAKPOINT` environment behavior remain runtime integration work.
#[test]
fn cpython_builtin_breakpoint_custom_hook_subset() {
    assert_output(
        "import builtins, sys\nprint(hasattr(builtins, 'breakpoint'), callable(builtins.breakpoint))\nprint(hasattr(sys, 'breakpointhook'), hasattr(sys, '__breakpointhook__'), sys.breakpointhook is sys.__breakpointhook__)\nfor fn in [builtins.breakpoint, builtins.len, builtins.print]:\n    print(fn.__name__, fn.__qualname__, fn.__module__, type(fn.__doc__).__name__, bool(fn.__doc__), all(name in dir(fn) for name in ['__doc__', '__module__', '__name__', '__qualname__']))\nhook_meta = sys.__breakpointhook__\nprint(hook_meta.__name__, hook_meta.__qualname__, hook_meta.__module__, type(hook_meta.__doc__).__name__, bool(hook_meta.__doc__), all(name in dir(hook_meta) for name in ['__doc__', '__module__', '__name__', '__qualname__']))\ndef hook(*args, **kwargs):\n    print('hook', args, kwargs)\n    return 'ret'\nsaved = sys.breakpointhook\nsys.breakpointhook = hook\nprint('call0', breakpoint())\nprint('callargs', breakpoint(1, 'x', key=3))\nprint('module-call', builtins.breakpoint())\ndel sys.breakpointhook\ntry:\n    breakpoint()\nexcept RuntimeError as error:\n    print('lost', type(error).__name__, str(error))\nfinally:\n    sys.breakpointhook = saved\nprint('reset-same', sys.breakpointhook is sys.__breakpointhook__)",
        &[
            "True True",
            "True True True",
            "breakpoint breakpoint builtins str True True",
            "len len builtins str True True",
            "print print builtins str True True",
            "breakpointhook breakpointhook sys str True True",
            "hook () {}",
            "call0 ret",
            "hook (1, 'x') {'key': 3}",
            "callargs ret",
            "hook () {}",
            "module-call ret",
            "lost RuntimeError lost sys.breakpointhook",
            "reset-same True",
        ],
    );
}

#[test]
fn cpython_builtin_breakpoint_default_stub_subset() {
    assert_output(
        "import sys\nfor label, callback in [\n    ('breakpoint', lambda: breakpoint()),\n    ('hook', lambda: sys.breakpointhook()),\n    ('dunder', lambda: sys.__breakpointhook__(1, key=2)),\n]:\n    print(label, callback())",
        &["breakpoint None", "hook None", "dunder None"],
    );
}

#[test]
fn cpython_builtin_breakpoint_passthru_error_subset() {
    assert_output(
        "import sys\ndef hook(required):\n    return required\nsaved = sys.breakpointhook\nsys.breakpointhook = hook\ntry:\n    for label, callback in [\n        ('missing', lambda: breakpoint()),\n        ('extra', lambda: breakpoint(1, 2)),\n        ('keyword', lambda: breakpoint(required=1)),\n        ('unknown', lambda: breakpoint(unknown=1)),\n    ]:\n        try:\n            print(label, callback())\n        except Exception as error:\n            print(label, type(error).__name__, isinstance(error, TypeError))\nfinally:\n    sys.breakpointhook = saved",
        &[
            "missing TypeError True",
            "extra TypeError True",
            "keyword 1",
            "unknown TypeError True",
        ],
    );
}

// Adapted from CPython's public `str` instance attribute assignment errors.
// MiniPython exposes string methods without adding a writable instance
// `__dict__`.
#[test]
fn cpython_str_attribute_assignment_errors_subset() {
    assert_output(
        r#"def show(label, expr):
    try:
        value = expr()
        print(label, value)
    except AttributeError as error:
        print(label, type(error).__name__, str(error))

s = 'spam'
for name in ['extra', 'upper', 'split']:
    show('set-' + name, lambda name=name: setattr(s, name, 99))
    show('del-' + name, lambda name=name: delattr(s, name))
print('read', s.upper(), s.split('a'))"#,
        &[
            "set-extra AttributeError 'str' object has no attribute 'extra' and no __dict__ for setting new attributes",
            "del-extra AttributeError 'str' object has no attribute 'extra' and no __dict__ for setting new attributes",
            "set-upper AttributeError 'str' object attribute 'upper' is read-only",
            "del-upper AttributeError 'str' object attribute 'upper' is read-only",
            "set-split AttributeError 'str' object attribute 'split' is read-only",
            "del-split AttributeError 'str' object attribute 'split' is read-only",
            "read SPAM ['sp', 'm']",
        ],
    );
}

