fn cpython_array_array_class_getitem_generic_alias_subset() {
    assert_output(
        r#"import array
typ = array.array
inst = array.array('i')
class C(array.array):
    pass
for label, expr in [
    ('visible', lambda: (hasattr(typ, '__class_getitem__'), '__class_getitem__' in dir(typ), type(typ.__class_getitem__).__name__)),
    ('visible-inst', lambda: (hasattr(inst, '__class_getitem__'), '__class_getitem__' in dir(inst))),
    ('subscript-int', lambda: (type(typ[int]).__name__, str(typ[int]), typ[int].__origin__ is typ, typ[int].__args__)),
    ('call-int', lambda: (type(typ.__class_getitem__(int)).__name__, str(typ.__class_getitem__(int)), typ.__class_getitem__(int) == typ[int], typ.__class_getitem__(int).__origin__ is typ, typ.__class_getitem__(int).__args__)),
    ('call-pair', lambda: (str(typ.__class_getitem__((int, str))), typ.__class_getitem__((int, str)) == typ[int, str], typ.__class_getitem__((int, str)).__args__)),
    ('inst-exact', lambda: (inst.__class_getitem__(int) == typ[int], inst.__class_getitem__(int).__origin__ is typ)),
    ('type-sub', lambda: (hasattr(C, '__class_getitem__'), '__class_getitem__' in dir(C), type(C.__class_getitem__).__name__, type(C.__class_getitem__(int)).__name__, C.__class_getitem__(int).__origin__ is C, C.__class_getitem__(int).__args__)),
    ('inst-sub', lambda: (hasattr(C('i'), '__class_getitem__'), '__class_getitem__' in dir(C('i')), type(C('i').__class_getitem__(str)).__name__, C('i').__class_getitem__(str).__origin__ is C, C('i').__class_getitem__(str).__args__)),
    ('call-noargs', lambda: typ.__class_getitem__()),
    ('call-extra', lambda: typ.__class_getitem__(int, str)),
    ('call-keyword', lambda: typ.__class_getitem__(item=int)),
    ('sub-keyword', lambda: C.__class_getitem__(item=int)),
]:
    try:
        result = expr()
        print(label, type(result).__name__, result)
    except Exception as error:
        print(label, type(error).__name__, str(error), error.args)"#,
        &[
            "visible tuple (True, True, 'builtin_function_or_method')",
            "visible-inst tuple (True, True)",
            "subscript-int tuple ('GenericAlias', 'array.array[int]', True, (<class 'int'>,))",
            "call-int tuple ('GenericAlias', 'array.array[int]', True, True, (<class 'int'>,))",
            "call-pair tuple ('array.array[int, str]', True, (<class 'int'>, <class 'str'>))",
            "inst-exact tuple (True, True)",
            "type-sub tuple (True, True, 'builtin_function_or_method', 'GenericAlias', True, (<class 'int'>,))",
            "inst-sub tuple (True, True, 'GenericAlias', True, (<class 'str'>,))",
            "call-noargs TypeError array.__class_getitem__() takes exactly one argument (0 given) ('array.__class_getitem__() takes exactly one argument (0 given)',)",
            "call-extra TypeError array.__class_getitem__() takes exactly one argument (2 given) ('array.__class_getitem__() takes exactly one argument (2 given)',)",
            "call-keyword TypeError array.__class_getitem__() takes no keyword arguments ('array.__class_getitem__() takes no keyword arguments',)",
            "sub-keyword TypeError C.__class_getitem__() takes no keyword arguments ('C.__class_getitem__() takes no keyword arguments',)",
        ],
    );
}

#[test]
fn cpython_array_iterator_type_metadata_dir_surface_subset() {
    assert_output(
        r#"from array import array
source = array('b', [1, -2, 3])
inst = iter(source)
typ = type(inst)
print('type-name', typ.__name__, typ.__module__, typ.__qualname__)
print('visible-type', '__base__' in dir(typ), '__bases__' in dir(typ), '__name__' in dir(typ), '__module__' in dir(typ), '__qualname__' in dir(typ), '__iter__' in dir(typ), '__next__' in dir(typ), '__length_hint__' in dir(typ), '__reduce__' in dir(typ))
print('visible-inst', '__base__' in dir(inst), '__bases__' in dir(inst), '__name__' in dir(inst), '__iter__' in dir(inst), '__next__' in dir(inst), '__length_hint__' in dir(inst), '__reduce__' in dir(inst))
print('has-length', hasattr(typ, '__length_hint__'), hasattr(inst, '__length_hint__'))
print('has-reduce', hasattr(typ, '__reduce__'), hasattr(inst, '__reduce__'))
print('readable-base', typ.__base__ is object, typ.__bases__ == (object,), object.__getattribute__(typ, '__name__'))
print('readable-module', object.__getattribute__(typ, '__module__'), object.__getattribute__(typ, '__qualname__'))
fresh = iter(source).__reduce__()
print('fresh-reduce', len(fresh), fresh[0] is iter, len(fresh[1]), type(fresh[1][0]).__name__, fresh[1][0] == source, fresh[2], len(fresh) == 3)
print('iter-next', iter(inst) is inst, next(inst), next(inst))
reduced = typ.__reduce__(inst)
print('reduce-shape', len(reduced), reduced[0] is iter, len(reduced[1]), type(reduced[1][0]).__name__, reduced[1][0] == source, reduced[2], len(reduced) == 3)
late = iter(source)
next(late)
next(late)
late_reduced = late.__reduce__()
print('late-reduce', len(late_reduced), late_reduced[0] is iter, len(late_reduced[1]), type(late_reduced[1][0]).__name__, late_reduced[1][0] == source, late_reduced[2], len(late_reduced) == 3)
empty_source = array('b')
empty = iter(empty_source).__reduce__()
print('empty-reduce', len(empty), empty[0] is iter, len(empty[1]), type(empty[1][0]).__name__, empty[1][0] == empty_source, empty[2], len(empty) == 3)
exhausted_source = array('b', [1])
exhausted = iter(exhausted_source)
next(exhausted)
exhausted_reduced = exhausted.__reduce__()
print('exhausted-reduce', len(exhausted_reduced), exhausted_reduced[0] is iter, len(exhausted_reduced[1]), type(exhausted_reduced[1][0]).__name__, exhausted_reduced[1][0] == exhausted_source, exhausted_reduced[2], len(exhausted_reduced) == 3)"#,
        &[
            "type-name arrayiterator array arrayiterator",
            "visible-type False False False True False True True False True",
            "visible-inst False False False True True False True",
            "has-length False False",
            "has-reduce True True",
            "readable-base True True arrayiterator",
            "readable-module array arrayiterator",
            "fresh-reduce 3 True 1 array True 0 True",
            "iter-next True 1 -2",
            "reduce-shape 3 True 1 array True 2 True",
            "late-reduce 3 True 1 array True 2 True",
            "empty-reduce 3 True 1 array True 0 True",
            "exhausted-reduce 3 True 1 array True 1 True",
        ],
    );
}

#[test]
fn cpython_array_iterator_setstate_subset() {
    assert_output(
        r#"from array import array

def show(label, callback):
    try:
        print(label, callback())
    except Exception as error:
        print(label, type(error).__name__, str(error))

source = array('b', [1, -2, 3])
inst = iter(source)
typ = type(inst)
print('visible-setstate', '__setstate__' in dir(typ), '__setstate__' in dir(inst), hasattr(typ, '__setstate__'), hasattr(inst, '__setstate__'))
for state in [-1, 0, 1, 2, 3, 99, True, False]:
    probe = iter(source)
    result = probe.__setstate__(state)
    try:
        value = next(probe)
    except StopIteration:
        value = 'StopIteration'
    print('setstate-next', repr(state), result, value)
for bad in [None, 1.5, '1', []]:
    probe = iter(source)
    show('bad-setstate-' + type(bad).__name__, lambda probe=probe, bad=bad: probe.__setstate__(bad))
show('missing', lambda: iter(source).__setstate__())
show('extra', lambda: iter(source).__setstate__(0, 1))
shifted = iter(source)
print('unbound-setstate', typ.__setstate__(shifted, 2))
print('unbound-next', next(shifted))
show('unbound-bad', lambda: typ.__setstate__(object(), 0))"#,
        &[
            "visible-setstate True True True True",
            "setstate-next -1 None 1",
            "setstate-next 0 None 1",
            "setstate-next 1 None -2",
            "setstate-next 2 None 3",
            "setstate-next 3 None StopIteration",
            "setstate-next 99 None StopIteration",
            "setstate-next True None -2",
            "setstate-next False None 1",
            "bad-setstate-NoneType TypeError an integer is required",
            "bad-setstate-float TypeError an integer is required",
            "bad-setstate-str TypeError an integer is required",
            "bad-setstate-list TypeError an integer is required",
            "missing TypeError arrayiterator.__setstate__() takes exactly one argument (0 given)",
            "extra TypeError arrayiterator.__setstate__() takes exactly one argument (2 given)",
            "unbound-setstate None",
            "unbound-next 3",
            "unbound-bad TypeError descriptor '__setstate__' for 'array.arrayiterator' objects doesn't apply to a 'object' object",
        ],
    );
}

