// Adapted from CPython public inherited `object.__getstate__` behavior for
// built-in pure-memory instances. This pins the default no-state result without
// promoting pickle support, custom instance state, or CPython object-layout
// state extraction.
#[test]
fn cpython_object_getstate_builtin_instance_subset() {
    assert_output(
        r#"def show(label, cb):
    try:
        v = cb()
        print(label, 'ok', repr(v), type(v).__name__)
    except Exception as e:
        print(label, type(e).__name__, str(e), e.args)

samples = [
    ('none', None),
    ('bool', True),
    ('int', 1),
    ('bigint', 10**30),
    ('float', 1.5),
    ('complex', 1+2j),
    ('str', 'x'),
    ('bytes', b'x'),
    ('bytearray', bytearray(b'x')),
    ('tuple', (1,)),
    ('list', [1]),
    ('dict', {'a': 1}),
    ('set', {1}),
    ('frozenset', frozenset({1})),
    ('range', range(2)),
    ('slice', slice(1)),
]
for label, value in samples:
    show(label + '-instance-getstate', lambda value=value: value.__getstate__())

for label, value in [('none', None), ('int', 1), ('list', [1]), ('dict', {'a': 1})]:
    show(label + '-getattribute-getstate', lambda value=value: object.__getattribute__(value, '__getstate__')())

for label, cb in [
    ('int-instance-extra', lambda: (1).__getstate__(2)),
    ('list-instance-extra', lambda: [1].__getstate__(2)),
    ('int-instance-keyword', lambda: (1).__getstate__(x=2)),
    ('list-instance-keyword', lambda: [1].__getstate__(x=2)),
]:
    show(label, cb)"#,
        &[
            "none-instance-getstate ok None NoneType",
            "bool-instance-getstate ok None NoneType",
            "int-instance-getstate ok None NoneType",
            "bigint-instance-getstate ok None NoneType",
            "float-instance-getstate ok None NoneType",
            "complex-instance-getstate ok None NoneType",
            "str-instance-getstate ok None NoneType",
            "bytes-instance-getstate ok None NoneType",
            "bytearray-instance-getstate ok None NoneType",
            "tuple-instance-getstate ok None NoneType",
            "list-instance-getstate ok None NoneType",
            "dict-instance-getstate ok None NoneType",
            "set-instance-getstate ok None NoneType",
            "frozenset-instance-getstate ok None NoneType",
            "range-instance-getstate ok None NoneType",
            "slice-instance-getstate ok None NoneType",
            "none-getattribute-getstate ok None NoneType",
            "int-getattribute-getstate ok None NoneType",
            "list-getattribute-getstate ok None NoneType",
            "dict-getattribute-getstate ok None NoneType",
            "int-instance-extra TypeError object.__getstate__() takes no arguments (1 given) ('object.__getstate__() takes no arguments (1 given)',)",
            "list-instance-extra TypeError object.__getstate__() takes no arguments (1 given) ('object.__getstate__() takes no arguments (1 given)',)",
            "int-instance-keyword TypeError object.__getstate__() takes no keyword arguments ('object.__getstate__() takes no keyword arguments',)",
            "list-instance-keyword TypeError object.__getstate__() takes no keyword arguments ('object.__getstate__() takes no keyword arguments',)",
        ],
    );
}

// Adapted from CPython `Lib/test/test_builtin.py` public str/format behavior.
// This covers ordinary `str()` conversion paths separately from direct
// `object.__str__` descriptor calls above.
#[test]
fn cpython_str_builtin_custom_dunder_subset() {
    assert_output(
        r#"class Custom:
    def __str__(self):
        return 'custom-str'
    def __repr__(self):
        return 'custom-repr'
custom = Custom()
print(str(custom), f'{custom}', f'{custom!s}', '%s' % custom)
print('print-call', custom)
print(object.__str__(custom), object.__str__(custom) == repr(custom))
print(object.__format__(custom, ''), format(custom, ''))
class Bad:
    def __str__(self):
        return 1
for label, expr in [('str-bad', lambda: str(Bad())), ('format-bad', lambda: f'{Bad()}'), ('percent-bad', lambda: '%s' % Bad())]:
    try:
        expr()
    except TypeError as error:
        print(label, type(error).__name__, '__str__ returned non-string' in str(error))
class Raises:
    def __str__(self):
        raise ValueError('boom')
try:
    str(Raises())
except ValueError as error:
    print('raises', type(error).__name__, str(error))
class InstanceOnly:
    pass
instance_only = InstanceOnly()
instance_only.__str__ = lambda: 'instance-str'
instance_value = str(instance_only)
print('instance-only', instance_value.startswith('<'), 'InstanceOnly object' in instance_value)
class ReprOnly:
    def __repr__(self):
        return 'repr-only'
repr_only = ReprOnly()
print('repr-only', str(repr_only), f'{repr_only}', '%s' % repr_only)
class BadReprOnly:
    def __repr__(self):
        return 1
for label, expr in [('str-bad-repr', lambda: str(BadReprOnly())), ('format-bad-repr', lambda: f'{BadReprOnly()}'), ('percent-bad-repr', lambda: '%s' % BadReprOnly())]:
    try:
        expr()
    except TypeError as error:
        print(label, type(error).__name__, '__str__ returned non-string' in str(error))
class Blocked:
    __str__ = None
try:
    str(Blocked())
except TypeError as error:
    print('blocked', type(error).__name__)
class WithFormat:
    def __str__(self):
        return 'str-value'
    def __format__(self, spec):
        return 'format-' + spec
formatted = WithFormat()
print('format-priority', f'{formatted}', format(formatted, 'x'), str(formatted))
class StrSub(str):
    def __str__(self):
        return 'sub-str'
sub = StrSub('base')
print('str-sub', str(sub), f'{sub}', '%s' % sub, format(sub, '>6'))"#,
        &[
            "custom-str custom-str custom-str custom-str",
            "print-call custom-str",
            "custom-repr True",
            "custom-str custom-str",
            "str-bad TypeError True",
            "format-bad TypeError True",
            "percent-bad TypeError True",
            "raises ValueError boom",
            "instance-only True True",
            "repr-only repr-only repr-only repr-only",
            "str-bad-repr TypeError True",
            "format-bad-repr TypeError True",
            "percent-bad-repr TypeError True",
            "blocked TypeError",
            "format-priority format- format-x str-value",
            "str-sub sub-str sub-str sub-str   base",
        ],
    );
}

// Covers CPython f-string and str.format `!r` / `!a` conversion dispatch
// through class-level `__repr__`. This is distinct from ordinary `str()`
// conversion and normalizes str-subclass `__repr__` results for the formatted
// string output. It does not expand `repr()` / `ascii()` / old-style `%r` /
// `%a` str-subclass result identity.
#[test]
fn cpython_format_conversion_repr_custom_dunder_subset() {
    assert_output(
        r#"class FormatRepr:
    def __repr__(self):
        return 'format-é'
value = FormatRepr()
print('format-repr', f'{value!r}', f'{value!a}', '{!r}'.format(value), '{!a}'.format(value))
class ReprSub(str):
    pass
class ReprSubReturn:
    def __repr__(self):
        return ReprSub('sub-é')
sub_value = ReprSubReturn()
print('repr-subclass-result', type(f'{sub_value!r}').__name__, f'{sub_value!r}', type(f'{sub_value!a}').__name__, f'{sub_value!a}', type('{!r}'.format(sub_value)).__name__, '{!r}'.format(sub_value), type('{!a}'.format(sub_value)).__name__, '{!a}'.format(sub_value))
class BadReturn:
    def __repr__(self):
        return 42
class Boom:
    def __repr__(self):
        raise ValueError('format-repr-boom')
for label, expr in [
    ('f-r-bad', lambda: f'{BadReturn()!r}'),
    ('f-a-bad', lambda: f'{BadReturn()!a}'),
    ('format-r-bad', lambda: '{!r}'.format(BadReturn())),
    ('format-a-bad', lambda: '{!a}'.format(BadReturn())),
    ('f-r-boom', lambda: f'{Boom()!r}'),
    ('f-a-boom', lambda: f'{Boom()!a}'),
    ('format-r-boom', lambda: '{!r}'.format(Boom())),
    ('format-a-boom', lambda: '{!a}'.format(Boom())),
]:
    try:
        expr()
    except Exception as error:
        print(label, type(error).__name__, str(error))"#,
        &[
            "format-repr format-é format-\\xe9 format-é format-\\xe9",
            "repr-subclass-result str sub-é str sub-\\xe9 str sub-é str sub-\\xe9",
            "f-r-bad TypeError __repr__ returned non-string (type int)",
            "f-a-bad TypeError __repr__ returned non-string (type int)",
            "format-r-bad TypeError __repr__ returned non-string (type int)",
            "format-a-bad TypeError __repr__ returned non-string (type int)",
            "f-r-boom ValueError format-repr-boom",
            "f-a-boom ValueError format-repr-boom",
            "format-r-boom ValueError format-repr-boom",
            "format-a-boom ValueError format-repr-boom",
        ],
    );
}

// Adapted from CPython `Lib/test/test_builtin.py::BuiltinTest::test___ne__`.
// `NoneType` inherits these methods from `object`; the public behavior is direct
// method-call identity comparison, the `None` fallback to `NotImplemented`, and
// CPython's direct `object.__ne__` bool result for builtin containers.
#[test]
fn cpython_builtin_none_ne_direct_subset() {
    assert_output(
        "print(None.__ne__(None))\nprint(None.__ne__(0) is NotImplemented)\nprint(None.__ne__('abc') is NotImplemented)\nprint(None.__eq__(None))\nprint(None.__eq__(0) is NotImplemented)\nprint(type(None).__ne__(None, None))\nprint(type(None).__ne__(None, 0) is NotImplemented)",
        &["False", "True", "True", "True", "True", "False", "True"],
    );
    assert_output(
        "left = []\nright = []\nprint(object.__eq__(None, None))\nprint(object.__eq__(left, left))\nprint(object.__eq__(left, right) is NotImplemented)\nprint(object.__ne__(None, None))\nprint(object.__ne__(left, right) is NotImplemented)",
        &["True", "True", "True", "False", "False"],
    );
    assert_output(
        "for expr in [lambda: None.__ne__(), lambda: None.__ne__(0, 1), lambda: object.__eq__(None), lambda: object.__ne__(None, 0, 1)]:\n    try:\n        expr()\n    except TypeError as error:\n        print(error.__class__.__name__)",
        &["TypeError", "TypeError", "TypeError", "TypeError"],
    );
}

// Adapted from CPython `Lib/test/test_builtin.py::BuiltinTest::test_bool_notimplemented`.
// `NotImplemented` is a sentinel for binary-operation dispatch and must not be
// consumed as an ordinary truth value.
#[test]
fn cpython_builtin_bool_notimplemented_subset() {
    let expected =
        "runtime error: TypeError: NotImplemented should not be used in a boolean context";
    assert_error("bool(NotImplemented)", expected);
    assert_error("if NotImplemented:\n    pass", expected);
    assert_error("not NotImplemented", expected);
}

