// Adapted from CPython's public `slice` object attributes. MiniPython exposes
// `start`, `stop`, and `step` as readonly data attributes without exposing an
// instance `__dict__`.
#[test]
fn cpython_slice_public_attributes_subset() {
    assert_output(
        r#"def show(label, expr):
    try:
        value = expr()
        print(label, value)
    except AttributeError as error:
        print(label, type(error).__name__, str(error))

cases = [
    slice(None),
    slice(1),
    slice(1, 5),
    slice(1, 10, 2),
    slice(None, None, -1),
]
for item in cases:
    print('attrs', item.start, item.stop, item.step, repr(item))

s = slice(1, 5, 2)
print('indices-visible', 'indices' in dir(s), 'indices' in dir(slice))
for name in ['start', 'stop', 'step']:
    show('set-' + name, lambda name=name: setattr(s, name, 99))
    show('del-' + name, lambda name=name: delattr(s, name))
for name in ['indices']:
    show('set-' + name, lambda name=name: setattr(s, name, 99))
    show('del-' + name, lambda name=name: delattr(s, name))
show('set-extra', lambda: setattr(s, 'extra', 99))
show('del-extra', lambda: delattr(s, 'extra'))"#,
        &[
            "attrs None None None slice(None, None, None)",
            "attrs None 1 None slice(None, 1, None)",
            "attrs 1 5 None slice(1, 5, None)",
            "attrs 1 10 2 slice(1, 10, 2)",
            "attrs None None -1 slice(None, None, -1)",
            "indices-visible True True",
            "set-start AttributeError readonly attribute",
            "del-start AttributeError readonly attribute",
            "set-stop AttributeError readonly attribute",
            "del-stop AttributeError readonly attribute",
            "set-step AttributeError readonly attribute",
            "del-step AttributeError readonly attribute",
            "set-indices AttributeError 'slice' object attribute 'indices' is read-only",
            "del-indices AttributeError 'slice' object attribute 'indices' is read-only",
            "set-extra AttributeError 'slice' object has no attribute 'extra' and no __dict__ for setting new attributes",
            "del-extra AttributeError 'slice' object has no attribute 'extra' and no __dict__ for setting new attributes",
        ],
    );
}

// Adapted from CPython's public `slice.__new__` behavior. MiniPython exposes
// the direct type allocation entry point but keeps slice subclassing outside
// this slice because CPython rejects `slice` as a base type at class creation.
#[test]
fn cpython_slice_new_direct_allocation_subset() {
    assert_output_with_stack(
        r#"class C:
    pass
def show(label, callback):
    try:
        value = callback()
        print(label, type(value).__name__, repr(value), value.start, value.stop, value.step)
    except Exception as error:
        print(label, type(error).__name__, str(error), error.args)

print('visible', hasattr(slice, '__new__'), '__new__' in dir(slice), hasattr(slice(0), '__new__'), '__new__' in dir(slice(0)))
for label, call in [
    ('missing', lambda: slice.__new__()),
    ('no-values', lambda: slice.__new__(slice)),
    ('exact-stop', lambda: slice.__new__(slice, 4)),
    ('exact-start-stop', lambda: slice.__new__(slice, 1, 5)),
    ('exact-step', lambda: slice.__new__(slice, 1, 6, 2)),
    ('instance-stop', lambda: slice(0).__new__(slice, 2)),
    ('too-many', lambda: slice.__new__(slice, 1, 2, 3, 4)),
    ('bad-class', lambda: slice.__new__(list, 4)),
    ('bad-user-class', lambda: slice.__new__(C, 4)),
    ('int-arg', lambda: slice.__new__(1, 4)),
    ('keyword', lambda: slice.__new__(slice, stop=4)),
]:
    show(label, call)"#,
        &[
            "visible True True True True",
            "missing TypeError slice.__new__(): not enough arguments ('slice.__new__(): not enough arguments',)",
            "no-values TypeError slice expected at least 1 argument, got 0 ('slice expected at least 1 argument, got 0',)",
            "exact-stop slice slice(None, 4, None) None 4 None",
            "exact-start-stop slice slice(1, 5, None) 1 5 None",
            "exact-step slice slice(1, 6, 2) 1 6 2",
            "instance-stop slice slice(None, 2, None) None 2 None",
            "too-many TypeError slice expected at most 3 arguments, got 4 ('slice expected at most 3 arguments, got 4',)",
            "bad-class TypeError slice.__new__(list): list is not a subtype of slice ('slice.__new__(list): list is not a subtype of slice',)",
            "bad-user-class TypeError slice.__new__(C): C is not a subtype of slice ('slice.__new__(C): C is not a subtype of slice',)",
            "int-arg TypeError slice.__new__(X): X is not a type object (int) ('slice.__new__(X): X is not a type object (int)',)",
            "keyword TypeError slice() takes no keyword arguments ('slice() takes no keyword arguments',)",
        ],
        32 * 1024 * 1024,
    );
}

// Adapted from CPython's public class-construction behavior. MiniPython rejects
// `slice` as a base type across direct class statements and public class
// construction helpers while keeping ordinary supported builtin bases intact.
#[test]
fn cpython_slice_unacceptable_base_type_subset() {
    assert_output_with_stack(
        r#"import types

EXPECTED_MESSAGE = "type 'slice' is not an acceptable base type"

def print_error(label, error):
    print(label, error.__class__.__name__, str(error), error.args, str(error) == EXPECTED_MESSAGE)

def show(label, callback):
    try:
        callback()
    except Exception as error:
        print_error(label, error)
    else:
        print(label, 'ok')

try:
    class SliceClass(slice):
        pass
except Exception as error:
    print_error('class-slice', error)
else:
    print('class-slice ok')

base = slice
try:
    class VariableSlice(base):
        pass
except Exception as error:
    print_error('variable-slice', error)
else:
    print('variable-slice ok')

for label, call in [
    ('type-slice', lambda: type('SliceType', (slice,), {})),
    ('type-new-slice', lambda: type.__new__(type, 'SliceNew', (slice,), {})),
    ('new-class-slice', lambda: types.new_class('SliceNewClass', (slice,), {})),
]:
    show(label, call)

class ListClass(list):
    pass
print('class-list', ListClass.__name__, ListClass.__bases__[0] is list, isinstance(ListClass(), list))
TypeList = type('TypeList', (list,), {})
print('type-list', TypeList.__name__, TypeList.__bases__[0] is list, isinstance(TypeList(), list))"#,
        &[
            "class-slice TypeError type 'slice' is not an acceptable base type (\"type 'slice' is not an acceptable base type\",) True",
            "variable-slice TypeError type 'slice' is not an acceptable base type (\"type 'slice' is not an acceptable base type\",) True",
            "type-slice TypeError type 'slice' is not an acceptable base type (\"type 'slice' is not an acceptable base type\",) True",
            "type-new-slice TypeError type 'slice' is not an acceptable base type (\"type 'slice' is not an acceptable base type\",) True",
            "new-class-slice TypeError type 'slice' is not an acceptable base type (\"type 'slice' is not an acceptable base type\",) True",
            "class-list ListClass True True",
            "type-list TypeList True True",
        ],
        32 * 1024 * 1024,
    );
}

