// Pins super() and class-level lookups that fall back to object's slot
// implementations when no class in the MRO overrides them.
#[test]
fn cpython_super_object_slot_fallback_subset() {
    assert_output(
        r#"class Base:
    pass
class Child(Base):
    def __init__(self, value):
        super().__init__()
        self.value = value
print('init-chain', Child(3).value)
class Direct:
    def __init__(self):
        print('init-direct', super().__init__())
Direct()
print('class-init', Child.__init__ is not object.__init__, Base.__init__ is object.__init__)
print('class-slots', [getattr(Base, name) is getattr(object, name) for name in ['__init__', '__repr__', '__str__', '__eq__', '__ne__', '__hash__', '__setattr__', '__delattr__', '__getattribute__', '__new__']])
class Hooked:
    def __init_subclass__(cls, **kwargs):
        print('init-subclass', cls.__name__, sorted(kwargs))
        super().__init_subclass__(**kwargs)
class Plain(Hooked):
    pass
try:
    class Keyed(Hooked, flag=1):
        pass
except TypeError as error:
    print('init-subclass-keywords', error)
class Slots:
    def __setattr__(self, name, value):
        super().__setattr__(name, value * 2)
    def __delattr__(self, name):
        print('delattr', name)
        super().__delattr__(name)
    def __getattribute__(self, name):
        return super().__getattribute__(name)
    def __repr__(self):
        return 'Slots:' + super().__repr__().split(' object at ')[0]
    def __str__(self):
        return 'str:' + super().__str__().split(' object at ')[0]
    def __eq__(self, other):
        return super().__eq__(other)
    def __ne__(self, other):
        return super().__ne__(other)
    def __hash__(self):
        return super().__hash__() == object.__hash__(self)
    def __format__(self, spec):
        return 'fmt:' + super().__format__(spec).split(' object at ')[0]
    def __sizeof__(self):
        return super().__sizeof__() > 0
s = Slots()
s.value = 4
print('setattr', s.value)
del s.value
print('deleted', hasattr(s, 'value'))
print('repr', repr(s), str(s), format(s, ''))
print('compare', s == s, s.__eq__(1), s != s, s.__ne__(1))
print('hash', hash(s), s.__sizeof__())
class Equal:
    def __eq__(self, other):
        return True
class EqualChild(Equal):
    def method(self):
        return super().__hash__
print('implicit-hash', Equal.__hash__, EqualChild.__hash__, EqualChild().method())
class Hook:
    @classmethod
    def check(cls):
        return super().__subclasshook__(int), super().__init_subclass__()
print('classmethod-super', Hook.check())
class StrChild(str):
    def __init__(self, value):
        super().__init__()
print('str-child', StrChild('text'))"#,
        &[
            "init-chain 3",
            "init-direct None",
            "class-init True True",
            "class-slots [True, True, True, True, True, True, True, True, True, True]",
            "init-subclass Plain []",
            "init-subclass Keyed ['flag']",
            "init-subclass-keywords Keyed.__init_subclass__() takes no keyword arguments",
            "setattr 8",
            "delattr value",
            "deleted False",
            "repr Slots:<__main__.Slots str:Slots:<__main__.Slots fmt:str:Slots:<__main__.Slots",
            "compare True NotImplemented False NotImplemented",
            "hash 1 True",
            "implicit-hash None None None",
            "classmethod-super (NotImplemented, None)",
            "str-child text",
        ],
    );
}

// Pins CPython's object.__init__/object.__new__ excess-argument rules for
// Python classes that override neither, one, or both slots.
#[test]
fn cpython_object_init_new_excess_arguments_subset() {
    assert_output(
        r#"def attempt(label, make):
    try:
        make()
    except TypeError as exc:
        print(label, "->", exc)
    else:
        print(label, "-> fine")

class Bare:
    pass

class HasInit:
    def __init__(self, *a, **k):
        object.__init__(self, *a, **k)

class HasNew:
    def __new__(cls, *a, **k):
        return object.__new__(cls)

class HasBoth(HasNew):
    def __init__(self, *a, **k):
        object.__init__(self, *a, **k)

class Inherits(HasInit):
    pass

class Shell:
    class Core:
        pass

attempt("bare positional", lambda: Bare(0))
attempt("bare keyword", lambda: Bare(k=0))
attempt("nested", lambda: Shell.Core(0))
attempt("init forwards args", lambda: HasInit(0))
attempt("init no args", lambda: HasInit())
attempt("inherited init kw", lambda: Inherits(k=0))
attempt("new only", lambda: HasNew(0, k=1))
attempt("both", lambda: HasBoth(0))
attempt("object.__init__ bare", lambda: object.__init__(Bare(), 0))
attempt("object.__init__ bare kw", lambda: object.__init__(Bare(), k=0))
attempt("object.__init__ nested", lambda: object.__init__(Shell.Core(), 0))
attempt("Bare.__init__", lambda: Bare.__init__(Bare(), 0))
attempt("object.__init__ new-only", lambda: object.__init__(HasNew(), 0))
attempt("object.__init__ init-only", lambda: object.__init__(HasInit(), 0))
attempt("object.__init__ no args", lambda: object.__init__(Bare()))
attempt("object.__init__ object", lambda: object.__init__(object(), 0))
attempt("object.__new__ bare", lambda: object.__new__(Bare, 0))
attempt("object.__new__ init-only", lambda: object.__new__(HasInit, 0, k=1))
attempt("object.__new__ new-only", lambda: object.__new__(HasNew, 0))
attempt("Bare.__new__ kw", lambda: Bare.__new__(Bare, k=0))"#,
        &[
            "bare positional -> Bare() takes no arguments",
            "bare keyword -> Bare() takes no arguments",
            "nested -> Core() takes no arguments",
            "init forwards args -> object.__init__() takes exactly one argument (the instance to initialize)",
            "init no args -> fine",
            "inherited init kw -> object.__init__() takes exactly one argument (the instance to initialize)",
            "new only -> fine",
            "both -> object.__init__() takes exactly one argument (the instance to initialize)",
            "object.__init__ bare -> Bare.__init__() takes exactly one argument (the instance to initialize)",
            "object.__init__ bare kw -> Bare.__init__() takes exactly one argument (the instance to initialize)",
            "object.__init__ nested -> Core.__init__() takes exactly one argument (the instance to initialize)",
            "Bare.__init__ -> Bare.__init__() takes exactly one argument (the instance to initialize)",
            "object.__init__ new-only -> fine",
            "object.__init__ init-only -> object.__init__() takes exactly one argument (the instance to initialize)",
            "object.__init__ no args -> fine",
            "object.__init__ object -> object.__init__() takes exactly one argument (the instance to initialize)",
            "object.__new__ bare -> Bare() takes no arguments",
            "object.__new__ init-only -> fine",
            "object.__new__ new-only -> object.__new__() takes exactly one argument (the type to instantiate)",
            "Bare.__new__ kw -> Bare() takes no arguments",
        ],
    );
}

