// Pins the with-statement __exit__ arguments for user-defined and builtin
// exception classes: the class itself, the identical instance, and a traceback.
#[test]
fn cpython_with_exit_receives_exception_class_subset() {
    assert_output(
        r#"class MyError(Exception):
    pass
class SubValue(ValueError):
    pass
class Recorder:
    def __init__(self, expected, suppress):
        self.expected = expected
        self.suppress = suppress
    def __enter__(self):
        return self
    def __exit__(self, exc_type, exc, tb):
        self.seen = (exc_type, exc, tb)
        print('exit', exc_type is self.expected, isinstance(exc_type, type), exc_type is type(exc))
        print('match', issubclass(exc_type, self.expected), isinstance(exc, self.expected), type(tb).__name__)
        return self.suppress
error = MyError('mine')
with Recorder(MyError, True) as recorder:
    raise error
print('suppressed', recorder.seen[1] is error, recorder.seen[1].args)
with Recorder(SubValue, True) as recorder:
    raise SubValue('sub')
with Recorder(ValueError, True) as recorder:
    raise SubValue('base-match')
print('base-match', recorder.seen[0] is SubValue, recorder.seen[0].__name__, recorder.seen[0].__mro__[1] is ValueError)
with Recorder(KeyError, True) as recorder:
    raise KeyError('builtin')
try:
    with Recorder(MyError, False) as recorder:
        raise MyError('propagate')
except MyError as caught:
    print('propagated', caught is recorder.seen[1])
with Recorder(MyError, True) as recorder:
    raise MyError
print('class-raise', type(recorder.seen[1]).__name__, recorder.seen[1].args)
class suppress:
    def __init__(self, *exceptions):
        self._exceptions = exceptions
    def __enter__(self):
        pass
    def __exit__(self, exctype, excinst, exctb):
        return exctype is not None and issubclass(exctype, self._exceptions)
with suppress(MyError, KeyError):
    raise MyError('quiet')
print('suppress-ok')
try:
    with suppress(KeyError):
        raise MyError('loud')
except MyError as caught:
    print('not-suppressed', caught)
class Clean:
    def __enter__(self):
        return self
    def __exit__(self, *args):
        print('clean', args)
with Clean():
    pass
class AsyncRecorder:
    async def __aenter__(self):
        return self
    async def __aexit__(self, exc_type, exc, tb):
        print('async-exit', exc_type is MyError, issubclass(exc_type, MyError), type(tb).__name__)
        return True
async def run():
    async with AsyncRecorder():
        raise MyError('async')
    return 'done'
coroutine = run()
try:
    coroutine.send(None)
except StopIteration as stop:
    print('async-result', stop.value)"#,
        &[
            "exit True True True",
            "match True True traceback",
            "suppressed True ('mine',)",
            "exit True True True",
            "match True True traceback",
            "exit False True True",
            "match True True traceback",
            "base-match True SubValue True",
            "exit True True True",
            "match True True traceback",
            "exit True True True",
            "match True True traceback",
            "propagated True",
            "exit True True True",
            "match True True traceback",
            "class-raise MyError ()",
            "suppress-ok",
            "not-suppressed loud",
            "clean (None, None, None)",
            "async-exit True True traceback",
            "async-result done",
        ],
    );
}

// Adapted from CPython `Lib/test/test_exceptions.py::testWithTraceback` and
// `::testInvalidTraceback`. This covers traceback object identity preservation,
// the CPython `None` path, and rejection of non-tracebacks.
#[test]
fn cpython_base_exception_with_traceback_subset() {
    assert_output(
        "try:\n    raise IndexError(4)\nexcept Exception as error:\n    tb = error.__traceback__\nprint(type(tb).__name__, tb is None, tb.__class__.__name__)\nfor error in [BaseException(), IndexError(5), Exception('wrapped')]:\n    same = error.with_traceback(tb)\n    print(same.__class__.__name__, same, same.args, same.__traceback__ is tb)\nfor error in [BaseException(), IndexError(5), Exception('wrapped')]:\n    same = error.with_traceback(None)\n    print(same.__class__.__name__, same, same.args, same.__traceback__)\ntry:\n    Exception().with_traceback(5)\nexcept TypeError as error:\n    print(error)\ntry:\n    Exception().__traceback__ = 5\nexcept TypeError as error:\n    print(error)",
        &[
            "traceback False traceback",
            "BaseException  () True",
            "IndexError 5 (5,) True",
            "Exception wrapped ('wrapped',) True",
            "BaseException  () None",
            "IndexError 5 (5,) None",
            "Exception wrapped ('wrapped',) None",
            "__traceback__ must be a traceback or None",
            "__traceback__ must be a traceback or None",
        ],
    );
}

// Adapted from CPython `Lib/test/test_exceptions.py::test_add_note`.
// This covers public BaseException.add_note() and __notes__ behavior without
// widening MiniPython to a full exception __dict__ model.
#[test]
fn cpython_base_exception_add_note_subset() {
    assert_output_with_stack(
        "def show(label, fn):\n    try:\n        result = fn()\n        print(label, 'OK', repr(result))\n    except Exception as error:\n        print(label, type(error).__name__, str(error), error.args)\n\ne = Exception('x')\nshow('missing-notes', lambda: e.__notes__)\nprint('add-return', e.add_note('one'))\nprint('notes1', e.__notes__)\nException.add_note(e, 'direct')\nprint('direct', e.__notes__)\nfirst = Exception('first')\nfirst.add_note('first-note')\nsecond = Exception('second')\nshow('second-missing', lambda: second.__notes__)\nfor label, fn in [\n    ('non-string-int', lambda: e.add_note(1)),\n    ('non-string-none', lambda: e.add_note(None)),\n    ('no-args', lambda: e.add_note()),\n    ('extra', lambda: e.add_note('x', 'y')),\n    ('keyword', lambda: e.add_note(note='kw')),\n]:\n    show(label, fn)\ne.__notes__ = ('manual',)\nshow('tuple-notes-add', lambda: e.add_note('three'))\nprint('notes-after-tuple', e.__notes__)\ne.__notes__ = ['manual']\ne.add_note('tail')\nprint('notes-after-list', e.__notes__)\ndel e.__notes__\nshow('after-del', lambda: e.__notes__)\ne.add_note('new')\nprint('notes-after-del-add', e.__notes__)\nclass MyError(Exception):\n    pass\nm = MyError('m')\nm.add_note('sub')\nprint('sub', m.__notes__)\ntry:\n    raise Exception('raised')\nexcept Exception as err:\n    err.add_note('caught')\n    print('caught', err.__notes__)",
        &[
            "missing-notes AttributeError 'Exception' object has no attribute '__notes__' (\"'Exception' object has no attribute '__notes__'\",)",
            "add-return None",
            "notes1 ['one']",
            "direct ['one', 'direct']",
            "second-missing AttributeError 'Exception' object has no attribute '__notes__' (\"'Exception' object has no attribute '__notes__'\",)",
            "non-string-int TypeError add_note() argument must be str, not int ('add_note() argument must be str, not int',)",
            "non-string-none TypeError add_note() argument must be str, not None ('add_note() argument must be str, not None',)",
            "no-args TypeError BaseException.add_note() takes exactly one argument (0 given) ('BaseException.add_note() takes exactly one argument (0 given)',)",
            "extra TypeError BaseException.add_note() takes exactly one argument (2 given) ('BaseException.add_note() takes exactly one argument (2 given)',)",
            "keyword TypeError BaseException.add_note() takes no keyword arguments ('BaseException.add_note() takes no keyword arguments',)",
            "tuple-notes-add TypeError Cannot add note: __notes__ is not a list ('Cannot add note: __notes__ is not a list',)",
            "notes-after-tuple ('manual',)",
            "notes-after-list ['manual', 'tail']",
            "after-del AttributeError 'Exception' object has no attribute '__notes__' (\"'Exception' object has no attribute '__notes__'\",)",
            "notes-after-del-add ['new']",
            "sub ['sub']",
            "caught ['caught']",
        ],
        64 * 1024 * 1024,
    );
}

// Mirrors public CPython metadata for BaseException helper method descriptors.
#[test]
fn cpython_base_exception_method_descriptor_metadata_subset() {
    assert_output_with_stack(
        r#"_doc = lambda value: '<doc>' if isinstance(value, str) and value else value
def show(label, fn):
    try:
        value = fn()
        print(label, type(value).__name__, repr(value))
    except Exception as error:
        print(label, type(error).__name__, str(error), error.args)

for label, obj in [
    ('base-add', BaseException.add_note),
    ('exception-add', Exception.add_note),
    ('base-traceback', BaseException.with_traceback),
    ('exception-traceback', Exception.with_traceback),
]:
    show(label + '-name', lambda obj=obj: obj.__name__)
    show(label + '-qualname', lambda obj=obj: obj.__qualname__)
    show(label + '-doc', lambda obj=obj: _doc(obj.__doc__))
    show(label + '-text-signature', lambda obj=obj: obj.__text_signature__)
    show(label + '-module', lambda obj=obj: obj.__module__)"#,
        &[
            "base-add-name str 'add_note'",
            "base-add-qualname str 'BaseException.add_note'",
            "base-add-doc str '<doc>'",
            "base-add-text-signature str '($self, note, /)'",
            "base-add-module AttributeError 'method_descriptor' object has no attribute '__module__' (\"'method_descriptor' object has no attribute '__module__'\",)",
            "exception-add-name str 'add_note'",
            "exception-add-qualname str 'BaseException.add_note'",
            "exception-add-doc str '<doc>'",
            "exception-add-text-signature str '($self, note, /)'",
            "exception-add-module AttributeError 'method_descriptor' object has no attribute '__module__' (\"'method_descriptor' object has no attribute '__module__'\",)",
            "base-traceback-name str 'with_traceback'",
            "base-traceback-qualname str 'BaseException.with_traceback'",
            "base-traceback-doc str '<doc>'",
            "base-traceback-text-signature str '($self, tb, /)'",
            "base-traceback-module AttributeError 'method_descriptor' object has no attribute '__module__' (\"'method_descriptor' object has no attribute '__module__'\",)",
            "exception-traceback-name str 'with_traceback'",
            "exception-traceback-qualname str 'BaseException.with_traceback'",
            "exception-traceback-doc str '<doc>'",
            "exception-traceback-text-signature str '($self, tb, /)'",
            "exception-traceback-module AttributeError 'method_descriptor' object has no attribute '__module__' (\"'method_descriptor' object has no attribute '__module__'\",)",
        ],
        64 * 1024 * 1024,
    );
}

