fn cpython_base_exception_bound_method_sizeof_wrapper_subset() {
    assert_output_with_stack(
        r#"_doc = lambda value: '<doc>' if isinstance(value, str) and value else value
for exc in [BaseException('b'), Exception('e'), IndexError('i')]:
    for helper in ['add_note', 'with_traceback']:
        obj = getattr(exc, helper)
        wrapper = obj.__sizeof__
        label = exc.__class__.__name__ + '-' + helper
        print(label, '__sizeof__' in dir(obj), type(wrapper).__name__, wrapper.__class__.__name__)
        try:
            module = wrapper.__module__
            print(label, 'module', type(module).__name__, module)
        except Exception as error:
            print(label, 'module', type(error).__name__, str(error), error.args)
        print(label, 'meta', wrapper.__self__ is obj, wrapper.__name__, wrapper.__qualname__, getattr(wrapper, '__text_signature__', 'MISSING'), _doc(wrapper.__doc__))
        for call_label, call in [
            ('empty', lambda wrapper=wrapper: wrapper()),
            ('extra', lambda wrapper=wrapper: wrapper(1)),
            ('kw', lambda wrapper=wrapper: wrapper(value=1)),
        ]:
            try:
                value = call()
                print(label, call_label, type(value).__name__, isinstance(value, int), value >= 0)
            except Exception as error:
                print(label, call_label, type(error).__name__, str(error), error.args)"#,
        &[
            "BaseException-add_note True builtin_function_or_method builtin_function_or_method",
            "BaseException-add_note module NoneType None",
            "BaseException-add_note meta True __sizeof__ builtin_function_or_method.__sizeof__ ($self, /) <doc>",
            "BaseException-add_note empty int True True",
            "BaseException-add_note extra TypeError builtin_function_or_method.__sizeof__() takes no arguments (1 given) ('builtin_function_or_method.__sizeof__() takes no arguments (1 given)',)",
            "BaseException-add_note kw TypeError builtin_function_or_method.__sizeof__() takes no keyword arguments ('builtin_function_or_method.__sizeof__() takes no keyword arguments',)",
            "BaseException-with_traceback True builtin_function_or_method builtin_function_or_method",
            "BaseException-with_traceback module NoneType None",
            "BaseException-with_traceback meta True __sizeof__ builtin_function_or_method.__sizeof__ ($self, /) <doc>",
            "BaseException-with_traceback empty int True True",
            "BaseException-with_traceback extra TypeError builtin_function_or_method.__sizeof__() takes no arguments (1 given) ('builtin_function_or_method.__sizeof__() takes no arguments (1 given)',)",
            "BaseException-with_traceback kw TypeError builtin_function_or_method.__sizeof__() takes no keyword arguments ('builtin_function_or_method.__sizeof__() takes no keyword arguments',)",
            "Exception-add_note True builtin_function_or_method builtin_function_or_method",
            "Exception-add_note module NoneType None",
            "Exception-add_note meta True __sizeof__ builtin_function_or_method.__sizeof__ ($self, /) <doc>",
            "Exception-add_note empty int True True",
            "Exception-add_note extra TypeError builtin_function_or_method.__sizeof__() takes no arguments (1 given) ('builtin_function_or_method.__sizeof__() takes no arguments (1 given)',)",
            "Exception-add_note kw TypeError builtin_function_or_method.__sizeof__() takes no keyword arguments ('builtin_function_or_method.__sizeof__() takes no keyword arguments',)",
            "Exception-with_traceback True builtin_function_or_method builtin_function_or_method",
            "Exception-with_traceback module NoneType None",
            "Exception-with_traceback meta True __sizeof__ builtin_function_or_method.__sizeof__ ($self, /) <doc>",
            "Exception-with_traceback empty int True True",
            "Exception-with_traceback extra TypeError builtin_function_or_method.__sizeof__() takes no arguments (1 given) ('builtin_function_or_method.__sizeof__() takes no arguments (1 given)',)",
            "Exception-with_traceback kw TypeError builtin_function_or_method.__sizeof__() takes no keyword arguments ('builtin_function_or_method.__sizeof__() takes no keyword arguments',)",
            "IndexError-add_note True builtin_function_or_method builtin_function_or_method",
            "IndexError-add_note module NoneType None",
            "IndexError-add_note meta True __sizeof__ builtin_function_or_method.__sizeof__ ($self, /) <doc>",
            "IndexError-add_note empty int True True",
            "IndexError-add_note extra TypeError builtin_function_or_method.__sizeof__() takes no arguments (1 given) ('builtin_function_or_method.__sizeof__() takes no arguments (1 given)',)",
            "IndexError-add_note kw TypeError builtin_function_or_method.__sizeof__() takes no keyword arguments ('builtin_function_or_method.__sizeof__() takes no keyword arguments',)",
            "IndexError-with_traceback True builtin_function_or_method builtin_function_or_method",
            "IndexError-with_traceback module NoneType None",
            "IndexError-with_traceback meta True __sizeof__ builtin_function_or_method.__sizeof__ ($self, /) <doc>",
            "IndexError-with_traceback empty int True True",
            "IndexError-with_traceback extra TypeError builtin_function_or_method.__sizeof__() takes no arguments (1 given) ('builtin_function_or_method.__sizeof__() takes no arguments (1 given)',)",
            "IndexError-with_traceback kw TypeError builtin_function_or_method.__sizeof__() takes no keyword arguments ('builtin_function_or_method.__sizeof__() takes no keyword arguments',)",
        ],
        64 * 1024 * 1024,
    );
}

