// Adapted from CPython's lambda parameter helper grammar rules:
// `lambda_params`, `lambda_param_no_default`, `lambda_param_with_default`,
// `lambda_param_maybe_default`, `lambda_star_etc`, `lambda_kwds`, and
// `lambda_param`.
#[test]
fn cpython_lambda_parameter_helper_rules_subset() {
    assert_output("f = lambda a, b,: a + b\nprint(f(1, 2))", &["3"]);
    assert_output("f = lambda a=1, b=2,: a + b\nprint(f(), f(3))", &["3 5"]);
    assert_output("f = lambda a=1, /: a\nprint(f(), f(2))", &["1 2"]);
    assert_output(
        "f = lambda a=1, /, *args, b=2, **kwds: (a, args, b, kwds)\nprint(f(), f(3, 4, b=5, c=6))",
        &["(1, (), 2, {}) (3, (4,), 5, {'c': 6})"],
    );
    assert_output("f = lambda *, b: b\nprint(f(b=7))", &["7"]);
    assert_output("f = lambda *, b=8: b\nprint(f(), f(b=9))", &["8 9"]);
    assert_output(
        "f = lambda *args, b, c=3, **kwds: (args, b, c, kwds)\nprint(f(1, 2, b=4, d=5))",
        &["((1, 2), 4, 3, {'d': 5})"],
    );
    assert_output(
        "f = lambda *, b, c=3, **kwds: (b, c, kwds)\nprint(f(b=4, d=5))",
        &["(4, 3, {'d': 5})"],
    );
    assert_output("f = lambda **kwds: kwds\nprint(f(x=1))", &["{'x': 1}"]);
}

// Adapted from CPython AST call coverage for starred positional and keyword
// unpacking in Lib/test/test_ast/snippets.py. MiniPython checks the executable
// subset through observable function-call behavior.
#[test]
fn cpython_ast_starred_call_arguments_subset() {
    assert_output(
        "def add(a, b):\n    return a + b\nprint(add(*[2, 3]))",
        &["5"],
    );
    assert_output(
        "def add(a, b):\n    return a + b\nprint(add(b=4, *[1]))",
        &["5"],
    );
    assert_output(
        "def add(a, b):\n    return a + b\nprint(add(**{'a': 2, 'b': 3}))",
        &["5"],
    );
    assert_output(
        "def collect(a, *items, **kwargs):\n    print(a, items, kwargs)\ncollect(*[1, 2], **{'x': 3})",
        &["1 (2,) {'x': 3}"],
    );
}

// Adapted from CPython's call argument helper grammar rules: `arguments`,
// `args`, `kwargs`, `kwarg_or_starred`, and `kwarg_or_double_starred`.
// MiniPython checks the same supported argument ordering and unpacking shapes
// through observable function-call behavior.
#[test]
fn cpython_call_argument_helper_rules_subset() {
    assert_output(
        "def collect(*args, **kwargs):\n    return (args, kwargs)\nprint(collect(1, 2,))",
        &["((1, 2), {})"],
    );
    assert_output(
        "def collect(*args, **kwargs):\n    return (args, kwargs)\nprint(collect(*[1], *[2],))",
        &["((1, 2), {})"],
    );
    assert_output(
        "def collect(*args, **kwargs):\n    return (args, kwargs)\nprint(collect(1, *[2], 3, a=4, **{'b': 5}, c=6))",
        &["((1, 2, 3), {'a': 4, 'b': 5, 'c': 6})"],
    );
    assert_output(
        "def collect(*args, **kwargs):\n    return (args, kwargs)\nprint(collect(a=1, *[2]))",
        &["((2,), {'a': 1})"],
    );
    assert_output(
        "def collect(*args, **kwargs):\n    return (args, kwargs)\nprint(collect(a=1, *[2], b=3))",
        &["((2,), {'a': 1, 'b': 3})"],
    );
    assert_output(
        "def collect(*args, **kwargs):\n    return (args, kwargs)\nprint(collect(**{'a': 1}, b=2))",
        &["((), {'a': 1, 'b': 2})"],
    );
    assert_output(
        "def collect(*args, **kwargs):\n    return (args, kwargs)\nprint(collect(**{'a': 1}, **{'b': 2},))",
        &["((), {'a': 1, 'b': 2})"],
    );
    assert_output(
        "def collect(*args, **kwargs):\n    return (args, kwargs)\nprint(collect(*[1], **{'b': 2}, c=3))",
        &["((1,), {'b': 2, 'c': 3})"],
    );
    assert_output(
        "def collect(*args, **kwargs):\n    return (args, kwargs)\nprint(collect(x := 1, *[x + 1]))\nprint(x)",
        &["((1, 2), {})", "1"],
    );
}

// Adapted from CPython invalid call argument syntax coverage in
// Lib/test/test_syntax.py and Lib/test/test_compile.py, plus the
// `invalid_arguments` and `invalid_kwarg` grammar rules. These cases are
// rejected by the parser before call execution.
#[test]
fn cpython_invalid_call_argument_syntax_subset() {
    for source in [
        "f(x()=2)",
        "f(a or b=1)",
        "f(x.y=1)",
        "f((x)=2)",
        "f(True=1)",
        "f(False=1)",
        "f(None=1)",
        "f(__debug__=1)",
        "f(a=)",
        "f(a, b, c=)",
        "f(a, b, c=, d)",
        "f(*args=[0])",
        "f(a, b, *args=[0])",
        "f(**kwargs={'a': 1})",
        "f(a, b, *args, **kwargs={'a': 1})",
        "f(**kwargs, *args)",
        "f(1 for x in [1], 2)",
        "f(1, x for x in [1])",
        "f(x=1 for x in [1])",
        "f(a=,)",
        "f(a=1, 2)",
    ] {
        assert_parse_error(source);
    }
}

// Adapted from CPython's `invalid_arguments` and `invalid_kwarg` grammar rules
// in Grammar/python.gram and the matching doctests in Lib/test/test_syntax.py.
// These assertions pin the MiniPython parser to the same invalid call-argument
// categories, with MiniPython wording where the project already has one.
#[test]
fn cpython_invalid_call_argument_helper_rules_subset() {
    assert_error(
        "f(**kwargs, *args)",
        "parse error: iterable argument unpacking follows keyword argument unpacking",
    );
    assert_error(
        "int(**{'base': 10}, *['2'])",
        "parse error: iterable argument unpacking follows keyword argument unpacking",
    );
    assert_error(
        "f(1 for x in [1], 2)",
        "parse error: Generator expression must be parenthesized",
    );
    assert_error(
        "f(1, x for x in [1])",
        "parse error: Generator expression must be parenthesized",
    );
    assert_error(
        "call(a,  b for b in data if b , c)",
        "parse error: Generator expression must be parenthesized",
    );
    assert_parse_error_diagnostic(
        "call(a,  b for b in data if b , c)",
        "Generator expression must be parenthesized",
        1,
        10,
        1,
        30,
    );
    assert_error(
        "f(a=1, 2)",
        "parse error: positional argument follows keyword argument",
    );
    assert_error(
        "int(base=10, '2')",
        "parse error: positional argument follows keyword argument",
    );
    assert_error(
        "int(**{'base': 10}, '2')",
        "parse error: positional argument follows keyword argument unpacking",
    );
    assert_error(
        "f(x=1 for x in [1])",
        "parse error: invalid syntax. Maybe you meant '==' or ':=' instead of '='?",
    );
    assert_error("f(a=)", "parse error: expected argument value expression");
    assert_error(
        "f(a, b, c=)",
        "parse error: expected argument value expression",
    );
    assert_error(
        "f(a, b, c=, d)",
        "parse error: expected argument value expression",
    );
    assert_error("f(1,,2)", "parse error: invalid syntax");
    assert_error("f(True=1)", "parse error: cannot assign to True");
    assert_error("f(False=1)", "parse error: cannot assign to False");
    assert_error("f(None=1)", "parse error: cannot assign to None");
    assert_error("f(__debug__=1)", "parse error: cannot assign to __debug__");
    assert_error("f(a=1, a=2)", "parse error: keyword argument repeated: a");
    assert_error(
        "call(\na=1,\na=1\n)",
        "parse error: keyword argument repeated: a",
    );

    assert_parse_error_diagnostic("f(a=)", "expected argument value expression", 1, 5, 1, 6);
    assert_parse_error_diagnostic(
        "f(a, b, c=)",
        "expected argument value expression",
        1,
        11,
        1,
        12,
    );
    assert_parse_error_diagnostic("f(1,,2)", "invalid syntax", 1, 5, 1, 6);
    assert_parse_error_diagnostic(
        "call(\na=1,\na=1\n)",
        "keyword argument repeated: a",
        3,
        1,
        3,
        2,
    );
    let raise_from_error_message =
        "if 1:\n        raise AssertionError() from None\n        print(1,,2)\n        ";
    assert_error(raise_from_error_message, "parse error: invalid syntax");
    assert_parse_error_diagnostic(raise_from_error_message, "invalid syntax", 3, 17, 3, 18);
    assert_error(
        "f(x()=2)",
        "parse error: expression cannot contain assignment, perhaps you meant \"==\"?",
    );
    assert_error(
        "f(a or b=1)",
        "parse error: expression cannot contain assignment, perhaps you meant \"==\"?",
    );
    assert_error(
        "f(x.y=1)",
        "parse error: expression cannot contain assignment, perhaps you meant \"==\"?",
    );
    assert_error(
        "f((x)=2)",
        "parse error: expression cannot contain assignment, perhaps you meant \"==\"?",
    );
    assert_error(
        "print(end1 + end2 = ' ')",
        "parse error: expression cannot contain assignment, perhaps you meant \"==\"?",
    );
    assert_parse_error_diagnostic(
        "print(end1 + end2 = ' ')",
        "expression cannot contain assignment, perhaps you meant \"==\"?",
        1,
        7,
        1,
        18,
    );
    assert_error(
        "f(**kwargs={'a': 1})",
        "parse error: cannot assign to keyword argument unpacking",
    );
}

// Adapted from CPython AST Return snippets in Lib/test/test_ast/snippets.py.
// MiniPython verifies the same observable return values through function calls.
#[test]
fn cpython_ast_return_stmt_subset() {
    assert_output("def f():\n    return 1\nprint(f())", &["1"]);
    assert_output("def f():\n    return\nprint(f())", &["None"]);
    assert_output(
        "def g1(): return\n\
         def g2(): return 1\n\
         def g3():\n\
         \tz = [2, 3]\n\
         \treturn 1, *z\n\
         g1()\n\
         x = g2()\n\
         y = g3()\n\
         print(x, y)",
        &["1 (1, 2, 3)"],
    );
    assert_output(
        "def f():\n    return 0, *[1, 2]\nprint(f())",
        &["(0, 1, 2)"],
    );
    assert_error(
        "def f():\n    return *[1, 2]",
        "parse error: can't use starred expression here",
    );
    assert_error("return 1", "compile error: return outside function");
    assert_rejected("class foo:return 1");
}

// Adapted from CPython grammar `global_stmt` and scope behavior covered in
// Lib/test/test_scope.py. MiniPython supports global declarations for simple
// name reads/writes inside functions.
#[test]
fn cpython_grammar_global_stmt_subset() {
    assert_output(
        r#"global counter
global counter, total
global w1, w2, w3, w4, w5, w6, w7, w8, w9
counter = total = w9 = 0
print("declarations accepted", counter, total, w9)"#,
        &[
            "declarations accepted 0 0 0",
        ],
    );
    assert_output(
        "x = 1\ndef f():\n    global x\n    x = 2\nf()\nprint(x)",
        &["2"],
    );
    assert_output(
        "x = 1\ndef inc():\n    global x\n    x += 1\ninc()\nprint(x)",
        &["2"],
    );
    assert_output(
        "x = 1\ny = 2\ndef swap():\n    global x, y\n    x = y\n    y = 3\nswap()\nprint(x, y)",
        &["2 3"],
    );
    assert_output("global x\nx = 3\nprint(x)", &["3"]);
}

// Adapted from Lib/test/test_global.py. CPython treats `global` as applying to
// all name-binding forms in the current scope, not just ordinary assignment.
#[test]
fn cpython_global_binding_targets_subset() {
    assert_output(
        "def f():\n    global name_unpacking_assignment\n    _, name_unpacking_assignment = [None, \"value\"]\nf()\nprint(name_unpacking_assignment)",
        &["value"],
    );
    assert_output(
        "def f():\n    global name_assignment_expression\n    if name_assignment_expression := \"value\":\n        pass\nf()\nprint(name_assignment_expression)",
        &["value"],
    );
    assert_output(
        "def f():\n    global name_iteration_variable\n    for name_iteration_variable in [\"value\"]:\n        pass\nf()\nprint(name_iteration_variable)",
        &["value"],
    );
    assert_output(
        "def f():\n    global name_func_def\n    def name_func_def():\n        return \"value\"\nf()\nprint(name_func_def())",
        &["value"],
    );
    assert_output(
        "def f():\n    global name_class_def\n    class name_class_def:\n        pass\nf()\nprint(name_class_def.__name__)",
        &["name_class_def"],
    );
    assert_output(
        "def f():\n    global name_type_alias\n    type name_type_alias = tuple[int, int]\nf()\nprint(name_type_alias.__name__)",
        &["name_type_alias"],
    );
    assert_output(
        "def f():\n    global name_caught_exc\n    try:\n        raise ValueError(\"value\")\n    except ValueError as name_caught_exc:\n        print(name_caught_exc)\nf()",
        &["value"],
    );
    assert_output(
        "class Manager:\n    def __enter__(self):\n        return \"value\"\n    def __exit__(self, exc_type, exc, tb):\n        return False\ndef f():\n    global name_enter_result\n    with Manager() as name_enter_result:\n        pass\nf()\nprint(name_enter_result)",
        &["value"],
    );
    assert_output(
        "def f():\n    global name_import_result\n    import math as name_import_result\nf()\nprint(name_import_result.__name__)",
        &["math"],
    );
    assert_output(
        "def f():\n    global name_match\n    match \"value\":\n        case name_match:\n            pass\nf()\nprint(name_match)",
        &["value"],
    );
    assert_output(
        "def f():\n    global name_match_as\n    match \"value\":\n        case _ as name_match_as:\n            pass\nf()\nprint(name_match_as)",
        &["value"],
    );
    assert_output(
        "def f():\n    global name_match_seq\n    match (None, \"value\"):\n        case (_, name_match_seq):\n            pass\nf()\nprint(name_match_seq)",
        &["value"],
    );
    assert_output(
        "def f():\n    global name_match_map\n    match {'key': 'value'}:\n        case {'key': name_match_map}:\n            pass\nf()\nprint(name_match_map)",
        &["value"],
    );
    assert_output(
        "class Box:\n    __match_args__ = ('key',)\n    key = \"value\"\ndef f():\n    global name_match_attr\n    match Box():\n        case Box(name_match_attr):\n            pass\nf()\nprint(name_match_attr)",
        &["value"],
    );
}

// Adapted from CPython scope behavior covered in Lib/test/test_scope.py.
// MiniPython supports closure reads and `nonlocal` writes for nested function
// scopes in this executable subset.
#[test]
fn cpython_scope_closure_and_nonlocal_subset() {
    assert_output(
        "def outer():\n    x = 0\n    y = 0\n    def f():\n        nonlocal x\n        nonlocal x, y\n    f()\nouter()",
        &[],
    );
    assert_output(
        "def outer():\n    x = 1\n    def inner():\n        return x\n    return inner()\nprint(outer())",
        &["1"],
    );
    assert_output(
        "def make_counter():\n    count = 0\n    def inc():\n        nonlocal count\n        count += 1\n        return count\n    return inc\ncounter = make_counter()\nprint(counter(), counter())",
        &["1 2"],
    );
    assert_output(
        "def outer():\n    x = 1\n    y = 2\n    def inner():\n        nonlocal x, y\n        x = y\n        y = 3\n    inner()\n    return x, y\nprint(outer())",
        &["(2, 3)"],
    );
    assert_output(
        "def outer():\n    x = 1\n    class C:\n        nonlocal x\n        x = 2\n    return x\nprint(outer())",
        &["2"],
    );
    assert_output(
        "def outer():\n    x = 1\n    class C:\n        def read():\n            nonlocal x\n            return x\n    return C.read()\nprint(outer())",
        &["1"],
    );
}

