// Adapted from CPython's global/nonlocal syntax diagnostics in
// Lib/test/test_syntax.py and compile-time scope checks in Lib/test/test_scope.py.
// The exact SyntaxError type is mapped to MiniPython's compile-error surface.
#[test]
fn cpython_scope_declaration_error_subset() {
    assert_error(
        "print(x)\nglobal x",
        "compile error: name 'x' is used prior to global declaration",
    );
    assert_error(
        "x = 1\nglobal x",
        "compile error: name 'x' is assigned to before global declaration",
    );
    assert_error(
        "def f():\n    print(x)\n    global x",
        "compile error: name 'x' is used prior to global declaration",
    );
    assert_error(
        "def f():\n    x = 1\n    global x",
        "compile error: name 'x' is assigned to before global declaration",
    );
    assert_error(
        "def f(x):\n    global x",
        "compile error: name 'x' is parameter and global",
    );
    let global_param_error_first = "if True:\n    def first(p):\n        global p  # bad\n    def second():\n        q = 0\n        global q\n";
    assert_error(
        global_param_error_first,
        "compile error: name 'p' is parameter and global",
    );
    assert_compile_error_diagnostic(
        global_param_error_first,
        "name 'p' is parameter and global",
        3,
        9,
        3,
        15,
    );
    assert_error(
        "nonlocal x",
        "compile error: nonlocal declaration not allowed at module level",
    );
    assert_error(
        "def f():\n    nonlocal x",
        "compile error: no binding for nonlocal 'x' found",
    );
    assert_error(
        "def outer():\n    def inner():\n        nonlocal x",
        "compile error: no binding for nonlocal 'x' found",
    );
    assert_error(
        "class C:\n    nonlocal x",
        "compile error: no binding for nonlocal 'x' found",
    );
    assert_error(
        "def outer():\n    x = 1\n    def inner():\n        print(x)\n        nonlocal x",
        "compile error: name 'x' is used prior to nonlocal declaration",
    );
    assert_error(
        "def outer():\n    x = 1\n    def inner():\n        x = 2\n        nonlocal x",
        "compile error: name 'x' is assigned to before nonlocal declaration",
    );
    assert_error(
        "def outer(x):\n    def inner(x):\n        nonlocal x",
        "compile error: name 'x' is parameter and nonlocal",
    );
    let nonlocal_param_error_first = "def wrap():\n    def first(p):\n        nonlocal p\n    def second():\n        q = 0\n        global q\n";
    assert_error(
        nonlocal_param_error_first,
        "compile error: name 'p' is parameter and nonlocal",
    );
    assert_compile_error_diagnostic(
        nonlocal_param_error_first,
        "name 'p' is parameter and nonlocal",
        3,
        9,
        3,
        17,
    );
    assert_error(
        "def outer():\n    x = 1\n    def inner():\n        global x\n        nonlocal x",
        "compile error: name 'x' is nonlocal and global",
    );
}

// Adapted from CPython's `simple_stmts` grammar shape, which allows multiple
// simple statements on one logical line separated by semicolons.
#[test]
fn cpython_grammar_semicolon_simple_statements_subset() {
    assert_output("x = 1; print(x)", &["1"]);
    assert_output("x = 1; x += 2; print(x);", &["3"]);
    assert_output("if True:\n    x = 1; print(x)", &["1"]);
}

// Adapted from CPython's `simple_stmts` rule. It covers both the fast single
// simple-statement line and the semicolon-separated form with an optional
// trailing semicolon.
#[test]
fn cpython_simple_stmts_subset() {
    assert_output("print(1)\n", &["1"]);
    assert_output("pass\nprint(2)", &["2"]);
    assert_output("print(1); print(2);", &["1", "2"]);
    assert_output("x = 1; pass; del x", &[]);
    assert_output("def foo():\n    x = 1; pass; del x;\nfoo()", &[]);
    assert_output("if True:\n    pass; print(3);", &["3"]);
    assert_output("if True: pass; print(4);", &["4"]);
}

// Adapted from CPython Lib/test/test_grammar.py::GrammarTests.test_expr_stmt.
// The method exercises expression statements, tuple-valued assignments,
// chained assignments, unpacking targets, and invalid assignment targets.
#[test]
fn cpython_grammar_tests_expr_stmt_subset() {
    assert_output("1\n1, 2, 3", &[]);
    assert_output("x = 1\nprint(x)", &["1"]);
    assert_output("x = 1, 2, 3\nprint(x)", &["(1, 2, 3)"]);
    assert_output(
        "x = y = z = 1, 2, 3\nprint(x, y, z)",
        &["(1, 2, 3) (1, 2, 3) (1, 2, 3)"],
    );
    assert_output("x, y, z = 1, 2, 3\nprint(x, y, z)", &["1 2 3"]);
    assert_output(
        "whole = (p, q), r = [s, t], u = data = (1, 2), 3\nprint(whole, p, q, r, s, t, u, data)",
        &["((1, 2), 3) 1 2 3 1 2 3 ((1, 2), 3)"],
    );

    assert_parse_error("x + 1 = 1");
    assert_parse_error("a + 1 = b + 2");
}

// Adapted from
// CPython Lib/test/test_grammar.py::GrammarTests.test_former_statements_refer_to_builtins.
// Python 2 statement-shaped `print foo` and `exec foo` forms should point users
// at the builtin function call spelling, while malformed parenthesized variants
// remain generic syntax errors.
#[test]
fn cpython_grammar_tests_former_statements_refer_to_builtins_subset() {
    let cases = [
        "{} foo",
        "{} {1:foo}",
        "if 1: {} foo",
        "if 1: {} {1:foo}",
        "if 1:\n    {} foo",
        "if 1:\n    {} {1:foo}",
    ];

    for keyword in ["print", "exec"] {
        let custom_message = format!("call to '{keyword}'");
        for case in cases {
            let source = case.replacen("{}", keyword, 1);
            assert_error_contains(&source, &custom_message);

            let malformed = source.replace("foo", "(foo.)");
            let actual = run_source(&malformed).expect_err("expected malformed source to fail");
            assert!(
                !actual.contains("call to '"),
                "expected generic syntax error, got {actual:?}\nsource:\n{malformed}"
            );
        }
    }
}

// Adapted from CPython AST redundant-parentheses and trailer coverage in
// Lib/test/test_ast/test_ast.py. MiniPython supports grouped expressions and a
// parenthesized callee for calls.
#[test]
fn cpython_ast_redundant_parentheses_and_call_trailer_subset() {
    assert_output("a = 1\nb = 2\nprint(((a + b)))", &["3"]);
    assert_output("(((print)))(4, \"x\")", &["4 x"]);
}

// Adapted from CPython's `group` grammar rule. A parenthesized group returns
// the wrapped `yield_expr` or `named_expression` without adding an AST wrapper.
#[test]
fn cpython_group_helper_rule_subset() {
    assert_output("print((x := 1 + 2), x)", &["3 3"]);
    assert_output(
        "def g():\n    value = (yield \"ready\")\n    yield value\ngen = g()\nprint(next(gen))\nprint(gen.send(\"sent\"))",
        &["ready", "sent"],
    );
}

// Adapted from CPython's `star_expression` / `star_named_expression` display
// grammar in Grammar/python.gram. MiniPython supports iterable unpacking in
// list, tuple, and set displays, plus CPython's invalid-group diagnostics for
// parenthesized starred expressions without a tuple comma.
#[test]
fn cpython_grammar_starred_displays_subset() {
    assert_output("items = [1, 2]\nprint([0, *items, 3])", &["[0, 1, 2, 3]"]);
    assert_output("items = [1, 2]\nprint((*items, 3))", &["(1, 2, 3)"]);
    assert_output("items = [1, 2]\nprint({*items, 2, 3})", &["{1, 2, 3}"]);
    assert_output("print([*\"ab\"])", &["['a', 'b']"]);
    assert_output("print((*range(3),))", &["(0, 1, 2)"]);
    assert_error("(*x)", "parse error: cannot use starred expression here");
    assert_error(
        "(**x)",
        "parse error: cannot use double starred expression here",
    );
    assert_error("print([*x for x in [[1]]])", "parse error: iterable unpacking cannot be used in comprehension");
}

// Adapted from CPython's display helper grammar rules:
// `star_named_expressions`, `star_named_expressions_sequence`,
// `star_named_expression`, and `star_named_expression_sequence`.
#[test]
fn cpython_star_named_expression_helper_rules_subset() {
    assert_output(
        "print([x := 1, *[x + 1], 3])\nprint(x)",
        &["[1, 2, 3]", "1"],
    );
    assert_output("print((x := 4, *[5], 6))", &["(4, 5, 6)"]);
    assert_output("print({x := 1, *[2, 3]})", &["{1, 2, 3}"]);
    assert_output("print([x := 7,])\nprint(x)", &["[7]", "7"]);
    assert_output("print([*[1, 2],])", &["[1, 2]"]);
    assert_output("print((x := 8,))\nprint(x)", &["(8,)", "8"]);
    assert_output("print({*[1, 2],})", &["{1, 2}"]);
    assert_output(
        "print([*(x := [1, 2]), 3])\nprint(x)",
        &["[1, 2, 3]", "[1, 2]"],
    );
}

// Adapted from CPython 3.14.6's `invalid_starred_expression_unpacking` and
// `invalid_starred_expression` grammar rules, plus diagnostics in
// Lib/test/test_unpack_ex.py and Lib/test/test_syntax.py.
#[test]
fn cpython_invalid_starred_expression_subset() {
    for source in [
        "[*x if flag else other]",
        "(*x if flag else other,)",
        "{*x if a else b}",
        "[1, *x if a else b]",
        "x = *a if b else c",
    ] {
        assert_error(source, "parse error: invalid syntax");
    }
    for source in [
        "[*x if x else y for x in z]",
        "{*x if a else b for x in y}",
        "(*x if a else b for x in y)",
        "print(*x if a else b for x in y)",
    ] {
        assert_error(
            source,
            "parse error: iterable unpacking cannot be used in comprehension",
        );
    }
    assert_error(
        "(*x if a else b)",
        "parse error: cannot use starred expression here",
    );
    assert_output("print(*[1] if True else [2])", &["1"]);
    for source in ["[**items]", "[**items,]", "[**items for items in seq]"] {
        assert_error(source, "parse error: invalid syntax");
    }
    for source in [
        "[1, **items]",
        "[1, **items,]",
        "[*items, **extra]",
        "[1, *items, **extra]",
        "[1, **items for items in seq]",
    ] {
        assert_error(source, "parse error: invalid syntax");
    }
    for source in [
        "{1, **items}",
        "{1, **items,}",
        "{*items, **extra}",
        "{1, *items, **extra}",
        "{1, **items for items in seq}",
    ] {
        assert_error(source, "parse error: invalid syntax");
    }
    for source in [
        "(**items,)",
        "(1, **items)",
        "(1, **items,)",
        "(*items, **extra)",
        "(*items, **extra,)",
        "(1, *items, **extra)",
        "(1, **items for items in seq)",
    ] {
        assert_error(source, "parse error: invalid syntax");
    }
    assert_error(
        "(**items)",
        "parse error: cannot use double starred expression here",
    );
    assert_error("[*]", "parse error: Invalid star expression");
    assert_error("(*,)", "parse error: Invalid star expression");
    assert_error("f(x, *)", "parse error: Invalid star expression");
    assert_error("f(x, *:)", "parse error: Invalid star expression");
    assert_error("A[*]", "parse error: Invalid star expression");
    assert_error(
        "f(*args=[0])",
        "parse error: cannot assign to iterable argument unpacking",
    );
    assert_error(
        "f(a, b, *args=[0])",
        "parse error: cannot assign to iterable argument unpacking",
    );
    assert_error(
        "f(**kwargs={'a': 1})",
        "parse error: cannot assign to keyword argument unpacking",
    );
    assert_error(
        "f(a, b, *args, **kwargs={'a': 1})",
        "parse error: cannot assign to keyword argument unpacking",
    );
}

// Adapted from CPython's display helper grammar rules: `list`, `tuple`,
// `set`, `dict`, and `kvpair`.
#[test]
fn cpython_display_helper_rules_subset() {
    assert_output("print([])\nprint([1, *[2, 3], 4])", &["[]", "[1, 2, 3, 4]"]);
    assert_output(
        "print(())\nprint((1,))\nprint((*[1, 2], 3))",
        &["()", "(1,)", "(1, 2, 3)"],
    );
    assert_output("print({1, *[2, 3], 2})", &["{1, 2, 3}"]);
    assert_output(
        "print({})\nprint({1: 2, **{3: 4}, 3: 5})\nprint({(x := 1): x + 1})\nprint(x)",
        &["{}", "{1: 2, 3: 5}", "{1: 2}", "1"],
    );
}

// Adapted from CPython's `list`, `tuple`, and `set` grammar rules. MiniPython
// covers optional list contents, tuple comma disambiguation, star-named
// expression sequences, and optional trailing commas.
#[test]
fn cpython_sequence_display_helper_rules_subset() {
    assert_output(
        "print([])\nprint([1 + 1, x := 3, *[x + 1],])\nprint(x)",
        &["[]", "[2, 3, 4]", "3"],
    );
    assert_output(
        "print(())\nprint((1))\nprint((1 + 1,))\nprint((x := 5, *[x + 1], 7,))\nprint(x)",
        &["()", "1", "(2,)", "(5, 6, 7)", "5"],
    );
    assert_output(
        "print({1 + 1, x := 3, *[x + 1],})\nprint(x)",
        &["{2, 3, 4}", "3"],
    );
}

// Adapted from CPython's `dict`, `double_starred_kvpairs`,
// `double_starred_kvpair`, and `kvpair` grammar rules. MiniPython covers empty
// dictionaries, expression key/value pairs, `**` unpack entries, mixed entries,
// and optional trailing commas.
#[test]
fn cpython_dict_kvpair_helper_rules_subset() {
    assert_output("print({})", &["{}"]);
    assert_output("print({1 + 1: 2 + 2,})", &["{2: 4}"]);
    assert_output("base = {1: 2}\nprint({**base,})", &["{1: 2}"]);
    assert_output(
        "base = {1: 2}\nprint({**base, 3: 4, **{5: 6},})",
        &["{1: 2, 3: 4, 5: 6}"],
    );
    assert_output(
        "flag = False\nleft = {1: 2}\nright = {3: 4}\nprint({**(left if flag else right), 5: 6})",
        &["{3: 4, 5: 6}"],
    );
}

// Adapted from CPython's `invalid_double_starred_kvpairs`,
// `invalid_kvpair_unpacking`, and `invalid_kvpair` grammar rules, plus
// Lib/test/test_syntax.py and Lib/test/test_unpack_ex.py diagnostics.
#[test]
fn cpython_invalid_dict_display_syntax_subset() {
    for source in [
        "{**x if x else y}",
        "{**x if flag else y}",
        "{**x if x else y, 1: 2}",
        "{**x if x else y for x in z}",
    ] {
        assert_error(source, "parse error: invalid syntax");
    }
    for source in [
        "{*a: b}",
        "{*a: b, 1: 2}",
        "{*a: b for a, b in items}",
        "{**base, *a: b}",
    ] {
        assert_error(source, "parse error: invalid syntax");
    }
    for source in [
        "{**a: b}",
        "{**a: b, 1: 2}",
        "{**a: b for a, b in items}",
        "{**base, **a: b}",
    ] {
        assert_error(source, "parse error: invalid syntax");
    }
    for source in [
        "{**items for items in seq}",
        "{**items async for items in seq}",
        "{**items for items in seq if items}",
        "{**items for items in seq for other in more}",
    ] {
        assert_error(
            source,
            "parse error: dict unpacking cannot be used in dict comprehension",
        );
    }
    assert_error(
        "{a: *b for a, b in {1: 2}.items()}",
        "parse error: cannot use a starred expression in a dictionary value",
    );
    assert_error("{a: **b for a, b in items}", "parse error: invalid syntax");
    for source in ["{1: **x}", "{1: **x, 2: 3}"] {
        assert_error(source, "parse error: invalid syntax");
    }
    assert_error(
        "{1:2, 3:4, 5}",
        "parse error: ':' expected after dictionary key",
    );
    assert_error(
        "{1:2, 3:4, 5:}",
        "parse error: expression expected after dictionary key and ':'",
    );
    assert_error(
        "{1:}",
        "parse error: expression expected after dictionary key and ':'",
    );
    assert_error(
        "{1: *12+1, 23: 1}",
        "parse error: cannot use a starred expression in a dictionary value",
    );
    assert_error(
        "{1: 23, 1: *12+1}",
        "parse error: cannot use a starred expression in a dictionary value",
    );
    assert_error(
        "{**base, 5}",
        "parse error: ':' expected after dictionary key",
    );
    assert_error(
        "{**base, 5:}",
        "parse error: expression expected after dictionary key and ':'",
    );
}

