// Adapted from CPython Lib/test/test_grammar.py::GrammarTests.test_listcomps.
#[test]
fn cpython_grammar_listcomps_method_subset() {
    let source = r#"values = [4, 7, 1, 9]
words = ["kiwi", "plum", "fig"]
padded = ["\tkiwi ", " plum", "fig\n"]
print([w.strip().upper() for w in padded])
print([v * v - 1 for v in values])
print([v for v in values if v % 2])
print([(w, v) for w in words for v in values if v > 5])
print([(v, w) for v in values[:2] for w in [c for c in words if "i" in c]])
print([(lambda n: [n * k for k in range(n)])(m) for m in range(4)])

def bounded(seq):
    return [1 < v <= 7 for v in seq if v != 9]

print(bounded(values))

def pairs_front():
    return [[c + d for c in "ab"] for d in "xy"]

print(pairs_front())
teams = [(1, "red"), (2, "blue")]
players = [(100, "ann", 1), (101, "bob", 2), (102, "cy", 1)]
scores = [(100, 7), (102, 3), (101, 5)]
joined = [
    (team, name, pts)
    for (tid, team) in teams
        for (pid, name, ptid) in players
            for (spid, pts) in scores
                if tid == ptid and pid == spid
]
print(joined)"#;
    assert_output_with_stack(
        source,
        &[
            "['KIWI', 'PLUM', 'FIG']",
            "[15, 48, 0, 80]",
            "[7, 1, 9]",
            "[('kiwi', 7), ('kiwi', 9), ('plum', 7), ('plum', 9), ('fig', 7), ('fig', 9)]",
            "[(4, 'kiwi'), (4, 'fig'), (7, 'kiwi'), (7, 'fig')]",
            "[[], [0], [0, 2], [0, 3, 6]]",
            "[True, True, False]",
            "[['ax', 'bx'], ['ay', 'by']]",
            "[('red', 'ann', 7), ('red', 'cy', 3), ('blue', 'bob', 5)]",
        ],
        32 * 1024 * 1024,
    );
    assert_error(
        "[i, s for i in nums for s in strs]",
        "parse error: did you forget parentheses around the comprehension target?",
    );
    assert_error(
        "[x if y]",
        "parse error: expected 'else' in conditional expression, found RightBracket",
    );
}

// Adapted from CPython's list comprehension coverage in
// Lib/test/test_grammar.py::test_listcomps and Lib/test/test_listcomps.py
// doctests. MiniPython currently supports list comprehensions with one or more
// `for` clauses, `if` filters, and tuple-unpacking targets.
#[test]
fn cpython_grammar_list_comprehension_subset() {
    assert_output(
        "nums = [1, 2, 3, 4, 5]\nprint([3 * x for x in nums])",
        &["[3, 6, 9, 12, 15]"],
    );
    assert_output(
        "nums = [1, 2, 3, 4, 5]\nprint([x for x in nums if x > 2])",
        &["[3, 4, 5]"],
    );
    assert_output(
        r#"print([(r, c) for r in 'ab' for c in range(3)])"#,
        &[
            "[('a', 0), ('a', 1), ('a', 2), ('b', 0), ('b', 1), ('b', 2)]",
        ],
    );
    assert_output(
        r#"print([(n, m) for n in range(1, 5) for m in range(n, 4)])"#,
        &[
            "[(1, 1), (1, 2), (1, 3), (2, 2), (2, 3), (3, 3)]",
        ],
    );
    assert_output(
        r#"print([p - q for n in range(3) for p, q in [(n * 3, n)]])"#,
        &[
            "[0, 2, 4]",
        ],
    );
    assert_output(
        "print([x for x in range(10) if x % 2 if x % 3])",
        &["[1, 5, 7]"],
    );
    assert_output("print([x for x, in [(4,), (5,), (6,)]])", &["[4, 5, 6]"]);

    assert_error(
        "[i, s for i in nums for s in strs]",
        "parse error: did you forget parentheses around the comprehension target?",
    );
    assert_error(
        "[x if y]",
        "parse error: expected 'else' in conditional expression, found RightBracket",
    );
    assert_parse_error("[x for x]");
    assert_parse_error("[x for x,]");
    assert_parse_error("print(x for x)");
}

// Adapted from CPython Lib/test/test_grammar.py::GrammarTests.test_genexps.
#[test]
fn cpython_grammar_genexps_method_subset() {
    let source = r#"outer = ([k * 2 for k in range(3)] for _ in "a")
print(next(outer))
try:
    next(outer)
except StopIteration:
    print("exhausted")
number = 5
try:
    lazy = (q for q in number)
    next(lazy)
except TypeError as exc:
    print("not iterable", type(exc).__name__)
print(list((c, d) for c in "xyz" for d in "uv") == [(c, d) for c in "xyz" for d in "uv"])
base = list(range(1, 8))
print(sum(v for v in (w for w in base)), sum(base))
print(sum(v ** 3 for v in base), max(v % 4 for v in base if v > 2))
print(min(v for v in (w * 2 for w in (u - 3 for u in base))))
print(list(v for v in [w for w in (u for u in base if u % 2)] if v > 1))
print(sum(v for v in (w for w in (u for u in base if True) if False) if True))
print(tuple(str(v) for v in base if v & 1 if v & 2))"#;
    assert_output_with_stack(
        source,
        &[
            "[0, 2, 4]",
            "exhausted",
            "not iterable TypeError",
            "True",
            "28 28",
            "784 3",
            "-4",
            "[3, 5, 7]",
            "0",
            "('3', '7')",
        ],
        32 * 1024 * 1024,
    );
    assert_error(
        "total(n for n in data, 1)",
        "parse error: Generator expression must be parenthesized",
    );
    assert_error(
        "total(1, n for n in data)",
        "parse error: Generator expression must be parenthesized",
    );
}

// Adapted from CPython's generator expression coverage in
// Lib/test/test_grammar.py::test_genexps and Lib/test/test_genexps.py doctests.
// MiniPython currently supports generator expressions with one or more `for`
// clauses, `if` filters, tuple-unpacking targets, direct `next()`, `for`
// iteration, and CPython-style early binding of the outermost iterable.
#[test]
fn cpython_grammar_generator_expression_subset() {
    assert_output(
        "g = (i * i for i in range(4))\nprint(next(g))\nprint(next(g))\nfor x in g:\n    print(x)",
        &["0", "1", "4", "9"],
    );
    assert_output(
        r#"for item in ((ch, n) for n in range(3) for ch in "pq"[:n]):
    print(item)"#,
        &[
            "('p', 1)",
            "('p', 2)",
            "('q', 2)",
        ],
    );
    assert_output(
        "for x in (x for x in range(10) if x % 2 if x % 3):\n    print(x)",
        &["1", "5", "7"],
    );
    assert_output(
        "x = 10\ng = (i for i in range(x))\nx = 5\ncount = 0\nfor i in g:\n    count = count + 1\nprint(count)",
        &["10"],
    );
    assert_output("print(next(i for i in range(3)))", &["0"]);
    let async_source = r#"async def value(x):
    return x + 10
async def pred(x):
    return x % 2
async def values():
    return [4, 5]
async def agen():
    yield 1
    yield 2
async def sender():
    value = yield "ready"
    yield value
async def catcher():
    try:
        yield "ready"
    except ValueError as error:
        yield error
async def closer():
    try:
        yield 1
    finally:
        print("cleanup")
async def empty_async_gen():
    if False:
        yield 1
class EmptyAsyncIter:
    def __aiter__(self):
        return self
    async def __anext__(self):
        raise StopAsyncIteration
module_gen = (await value(x) for x in [1, 2])
async def main():
    print([item async for item in module_gen])
    print([item async for item in (x for x in [0, 1, 2] if await pred(x))])
    print(list(x for x in await values()))
    print([item async for item in (x async for x in agen())])
    ag = agen()
    print(await ag.__anext__())
    print(await ag.__anext__())
    try:
        await ag.__anext__()
    except StopAsyncIteration:
        print("done")
    ag = sender()
    print(await anext(ag))
    print(await ag.asend(42))
    try:
        await anext(ag)
    except StopAsyncIteration:
        print("asend done")
    ag = sender()
    try:
        await ag.asend(42)
    except TypeError as error:
        print(error)
    ag = catcher()
    print(await anext(ag))
    print(await ag.athrow(ValueError("bad")))
    try:
        await anext(ag)
    except StopAsyncIteration:
        print("athrow done")
    ag = closer()
    print(await anext(ag))
    print(await ag.aclose())
    try:
        await anext(ag)
    except StopAsyncIteration:
        print("closed done")
    print(await anext(empty_async_gen(), "fallback"))
    print(await anext(EmptyAsyncIter(), "generic fallback"))
coro = main()
try:
    coro.send(None)
except StopIteration:
    print("finished")"#;
    assert_output_with_stack(
        async_source,
        &[
            "[11, 12]",
            "[1]",
            "[4, 5]",
            "[1, 2]",
            "1",
            "2",
            "done",
            "ready",
            "42",
            "asend done",
            "can't send non-None value to a just-started async generator",
            "ready",
            "bad",
            "athrow done",
            "1",
            "cleanup",
            "None",
            "closed done",
            "fallback",
            "generic fallback",
            "finished",
        ],
        32 * 1024 * 1024,
    );

    assert_error(
        "print(x for x in range(3), 100)",
        "parse error: Generator expression must be parenthesized",
    );
}

// CPython builtin async-iterator entrypoint public behavior. This keeps
// `aiter()` protocol validation separate from async-for lowering tests.
#[test]
fn cpython_aiter_anext_builtin_subset() {
    assert_output(
        r#"class AI:
    def __aiter__(self):
        return self
    async def __anext__(self):
        raise StopAsyncIteration
class AiterRaises:
    def __aiter__(self):
        raise ValueError("bad")
class BadAiter:
    def __aiter__(self):
        return 42
ai = AI()
print(hasattr(__import__("builtins"), "aiter"), callable(aiter), aiter(ai) is ai)
for label, callback in [
    ("missing", lambda: aiter(())),
    ("raises", lambda: aiter(AiterRaises())),
    ("bad", lambda: aiter(BadAiter())),
    ("arity0", lambda: aiter()),
    ("arity2", lambda: aiter(ai, ai)),
]:
    try:
        callback()
    except Exception as error:
        print(label, type(error).__name__, str(error))"#,
        &[
            "True True True",
            "missing TypeError 'tuple' object is not an async iterable",
            "raises ValueError bad",
            "bad TypeError aiter() returned not an async iterator of type 'int'",
            "arity0 TypeError aiter() takes exactly one argument (0 given)",
            "arity2 TypeError aiter() takes exactly one argument (2 given)",
        ],
    );
}

