// Adapted from CPython's string method coverage in
// Lib/test/string_tests.py::test_partition and ::test_rpartition. MiniPython
// covers first/last separator search, not-found triples, Unicode separators,
// and representative TypeError / ValueError paths.
#[test]
fn cpython_string_partition_rpartition_subset() {
    assert_output(
        "S = 'http://www.python.org'\nprint(S.partition('://'))\nprint(S.partition('?'))\nprint(S.partition('http://'))\nprint(S.partition('org'))",
        &[
            "('http', '://', 'www.python.org')",
            "('http://www.python.org', '', '')",
            "('', 'http://', 'www.python.org')",
            "('http://www.python.', 'org', '')",
        ],
    );
    assert_output(
        "S = 'http://www.python.org'\nprint(S.rpartition('://'))\nprint(S.rpartition('?'))\nprint(S.rpartition('http://'))\nprint(S.rpartition('org'))",
        &[
            "('http', '://', 'www.python.org')",
            "('', '', 'http://www.python.org')",
            "('', 'http://', 'www.python.org')",
            "('http://www.python.', 'org', '')",
        ],
    );
    assert_output(
        "left = 'āĀ' * 3\nright = '𐌁𐌀' * 3\nprint((left + right).partition('Ă'))\nprint((left + 'Ă' + right).partition('Ă'))\nprint((left + 'ĂĂ' + right).rpartition('ĂĂ'))",
        &[
            "('āĀāĀāĀ𐌁𐌀𐌁𐌀𐌁𐌀', '', '')",
            "('āĀāĀāĀ', 'Ă', '𐌁𐌀𐌁𐌀𐌁𐌀')",
            "('āĀāĀāĀ', 'ĂĂ', '𐌁𐌀𐌁𐌀𐌁𐌀')",
        ],
    );
    assert_output(
        "S = 'http://www.python.org'\nfor expr in [lambda: S.partition(''), lambda: S.rpartition(''), lambda: S.partition(None), lambda: S.rpartition(None), lambda: S.partition('x', 'y')]:\n    try:\n        expr()\n    except (TypeError, ValueError) as error:\n        print(error.__class__.__name__)",
        &[
            "ValueError",
            "ValueError",
            "TypeError",
            "TypeError",
            "TypeError",
        ],
    );
}

// Adapted from CPython's string method coverage in
// Lib/test/string_tests.py::test_join. MiniPython covers list, tuple, generator,
// sequence-protocol, repeated-item, and representative TypeError join paths.
#[test]
fn cpython_string_join_subset() {
    assert_output(
        "print(' '.join(['a', 'b', 'c', 'd']))\nprint(''.join(('a', 'b', 'c', 'd')))\nprint(''.join(('', 'b', '', 'd')))\nprint(''.join(('a', '', 'c', '')))\nprint('a'.join(('abc',)))\nprint('.'.join(['a', 'b', 'c']))",
        &["a b c d", "abcd", "bd", "ac", "abc", "a.b.c"],
    );
    assert_output(
        "class Letters:\n    def __init__(self, text):\n        self.text = text\n    def __getitem__(self, i):\n        return self.text[i]\nclass WrongLength(Letters):\n    def __len__(self):\n        return 99\nprint(\"-\".join(Letters(\"pqr\")), \"+\".join(WrongLength(\"st\")), \"\".join(c.upper() for c in \"uvw\"))",
        &["p-q-r s+t UVW"],
    );
    assert_output(
        "for i in [5, 25, 125]:\n    value = '-'.join(['a' * i] * i)\n    expected = ((('a' * i) + '-') * i)[:-1]\n    print(value == expected, len(value))",
        &["True 29", "True 649", "True 15749"],
    );
    assert_output(
        "for expr in [lambda: ' '.join(), lambda: ' '.join(None), lambda: ' '.join(7), lambda: '.'.join(['a', 'b', 3]), lambda: ' '.join([1, 2, bytes()])]:\n    try:\n        expr()\n    except TypeError as error:\n        print(error.__class__.__name__)",
        &[
            "TypeError",
            "TypeError",
            "TypeError",
            "TypeError",
            "TypeError",
        ],
    );
    assert_output(
        "def f():\n    yield 4 + ''\ntry:\n    ' '.join(f())\nexcept TypeError as error:\n    print('+' in str(error))",
        &["True"],
    );
}

// Adapted from CPython's inherited string method behavior for str subclasses.
// MiniPython keeps the bound-method receiver as the original subclass instance,
// while supported string methods read the subclass's stored text and return
// exact str/bytes/list results matching the base string operation.
#[test]
fn cpython_string_subclass_inherited_methods_subset() {
    assert_output(
        "class S(str):\n    pass\ns = S('Abc def')\nfor label, expr in [\n    ('iter-visible', lambda: hasattr(s, '__iter__')),\n    ('iter-result', lambda: list(s.__iter__())),\n    ('len-result', lambda: s.__len__()),\n    ('contains-result', lambda: s.__contains__(S('b'))),\n    ('getitem-result', lambda: s.__getitem__(1)),\n    ('upper-visible', lambda: hasattr(s, 'upper')),\n    ('upper-bound-type', lambda: type(s.upper).__name__),\n    ('upper-self', lambda: (type(s.upper.__self__).__name__, s.upper.__self__ is s)),\n    ('upper-result', lambda: s.upper()),\n    ('replace-result', lambda: s.replace(S('b'), S('B'))),\n    ('startswith-result', lambda: s.startswith(S('A'))),\n    ('split-result', lambda: s.split(S(' '))),\n    ('strip-result', lambda: S('  x  ').strip(S(' '))),\n    ('join-result', lambda: S('-').join([S('a'), S('b')])),\n    ('encode-result', lambda: S('Az').encode('ascii')),\n    ('translate-result', lambda: S('az').translate({ord('a'): S('A')})),\n]:\n    value = expr()\n    print(label, type(value).__name__, value)",
        &[
            "iter-visible bool True",
            "iter-result list ['A', 'b', 'c', ' ', 'd', 'e', 'f']",
            "len-result int 7",
            "contains-result bool True",
            "getitem-result str b",
            "upper-visible bool True",
            "upper-bound-type str builtin_function_or_method",
            "upper-self tuple ('S', True)",
            "upper-result str ABC DEF",
            "replace-result str ABc def",
            "startswith-result bool True",
            "split-result list ['Abc', 'def']",
            "strip-result str x",
            "join-result str a-b",
            "encode-result bytes b'Az'",
            "translate-result str Az",
        ],
    );
}

// CPython exposes str.__str__ and str.__repr__ as wrapper descriptors, and
// exact str plus str subclasses receive bound method-wrapper objects that use
// the stored string text rather than object display fallback.
#[test]
fn cpython_string_direct_str_repr_methods_subset() {
    assert_output(
        "class S(str):\n    pass\nfor label, value in [('exact', 'ab'), ('subclass', S('ab'))]:\n    for name in ['__str__', '__repr__']:\n        m = getattr(value, name)\n        print(label, name, type(m).__name__, type(m()).__name__, m())\nprint('class', type(str.__str__).__name__, type(str.__repr__).__name__)",
        &[
            "exact __str__ method-wrapper str ab",
            "exact __repr__ method-wrapper str 'ab'",
            "subclass __str__ method-wrapper str ab",
            "subclass __repr__ method-wrapper str 'ab'",
            "class wrapper_descriptor wrapper_descriptor",
        ],
    );
}

// CPython exposes str.__add__ as a wrapper descriptor; exact str and str
// subclasses receive bound method-wrapper objects and concatenate to exact str.
#[test]
fn cpython_string_direct_add_method_subset() {
    assert_output(
        "class S(str):\n    pass\nfor label, value in [('exact', 'ab'), ('subclass', S('ab'))]:\n    for name in ['__add__', '__radd__']:\n        print(label, name, hasattr(value, name))\nfor label, value in [('exact', 'ab'), ('subclass', S('ab'))]:\n    m = value.__add__\n    print(label, 'bound-type', type(m).__name__, type(m('c')).__name__, m('c'))\n    print(label, 'sub-arg', type(m(S('d'))).__name__, m(S('d')))\nprint('class', type(str.__add__).__name__, type(str.__add__('a', 'b')).__name__, str.__add__('a', 'b'))",
        &[
            "exact __add__ True",
            "exact __radd__ False",
            "subclass __add__ True",
            "subclass __radd__ False",
            "exact bound-type method-wrapper str abc",
            "exact sub-arg str abd",
            "subclass bound-type method-wrapper str abc",
            "subclass sub-arg str abd",
            "class wrapper_descriptor str ab",
        ],
    );
}

