// CPython's default str.__subclasshook__ binding returns NotImplemented while
// preserving owner-specific argument and keyword TypeError messages.
#[test]
fn cpython_string_direct_subclasshook_binding_call_subset() {
    assert_output(
        r#"class S(str):
    pass
left = S('ab')
print('type-call', type(str.__subclasshook__(object)).__name__, str.__subclasshook__(object))
print('exact-call', type('ab'.__subclasshook__(object)).__name__, 'ab'.__subclasshook__(object))
print('sub-call', type(left.__subclasshook__(object)).__name__, left.__subclasshook__(object))
try:
    str.__subclasshook__()
except Exception as error:
    print('missing', type(error).__name__, str(error), error.args)
try:
    left.__subclasshook__(object, object)
except Exception as error:
    print('extra', type(error).__name__, str(error), error.args)
try:
    left.__subclasshook__(object=object)
except Exception as error:
    print('keyword', type(error).__name__, str(error), error.args)"#,
        &[
            "type-call NotImplementedType NotImplemented",
            "exact-call NotImplementedType NotImplemented",
            "sub-call NotImplementedType NotImplemented",
            "missing TypeError str.__subclasshook__() takes exactly one argument (0 given) ('str.__subclasshook__() takes exactly one argument (0 given)',)",
            "extra TypeError S.__subclasshook__() takes exactly one argument (2 given) ('S.__subclasshook__() takes exactly one argument (2 given)',)",
            "keyword TypeError S.__subclasshook__() takes no keyword arguments ('S.__subclasshook__() takes no keyword arguments',)",
        ],
    );
}

