// CPython exposes str.__format__ as a method descriptor. Exact str plus str
// subclasses receive builtin_function_or_method bound objects; str subclass
// results preserve the subclass only when the public formatting result is
// unchanged and the spec is non-empty.
#[test]
fn cpython_string_direct_format_method_subset() {
    assert_output(
        "class S(str):\n    pass\nfor name in ['__format__']:\n    print('class', name, type(getattr(str, name)).__name__)\nfor label, value in [('exact', 'ab'), ('subclass', S('ab'))]:\n    m = getattr(value, '__format__')\n    print(label, type(m).__name__, type(m('')).__name__, m(''), type(m('s')).__name__, m('s'), type(m('>5')).__name__, m('>5'), type(m(S('s'))).__name__, m(S('s')))\nfor label, call in [('class-empty', lambda: str.__format__('ab', '')), ('class-subclass-empty', lambda: str.__format__(S('ab'), '')), ('class-subclass-s', lambda: str.__format__(S('ab'), 's')), ('class-align', lambda: str.__format__('ab', '>5')), ('bound-missing', lambda: 'ab'.__format__()), ('bound-extra', lambda: 'ab'.__format__('', 'x')), ('spec-int', lambda: 'ab'.__format__(1)), ('bad-receiver', lambda: str.__format__(1, '')), ('bad-receiver-nonempty', lambda: str.__format__(1, 's'))]:\n    try:\n        result = call()\n        print(label, type(result).__name__, result)\n    except Exception as exc:\n        print(label, type(exc).__name__, str(exc), getattr(exc, 'args', None))",
        &[
            "class __format__ method_descriptor",
            "exact builtin_function_or_method str ab str ab str    ab str ab",
            "subclass builtin_function_or_method str ab S ab str    ab S ab",
            "class-empty str ab",
            "class-subclass-empty str ab",
            "class-subclass-s S ab",
            "class-align str    ab",
            "bound-missing TypeError str.__format__() takes exactly one argument (0 given) ('str.__format__() takes exactly one argument (0 given)',)",
            "bound-extra TypeError str.__format__() takes exactly one argument (2 given) ('str.__format__() takes exactly one argument (2 given)',)",
            "spec-int TypeError __format__() argument must be str, not int ('__format__() argument must be str, not int',)",
            "bad-receiver TypeError descriptor '__format__' for 'str' objects doesn't apply to a 'int' object (\"descriptor '__format__' for 'str' objects doesn't apply to a 'int' object\",)",
            "bad-receiver-nonempty TypeError descriptor '__format__' for 'str' objects doesn't apply to a 'int' object (\"descriptor '__format__' for 'str' objects doesn't apply to a 'int' object\",)",
        ],
    );
}

