// Adapted from CPython Lib/test/test_bytes.py::BaseBytesTest::test_join.
// The CPython stress loops are reduced in size, but the port keeps the same
// public semantics: receiver-driven result type, bytes-like sequence items,
// iterator inputs, empty separators, and TypeError paths for bad iterables or
// bad items.
#[test]
fn cpython_bytes_join_subset() {
    assert_output(
        "for make in (bytes, bytearray):\n    nothing = make()\n    print(nothing.join([]), nothing.join([b\"\"]), nothing.join((b\"x\", bytearray(b\"y\"))), nothing.join(iter([b\"p\", b\"q\"])))\n    glue = make(b\"<>\")\n    print(glue.join([b\"1\", b\"2\", b\"3\"]), glue.join([memoryview(b\"m\"), bytearray(b\"b\"), b\"s\"]))\n    base = memoryview(bytearray(b\"0123456789\"))\n    for label, piece in ((\"middle\", base[3:6]), (\"stepped\", base[1::3]), (\"reversed\", base[::-2])):\n        try:\n            joined = glue.join([piece, b\"!\"])\n            print(label, type(joined).__name__, joined)\n        except TypeError as exc:\n            print(label, \"TypeError\")\n    many = [b\"ab\"] * 250\n    print(glue.join(many) == make(b\"ab\" + b\"<>ab\" * 249), len(nothing.join(many)))\n    for label, items in ((\"None\", None), (\"str inside\", [b\"a\", \"b\"]), (\"int inside\", [b\"a\", 5])):\n        try:\n            glue.join(items)\n        except TypeError as exc:\n            print(label, type(exc).__name__)",
        &["b'' b'' b'xy' b'pq'", "b'1<>2<>3' b'm<>b<>s'", "middle bytes b'345<>!'", "stepped TypeError", "reversed TypeError", "True 500", "None TypeError", "str inside TypeError", "int inside TypeError", "bytearray(b'') bytearray(b'') bytearray(b'xy') bytearray(b'pq')", "bytearray(b'1<>2<>3') bytearray(b'm<>b<>s')", "middle bytearray bytearray(b'345<>!')", "stepped TypeError", "reversed TypeError", "True 500", "None TypeError", "str inside TypeError", "int inside TypeError"],
    );
}

