// Adapted from CPython Lib/test/test_bytes.py::BaseBytesTest::test_mod
// direct dunder behavior and ByteArrayTest::test_mod_concurrent_mutation.
// The bytearray receiver must stay resize-locked while formatting invokes
// user code such as __repr__ for %a.
#[test]
fn cpython_bytes_percent_dunder_and_reentrant_bytearray_subset() {
    assert_output(
        "class SubB(bytes):\n    pass\nclass SubBA(bytearray):\n    pass\nfor fmt in (b\"<%s>\", SubB(b\"<%s>\"), bytearray(b\"<%s>\"), SubBA(b\"<%s>\")):\n    out = fmt.__mod__(b\"z\")\n    print(type(fmt).__name__, type(out).__name__, out, out is fmt)\nfor base, fmt in ((bytes, SubB(b\"%d!\")), (bytearray, SubBA(b\"%d!\")), (bytes, b\"%d!\"), (bytearray, bytearray(b\"%d!\"))):\n    out = base.__mod__(fmt, 42)\n    print(\"unbound\", base.__name__, type(out).__name__, out)\nprint(all(\"__mod__\" in dir(t) for t in (bytes, bytearray, SubB, SubBA)))\nfor style in (\"method\", \"operator\"):\n    target = bytearray(b\"value=%a;\")\n    class Clearing:\n        def __repr__(self):\n            target.clear()\n            return \"R\"\n    try:\n        if style == \"method\":\n            target.__mod__(Clearing())\n        else:\n            target % Clearing()\n    except BufferError as exc:\n        print(style, type(exc).__name__, target)\n    else:\n        print(style, \"accepted\", target)",
        &["bytes bytes b'<z>' False", "SubB bytes b'<z>' False", "bytearray bytearray bytearray(b'<z>') False", "SubBA bytearray bytearray(b'<z>') False", "unbound bytes bytes b'42!'", "unbound bytearray bytearray bytearray(b'42!')", "unbound bytes bytes b'42!'", "unbound bytearray bytearray bytearray(b'42!')", "True", "method BufferError bytearray(b'value=%a;')", "operator BufferError bytearray(b'value=%a;')"],
    );
}

