fn cpython_bytearray_search_reentrancy_buffererror_subset() {
    assert_output(
        "class Tricky:\n    def __init__(self, owner):\n        self.owner = owner\n    def __buffer__(self, flags):\n        self.owner.clear()\n        return memoryview(self.owner)\n    def __release_buffer__(self, view):\n        view.release()\n    def __index__(self):\n        self.owner.clear()\n        return ord(\"q\")\ndef attempt(label, call):\n    owner = bytearray(b\"q\")\n    try:\n        call(owner, Tricky(owner))\n    except BufferError as exc:\n        print(label, type(exc).__name__, owner)\n    else:\n        print(label, \"accepted\", owner)\nfor name in (\"find\", \"rfind\", \"index\", \"rindex\", \"count\", \"split\", \"rsplit\"):\n    attempt(name, lambda owner, probe, name=name: getattr(owner, name)(probe))\nattempt(\"in\", lambda owner, probe: probe in owner)",
        &["find BufferError bytearray(b'q')", "rfind BufferError bytearray(b'q')", "index BufferError bytearray(b'q')", "rindex BufferError bytearray(b'q')", "count BufferError bytearray(b'q')", "split BufferError bytearray(b'q')", "rsplit BufferError bytearray(b'q')", "in BufferError bytearray(b'q')"],
    );
}

