// Adapted from CPython Lib/test/list_tests.py index start/stop bounds:
// list.index() uses the public __index__ protocol for start and stop.
#[test]
fn cpython_list_index_bounds_index_subset() {
    assert_output(
        "class Pos:\n    def __init__(self, n):\n        self.n = n\n    def __index__(self):\n        return self.n\nclass Huge:\n    def __index__(self):\n        return 7 ** 200\nclass NegHuge:\n    def __index__(self):\n        return -(7 ** 200)\nclass WrongType:\n    def __index__(self):\n        return 2.0\nclass Raises:\n    def __index__(self):\n        raise LookupError(\"nope\")\nitems = [\"a\", \"b\", \"c\", \"a\"]\nprobes = [\n    (\"start\", lambda: items.index(\"a\", Pos(1))),\n    (\"stop\", lambda: items.index(\"c\", 0, Pos(2))),\n    (\"negative start\", lambda: items.index(\"a\", Pos(-50))),\n    (\"huge start\", lambda: items.index(\"a\", Huge())),\n    (\"huge negative start\", lambda: items.index(\"b\", NegHuge())),\n    (\"huge stop\", lambda: items.index(\"c\", 0, Huge())),\n    (\"wrong type\", lambda: items.index(\"a\", WrongType())),\n    (\"raises\", lambda: items.index(\"a\", Raises())),\n    (\"str bound\", lambda: items.index(\"a\", \"1\")),\n    (\"None bound\", lambda: items.index(\"a\", 0, None)),\n    (\"float bound\", lambda: items.index(\"a\", 0.5)),\n]\nfor label, fn in probes:\n    try:\n        print(label, fn())\n    except (TypeError, ValueError, LookupError) as exc:\n        print(label, type(exc).__name__, exc)",
        &["start 3", "stop ValueError list.index(x): x not in list", "negative start 0", "huge start ValueError list.index(x): x not in list", "huge negative start 1", "huge stop 2", "wrong type TypeError __index__ returned non-int (type float)", "raises LookupError nope", "str bound TypeError slice indices must be integers or have an __index__ method", "None bound TypeError slice indices must be integers or have an __index__ method", "float bound TypeError slice indices must be integers or have an __index__ method"],
    );
}

#[test]
fn cpython_list_search_mutating_eq_subset() {
    assert_output_with_stack(
        r#"class Clears:
    def __eq__(self, other):
        target.clear()
        print("clear-eq", len(target))
        return False
target = [Clears(), 1]
print("contains-clear", 1 in target, len(target))
class Appends:
    def __eq__(self, other):
        target.append("needle")
        print("append-eq", len(target))
        return False
target = [Appends()]
print("contains-append", "needle" in target, len(target), target[-1])
class RemovesSecond:
    def __eq__(self, other):
        target.pop(1)
        print("remove-second", len(target))
        return False
target = [RemovesSecond(), "needle"]
try:
    print("index-remove", target.index("needle"))
except ValueError:
    print("index-remove", "ValueError", len(target))
class APIAppends:
    def __eq__(self, other):
        target.append("needle")
        print("api-append-eq", len(target))
        return False
for label, call in [
    ("contains", lambda: "needle" in target),
    ("dunder", lambda: target.__contains__("needle")),
    ("count", lambda: target.count("needle")),
    ("index", lambda: target.index("needle")),
    ("remove", lambda: target.remove("needle")),
    ("index-stop", lambda: target.index("needle", 0, 1)),
]:
    target = [APIAppends()]
    try:
        result = call()
        print("api-append", label, result, len(target), type(target[-1]).__name__ if target else "empty")
    except ValueError:
        print("api-append", label, "ValueError", len(target), target[-1] if target else "empty")
class TrueClears:
    def __eq__(self, other):
        target.clear()
        print("true-clear-eq", len(target))
        return True
for label, call in [
    ("contains", lambda: "needle" in target),
    ("dunder", lambda: target.__contains__("needle")),
    ("count", lambda: target.count("needle")),
    ("index", lambda: target.index("needle")),
    ("remove", lambda: target.remove("needle")),
]:
    target = [TrueClears()]
    result = call()
    print("true-clear", label, result, len(target))"#,
        &[
            "clear-eq 0",
            "contains-clear False 0",
            "append-eq 2",
            "contains-append True 2 needle",
            "remove-second 1",
            "index-remove ValueError 1",
            "api-append-eq 2",
            "api-append contains True 2 str",
            "api-append-eq 2",
            "api-append dunder True 2 str",
            "api-append-eq 2",
            "api-append count 1 2 str",
            "api-append-eq 2",
            "api-append index 1 2 str",
            "api-append-eq 2",
            "api-append remove None 1 APIAppends",
            "api-append-eq 2",
            "api-append index-stop ValueError 2 needle",
            "true-clear-eq 0",
            "true-clear contains True 0",
            "true-clear-eq 0",
            "true-clear dunder True 0",
            "true-clear-eq 0",
            "true-clear count 1 0",
            "true-clear-eq 0",
            "true-clear index 0 0",
            "true-clear-eq 0",
            "true-clear remove None 0",
        ],
        16 * 1024 * 1024,
    );
}

