#[test]
fn cpython_json_function_setattr_delattr_wrapper_metadata_subset() {
    assert_output(
        r#"_doc = lambda value: '<doc>' if isinstance(value, str) and value else value
import json
for name in ['loads', 'dumps']:
    function = getattr(json, name)
    setter = function.__setattr__
    deleter = function.__delattr__
    print(name, '__setattr__' in dir(function), '__delattr__' in dir(function), type(setter).__name__, type(deleter).__name__)
    print(name, setter.__self__ is function, setter.__name__, setter.__qualname__, _doc(setter.__doc__), getattr(setter, '__module__', 'MISSING'), setter.__text_signature__)
    print(name, deleter.__self__ is function, deleter.__name__, deleter.__qualname__, _doc(deleter.__doc__), getattr(deleter, '__module__', 'MISSING'), deleter.__text_signature__)
    setter('mini_probe_attr', 7)
    print(name, function.mini_probe_attr, function.__dict__['mini_probe_attr'], 'mini_probe_attr' in dir(function))
    setter('__call__', 'shadow-call')
    print(name, function.__call__, function.__dict__['__call__'])
    deleter('__call__')
    deleter('mini_probe_attr')
    print(name, 'mini_probe_attr' in function.__dict__, hasattr(function, 'mini_probe_attr'))
    for label, call in [
        ('del-missing', lambda deleter=deleter: deleter('mini_probe_attr')),
        ('set-name-nonstr', lambda setter=setter: setter(1, 2)),
        ('del-name-nonstr', lambda deleter=deleter: deleter(1)),
        ('set-extra', lambda setter=setter: setter('x', 1, 2)),
        ('del-extra', lambda deleter=deleter: deleter('x', 1)),
        ('set-keyword', lambda setter=setter: setter(name='kw', value=3)),
        ('del-keyword', lambda deleter=deleter: deleter(name='kw')),
    ]:
        try:
            call()
        except (TypeError, AttributeError) as error:
            print(name, label, type(error).__name__, str(error), error.args)"#,
        &[
            "loads True True method-wrapper method-wrapper",
            "loads True __setattr__ object.__setattr__ <doc> MISSING ($self, name, value, /)",
            "loads True __delattr__ object.__delattr__ <doc> MISSING ($self, name, /)",
            "loads 7 7 True",
            "loads shadow-call shadow-call",
            "loads False False",
            "loads del-missing AttributeError 'function' object has no attribute 'mini_probe_attr' (\"'function' object has no attribute 'mini_probe_attr'\",)",
            "loads set-name-nonstr TypeError attribute name must be string, not 'int' (\"attribute name must be string, not 'int'\",)",
            "loads del-name-nonstr TypeError attribute name must be string, not 'int' (\"attribute name must be string, not 'int'\",)",
            "loads set-extra TypeError __setattr__ expected 2 arguments, got 3 ('__setattr__ expected 2 arguments, got 3',)",
            "loads del-extra TypeError expected 1 argument, got 2 ('expected 1 argument, got 2',)",
            "loads set-keyword TypeError wrapper __setattr__() takes no keyword arguments ('wrapper __setattr__() takes no keyword arguments',)",
            "loads del-keyword TypeError wrapper __delattr__() takes no keyword arguments ('wrapper __delattr__() takes no keyword arguments',)",
            "dumps True True method-wrapper method-wrapper",
            "dumps True __setattr__ object.__setattr__ <doc> MISSING ($self, name, value, /)",
            "dumps True __delattr__ object.__delattr__ <doc> MISSING ($self, name, /)",
            "dumps 7 7 True",
            "dumps shadow-call shadow-call",
            "dumps False False",
            "dumps del-missing AttributeError 'function' object has no attribute 'mini_probe_attr' (\"'function' object has no attribute 'mini_probe_attr'\",)",
            "dumps set-name-nonstr TypeError attribute name must be string, not 'int' (\"attribute name must be string, not 'int'\",)",
            "dumps del-name-nonstr TypeError attribute name must be string, not 'int' (\"attribute name must be string, not 'int'\",)",
            "dumps set-extra TypeError __setattr__ expected 2 arguments, got 3 ('__setattr__ expected 2 arguments, got 3',)",
            "dumps del-extra TypeError expected 1 argument, got 2 ('expected 1 argument, got 2',)",
            "dumps set-keyword TypeError wrapper __setattr__() takes no keyword arguments ('wrapper __setattr__() takes no keyword arguments',)",
            "dumps del-keyword TypeError wrapper __delattr__() takes no keyword arguments ('wrapper __delattr__() takes no keyword arguments',)",
        ],
    );
}

#[test]
fn cpython_json_function_doc_module_assignment_metadata_subset() {
    assert_output(
        r#"import json
for name in ['loads', 'dumps']:
    function = getattr(json, name)
    bound = function.__get__('receiver', str)
    original_doc = function.__doc__
    original_module = function.__module__
    print(name, type(original_doc).__name__, bool(original_doc), original_module, function.__dict__ == {})
    function.__doc__ = 123
    function.__module__ = name + '_module'
    print(name, function.__doc__, bound.__doc__, function.__module__, bound.__module__, function.__dict__ == {}, '__doc__' in function.__dict__, '__module__' in function.__dict__)
    function.__setattr__('__doc__', None)
    function.__setattr__('__module__', 99)
    print(name, function.__doc__, function.__doc__ is None, function.__module__, type(function.__module__).__name__, bound.__doc__ is function.__doc__, bound.__module__ is function.__module__)
    del function.__doc__
    del function.__module__
    print(name, function.__doc__, function.__doc__ is None, function.__module__, function.__module__ is None, bound.__doc__ is function.__doc__, bound.__module__ is function.__module__)
    function.__delattr__('__doc__')
    function.__delattr__('__module__')
    print(name, function.__doc__ is None, function.__module__ is None, function.__dict__ == {})
    function.__doc__ = original_doc
    function.__module__ = original_module
print(json.loads.__module__ is json.dumps.__module__, json.loads.__module__, json.dumps.__module__)"#,
        &[
            "loads str True json True",
            "loads 123 123 loads_module loads_module True False False",
            "loads None True 99 int True True",
            "loads None True None True True True",
            "loads True True True",
            "dumps str True json True",
            "dumps 123 123 dumps_module dumps_module True False False",
            "dumps None True 99 int True True",
            "dumps None True None True True True",
            "dumps True True True",
            "True json json",
        ],
    );
}

#[test]
fn cpython_json_function_dict_assignment_metadata_subset() {
    assert_output(
        r#"import json
class D(dict):
    pass
for name in ['loads', 'dumps']:
    function = getattr(json, name)
    function.__dict__ = {}
    print(name, 'start', function.__dict__, function.__dict__ is function.__dict__)
    function.mini_probe = 1
    print(name, 'custom', function.__dict__, function.mini_probe, 'mini_probe' in dir(function))
    replacement = {'replacement': 2}
    function.__dict__ = replacement
    print(name, 'assigned-dict', function.__dict__ is replacement, function.__dict__, hasattr(function, 'mini_probe'), function.replacement, 'replacement' in dir(function))
    subclass = D({'sub': 3})
    function.__dict__ = subclass
    print(name, 'assigned-subclass', function.__dict__ is subclass, type(function.__dict__).__name__, function.sub, 'sub' in dir(function))
    function.extra = 4
    print(name, 'subclass-extra', function.__dict__, function.extra)
    for label, call in [
        ('assign-list', lambda function=function: setattr(function, '__dict__', [])),
        ('del-direct', lambda function=function: delattr(function, '__dict__')),
        ('del-wrapper', lambda function=function: function.__delattr__('__dict__')),
    ]:
        try:
            call()
        except TypeError as error:
            print(name, label, type(error).__name__, str(error), error.args)
    print(name, 'after-errors', type(function.__dict__).__name__, function.__dict__)
    function.__dict__ = {}
print(json.loads.__dict__, json.dumps.__dict__)"#,
        &[
            "loads start {} True",
            "loads custom {'mini_probe': 1} 1 True",
            "loads assigned-dict True {'replacement': 2} False 2 True",
            "loads assigned-subclass True D 3 True",
            "loads subclass-extra {'sub': 3, 'extra': 4} 4",
            "loads assign-list TypeError __dict__ must be set to a dictionary, not a 'list' (\"__dict__ must be set to a dictionary, not a 'list'\",)",
            "loads del-direct TypeError cannot delete __dict__ ('cannot delete __dict__',)",
            "loads del-wrapper TypeError cannot delete __dict__ ('cannot delete __dict__',)",
            "loads after-errors D {'sub': 3, 'extra': 4}",
            "dumps start {} True",
            "dumps custom {'mini_probe': 1} 1 True",
            "dumps assigned-dict True {'replacement': 2} False 2 True",
            "dumps assigned-subclass True D 3 True",
            "dumps subclass-extra {'sub': 3, 'extra': 4} 4",
            "dumps assign-list TypeError __dict__ must be set to a dictionary, not a 'list' (\"__dict__ must be set to a dictionary, not a 'list'\",)",
            "dumps del-direct TypeError cannot delete __dict__ ('cannot delete __dict__',)",
            "dumps del-wrapper TypeError cannot delete __dict__ ('cannot delete __dict__',)",
            "dumps after-errors D {'sub': 3, 'extra': 4}",
            "{} {}",
        ],
    );
}

