#[test]
fn cpython_json_dumps_key_coercion_subset() {
    assert_output(
        "import json\nfrom collections import Counter\nfrom enum import IntEnum\nclass S(str):\n    pass\nclass I(int):\n    pass\nclass F(float):\n    pass\nclass Code(IntEnum):\n    ok = 200\nclass NestedDictSubclass(dict):\n    def items(self):\n        return [('é', 4)]\nclass DictSubclass(dict):\n    def items(self):\n        return [('z', 3), ('a', NestedDictSubclass(ignored=0))]\nclass EmptyDictSubclass(dict):\n    def items(self):\n        return [('bad', self)]\nclass Pair(tuple):\n    pass\nclass TupleSubclassItems(dict):\n    def items(self):\n        return [Pair(('pair', 5))]\nclass BadIter:\n    def __iter__(self):\n        return 42\nclass DictItemsBadIter(dict):\n    def items(self):\n        return BadIter()\nclass ItemsNone(dict):\n    def items(self):\n        return None\nclass ItemsInt(dict):\n    def items(self):\n        return 7\ncases = [\n    {'s': 1, 2: 'two', 4.5: 'float', False: 'no', None: 'nil'},\n    {S('sub'): S('value'), I(7): I(8), F(1.5): F(2.5)},\n    {Code.ok: Code.ok},\n    Counter({'a': 2, 'b': 0}),\n    Counter({2: 3, False: 1}),\n    DictSubclass(ignored=1),\n    EmptyDictSubclass(),\n    {'empty': EmptyDictSubclass()},\n    TupleSubclassItems(x=1),\n]\nfor value in cases:\n    print(json.dumps(value))\n    print(json.dumps(value, ensure_ascii=False, separators=(',', ':')))\nfor items in [[['a', 1]], ['ab'], [('a',)], [('a', 1, 2)]]:\n    class BadItems(dict):\n        def items(self):\n            return items\n    try:\n        json.dumps(BadItems(x=1))\n    except ValueError as error:\n        print(type(error).__name__, str(error))\ntry:\n    json.dumps(DictItemsBadIter(x=1))\nexcept TypeError as error:\n    print(type(error).__name__, str(error))\nfor value in [ItemsNone(x=1), ItemsInt(x=1)]:\n    try:\n        json.dumps(value)\n    except TypeError as error:\n        print(type(error).__name__, str(error))",
        &[
            "{\"s\": 1, \"2\": \"two\", \"4.5\": \"float\", \"false\": \"no\", \"null\": \"nil\"}",
            "{\"s\":1,\"2\":\"two\",\"4.5\":\"float\",\"false\":\"no\",\"null\":\"nil\"}",
            "{\"sub\": \"value\", \"7\": 8, \"1.5\": 2.5}",
            "{\"sub\":\"value\",\"7\":8,\"1.5\":2.5}",
            "{\"200\": 200}",
            "{\"200\":200}",
            "{\"a\": 2, \"b\": 0}",
            "{\"a\":2,\"b\":0}",
            "{\"2\": 3, \"false\": 1}",
            "{\"2\":3,\"false\":1}",
            "{\"z\": 3, \"a\": {\"\\u00e9\": 4}}",
            "{\"z\":3,\"a\":{\"é\":4}}",
            "{}",
            "{}",
            "{\"empty\": {}}",
            "{\"empty\":{}}",
            "{\"pair\": 5}",
            "{\"pair\":5}",
            "ValueError items must return 2-tuples",
            "ValueError items must return 2-tuples",
            "ValueError items must return 2-tuples",
            "ValueError items must return 2-tuples",
            "TypeError DictItemsBadIter.items() returned a non-iterable (type BadIter)",
            "TypeError ItemsNone.items() returned a non-iterable (type NoneType)",
            "TypeError ItemsInt.items() returned a non-iterable (type int)",
        ],
    );
}

#[test]
fn cpython_json_dumps_ordered_dict_subset() {
    assert_output(
        "import json\nfrom collections import OrderedDict\nplain = OrderedDict([('b', 2), ('a', 1)])\nprint(json.dumps(plain))\nprint(json.dumps(plain, sort_keys=True))\nnested = OrderedDict([('é', ['𝄠', OrderedDict([('b', 1), ('a', 2)])])])\nprint(json.dumps(nested, ensure_ascii=False, sort_keys=True, separators=(',', ':')))\nprint(json.loads(json.dumps(OrderedDict([('x', OrderedDict([('y', 3)]))]))))\ncycle = OrderedDict()\ncycle['self'] = cycle\ntry:\n    json.dumps(cycle)\nexcept Exception as error:\n    print('cycle', type(error).__name__, isinstance(error, ValueError), 'Circular' in str(error))",
        &[
            "{\"b\": 2, \"a\": 1}",
            "{\"a\": 1, \"b\": 2}",
            "{\"é\":[\"𝄠\",{\"a\":2,\"b\":1}]}",
            "{'x': {'y': 3}}",
            "cycle ValueError True True",
        ],
    );
}

#[test]
fn cpython_json_dumps_counter_subclass_subset() {
    assert_output(
        "import json\nfrom collections import Counter\nclass C(Counter):\n    pass\nclass Items(Counter):\n    def items(self):\n        print('items-called')\n        return [('z', 3), ('a', 1)]\nclass EmptyItemsBoom(Counter):\n    def items(self):\n        raise RuntimeError('items should not be called')\nclass BadItems(Counter):\n    def items(self):\n        return [[1, 2]]\nclass BadItemsLen(Counter):\n    def items(self):\n        return [('a', 1, 2)]\nclass BadItemsNonIterable(Counter):\n    def items(self):\n        return 7\nbasic = C('aba')\nprint(type(basic).__name__, json.dumps(basic), json.dumps(basic, sort_keys=True))\nprint(json.dumps({'nested': C({'b': 2, 'a': 1})}, sort_keys=True, separators=(',', ':')))\nprint(json.dumps(Items({'ignored': 9}), sort_keys=True, separators=(',', ':')))\nprint(json.dumps(EmptyItemsBoom()))\ncycle = C()\ncycle['self'] = cycle\ntry:\n    json.dumps(cycle)\nexcept Exception as error:\n    print('cycle', type(error).__name__, isinstance(error, ValueError), 'Circular' in str(error))\nfor value in [BadItems({'x': 1}), BadItemsLen({'x': 1}), BadItemsNonIterable({'x': 1})]:\n    try:\n        json.dumps(value)\n    except Exception as error:\n        print(type(value).__name__, type(error).__name__, str(error))",
        &[
            "C {\"a\": 2, \"b\": 1} {\"a\": 2, \"b\": 1}",
            "{\"nested\":{\"a\":1,\"b\":2}}",
            "items-called",
            "{\"a\":1,\"z\":3}",
            "{}",
            "cycle ValueError True True",
            "BadItems ValueError items must return 2-tuples",
            "BadItemsLen ValueError items must return 2-tuples",
            "BadItemsNonIterable TypeError BadItemsNonIterable.items() returned a non-iterable (type int)",
        ],
    );
}

