#[test]
fn cpython_json_loads_nonfinite_constants_subset() {
    assert_output(
        "import json, math\nfor source in ['NaN', 'Infinity', '-Infinity', '[NaN, Infinity, -Infinity]', '{\"x\": NaN, \"y\": Infinity}']:\n    value = json.loads(source)\n    print(source, type(value).__name__, repr(value))\n    encoded = json.dumps(value)\n    print(encoded)\n    reparsed = json.loads(encoded)\n    if isinstance(reparsed, list):\n        print(math.isnan(reparsed[0]), math.isinf(reparsed[1]), math.isinf(reparsed[2]), reparsed[2] < 0)\n    elif isinstance(reparsed, dict):\n        print(math.isnan(reparsed['x']), math.isinf(reparsed['y']))\n    else:\n        print(math.isnan(reparsed) if source == 'NaN' else math.isinf(reparsed), reparsed < 0)",
        &[
            "NaN float nan",
            "NaN",
            "True False",
            "Infinity float inf",
            "Infinity",
            "True False",
            "-Infinity float -inf",
            "-Infinity",
            "True True",
            "[NaN, Infinity, -Infinity] list [nan, inf, -inf]",
            "[NaN, Infinity, -Infinity]",
            "True True True True",
            "{\"x\": NaN, \"y\": Infinity} dict {'x': nan, 'y': inf}",
            "{\"x\": NaN, \"y\": Infinity}",
            "True True",
        ],
    );
}

#[test]
fn cpython_json_loads_parse_hooks_subset() {
    assert_output(
        r#"import json

def pint(s):
    print('parse_int', s)
    return 'I:' + s

def pfloat(s):
    print('parse_float', s)
    return 'F:' + s

def pconst(s):
    print('parse_constant', s)
    return 'C:' + s
value = json.loads('[1, -2, 3.5, -0.0, 6.02e+23, NaN, Infinity, -Infinity]', parse_int=pint, parse_float=pfloat, parse_constant=pconst)
print(value)
print(json.loads('{"a": 123, "b": 4.5}', parse_int=lambda s: ('int', s), parse_float=lambda s: ('float', s)))
print(json.loads('"x"', parse_int=1))
print(json.loads('1', parse_int=lambda s: None))
print(json.loads('1', parse_int=lambda s: [s]))
print(json.loads('1.5', parse_float=lambda s: None))
print(json.loads('NaN', parse_constant=lambda s: [s]))
print(json.loads('[1, 2]', parse_int=lambda s: {'n': s}))
for label, source, kwargs in [
    ('int-false', '1', dict(parse_int=False)),
    ('int-zero', '1', dict(parse_int=0)),
    ('int-empty-string', '1', dict(parse_int='')),
    ('int-empty-list', '1', dict(parse_int=[])),
    ('float-false', '1.5', dict(parse_float=False)),
    ('constant-false', 'NaN', dict(parse_constant=False)),
]:
    value = json.loads(source, **kwargs)
    print(label, type(value).__name__, repr(value), value != value)
class FalseHook:
    def __bool__(self):
        print('bool falsehook')
        return False
class BoolBoom:
    def __bool__(self):
        print('bool boom')
        raise ValueError('bool-boom')
print('falsehook', json.loads('1', parse_int=FalseHook()))
try:
    json.loads('1', parse_int=BoolBoom())
except Exception as error:
    print('boom', type(error).__name__, str(error))
def boom_int(s):
    raise ValueError('boom-int')

def boom_float(s):
    raise ValueError('boom-float')

def boom_constant(s):
    raise ValueError('boom-constant')

for label, source, kwargs in [
    ('int-noncallable', '1', dict(parse_int=1)),
    ('float-noncallable', '1.5', dict(parse_float=1)),
    ('constant-noncallable', 'NaN', dict(parse_constant=1)),
]:
    try:
        json.loads(source, **kwargs)
    except Exception as error:
        print(label, type(error).__name__, str(error))
for label, kwargs in [
    ('int-boom', dict(parse_int=boom_int)),
    ('float-boom', dict(parse_float=boom_float)),
    ('constant-boom', dict(parse_constant=boom_constant)),
]:
    try:
        json.loads({'int-boom':'1','float-boom':'1.5','constant-boom':'NaN'}[label], **kwargs)
    except Exception as error:
        print(label, type(error).__name__, str(error))"#,
        &[
            "parse_int 1",
            "parse_int -2",
            "parse_float 3.5",
            "parse_float -0.0",
            "parse_float 6.02e+23",
            "parse_constant NaN",
            "parse_constant Infinity",
            "parse_constant -Infinity",
            "['I:1', 'I:-2', 'F:3.5', 'F:-0.0', 'F:6.02e+23', 'C:NaN', 'C:Infinity', 'C:-Infinity']",
            "{'a': ('int', '123'), 'b': ('float', '4.5')}",
            "x",
            "None",
            "['1']",
            "None",
            "['NaN']",
            "[{'n': '1'}, {'n': '2'}]",
            "int-false int 1 False",
            "int-zero int 1 False",
            "int-empty-string int 1 False",
            "int-empty-list int 1 False",
            "float-false float 1.5 False",
            "constant-false float nan True",
            "bool falsehook",
            "falsehook 1",
            "bool boom",
            "boom ValueError bool-boom",
            "int-noncallable TypeError 'int' object is not callable",
            "float-noncallable TypeError 'int' object is not callable",
            "constant-noncallable TypeError 'int' object is not callable",
            "int-boom ValueError boom-int",
            "float-boom ValueError boom-float",
            "constant-boom ValueError boom-constant",
        ],
    );
}

#[test]
fn cpython_json_loads_object_hook_subset() {
    assert_output(
        "import json\n\nevents = []\ndef hook(value):\n    print('hook', sorted(value.items()))\n    events.append(sorted(value.items()))\n    return {'seen': len(events), 'value': value}\n\nprint(json.loads('{}', object_hook=hook))\nprint(json.loads('{\"outer\": {\"inner\": 1}, \"list\": [{\"x\": 2}]}', object_hook=hook))\nprint(json.loads('{\"a\": 1}', object_hook=lambda value: None))\nprint(json.loads('{\"a\": 1}', object_hook=lambda value: [value]))\nprint(json.loads('{\"outer\": {\"inner\": 1}}', object_hook=lambda value: list(sorted(value))))\nprint(json.loads('[1, 2]', object_hook=1))\n\ndef boom(value):\n    raise ValueError('boom-object')\n\nfor label, source, kwargs in [\n    ('object-hook-noncallable', '{}', dict(object_hook=1)),\n    ('object-hook-boom', '{}', dict(object_hook=boom)),\n]:\n    try:\n        json.loads(source, **kwargs)\n    except Exception as error:\n        if label == 'object-hook-boom':\n            print(label, type(error).__name__, str(error))\n        else:\n            print(label, type(error).__name__, str(error))",
        &[
            "hook []",
            "{'seen': 1, 'value': {}}",
            "hook [('inner', 1)]",
            "hook [('x', 2)]",
            "hook [('list', [{'seen': 3, 'value': {'x': 2}}]), ('outer', {'seen': 2, 'value': {'inner': 1}})]",
            "{'seen': 4, 'value': {'outer': {'seen': 2, 'value': {'inner': 1}}, 'list': [{'seen': 3, 'value': {'x': 2}}]}}",
            "None",
            "[{'a': 1}]",
            "['outer']",
            "[1, 2]",
            "object-hook-noncallable TypeError 'int' object is not callable",
            "object-hook-boom ValueError boom-object",
        ],
    );
}

#[test]
fn cpython_json_loads_object_pairs_hook_subset() {
    assert_output(
        "import json\n\ndef pairs(value):\n    print('pairs', value)\n    return ('pairs', value)\n\ndef obj(value):\n    print('obj', value)\n    return ('obj', value)\n\nprint(json.loads('{}', object_pairs_hook=pairs))\nprint(json.loads('{\"a\": 1, \"a\": 2, \"b\": {\"c\": 3}}', object_pairs_hook=pairs))\nprint(json.loads('{\"a\": 1, \"b\": {\"c\": 2}}', object_hook=obj, object_pairs_hook=pairs))\nprint(json.loads('{\"a\": 1}', object_pairs_hook=lambda value: None))\nprint(json.loads('{\"a\": 1}', object_pairs_hook=lambda value: [value]))\nprint(json.loads('{\"outer\": {\"inner\": 1}}', object_pairs_hook=lambda value: [key for key, _ in value]))\nprint(json.loads('[1, 2]', object_pairs_hook=1))\n\ndef boom(value):\n    raise ValueError('boom-pairs')\n\nfor label, source, kwargs in [\n    ('pairs-noncallable', '{}', dict(object_pairs_hook=1)),\n    ('pairs-boom', '{}', dict(object_pairs_hook=boom)),\n]:\n    try:\n        json.loads(source, **kwargs)\n    except Exception as error:\n        if label == 'pairs-boom':\n            print(label, type(error).__name__, str(error))\n        else:\n            print(label, type(error).__name__, str(error))",
        &[
            "pairs []",
            "('pairs', [])",
            "pairs [('c', 3)]",
            "pairs [('a', 1), ('a', 2), ('b', ('pairs', [('c', 3)]))]",
            "('pairs', [('a', 1), ('a', 2), ('b', ('pairs', [('c', 3)]))])",
            "pairs [('c', 2)]",
            "pairs [('a', 1), ('b', ('pairs', [('c', 2)]))]",
            "('pairs', [('a', 1), ('b', ('pairs', [('c', 2)]))])",
            "None",
            "[[('a', 1)]]",
            "['outer']",
            "[1, 2]",
            "pairs-noncallable TypeError 'int' object is not callable",
            "pairs-boom ValueError boom-pairs",
        ],
    );
}

#[test]
fn cpython_json_loads_dumps_error_boundary_subset() {
    assert_output(
        "import json\n\ndef show_call(label, call):\n    try:\n        call()\n    except Exception as error:\n        print(label, isinstance(error, TypeError), isinstance(error, ValueError))\n    else:\n        print(label, 'OK')\n\ndef show_load(label, source, expected):\n    try:\n        json.loads(source)\n    except Exception as error:\n        print(label, isinstance(error, ValueError), expected in str(error))\n    else:\n        print(label, 'OK')\n\nshow_call('loads-no-args', json.loads)\ntry:\n    json.loads('{}', 1)\nexcept Exception as error:\n    print('loads-extra-arg', isinstance(error, TypeError), isinstance(error, ValueError))\ntry:\n    json.loads('{}', unknown=1)\nexcept Exception as error:\n    print('loads-unknown-keyword', isinstance(error, TypeError), isinstance(error, ValueError))\ntry:\n    json.loads(memoryview(b'{}'))\nexcept Exception as error:\n    print('loads-memoryview', isinstance(error, TypeError), isinstance(error, ValueError))\ntry:\n    json.loads(b'\\xff')\nexcept Exception as error:\n    print('loads-invalid-utf8', isinstance(error, UnicodeDecodeError), isinstance(error, ValueError))\ntry:\n    json.loads(bytes([255]))\nexcept Exception as error:\n    print('loads-invalid-utf8-unicode', isinstance(error, UnicodeDecodeError))\nshow_load('loads-odd-leading-nul', bytes([0, ord('1'), 0]), 'Expecting value')\nshow_load('loads-odd-trailing-nul', bytes([ord('1'), 0, 0]), 'Extra data')\nshow_load('loads-missing-colon', '{\"a\" 1}', \"Expecting ':' delimiter\")\nshow_load('loads-array-trailing-comma', '[1,]', 'Illegal trailing comma before end of array')\nshow_load('loads-object-trailing-comma', '{\"a\": 1,}', 'Illegal trailing comma before end of object')\nshow_load('loads-trailing-data', '{} []', 'Extra data')\nshow_load('loads-invalid-escape', '\"\\\\q\"', 'Invalid \\\\escape')\nshow_load('loads-raw-newline', '\"line\\nbreak\"', 'Invalid control character at')",
        &[
            "loads-no-args True False",
            "loads-extra-arg True False",
            "loads-unknown-keyword True False",
            "loads-memoryview True False",
            "loads-invalid-utf8 True True",
            "loads-invalid-utf8-unicode True",
            "loads-odd-leading-nul True True",
            "loads-odd-trailing-nul True True",
            "loads-missing-colon True True",
            "loads-array-trailing-comma True True",
            "loads-object-trailing-comma True True",
            "loads-trailing-data True True",
            "loads-invalid-escape True True",
            "loads-raw-newline True True",
        ],
    );
}

#[test]
fn cpython_json_loads_delimiter_and_leading_zero_boundary_subset() {
    assert_output(
        concat!(
            "import json\n",
            "def show(label, source, expected):\n",
            "    try:\n",
            "        json.loads(source)\n",
            "    except Exception as error:\n",
            "        print(label, expected in str(error))\n",
            "try:\n",
            "    json.loads(b'\\xff')\n",
            "except Exception as error:\n",
            "    print('loads-invalid-utf8', isinstance(error, TypeError), isinstance(error, ValueError))\n",
            "try:\n",
            "    json.loads(bytes([255]))\n",
            "except Exception as error:\n",
            "    print('loads-invalid-utf8-unicode', isinstance(error, UnicodeDecodeError))\n",
            "try:\n",
            "    json.loads(chr(65279) + '{}')\n",
            "except Exception as error:\n",
            "    print('loads-string-bom', isinstance(error, ValueError), 'Unexpected UTF-8 BOM' in str(error))\n",
            "for label, data, text in [\n",
            "    ('loads-odd-leading-nul', bytes([0, ord('1'), 0]), 'Expecting value'),\n",
            "    ('loads-odd-trailing-nul', bytes([ord('1'), 0, 0]), 'Extra data'),\n",
            "]:\n",
            "    try:\n",
            "        json.loads(data)\n",
            "    except Exception as error:\n",
            "        print(label, isinstance(error, ValueError), isinstance(error, UnicodeDecodeError), text in str(error))\n",
            "show('loads-leading-zero-extra', '01', 'Extra data')\n",
            "show('loads-missing-colon-text', '{\"a\" 1}', \"Expecting ':' delimiter\")\n",
            "show('loads-array-missing-comma-text', '[1 2]', \"Expecting ',' delimiter\")\n",
            "show('loads-object-missing-comma-text', '{\"a\":1 \"b\":2}', \"Expecting ',' delimiter\")",
        ),
        &[
            "loads-invalid-utf8 False True",
            "loads-invalid-utf8-unicode True",
            "loads-string-bom True True",
            "loads-odd-leading-nul True False True",
            "loads-odd-trailing-nul True False True",
            "loads-leading-zero-extra True",
            "loads-missing-colon-text True",
            "loads-array-missing-comma-text True",
            "loads-object-missing-comma-text True",
        ],
    );
}

#[test]
fn cpython_json_dumps_error_boundary_subset() {
    assert_output(
        "import json\ntry:\n    json.dumps()\nexcept Exception as error:\n    print('dumps-no-args', isinstance(error, TypeError), isinstance(error, ValueError))\ntry:\n    json.dumps({}, 1)\nexcept Exception as error:\n    print('dumps-extra-arg', isinstance(error, TypeError), isinstance(error, ValueError))\ntry:\n    json.dumps({}, unknown=1)\nexcept Exception as error:\n    print('dumps-unknown-keyword', isinstance(error, TypeError), isinstance(error, ValueError))\ntry:\n    json.dumps(object())\nexcept Exception as error:\n    print('dumps-object', isinstance(error, TypeError), isinstance(error, ValueError))\ntry:\n    json.dumps(b'abc')\nexcept Exception as error:\n    print('dumps-bytes', isinstance(error, TypeError), isinstance(error, ValueError))\ntry:\n    json.dumps({(1, 2): 3})\nexcept Exception as error:\n    print('dumps-bad-key', isinstance(error, TypeError), isinstance(error, ValueError))\ncycle_list = []\ncycle_list.append(cycle_list)\ntry:\n    json.dumps(cycle_list)\nexcept Exception as error:\n    print('dumps-list-cycle', isinstance(error, TypeError), isinstance(error, ValueError))\ncycle_dict = {}\ncycle_dict['self'] = cycle_dict\ntry:\n    json.dumps(cycle_dict)\nexcept Exception as error:\n    print('dumps-dict-cycle', isinstance(error, TypeError), isinstance(error, ValueError))",
        &[
            "dumps-no-args True False",
            "dumps-extra-arg True False",
            "dumps-unknown-keyword True False",
            "dumps-object True False",
            "dumps-bytes True False",
            "dumps-bad-key True False",
            "dumps-list-cycle False True",
            "dumps-dict-cycle False True",
        ],
    );
}

#[test]
fn cpython_json_dumps_additional_error_boundary_subset() {
    assert_output_with_stack(
        concat!(
            "import json\n",
            "from collections import namedtuple\n",
            "def show(label, callback):\n",
            "    try:\n",
            "        callback()\n",
            "    except Exception as error:\n",
            "        print(label, isinstance(error, TypeError), isinstance(error, ValueError))\n",
            "show('dumps-bytearray', lambda: json.dumps(bytearray(b'abc')))\n",
            "show('dumps-memoryview', lambda: json.dumps(memoryview(b'abc')))\n",
            "inner = []\n",
            "cycle_tuple = (inner,)\n",
            "inner.append(cycle_tuple)\n",
            "show('dumps-tuple-cycle', lambda: json.dumps(cycle_tuple))\n",
            "items = []\n",
            "Cycle = namedtuple('Cycle', 'items')\n",
            "cycle_namedtuple = Cycle(items)\n",
            "items.append(cycle_namedtuple)\n",
            "show('dumps-namedtuple-cycle', lambda: json.dumps(cycle_namedtuple))",
        ),
        &[
            "dumps-bytearray True False",
            "dumps-memoryview True False",
            "dumps-tuple-cycle False True",
            "dumps-namedtuple-cycle False True",
        ],
        8 * 1024 * 1024,
    );
}

#[test]
fn cpython_json_loads_invalid_utf8_error_detail_subset() {
    assert_output(
        concat!(
            "import json\n",
            "def show(label, data):\n",
            "    try:\n",
            "        json.loads(data)\n",
            "    except Exception as error:\n",
            "        print(label, type(error).__name__, str(error))\n",
            "    else:\n",
            "        print(label, 'OK')\n",
            "for label, data in [\n",
            "    ('start-ff', b'\\xff'),\n",
            "    ('start-80', b'\\x80'),\n",
            "    ('cont-c3-28', b'\\xc3('),\n",
            "    ('truncated-e2', b'\\xe2'),\n",
            "    ('truncated-e2-82', b'\\xe2\\x82'),\n",
            "    ('after-prefix', b'{\"a\": \\xff}'),\n",
            "    ('bom-invalid', b'\\xef\\xbb\\xbf\\xff'),\n",
            "    ('bytearray-start', bytearray(b'\\xff')),\n",
            "]:\n",
            "    show(label, data)"
        ),
        &[
            "start-ff UnicodeDecodeError 'utf-8' codec can't decode byte 0xff in position 0: invalid start byte",
            "start-80 UnicodeDecodeError 'utf-8' codec can't decode byte 0x80 in position 0: invalid start byte",
            "cont-c3-28 UnicodeDecodeError 'utf-8' codec can't decode byte 0xc3 in position 0: invalid continuation byte",
            "truncated-e2 UnicodeDecodeError 'utf-8' codec can't decode byte 0xe2 in position 0: unexpected end of data",
            "truncated-e2-82 UnicodeDecodeError 'utf-8' codec can't decode bytes in position 0-1: unexpected end of data",
            "after-prefix UnicodeDecodeError 'utf-8' codec can't decode byte 0xff in position 6: invalid start byte",
            "bom-invalid UnicodeDecodeError 'utf-8' codec can't decode byte 0xff in position 0: invalid start byte",
            "bytearray-start UnicodeDecodeError 'utf-8' codec can't decode byte 0xff in position 0: invalid start byte",
        ],
    );
}

