// Adapted from CPython Lib/test/test_builtin.py::TestType::test_type_typeparams.
// This covers the public class __type_params__ surface: generic class metadata,
// user assignment override, and delete rejection that preserves the override.
#[test]
fn cpython_type_typeparams_subset() {
    assert_output(
        "from typing import TypeVar\nclass A[T]:\n    pass\nT, = A.__type_params__\nprint(isinstance(T, TypeVar), T.__name__)\nA.__type_params__ = 'whatever'\nprint(A.__type_params__)\ntry:\n    del A.__type_params__\nexcept TypeError as error:\n    print(type(error).__name__, A.__type_params__)\nprint(A.__type_params__)",
        &["True T", "whatever", "TypeError whatever", "whatever"],
    );
}

// Adapted from CPython Lib/test/test_builtin.py::TestType public
// __type_params__ deletion behavior. The deletion TypeError uses the current
// public class name and preserves any assigned override.
#[test]
fn cpython_type_typeparams_delete_error_name_subset() {
    assert_output(
        "class A:\n    pass\nA.__name__ = 'Renamed'\nprint('initial', A.__type_params__, '__type_params__' in A.__dict__)\nA.__type_params__ = 1\nprint('assigned', A.__type_params__, '__type_params__' in A.__dict__)\ntry:\n    del A.__type_params__\nexcept TypeError as error:\n    print('delete-custom', error.__class__.__name__, str(error), error.args == (str(error),), A.__type_params__, '__type_params__' in A.__dict__)\nprint('final', A.__type_params__, '__type_params__' in A.__dict__)\nclass B[T]:\n    pass\nB.__type_params__ = 'custom'\ntry:\n    del B.__type_params__\nexcept TypeError as error:\n    print('delete-generic', error.__class__.__name__, str(error), error.args == (str(error),), B.__type_params__)",
        &[
            "initial () False",
            "assigned 1 True",
            "delete-custom TypeError cannot delete '__type_params__' attribute of immutable type 'Renamed' True 1 True",
            "final 1 True",
            "delete-generic TypeError cannot delete '__type_params__' attribute of immutable type 'B' True custom",
        ],
    );
}

// Adapted from CPython Lib/test/test_builtin.py::TestType public type-parameter
// metadata behavior. Ordinary non-generic classes do not expose
// __parameters__ unless user code assigns it, while generic classes still do.
#[test]
fn cpython_type_parameters_missing_for_nongeneric_subset() {
    assert_output(
        "class A:\n    pass\nA.__name__ = 'Renamed'\ntry:\n    print('initial', A.__parameters__)\nexcept AttributeError as error:\n    print('initial', error.__class__.__name__, str(error), error.args == (str(error),), '__parameters__' in A.__dict__)\nA.__parameters__ = 1\nprint('assigned', A.__parameters__, '__parameters__' in A.__dict__)\ndel A.__parameters__\ntry:\n    print('after-delete', A.__parameters__)\nexcept AttributeError as error:\n    print('after-delete', error.__class__.__name__, str(error), error.args == (str(error),), hasattr(A, '__parameters__'), '__parameters__' in A.__dict__)\nclass G[T]:\n    pass\nprint('generic', tuple(param.__name__ for param in G.__parameters__), G.__parameters__ == G.__type_params__)",
        &[
            "initial AttributeError type object 'Renamed' has no attribute '__parameters__' True False",
            "assigned 1 True",
            "after-delete AttributeError type object 'Renamed' has no attribute '__parameters__' True False False",
            "generic ('T',) True",
        ],
    );
}

// Adapted from CPython Lib/test/test_builtin.py::TestType::test_namespace_order.
// MiniPython covers the public behavior that a dynamic class preserves the
// insertion order of an ordered namespace mapping in its class dictionary.
#[test]
fn cpython_type_namespace_order_subset() {
    assert_output(
        "from collections import OrderedDict as OD\nbase = OD([(\"k\", 10), (\"j\", 20)])\nprint(OD.__module__, OD.__qualname__, isinstance(OD.__doc__, str) and len(OD.__doc__) > 0, isinstance(base.__doc__, str))\none = OD(q=5)\nprint(repr(one), str(one), format(one), one.__repr__() == OD.__repr__(one) == OD.__str__(one) == OD.__format__(one, \"\"))\nloop = OD()\nloop[\"me\"] = loop\nloop[\"n\"] = 1\nprint(repr(loop), str(loop))\ntry:\n    one.__format__(\"s\")\nexcept TypeError as exc:\n    print(\"format spec\", type(exc).__name__)\nga = OD[bytes, float]\nprint(repr(ga), ga.__origin__ is OD, ga.__args__, ga.__origin__.__module__)\nprint(hasattr(OD, \"__class_getitem__\"), \"__class_getitem__\" in dir(OD), type(OD.__class_getitem__).__name__, hasattr(base, \"__class_getitem__\"), \"__class_getitem__\" in dir(base))\nfor label, alias in ((\"direct\", OD.__class_getitem__(bytes)), (\"instance\", base.__class_getitem__(bytes)), (\"tuple\", OD.__class_getitem__((bytes, float)))):\n    print(label, repr(alias), alias.__args__, alias.__origin__ is OD, alias == OD[alias.__args__])\nfor label, call in ((\"none\", lambda: OD.__class_getitem__()), (\"two\", lambda: OD.__class_getitem__(bytes, float)), (\"keyword\", lambda: OD.__class_getitem__(item=bytes))):\n    try:\n        call()\n    except TypeError as exc:\n        print(label, exc)\nmade = OD.fromkeys(\"zy\", 0)\nmade2 = base.fromkeys([\"m\"])\nprint(type(made).__name__, list(made.items()), type(made2).__name__, list(made2.items()))\nfor dup in (base.copy(), OD.copy(base)):\n    print(type(dup).__name__, dup == base, dup is base, list(dup.items()))\nflipped = OD([(\"j\", 20), (\"k\", 10)])\nplain = {\"j\": 20, \"k\": 10}\nprint(base == flipped, base != flipped, OD.__eq__(base, flipped), OD.__ne__(base, flipped))\nprint(base == plain, base != plain, OD.__eq__(base, ()), OD.__ne__(base, ()))\nprint(type(base | {\"m\": 30}).__name__, list((base | {\"m\": 30}).items()))\nprint(type({\"a\": 0} | base).__name__, list(({\"a\": 0} | base).items()), OD.__or__(base, ()))\ngrow = OD(a=1)\nsame = grow.__ior__({\"b\": 2})\ngrow |= [(\"c\", 3)]\nprint(same is grow, list(grow.items()))\nfor kwargs in ({}, {\"last\": True}, {\"last\": False}):\n    sample = OD(x=1, y=2, w=3)\n    print(kwargs, sample.popitem(**kwargs), list(sample))\nprint(list(reversed(base)), list(OD.__reversed__(base)))\nns = OD([(\"first\", 1), (\"second\", 2), (\"third\", 3)])\nns.move_to_end(\"first\")\nns.move_to_end(\"third\", last=False)\nDyn = type(\"Dyn\", (), ns)\nprint(list(ns), [k for k in Dyn.__dict__ if not k.startswith(\"__\")])\nwanted = [\"fromkeys\", \"__class_getitem__\", \"move_to_end\", \"__eq__\", \"__ne__\", \"__or__\", \"__ior__\", \"__ror__\", \"__reversed__\", \"popitem\", \"__repr__\", \"__format__\"]\nprint(all(name in dir(OD) for name in wanted), all(name in dir(base) for name in wanted), \"move_to_end\" in dir({}))",
        &["collections OrderedDict True True", "OrderedDict({'q': 5}) OrderedDict({'q': 5}) OrderedDict({'q': 5}) True", "OrderedDict({'me': ..., 'n': 1}) OrderedDict({'me': ..., 'n': 1})", "format spec TypeError", "collections.OrderedDict[bytes, float] True (<class 'bytes'>, <class 'float'>) collections", "True True builtin_function_or_method True True", "direct collections.OrderedDict[bytes] (<class 'bytes'>,) True True", "instance collections.OrderedDict[bytes] (<class 'bytes'>,) True True", "tuple collections.OrderedDict[bytes, float] (<class 'bytes'>, <class 'float'>) True True", "none OrderedDict.__class_getitem__() takes exactly one argument (0 given)", "two OrderedDict.__class_getitem__() takes exactly one argument (2 given)", "keyword OrderedDict.__class_getitem__() takes no keyword arguments", "OrderedDict [('z', 0), ('y', 0)] OrderedDict [('m', None)]", "OrderedDict True False [('k', 10), ('j', 20)]", "OrderedDict True False [('k', 10), ('j', 20)]", "False True False True", "True False NotImplemented NotImplemented", "OrderedDict [('k', 10), ('j', 20), ('m', 30)]", "OrderedDict [('a', 0), ('k', 10), ('j', 20)] NotImplemented", "True [('a', 1), ('b', 2), ('c', 3)]", "{} ('w', 3) ['x', 'y']", "{'last': True} ('w', 3) ['x', 'y']", "{'last': False} ('x', 1) ['y', 'w']", "['j', 'k'] ['j', 'k']", "['third', 'second', 'first'] ['third', 'second', 'first']", "True True False"],
    );
}

// Mirrors CPython public collections.OrderedDict __class_getitem__ behavior.
// This pins GenericAlias origin/args, direct type calls, exact instance lookup,
// and inherited subclass lookup without expanding the OrderedDict sandbox
// surface beyond pure-memory mapping behavior.
#[test]
fn cpython_ordered_dict_class_getitem_generic_alias_subset() {
    assert_output(
        r#"from collections import OrderedDict
typ = OrderedDict
inst = OrderedDict()
class C(OrderedDict):
    pass
for label, expr in [
    ('visible', lambda: (hasattr(typ, '__class_getitem__'), '__class_getitem__' in dir(typ), type(typ.__class_getitem__).__name__)),
    ('visible-inst', lambda: (hasattr(inst, '__class_getitem__'), '__class_getitem__' in dir(inst))),
    ('subscript-int', lambda: (type(typ[int]).__name__, str(typ[int]), typ[int].__origin__ is typ, typ[int].__args__)),
    ('call-int', lambda: (type(typ.__class_getitem__(int)).__name__, str(typ.__class_getitem__(int)), typ.__class_getitem__(int) == typ[int], typ.__class_getitem__(int).__origin__ is typ, typ.__class_getitem__(int).__args__)),
    ('call-pair', lambda: (str(typ.__class_getitem__((int, str))), typ.__class_getitem__((int, str)) == typ[int, str], typ.__class_getitem__((int, str)).__args__)),
    ('inst-exact', lambda: (inst.__class_getitem__(int) == typ[int], inst.__class_getitem__(int).__origin__ is typ)),
    ('type-sub', lambda: (hasattr(C, '__class_getitem__'), '__class_getitem__' in dir(C), type(C.__class_getitem__).__name__, type(C.__class_getitem__(int)).__name__, C.__class_getitem__(int).__origin__ is C, C.__class_getitem__(int).__args__)),
    ('inst-sub', lambda: (hasattr(C(), '__class_getitem__'), '__class_getitem__' in dir(C()), type(C().__class_getitem__(str)).__name__, C().__class_getitem__(str).__origin__ is C, C().__class_getitem__(str).__args__)),
    ('call-noargs', lambda: typ.__class_getitem__()),
    ('call-extra', lambda: typ.__class_getitem__(int, str)),
    ('call-keyword', lambda: typ.__class_getitem__(item=int)),
    ('sub-keyword', lambda: C.__class_getitem__(item=int)),
]:
    try:
        result = expr()
        print(label, type(result).__name__, result)
    except Exception as error:
        print(label, type(error).__name__, str(error), error.args)"#,
        &[
            "visible tuple (True, True, 'builtin_function_or_method')",
            "visible-inst tuple (True, True)",
            "subscript-int tuple ('GenericAlias', 'collections.OrderedDict[int]', True, (<class 'int'>,))",
            "call-int tuple ('GenericAlias', 'collections.OrderedDict[int]', True, True, (<class 'int'>,))",
            "call-pair tuple ('collections.OrderedDict[int, str]', True, (<class 'int'>, <class 'str'>))",
            "inst-exact tuple (True, True)",
            "type-sub tuple (True, True, 'builtin_function_or_method', 'GenericAlias', True, (<class 'int'>,))",
            "inst-sub tuple (True, True, 'GenericAlias', True, (<class 'str'>,))",
            "call-noargs TypeError OrderedDict.__class_getitem__() takes exactly one argument (0 given) ('OrderedDict.__class_getitem__() takes exactly one argument (0 given)',)",
            "call-extra TypeError OrderedDict.__class_getitem__() takes exactly one argument (2 given) ('OrderedDict.__class_getitem__() takes exactly one argument (2 given)',)",
            "call-keyword TypeError OrderedDict.__class_getitem__() takes no keyword arguments ('OrderedDict.__class_getitem__() takes no keyword arguments',)",
            "sub-keyword TypeError C.__class_getitem__() takes no keyword arguments ('C.__class_getitem__() takes no keyword arguments',)",
        ],
    );
}

