// Adapted from CPython
// Lib/test/test_builtin.py::BuiltinTest::test_all_any_tuple_list_set_optimization.
// MiniPython does not expose CPython code-object internals, so this ports the
// public semantic part: these builtin names are resolved dynamically, including
// when the global binding and the builtins module are both overwritten.
#[test]
fn cpython_builtin_generator_dynamic_lookup_subset() {
    assert_output(
        "import builtins\ndef use_all():\n    return all(v > 0 for v in (3, 0, 5))\ndef use_any():\n    return any(v % 4 == 0 for v in (3, 0, 5))\ndef use_tuple():\n    return tuple(v + 1 for v in (3, 0, 5))\ndef use_list():\n    return list(-v for v in (3, 0, 5))\ndef use_set():\n    return set(v // 2 for v in (3, 0, 5))\nusers = [use_all, use_any, use_tuple, use_list, use_set]\nprint([sorted(r) if isinstance(r, set) else r for r in (f() for f in users)])\noriginal = {n: getattr(builtins, n) for n in (\"all\", \"any\", \"tuple\", \"list\", \"set\")}\nscope = globals()\nfor n in original:\n    scope[n] = (lambda tag: lambda gen: \"global \" + tag)(n)\nprint([f() for f in users])\nfor n in original:\n    del scope[n]\nprint([type(f()).__name__ for f in users])\ntry:\n    for n in original:\n        setattr(builtins, n, (lambda tag: lambda gen: \"builtin \" + tag)(n))\n    print([f() for f in users])\nfinally:\n    for n, fn in original.items():\n        setattr(builtins, n, fn)\nprint([type(f()).__name__ for f in users])",
        &["[False, True, (4, 1, 6), [-3, 0, -5], [0, 1, 2]]", "['global all', 'global any', 'global tuple', 'global list', 'global set']", "['bool', 'bool', 'tuple', 'list', 'set']", "['builtin all', 'builtin any', 'builtin tuple', 'builtin list', 'builtin set']", "['bool', 'bool', 'tuple', 'list', 'set']"],
    );
}

// Adapted from CPython Lib/test/test_builtin.py::BuiltinTest::test_hash.
// MiniPython checks CPython's portable hash invariants rather than randomized
// process-specific hash values.
#[test]
fn cpython_hash_builtin_subset() {
    assert_output(
        "print(type(hash(None)).__name__)\nprint(hash(1) == hash(1), hash(1) == hash(1.0), hash(True) == hash(1))\nprint(type(hash('spam')).__name__, hash('spam') == hash(b'spam'))\nprint(type(hash((0, 1, 2, 3))).__name__)\ndef f(): pass\nprint(type(hash(f)).__name__)",
        &["int", "True True True", "int True", "int", "int"],
    );
    assert_output(
        "class X:\n    def __hash__(self):\n        return 2 ** 100\nclass Bad:\n    def __hash__(self):\n        return 1.0\nclass NoHash:\n    __hash__ = None\nprint(type(hash(X())).__name__)\nfor expr in [lambda: hash(), lambda: hash(1, 2), lambda: hash([]), lambda: hash({}), lambda: hash(([1],)), lambda: hash(Bad()), lambda: hash(NoHash())]:\n    try:\n        expr()\n    except TypeError as error:\n        print(error.__class__.__name__)",
        &[
            "int",
            "TypeError",
            "TypeError",
            "TypeError",
            "TypeError",
            "TypeError",
            "TypeError",
            "TypeError",
        ],
    );
    assert_output(
        "class IntHash(int):\n    def __hash__(self):\n        return self\nvalue = IntHash(42)\nprint(hash(value) == 42, type(hash(value)).__name__)",
        &["True int"],
    );
}

// Adapted from CPython Lib/test/test_builtin.py::BuiltinTest::test_id.
// The actual id value is process-specific, so the test checks type and stable
// object identity relationships.
#[test]
fn cpython_id_builtin_subset() {
    assert_output(
        "print(type(id(None)).__name__, type(id(1)).__name__, type(id(1.0)).__name__)\nprint(type(id('spam')).__name__, type(id((0, 1, 2, 3))).__name__)\nitems = [0, 1, 2, 3]\nalias = items\nother = [0, 1, 2, 3]\nprint(id(items) == id(alias), id(items) == id(other))\nd = {'spam': 1, 'eggs': 2, 'ham': 3}\nprint(type(id(d)).__name__, id(d) == id(d))",
        &["int int int", "int int", "True False", "int True"],
    );
    assert_output(
        "for expr in [lambda: id(), lambda: id(1, 2)]:\n    try:\n        expr()\n    except TypeError as error:\n        print(error.__class__.__name__)",
        &["TypeError", "TypeError"],
    );
}

