// Adapted from CPython Lib/test/test_int.py::IntTestCases::test_string_float
// and ::test_error_message. MiniPython's safe Rust string model cannot carry
// lone surrogate code points yet, so the surrogate-only CPython rows remain
// outside this executable slice.
#[test]
fn cpython_int_constructor_error_message_subset() {
    assert_output(
        r#"def check(label, source, base=None):
    try:
        if base is None:
            int(source)
        else:
            int(source, base)
    except ValueError as error:
        base_value = 10 if base is None else base
        expected = "invalid literal for int() with base " + str(base_value) + ": " + repr(source)
        print(label, type(error).__name__, error.args[0] == expected)

check("float-string", "1.2")
check("half", chr(0xbd))
check("prefix-half", "123" + chr(0xbd))
check("spaces", "  123 456  ")
check("nul", "123" + chr(0))
check("nul-base10", "123" + chr(0), 10)
check("nul-space-base20", "123" + chr(0) + " 245", 20)
check("nul-space-base16", "123" + chr(0) + " 245", 16)
check("nul-base20", "123" + chr(0) + "245", 20)
check("nul-base16", "123" + chr(0) + "245", 16)
check("bytes-nul", b"123\x00")
check("bytes-nul-base10", b"123\x00", 10)
check("bytes-nonutf8", b"123\xbd")
check("bytes-nonutf8-base10", b"123\xbd", 10)"#,
        &[
            "float-string ValueError True",
            "half ValueError True",
            "prefix-half ValueError True",
            "spaces ValueError True",
            "nul ValueError True",
            "nul-base10 ValueError True",
            "nul-space-base20 ValueError True",
            "nul-space-base16 ValueError True",
            "nul-base20 ValueError True",
            "nul-base16 ValueError True",
            "bytes-nul ValueError True",
            "bytes-nul-base10 ValueError True",
            "bytes-nonutf8 ValueError True",
            "bytes-nonutf8-base10 ValueError True",
        ],
    );

    assert_output(
        r#"for label, expr in [
    ("many-pos", lambda: int("10", 2, 3)),
    ("pos-base-kw", lambda: int("10", 2, base=10)),
    ("extra-kw", lambda: int("10", base=2, other=3)),
    ("bad-x-kw", lambda: int(x=1.2)),
    ("bad-y-kw", lambda: int("1", y=2)),
]:
    try:
        expr()
    except TypeError as error:
        print(label, str(error))"#,
        &[
            "many-pos int expected at most 2 arguments, got 3",
            "pos-base-kw int() takes at most 2 arguments (3 given)",
            "extra-kw int() takes at most 2 arguments (3 given)",
            "bad-x-kw int() got an unexpected keyword argument 'x'",
            "bad-y-kw int() got an unexpected keyword argument 'y'",
        ],
    );
}

// Adapted from CPython Lib/test/test_int.py::IntStrDigitLimitsTests.
#[test]
fn cpython_int_max_str_digits_runtime_subset() {
    assert_output(
        r#"import sys
old_limit = sys.get_int_max_str_digits()
sys.set_int_max_str_digits(640)
try:
    maxdigits = sys.get_int_max_str_digits()
    int('1' * maxdigits)
    int(' ' + '1' * maxdigits)
    int('1' * maxdigits + ' ')
    int('+' + '1' * maxdigits)
    int('-' + '1' * maxdigits)
    print(len(str(10 ** (maxdigits - 1))))
    for text in ['1' * (maxdigits + 1), ' ' + '1' * (maxdigits + 1), '1' * (maxdigits + 1) + ' ', '+' + '1' * (maxdigits + 1), '-' + '1' * (maxdigits + 1)]:
        try:
            int(text)
        except ValueError as error:
            message = str(error)
            print('int', 'Exceeds the limit' in message, 'conversion' in message)
    too_big = 10 ** maxdigits
    for expr in [lambda: str(too_big), lambda: repr(too_big), lambda: repr([too_big])]:
        try:
            expr()
        except ValueError as error:
            message = str(error)
            print('render', 'Exceeds the limit' in message, 'conversion' in message)
    for base in [2, 4, 8, 16, 32]:
        int('1' * (maxdigits + 1), base)
    print('power-bases')
    int('1_1' * (maxdigits // 2))
    try:
        int('1_1' * (maxdigits // 2) + '_1')
    except ValueError as error:
        message = str(error)
        print('underscore', 'Exceeds the limit' in message, 'conversion' in message)
    for label, expr in [
        ('get-arg', lambda: sys.get_int_max_str_digits(1)),
        ('get-kw', lambda: sys.get_int_max_str_digits(x=1)),
        ('set-noargs', lambda: sys.set_int_max_str_digits()),
        ('set-extra', lambda: sys.set_int_max_str_digits(640, 1)),
        ('set-kw', lambda: sys.set_int_max_str_digits(maxdigits=640)),
        ('set-str', lambda: sys.set_int_max_str_digits('640')),
        ('set-small', lambda: sys.set_int_max_str_digits(1)),
        ('set-neg', lambda: sys.set_int_max_str_digits(-1)),
    ]:
        try:
            result = expr()
            print(label, 'OK', result)
        except Exception as error:
            print(label, error.__class__.__name__, str(error))
finally:
    sys.set_int_max_str_digits(old_limit)"#,
        &[
            "640",
            "int True True",
            "int True True",
            "int True True",
            "int True True",
            "int True True",
            "render True True",
            "render True True",
            "render True True",
            "power-bases",
            "underscore True True",
            "get-arg TypeError sys.get_int_max_str_digits() takes no arguments (1 given)",
            "get-kw TypeError sys.get_int_max_str_digits() takes no keyword arguments",
            "set-noargs TypeError set_int_max_str_digits() missing required argument 'maxdigits' (pos 1)",
            "set-extra TypeError set_int_max_str_digits() takes at most 1 argument (2 given)",
            "set-kw OK None",
            "set-str TypeError 'str' object cannot be interpreted as an integer",
            "set-small ValueError maxdigits must be >= 640 or 0 for unlimited",
            "set-neg ValueError maxdigits must be >= 640 or 0 for unlimited",
        ],
    );
}

