// Adapted from CPython Lib/test/test_builtin.py::BuiltinTest::test_iter /
// ::test_next and selected Lib/test/test_iter.py iterator exhaustion cases.
#[test]
fn cpython_iter_next_builtin_subset() {
    assert_output_with_stack(
        "for value in [('1', '2'), ['1', '2'], '12']:\n    iterator = iter(value)\n    print(next(iterator), next(iterator))\n    try:\n        next(iterator)\n    except StopIteration:\n        print('stopped')\nfor expr in [lambda: iter(), lambda: iter(42, 42)]:\n    try:\n        expr()\n    except TypeError as error:\n        print(error.__class__.__name__)",
        &[
            "1 2",
            "stopped",
            "1 2",
            "stopped",
            "1 2",
            "stopped",
            "TypeError",
            "TypeError",
        ],
        8 * 1024 * 1024,
    );
    assert_output_with_stack(
        "for label, expr in [('missing', lambda: iter()), ('too-many', lambda: iter(1, 2, 3))]:\n    try:\n        expr()\n    except TypeError as error:\n        print(label, error.__class__.__name__, str(error))",
        &[
            "missing TypeError iter expected at least 1 argument, got 0",
            "too-many TypeError iter expected at most 2 arguments, got 3",
        ],
        8 * 1024 * 1024,
    );
    assert_output_with_stack(
        "for label, expr in [('int', lambda: iter(1, 2)), ('none', lambda: iter(None, 2)), ('list', lambda: iter([], 2))]:\n    try:\n        expr()\n    except TypeError as error:\n        print(label, error.__class__.__name__, str(error))",
        &[
            "int TypeError iter(v, w): v must be callable",
            "none TypeError iter(v, w): v must be callable",
            "list TypeError iter(v, w): v must be callable",
        ],
        8 * 1024 * 1024,
    );
    assert_output_with_stack(
        "for label, expr in [('int', lambda: iter(42)), ('none', lambda: iter(None)), ('float', lambda: iter(1.5)), ('object', lambda: iter(object()))]:\n    try:\n        expr()\n    except TypeError as error:\n        print(label, error.__class__.__name__, str(error))",
        &[
            "int TypeError 'int' object is not iterable",
            "none TypeError 'NoneType' object is not iterable",
            "float TypeError 'float' object is not iterable",
            "object TypeError 'object' object is not iterable",
        ],
        8 * 1024 * 1024,
    );
    assert_output_with_stack(
        "for label, expr in [('missing', lambda: next()), ('too-many', lambda: next(iter([]), 1, 2))]:\n    try:\n        expr()\n    except TypeError as error:\n        print(label, error.__class__.__name__, str(error))",
        &[
            "missing TypeError next expected at least 1 argument, got 0",
            "too-many TypeError next expected at most 2 arguments, got 3",
        ],
        8 * 1024 * 1024,
    );
    assert_output_with_stack(
        "for label, expr in [('int', lambda: next(42)), ('list', lambda: next([])), ('none', lambda: next(None)), ('int-default', lambda: next(42, 'x')), ('list-default', lambda: next([], 'x'))]:\n    try:\n        expr()\n    except TypeError as error:\n        print(label, error.__class__.__name__, str(error))",
        &[
            "int TypeError 'int' object is not an iterator",
            "list TypeError 'list' object is not an iterator",
            "none TypeError 'NoneType' object is not an iterator",
            "int-default TypeError 'int' object is not an iterator",
            "list-default TypeError 'list' object is not an iterator",
        ],
        8 * 1024 * 1024,
    );
    assert_output_with_stack(
        "iterator = iter(range(2))\nprint(next(iterator))\nprint(next(iterator))\nfor _ in [0, 1]:\n    try:\n        next(iterator)\n    except StopIteration:\n        print('stopped')\nprint(next(iterator, 42))\nclass Iter:\n    def __iter__(self):\n        return self\n    def __next__(self):\n        raise StopIteration\niterator = iter(Iter())\nprint(next(iterator, 42))\ntry:\n    next(iterator)\nexcept StopIteration:\n    print('stopped')\ndef gen():\n    yield 1\n    return\niterator = gen()\nprint(next(iterator))\ntry:\n    next(iterator)\nexcept StopIteration:\n    print('stopped')\nprint(next(iterator, 42))",
        &[
            "0", "1", "stopped", "stopped", "42", "42", "stopped", "1", "stopped", "42",
        ],
        8 * 1024 * 1024,
    );
    assert_output_with_stack(
        concat!(
            "HAS_MORE = 1\n",
            "NO_MORE = 2\n",
            "def exhaust(iterator):\n",
            "    list(iterator)\n",
            "state = [False, None]\n",
            "def spam():\n",
            "    if state[0]:\n",
            "        return NO_MORE\n",
            "    state[0] = True\n",
            "    exhaust(state[1])\n",
            "    return HAS_MORE\n",
            "state[1] = iter(spam, NO_MORE)\n",
            "try:\n",
            "    next(state[1])\n",
            "except StopIteration:\n",
            "    print('stopped')\n",
            "print(next(state[1], 'done'))\n",
            "counter = [0]\n",
            "def stop_by_exception():\n",
            "    counter[0] += 1\n",
            "    if counter[0] == 3:\n",
            "        raise StopIteration\n",
            "    return counter[0]\n",
            "print(list(iter(stop_by_exception, 99)))",
        ),
        &["stopped", "done", "[1, 2]"],
        8 * 1024 * 1024,
    );
    assert_output_with_stack(
        concat!(
            "def show(label, iterator, mutate=None):\n",
            "    print(label, list(iterator))\n",
            "    if mutate is not None:\n",
            "        mutate()\n",
            "    print(label, list(iterator))\n",
            "items = list(range(5))\n",
            "show('list', iter(items), lambda: items.extend(range(5, 10)))\n",
            "show('tuple', iter((0, 1, 2, 3, 4)))\n",
            "show('string', iter('abcde'))\n",
            "class Sequence:\n",
            "    def __init__(self, n):\n",
            "        self.n = n\n",
            "    def __getitem__(self, index):\n",
            "        if index < self.n:\n",
            "            return index\n",
            "        raise IndexError\n",
            "sequence = Sequence(5)\n",
            "show('sequence', iter(sequence), lambda: setattr(sequence, 'n', 10))\n",
            "state = [0]\n",
            "def spam():\n",
            "    value = state[0]\n",
            "    state[0] = value + 1\n",
            "    if value == 10:\n",
            "        raise AssertionError(\"should not be called after exhaustion\")\n",
            "    return value\n",
            "show('callable', iter(spam, 5))\n",
            "show('range', iter(range(5)))\n",
            "def gen():\n",
            "    for value in range(5):\n",
            "        yield value\n",
            "show('yield', gen())\n",
            "show('enumerate', enumerate(range(5)))",
        ),
        &[
            "list [0, 1, 2, 3, 4]",
            "list []",
            "tuple [0, 1, 2, 3, 4]",
            "tuple []",
            "string ['a', 'b', 'c', 'd', 'e']",
            "string []",
            "sequence [0, 1, 2, 3, 4]",
            "sequence []",
            "callable [0, 1, 2, 3, 4]",
            "callable []",
            "range [0, 1, 2, 3, 4]",
            "range []",
            "yield [0, 1, 2, 3, 4]",
            "yield []",
            "enumerate [(0, 0), (1, 1), (2, 2), (3, 3), (4, 4)]",
            "enumerate []",
        ],
        8 * 1024 * 1024,
    );
    assert_output_with_stack(
        concat!(
            "class MyIndexError(IndexError):\n",
            "    pass\n",
            "class StopSeq:\n",
            "    def __getitem__(self, index):\n",
            "        if index < 2:\n",
            "            return index\n",
            "        raise StopIteration('done')\n",
            "class ValueSeq:\n",
            "    def __getitem__(self, index):\n",
            "        if index < 2:\n",
            "            return index\n",
            "        raise ValueError('bad')\n",
            "class SubIndexSeq:\n",
            "    def __getitem__(self, index):\n",
            "        if index < 2:\n",
            "            return index\n",
            "        raise MyIndexError('done')\n",
            "class ReverseStopSeq:\n",
            "    def __len__(self):\n",
            "        return 3\n",
            "    def __getitem__(self, index):\n",
            "        if index == 2:\n",
            "            return index\n",
            "        raise StopIteration('done')\n",
            "for label, value in [('stop', StopSeq()), ('subindex', SubIndexSeq())]:\n",
            "    print(label, list(iter(value)))\n",
            "try:\n",
            "    list(iter(ValueSeq()))\n",
            "except ValueError as error:\n",
            "    print('value', error)\n",
            "print('reverse-stop', list(reversed(ReverseStopSeq())))",
        ),
        &[
            "stop [0, 1]",
            "subindex [0, 1]",
            "value bad",
            "reverse-stop [2]",
        ],
        8 * 1024 * 1024,
    );
    assert_output_with_stack(
        concat!(
            "import itertools\n",
            "class BlockedIterable:\n",
            "    __iter__ = None\n",
            "    def __getitem__(self, index):\n",
            "        if index < 2:\n",
            "            return index\n",
            "        raise IndexError\n",
            "for label, action in [\n",
            "    ('iter', lambda: iter(BlockedIterable())),\n",
            "    ('list', lambda: list(BlockedIterable())),\n",
            "    ('unpack', lambda: (lambda first, second: (first, second))(*BlockedIterable())),\n",
            "]:\n",
            "    try:\n",
            "        action()\n",
            "    except TypeError as error:\n",
            "        print(label, error)\n",
            "class BadIterReturn:\n",
            "    def __iter__(self):\n",
            "        return 42\n",
            "for label, action in [\n",
            "    ('iter-bad', lambda: iter(BadIterReturn())),\n",
            "    ('list-bad', lambda: list(BadIterReturn())),\n",
            "    ('chain-bad', lambda: list(itertools.chain.from_iterable(BadIterReturn()))),\n",
            "]:\n",
            "    try:\n",
            "        action()\n",
            "    except TypeError as error:\n",
            "        print(label, error)",
        ),
        &[
            "iter 'BlockedIterable' object is not iterable",
            "list 'BlockedIterable' object is not iterable",
            "unpack 'BlockedIterable' object is not iterable",
            "iter-bad iter() returned non-iterator of type 'int'",
            "list-bad iter() returned non-iterator of type 'int'",
            "chain-bad iter() returned non-iterator of type 'int'",
        ],
        8 * 1024 * 1024,
    );
    assert_output_with_stack(
        concat!(
            "class EqSentinel:\n",
            "    def __init__(self, value):\n",
            "        self.value = value\n",
            "    def __eq__(self, other):\n",
            "        print('eq', self.value, getattr(other, 'value', other))\n",
            "        return self.value == getattr(other, 'value', other)\n",
            "values = [EqSentinel(1), EqSentinel(2), EqSentinel(3)]\n",
            "def next_value():\n",
            "    return values.pop(0)\n",
            "print([item.value for item in iter(next_value, EqSentinel(3))])",
        ),
        &["eq 3 1", "eq 3 2", "eq 3 3", "[1, 2]"],
        8 * 1024 * 1024,
    );
    assert_output_with_stack(
        concat!(
            "state = {'n': 0, 'it': None}\n",
            "def producer():\n",
            "    state['n'] += 1\n",
            "    if state['n'] > 4:\n",
            "        raise AssertionError('too far')\n",
            "    return state['n']\n",
            "class ReentrantSentinel:\n",
            "    def __eq__(self, other):\n",
            "        print('eq', other)\n",
            "        if other == 2:\n",
            "            print('inner', list(state['it']))\n",
            "        return other == 3\n",
            "state['it'] = iter(producer, ReentrantSentinel())\n",
            "print('outer', next(state['it']))\n",
            "print('outer', next(state['it']))\n",
            "print('tail', list(state['it']))",
        ),
        &[
            "eq 1", "outer 1", "eq 2", "eq 3", "inner []", "outer 2", "tail []",
        ],
        8 * 1024 * 1024,
    );
}

// Covers the public StopIteration.value attribute used by generator return
// values without expanding into CPython's implementation-internal tests.
#[test]
fn cpython_stop_iteration_value_subset() {
    assert_output_with_stack(
        "def g(value):\n    if False:\n        yield None\n    return value\n\nfor args in [(), (42,), (1, 2)]:\n    error = StopIteration(*args)\n    print('ctor', args, error.args, error.value)\nfor value in [None, 99, (1, 2)]:\n    gen = g(value)\n    try:\n        next(gen)\n    except StopIteration as error:\n        print('gen', value, error.args, error.value)\nclass MyStop(StopIteration):\n    pass\ncustom = MyStop('x', 'y')\nprint('sub', custom.args, custom.value)",
        &[
            "ctor () () None",
            "ctor (42,) (42,) 42",
            "ctor (1, 2) (1, 2) 1",
            "gen None () None",
            "gen 99 (99,) 99",
            "gen (1, 2) ((1, 2),) (1, 2)",
            "sub ('x', 'y') x",
        ],
        8 * 1024 * 1024,
    );
}

// Adapted from CPython Lib/test/test_enumerate.py::EnumerateTestCase and
// Lib/test/test_builtin.py::BuiltinTest::test_zip / ::test_sorted.
#[test]
fn cpython_enumerate_zip_sorted_builtin_subset() {
    assert_output(
        "class G:\n    def __init__(self, seqn):\n        self.seqn = seqn\n    def __getitem__(self, index):\n        return self.seqn[index]\nclass I:\n    def __init__(self, seqn):\n        self.seqn = seqn\n        self.index = 0\n    def __iter__(self):\n        return self\n    def __next__(self):\n        if self.index >= len(self.seqn):\n            raise StopIteration\n        value = self.seqn[self.index]\n        self.index += 1\n        return value\nclass Ig:\n    def __init__(self, seqn):\n        self.seqn = seqn\n    def __iter__(self):\n        for value in self.seqn:\n            yield value\nseq = 'abc'\ne = enumerate(seq)\nprint(iter(e) is e)\nprint(list(enumerate(seq)))\nprint(list(enumerate(G(seq))))\nprint(list(enumerate(I(seq))))\nprint(list(enumerate(Ig(seq))))\nfor empty in [G(''), I(''), Ig('')]:\n    try:\n        next(enumerate(empty))\n    except StopIteration:\n        print('stopped')\nprint(list(enumerate(iterable=Ig(seq))))\nprint(list(enumerate(iterable=Ig(seq), start=0)))\nprint(list(enumerate(start=0, iterable=Ig(seq))))",
        &[
            "True",
            "[(0, 'a'), (1, 'b'), (2, 'c')]",
            "[(0, 'a'), (1, 'b'), (2, 'c')]",
            "[(0, 'a'), (1, 'b'), (2, 'c')]",
            "[(0, 'a'), (1, 'b'), (2, 'c')]",
            "stopped",
            "stopped",
            "stopped",
            "[(0, 'a'), (1, 'b'), (2, 'c')]",
            "[(0, 'a'), (1, 'b'), (2, 'c')]",
            "[(0, 'a'), (1, 'b'), (2, 'c')]",
        ],
    );
    assert_output(
        "class X:\n    def __init__(self, seqn):\n        self.seqn = seqn\n        self.index = 0\n    def __next__(self):\n        if self.index >= len(self.seqn):\n            raise StopIteration\n        value = self.seqn[self.index]\n        self.index += 1\n        return value\nclass N:\n    def __init__(self, seqn):\n        self.seqn = seqn\n    def __iter__(self):\n        return self\nclass E:\n    def __init__(self, seqn):\n        self.seqn = seqn\n    def __iter__(self):\n        return self\n    def __next__(self):\n        3 // 0\nfor expr in [lambda: enumerate(), lambda: enumerate(1), lambda: enumerate('abc', 'a'), lambda: enumerate('abc', 2, 3), lambda: enumerate(iterable=[], x=3), lambda: enumerate(start=0, x=3), lambda: enumerate(x=0, y=3), lambda: enumerate(x=0), lambda: enumerate(X('abc')), lambda: enumerate(N('abc'))]:\n    try:\n        expr()\n    except TypeError as error:\n        print(error.__class__.__name__)\ntry:\n    list(enumerate(E('abc')))\nexcept ZeroDivisionError as error:\n    print(error.__class__.__name__)",
        &[
            "TypeError",
            "TypeError",
            "TypeError",
            "TypeError",
            "TypeError",
            "TypeError",
            "TypeError",
            "TypeError",
            "TypeError",
            "TypeError",
            "ZeroDivisionError",
        ],
    );
    assert_output(
        "for label, expr in [\n    ('missing', lambda: enumerate()),\n    ('pos-start-bad', lambda: enumerate(['a'], start=2, bad=3)),\n    ('pos2-bad', lambda: enumerate(['a'], 2, bad=3)),\n    ('pos3', lambda: enumerate('abc', 2, 3)),\n    ('dup-iterable', lambda: enumerate([], iterable=[])),\n    ('dup-start', lambda: enumerate([], 0, start=1)),\n]:\n    try:\n        expr()\n    except TypeError as error:\n        print(label, error.__class__.__name__, str(error))",
        &[
            "missing TypeError enumerate() missing required argument 'iterable'",
            "pos-start-bad TypeError enumerate() takes at most 2 arguments (3 given)",
            "pos2-bad TypeError enumerate() takes at most 2 arguments (3 given)",
            "pos3 TypeError enumerate() takes at most 2 arguments (3 given)",
            "dup-iterable TypeError 'iterable' is an invalid keyword argument for enumerate()",
            "dup-start TypeError enumerate() takes at most 2 arguments (3 given)",
        ],
    );
    assert_output(
        "a = (1, 2, 3)\nb = (4, 5, 6)\nprint(list(zip(a, b)))\nprint(list(zip(a, [4, 5, 6])))\nprint(list(zip(a, (4, 5, 6, 7))))\nclass I:\n    def __getitem__(self, index):\n        if index < 0 or index > 2:\n            raise IndexError\n        return index + 4\nprint(list(zip(a, I())))\nprint(list(zip()), list(zip(*[])))\nprint(list(zip(range(5), range(10))))\nprint(sorted([3, 1, 2]))\nprint(sorted([1, 2, 3], key=lambda x: -x))\nprint(sorted([3, 1, 2], reverse=True))\nclass G:\n    pass\nfor expr in [lambda: zip(None), lambda: zip(a, G()), lambda: sorted(), lambda: sorted([], bad=True)]:\n    try:\n        expr()\n    except TypeError as error:\n        print(error.__class__.__name__)",
        &[
            "[(1, 4), (2, 5), (3, 6)]",
            "[(1, 4), (2, 5), (3, 6)]",
            "[(1, 4), (2, 5), (3, 6)]",
            "[(1, 4), (2, 5), (3, 6)]",
            "[] []",
            "[(0, 0), (1, 1), (2, 2), (3, 3), (4, 4)]",
            "[1, 2, 3]",
            "[3, 2, 1]",
            "[3, 2, 1]",
            "TypeError",
            "TypeError",
            "TypeError",
            "TypeError",
        ],
    );
}

// Adapted from CPython public enumerate __class_getitem__ behavior. This pins
// GenericAlias origin/args, direct type calls, and exact enumerate instance
// lookup without promoting enumerate subclassing in MiniPython's class model.
#[test]
fn cpython_enumerate_class_getitem_generic_alias_subset() {
    assert_output(
        r#"typ = enumerate
inst = enumerate(['a', 'b'])
for label, expr in [
    ('visible', lambda: (hasattr(typ, '__class_getitem__'), '__class_getitem__' in dir(typ), type(typ.__class_getitem__).__name__, hasattr(inst, '__class_getitem__'), '__class_getitem__' in dir(inst))),
    ('subscript-int', lambda: (type(typ[int]).__name__, str(typ[int]), typ[int].__origin__ is typ, typ[int].__args__)),
    ('call-int', lambda: (type(typ.__class_getitem__(int)).__name__, str(typ.__class_getitem__(int)), typ.__class_getitem__(int) == typ[int], typ.__class_getitem__(int).__origin__ is typ, typ.__class_getitem__(int).__args__)),
    ('call-pair', lambda: (str(typ.__class_getitem__((int, str))), typ.__class_getitem__((int, str)) == typ[int, str], typ.__class_getitem__((int, str)).__args__)),
    ('inst-exact', lambda: (inst.__class_getitem__(int) == typ[int], inst.__class_getitem__(int).__origin__ is typ)),
    ('call-noargs', lambda: typ.__class_getitem__()),
    ('call-extra', lambda: typ.__class_getitem__(int, str)),
    ('call-keyword', lambda: typ.__class_getitem__(item=int)),
]:
    try:
        result = expr()
        print(label, type(result).__name__, result)
    except Exception as error:
        print(label, type(error).__name__, str(error), error.args)"#,
        &[
            "visible tuple (True, True, 'builtin_function_or_method', True, True)",
            "subscript-int tuple ('GenericAlias', 'enumerate[int]', True, (<class 'int'>,))",
            "call-int tuple ('GenericAlias', 'enumerate[int]', True, True, (<class 'int'>,))",
            "call-pair tuple ('enumerate[int, str]', True, (<class 'int'>, <class 'str'>))",
            "inst-exact tuple (True, True)",
            "call-noargs TypeError enumerate.__class_getitem__() takes exactly one argument (0 given) ('enumerate.__class_getitem__() takes exactly one argument (0 given)',)",
            "call-extra TypeError enumerate.__class_getitem__() takes exactly one argument (2 given) ('enumerate.__class_getitem__() takes exactly one argument (2 given)',)",
            "call-keyword TypeError enumerate.__class_getitem__() takes no keyword arguments ('enumerate.__class_getitem__() takes no keyword arguments',)",
        ],
    );
}

// Mirrors CPython's public enumerate type-metadata surface. The metadata is
// directly readable on the type, but CPython does not list it in dir(enumerate)
// or dir(enumerate(...)); enumerate __class_getitem__ remains visible.
#[test]
fn cpython_enumerate_type_metadata_dir_surface_subset() {
    assert_output(
        "typ = enumerate\ninst = enumerate(['a'])\nprint('visible-type', '__base__' in dir(typ), '__bases__' in dir(typ), '__name__' in dir(typ), '__module__' in dir(typ), '__qualname__' in dir(typ), '__class_getitem__' in dir(typ))\nprint('visible-inst', '__base__' in dir(inst), '__bases__' in dir(inst), '__name__' in dir(inst), '__class_getitem__' in dir(inst))\nprint('readable-base', typ.__base__ is object, typ.__bases__ == (object,), typ.__name__, object.__getattribute__(typ, '__name__'))\nprint('readable-module', typ.__module__, typ.__qualname__, object.__getattribute__(typ, '__module__'), object.__getattribute__(typ, '__qualname__'))\nprint('method-kept', hasattr(typ, '__class_getitem__'), '__class_getitem__' in dir(typ), hasattr(inst, '__class_getitem__'), '__class_getitem__' in dir(inst))",
        &[
            "visible-type False False False False False True",
            "visible-inst False False False True",
            "readable-base True True enumerate enumerate",
            "readable-module builtins enumerate builtins enumerate",
            "method-kept True True True True",
        ],
    );
}

#[test]
fn cpython_enumerate_reduce_type_dict_subset() {
    assert_output(
        r#"for start in [0, 5]:
    e = enumerate(['a', 'b'], start)
    reduced = e.__reduce__()
    print('fresh', start, reduced[0] is enumerate, type(reduced[1][0]).__name__, reduced[1][1])
    next(e)
    reduced = type(e).__reduce__(e)
    print('after1', start, reduced[0] is enumerate, type(reduced[1][0]).__name__, reduced[1][1])
namespace = enumerate.__dict__
print('dir-reduce', '__reduce__' in dir(enumerate), '__reduce__' in dir(enumerate(['x'])))
print('dict-type', type(namespace).__name__, '__iter__' in namespace, '__next__' in namespace, '__reduce__' in namespace, '__class_getitem__' in namespace, '__setstate__' in namespace, '__doc__' in namespace)
e = enumerate(['x'], 3)
print('dict-call', namespace['__iter__'](e) is e, namespace['__reduce__'](e)[0] is enumerate, namespace['__reduce__'](e)[1][1])"#,
        &[
            "fresh 0 True list_iterator 0",
            "after1 0 True list_iterator 1",
            "fresh 5 True list_iterator 5",
            "after1 5 True list_iterator 6",
            "dir-reduce True True",
            "dict-type mappingproxy True True True True False True",
            "dict-call True True 3",
        ],
    );
}

// Mirrors CPython's public zip type-metadata surface. The metadata is directly
// readable on the type, but CPython does not list it in dir(zip) or
// dir(zip(...)); zip iterator dir() method visibility remains a separate slice.
#[test]
fn cpython_zip_type_metadata_dir_surface_subset() {
    assert_output(
        "typ = zip\ninst = zip([1], [2])\nprint('visible-type', '__base__' in dir(typ), '__bases__' in dir(typ), '__name__' in dir(typ), '__module__' in dir(typ), '__qualname__' in dir(typ))\nprint('visible-inst', '__base__' in dir(inst), '__bases__' in dir(inst), '__name__' in dir(inst))\nprint('readable-base', typ.__base__ is object, typ.__bases__ == (object,), typ.__name__, object.__getattribute__(typ, '__name__'))\nprint('readable-module', typ.__module__, typ.__qualname__, object.__getattribute__(typ, '__module__'), object.__getattribute__(typ, '__qualname__'))\nprint('iter-kept', iter(inst) is inst, next(zip([1], [2])), list(zip([1], [2], strict=True)))",
        &[
            "visible-type False False False False False",
            "visible-inst False False False",
            "readable-base True True zip zip",
            "readable-module builtins zip builtins zip",
            "iter-kept True (1, 2) [(1, 2)]",
        ],
    );
}

#[test]
fn cpython_zip_reduce_setstate_type_dict_subset() {
    assert_output(
        r#"z = zip([1, 2], [10])
namespace = zip.__dict__
print('dict-type', type(namespace).__name__, '__iter__' in namespace, '__next__' in namespace, '__reduce__' in namespace, '__setstate__' in namespace, '__doc__' in namespace)
r = z.__reduce__()
print('fresh', r[0] is zip, len(r), len(r[1]), [type(value).__name__ for value in r[1]])
print('set-true', zip.__setstate__(z, True), next(z))
try:
    next(z)
except Exception as error:
    print('strict-error', type(error).__name__, str(error))
z = zip([1, 2], [10], strict=True)
r = z.__reduce__()
print('strict-fresh', r[0] is zip, len(r), len(r[1]), r[2])
print('set-false', z.__setstate__(False), next(z))
try:
    next(z)
except Exception as error:
    print('loose-stop', type(error).__name__, str(error) == '')
r = namespace['__reduce__'](zip([1], [2]))
print('dict-call', namespace['__iter__'](z) is z, r[0] is zip, len(r), len(r[1]))
print('dir-methods', '__reduce__' in dir(zip), '__setstate__' in dir(zip), '__reduce__' in dir(zip([], [])), '__setstate__' in dir(zip([], [])))"#,
        &[
            "dict-type mappingproxy True True True True True",
            "fresh True 2 2 ['list_iterator', 'list_iterator']",
            "set-true None (1, 10)",
            "strict-error ValueError zip() argument 2 is shorter than argument 1",
            "strict-fresh True 3 2 True",
            "set-false None (1, 10)",
            "loose-stop StopIteration True",
            "dict-call True True 2 2",
            "dir-methods True True True True",
        ],
    );
}

// Mirrors CPython's public map type-metadata surface. The metadata is directly
