#[test]
fn cpython_str_ascii_iterator_setstate_subset() {
    assert_output(
        r#"def show(label, callback):
    try:
        print(label, callback())
    except Exception as error:
        print(label, type(error).__name__, str(error))

class Index:
    def __index__(self):
        print('index-called')
        return 1

class IntSub(int):
    pass

source = 'abc'
inst = iter(source)
typ = type(inst)
print('visible-setstate', '__setstate__' in dir(typ), '__setstate__' in dir(inst), hasattr(typ, '__setstate__'), hasattr(inst, '__setstate__'))
for state in [-1, 0, 1, 2, 3, 99, True, False, IntSub(2)]:
    probe = iter(source)
    result = probe.__setstate__(state)
    try:
        value = next(probe)
    except StopIteration:
        value = 'StopIteration'
    print('setstate-next', repr(state), result, value)
for bad in [None, 1.5, '1', [], Index()]:
    probe = iter(source)
    show('bad-setstate-' + type(bad).__name__, lambda probe=probe, bad=bad: probe.__setstate__(bad))
for state in [10**200, -(10**200)]:
    probe = iter(source)
    show('big-setstate-' + ('neg' if state < 0 else 'pos'), lambda probe=probe, state=state: probe.__setstate__(state))
show('missing', lambda: iter(source).__setstate__())
show('extra', lambda: iter(source).__setstate__(0, 1))
shifted = iter(source)
print('unbound-setstate', typ.__setstate__(shifted, 2))
print('unbound-next', next(shifted))
unicode_iter = iter('aé')
show('unbound-unicode', lambda: typ.__setstate__(unicode_iter, 1))
print('unicode-next', next(unicode_iter))
show('unbound-bad', lambda: typ.__setstate__(object(), 0))"#,
        &[
            "visible-setstate True True True True",
            "setstate-next -1 None a",
            "setstate-next 0 None a",
            "setstate-next 1 None b",
            "setstate-next 2 None c",
            "setstate-next 3 None StopIteration",
            "setstate-next 99 None StopIteration",
            "setstate-next True None b",
            "setstate-next False None a",
            "setstate-next 2 None c",
            "bad-setstate-NoneType TypeError an integer is required",
            "bad-setstate-float TypeError an integer is required",
            "bad-setstate-str TypeError an integer is required",
            "bad-setstate-list TypeError an integer is required",
            "bad-setstate-Index TypeError an integer is required",
            "big-setstate-pos OverflowError Python int too large to convert to C ssize_t",
            "big-setstate-neg OverflowError Python int too large to convert to C ssize_t",
            "missing TypeError str_ascii_iterator.__setstate__() takes exactly one argument (0 given)",
            "extra TypeError str_ascii_iterator.__setstate__() takes exactly one argument (2 given)",
            "unbound-setstate None",
            "unbound-next c",
            "unbound-unicode TypeError descriptor '__setstate__' for 'str_ascii_iterator' objects doesn't apply to a 'str_iterator' object",
            "unicode-next a",
            "unbound-bad TypeError descriptor '__setstate__' for 'str_ascii_iterator' objects doesn't apply to a 'object' object",
        ],
    );
}

