#[test]
fn cpython_itertools_product_subset() {
    assert_output(
        concat!(
            "import itertools\n",
            "p = itertools.product('AB', [1, 2])\n",
            "print(type(p).__name__, iter(p) is p, list(p), list(p))\n",
            "print(list(itertools.product()))\n",
            "print(list(itertools.product('AB')))\n",
            "print(list(itertools.product('AB', repeat=2)))\n",
            "print(list(itertools.product('AB', repeat=0)))\n",
            "print(list(itertools.product('AB', [])))\n",
            "it = itertools.product((value for value in [1, 2]), 'ab')\n",
            "print(next(it), list(it))\n",
            "class IndexLike:\n",
            "    def __index__(self):\n",
            "        return 2\n",
            "print(list(itertools.product([1, 2], repeat=IndexLike())))\n",
            "class HugeIndex:\n",
            "    def __index__(self):\n",
            "        return 10**100\n",
            "try:\n",
            "    itertools.product([1], repeat=HugeIndex())\n",
            "except OverflowError as error:\n",
            "    print(error.__class__.__name__, str(error))\n",
            "for expr in [\n",
            "    lambda: itertools.product([1], repeat=-1),\n",
            "    lambda: itertools.product([1], repeat='x'),\n",
            "    lambda: itertools.product([1], unknown=1),\n",
            "    lambda: itertools.product(1),\n",
            "]:\n",
            "    try:\n",
            "        expr()\n",
            "    except (TypeError, ValueError) as error:\n",
            "        print(error.__class__.__name__)",
        ),
        &[
            "product True [('A', 1), ('A', 2), ('B', 1), ('B', 2)] []",
            "[()]",
            "[('A',), ('B',)]",
            "[('A', 'A'), ('A', 'B'), ('B', 'A'), ('B', 'B')]",
            "[()]",
            "[]",
            "(1, 'a') [(1, 'b'), (2, 'a'), (2, 'b')]",
            "[(1, 1), (1, 2), (2, 1), (2, 2)]",
            "OverflowError Python int too large to convert to C ssize_t",
            "ValueError",
            "TypeError",
            "TypeError",
            "TypeError",
        ],
    );
}

#[test]
fn cpython_itertools_combinations_subset() {
    assert_output(
        "import itertools as it\nimport math\ntrios = it.combinations(\"wxyz\", 3)\nprint(type(trios).__name__, iter(trios) is trios, [\"\".join(p) for p in trios], list(trios))\nprint(list(it.combinations(range(4), 0)), list(it.combinations((7, 8), 2)), list(it.combinations(\"pq\", 5)), list(it.combinations([], 0)), list(it.combinations((), 2)))\nlazy = it.combinations((n * n for n in range(1, 5)), 3)\nprint(next(lazy), list(lazy))\nclass Two:\n    def __index__(self):\n        return 2\nprint(len(list(it.combinations(range(6), Two()))), list(it.combinations(r=1, iterable=\"uv\")))\nprint(all(len(list(it.combinations(range(n), r))) == math.comb(n, r) for n in range(7) for r in range(8)))\nclass Enormous:\n    def __index__(self):\n        return 1 << 200\ntry:\n    it.combinations(\"abc\", Enormous())\nexcept OverflowError as exc:\n    print(type(exc).__name__, exc)\nfor label, fn in ((\"no r\", lambda: it.combinations(\"abc\")), (\"extra\", lambda: it.combinations(\"abc\", 1, 1)), (\"str r\", lambda: it.combinations(\"abc\", \"1\")),\n                  (\"negative\", lambda: it.combinations(\"abc\", -2)), (\"not iterable\", lambda: it.combinations(3.5, 1)), (\"float r\", lambda: it.combinations(\"ab\", 1.0))):\n    try:\n        fn()\n    except (TypeError, ValueError) as exc:\n        print(label, type(exc).__name__)",
        &["combinations True ['wxy', 'wxz', 'wyz', 'xyz'] []", "[()] [(7, 8)] [] [()] []", "(1, 4, 9) [(1, 4, 16), (1, 9, 16), (4, 9, 16)]", "15 [('u',), ('v',)]", "True", "OverflowError Python int too large to convert to C ssize_t", "no r TypeError", "extra TypeError", "str r TypeError", "negative ValueError", "not iterable TypeError", "float r TypeError"],
    );
}

