// Adapted from CPython public tuple-subclass behavior used by sequence and
// class-creation tests. This pins the supported immutable sequence protocol
// without depending on CPython's object layout.
#[test]
fn cpython_tuple_subclass_core_sequence_subset() {
    assert_output(
        concat!(
            "class TupleSubclass(tuple):\n",
            "    pass\n",
            "items = TupleSubclass([1, 2])\n",
            "print('type', type(items).__name__, isinstance(items, tuple), items.__class__ is TupleSubclass)\n",
            "print('state', bool(items), len(items), list(items), repr(items), str(items), f'{items!r}', f'{items!s}')\n",
            "print('index-slice', items[0], items[:], list(reversed(items)))\n",
            "empty = TupleSubclass()\n",
            "print('empty', bool(empty), len(empty), list(empty), repr(empty), list(reversed(empty)))\n",
            "for expr in [lambda: TupleSubclass(sequence=[]), lambda: TupleSubclass(1, 2), lambda: TupleSubclass(42)]:\n",
            "    try:\n",
            "        expr()\n",
            "    except TypeError as error:\n",
            "        print('error', error.__class__.__name__)",
        ),
        &[
            "type TupleSubclass True True",
            "state True 2 [1, 2] (1, 2) (1, 2) (1, 2) (1, 2)",
            "index-slice 1 (1, 2) [2, 1]",
            "empty False 0 [] () []",
            "error TypeError",
            "error TypeError",
            "error TypeError",
        ],
    );
}

// Adapted from CPython public tuple-subclass binary addition behavior. This
// pins tuple-subclass operands and inherited direct tuple.__add__ without
// adding a reflected __radd__ surface.
#[test]
fn cpython_tuple_subclass_add_subset() {
    assert_output(
        concat!(
            "class T(tuple):\n",
            "    pass\n",
            "left = T((1, 2))\n",
            "right = T((3, 4))\n",
            "for label, expr in [\n",
            "    ('sub-plus-tuple', lambda: left + (9,)),\n",
            "    ('tuple-plus-sub', lambda: (0,) + left),\n",
            "    ('sub-plus-sub', lambda: left + right),\n",
            "    ('direct-add', lambda: left.__add__((5,))),\n",
            "    ('type-direct-add', lambda: tuple.__add__(left, (8,))),\n",
            "    ('direct-radd', lambda: left.__radd__((6,))),\n",
            "    ('bad-list', lambda: left + [7]),\n",
            "    ('direct-bad-list', lambda: left.__add__([7])),\n",
            "    ('type-direct-bad-list', lambda: tuple.__add__(left, [8])),\n",
            "]:\n",
            "    try:\n",
            "        result = expr()\n",
            "        print(label, type(result).__name__, isinstance(result, T), result, left)\n",
            "    except Exception as error:\n",
            "        print(label, type(error).__name__, str(error), left)\n",
            "print('visible', hasattr(left, '__add__'), hasattr(left, '__radd__'), '__add__' in dir(left), '__radd__' in dir(T))",
        ),
        &[
            "sub-plus-tuple tuple False (1, 2, 9) (1, 2)",
            "tuple-plus-sub tuple False (0, 1, 2) (1, 2)",
            "sub-plus-sub tuple False (1, 2, 3, 4) (1, 2)",
            "direct-add tuple False (1, 2, 5) (1, 2)",
            "type-direct-add tuple False (1, 2, 8) (1, 2)",
            "direct-radd AttributeError 'T' object has no attribute '__radd__' (1, 2)",
            "bad-list TypeError can only concatenate tuple (not \"list\") to tuple (1, 2)",
            "direct-bad-list TypeError can only concatenate tuple (not \"list\") to tuple (1, 2)",
            "type-direct-bad-list TypeError can only concatenate tuple (not \"list\") to tuple (1, 2)",
            "visible True False True False",
        ],
    );
}

// Adapted from CPython public tuple-subclass repeat behavior. This pins
// tuple-subclass repeat operators and direct tuple repeat methods without
// adding an __imul__ surface.
#[test]
fn cpython_tuple_subclass_repeat_subset() {
    assert_output(
        concat!(
            "class T(tuple):\n",
            "    pass\n",
            "class I(int):\n",
            "    pass\n",
            "left = T((1, 2))\n",
            "value = left\n",
            "value *= 2\n",
            "print('inplace', type(value).__name__, isinstance(value, T), value, left)\n",
            "for label, expr in [\n",
            "    ('sub-mul-int', lambda: left * 2),\n",
            "    ('int-mul-sub', lambda: 2 * left),\n",
            "    ('sub-mul-bool', lambda: left * True),\n",
            "    ('sub-mul-subint', lambda: left * I(2)),\n",
            "    ('sub-mul-zero', lambda: left * 0),\n",
            "    ('sub-mul-neg', lambda: left * -1),\n",
            "    ('direct-mul', lambda: left.__mul__(2)),\n",
            "    ('direct-mul-subint', lambda: left.__mul__(I(2))),\n",
            "    ('direct-rmul', lambda: left.__rmul__(2)),\n",
            "    ('direct-rmul-subint', lambda: left.__rmul__(I(2))),\n",
            "    ('type-direct-mul', lambda: tuple.__mul__(left, 2)),\n",
            "    ('type-direct-rmul', lambda: tuple.__rmul__(left, 2)),\n",
            "    ('bad-float', lambda: left * 1.5),\n",
            "    ('direct-bad-float', lambda: left.__mul__(1.5)),\n",
            "    ('type-direct-bad-float', lambda: tuple.__mul__(left, 1.5)),\n",
            "]:\n",
            "    try:\n",
            "        result = expr()\n",
            "        print(label, type(result).__name__, isinstance(result, T), result, left)\n",
            "    except Exception as error:\n",
            "        print(label, type(error).__name__, str(error), left)\n",
            "print('visible', hasattr(left, '__mul__'), hasattr(left, '__rmul__'), hasattr(left, '__imul__'), '__mul__' in dir(left), '__rmul__' in dir(T), '__imul__' in dir(left))",
        ),
        &[
            "inplace tuple False (1, 2, 1, 2) (1, 2)",
            "sub-mul-int tuple False (1, 2, 1, 2) (1, 2)",
            "int-mul-sub tuple False (1, 2, 1, 2) (1, 2)",
            "sub-mul-bool tuple False (1, 2) (1, 2)",
            "sub-mul-subint tuple False (1, 2, 1, 2) (1, 2)",
            "sub-mul-zero tuple False () (1, 2)",
            "sub-mul-neg tuple False () (1, 2)",
            "direct-mul tuple False (1, 2, 1, 2) (1, 2)",
            "direct-mul-subint tuple False (1, 2, 1, 2) (1, 2)",
            "direct-rmul tuple False (1, 2, 1, 2) (1, 2)",
            "direct-rmul-subint tuple False (1, 2, 1, 2) (1, 2)",
            "type-direct-mul tuple False (1, 2, 1, 2) (1, 2)",
            "type-direct-rmul tuple False (1, 2, 1, 2) (1, 2)",
            "bad-float TypeError can't multiply sequence by non-int of type 'float' (1, 2)",
            "direct-bad-float TypeError 'float' object cannot be interpreted as an integer (1, 2)",
            "type-direct-bad-float TypeError 'float' object cannot be interpreted as an integer (1, 2)",
            "visible True True False True True False",
        ],
    );
}

