// Adapted from CPython Lib/test/test_operator.py::OperatorTestCase sequence
// helper tests for concat, countOf, indexOf, contains, getitem, setitem, and
// delitem. The iterator indexOf case preserves the public partial-consumption
// behavior instead of materializing the whole iterator.
#[test]
fn cpython_operator_sequence_member_subset() {
    assert_output(
        concat!(
            "import operator\n",
            "class Seq:\n",
            "    def __init__(self, lst):\n",
            "        self.lst = lst\n",
            "    def __len__(self):\n",
            "        return len(self.lst)\n",
            "    def __getitem__(self, i):\n",
            "        return self.lst[i]\n",
            "    def __add__(self, other):\n",
            "        return self.lst + other.lst\n",
            "class BadIterable:\n",
            "    def __iter__(self):\n",
            "        raise ZeroDivisionError\n",
            "class BlockContainsIter:\n",
            "    __contains__ = None\n",
            "    def __iter__(self):\n",
            "        return iter([1, 2])\n",
            "class BlockContainsGetitem:\n",
            "    __contains__ = None\n",
            "    def __getitem__(self, index):\n",
            "        if index < 2:\n",
            "            return index + 1\n",
            "        raise IndexError\n",
            "class BlockContainsOnly:\n",
            "    __contains__ = None\n",
            "print(operator.concat('py', 'thon'))\n",
            "print(operator.concat([1, 2], [3, 4]))\n",
            "print(operator.concat(Seq([5, 6]), Seq([7])))\n",
            "print(operator.countOf([1, 2, 1, 3, 1, 4], 3), operator.countOf([1, 2, 1, 3, 1, 4], 5))\n",
            "nan = float('nan')\n",
            "print(operator.countOf([nan, nan, 21], nan), operator.countOf([{}, 1, {}, 2], {}))\n",
            "print(operator.indexOf([4, 3, 2, 1], 3))\n",
            "try:\n",
            "    operator.indexOf([4, 3, 2, 1], 0)\n",
            "except ValueError as error:\n",
            "    print(type(error).__name__)\n",
            "print(operator.indexOf([nan, nan, 21], nan), operator.indexOf([{}, 1, {}, 2], {}))\n",
            "it = iter('leave the iterator at exactly the position after the match')\n",
            "print(operator.indexOf(it, 'a'), next(it))\n",
            "print(operator.contains(range(4), 2), operator.contains(range(4), 5))\n",
            "for label, source in [('iter', BlockContainsIter()), ('getitem', BlockContainsGetitem()), ('only', BlockContainsOnly())]:\n",
            "    try:\n",
            "        operator.contains(source, 1)\n",
            "    except TypeError as error:\n",
            "        print(label, error)\n",
            "a = list(range(4))\n",
            "print(operator.getitem(a, 2))\n",
            "print(operator.setitem(a, 0, 9), a)\n",
            "print(operator.delitem(a, 1), a)\n",
            "for expr in [lambda: operator.concat(), lambda: operator.concat(None, None), lambda: operator.countOf(), lambda: operator.getitem(), lambda: operator.getitem(a, None), lambda: operator.setitem(a), lambda: operator.delitem(a)]:\n",
            "    try:\n",
            "        expr()\n",
            "    except TypeError as error:\n",
            "        print(type(error).__name__)\n",
            "for label, expr in [('getitem-noargs', lambda: operator.getitem()), ('getitem-one', lambda: operator.getitem(a)), ('setitem-two', lambda: operator.setitem(a, 0)), ('delitem-noargs', lambda: operator.delitem())]:\n",
            "    try:\n",
            "        expr()\n",
            "    except TypeError as error:\n",
            "        print(label, type(error).__name__, str(error))\n",
            "for expr in [lambda: operator.countOf(BadIterable(), 1), lambda: operator.indexOf(BadIterable(), 1)]:\n",
            "    try:\n",
            "        expr()\n",
            "    except ZeroDivisionError as error:\n",
            "        print(type(error).__name__)\n",
        ),
        &[
            "python",
            "[1, 2, 3, 4]",
            "[5, 6, 7]",
            "1 0",
            "2 2",
            "1",
            "ValueError",
            "0 0",
            "2 v",
            "True False",
            "iter 'BlockContainsIter' object is not a container",
            "getitem 'BlockContainsGetitem' object is not a container",
            "only 'BlockContainsOnly' object is not a container",
            "2",
            "None [9, 1, 2, 3]",
            "None [9, 2, 3]",
            "TypeError",
            "TypeError",
            "TypeError",
            "TypeError",
            "TypeError",
            "TypeError",
            "TypeError",
            "getitem-noargs TypeError getitem expected 2 arguments, got 0",
            "getitem-one TypeError getitem expected 2 arguments, got 1",
            "setitem-two TypeError setitem expected 3 arguments, got 2",
            "delitem-noargs TypeError delitem expected 2 arguments, got 0",
            "ZeroDivisionError",
            "ZeroDivisionError",
        ],
    );
}

// Adapted from CPython _operator sequence concatenation builtin metadata.
#[test]
fn cpython_operator_sequence_concat_builtin_metadata_subset() {
    assert_output(
        concat!(
            "_doc = lambda value: '<doc>' if isinstance(value, str) and value else value\n",
            "import operator\n",
            "for name in ['concat', 'iconcat']:\n",
            "    value = getattr(operator, name)\n",
            "    doc = _doc(value.__doc__).splitlines()[0] if _doc(value.__doc__) else None\n",
            "    print(name, value.__module__, value.__name__, value.__qualname__, doc, getattr(value, '__text_signature__', None))\n",
            "for alias in ['__concat__', '__iconcat__']:\n",
            "    value = getattr(operator, alias)\n",
            "    public = getattr(operator, alias.strip('_'))\n",
            "    print(alias, _doc(value.__doc__).splitlines()[0], value.__text_signature__, value is public)\n",
            "\n",
        ),
        &[
            "concat _operator concat concat <doc> ($module, a, b, /)",
            "iconcat _operator iconcat iconcat <doc> ($module, a, b, /)",
            "__concat__ <doc> ($module, a, b, /) True",
            "__iconcat__ <doc> ($module, a, b, /) True",
        ],
    );
}

