// Adapted from CPython operator helper type classinfo behavior.
#[test]
fn cpython_operator_helper_type_classinfo_metadata_subset() {
    assert_output(
        concat!(
            "import operator\n",
            "def report(label, callback, expected):\n",
            "    try:\n",
            "        callback()\n",
            "    except TypeError as error:\n",
            "        print(label, type(error).__name__, str(error), error.args, str(error) == expected)\n",
            "    else:\n",
            "        print(label, 'ok')\n",
            "for helper in [operator.attrgetter('name'), operator.itemgetter(0), operator.methodcaller('strip')]:\n",
            "    typ = type(helper)\n",
            "    print(typ.__name__, isinstance(helper, typ), isinstance(helper, object), isinstance(typ, type), isinstance(typ, object), typ.__type_params__)\n",
            "    print(typ.__name__, issubclass(typ, typ), issubclass(typ, object), issubclass(typ, (object,)), issubclass(object, typ))\n",
            "    expected = \"type 'operator.\" + typ.__name__ + \"' is not an acceptable base type\"\n",
            "    def class_stmt():\n",
            "        class X(typ):\n",
            "            pass\n",
            "    report(typ.__name__ + '-class', class_stmt, expected)\n",
            "    report(typ.__name__ + '-type', lambda: type('X', (typ,), {}), expected)\n",
        ),
        &[
            "attrgetter True True True True ()",
            "attrgetter True True True False",
            "attrgetter-class TypeError type 'operator.attrgetter' is not an acceptable base type (\"type 'operator.attrgetter' is not an acceptable base type\",) True",
            "attrgetter-type TypeError type 'operator.attrgetter' is not an acceptable base type (\"type 'operator.attrgetter' is not an acceptable base type\",) True",
            "itemgetter True True True True ()",
            "itemgetter True True True False",
            "itemgetter-class TypeError type 'operator.itemgetter' is not an acceptable base type (\"type 'operator.itemgetter' is not an acceptable base type\",) True",
            "itemgetter-type TypeError type 'operator.itemgetter' is not an acceptable base type (\"type 'operator.itemgetter' is not an acceptable base type\",) True",
            "methodcaller True True True True ()",
            "methodcaller True True True False",
            "methodcaller-class TypeError type 'operator.methodcaller' is not an acceptable base type (\"type 'operator.methodcaller' is not an acceptable base type\",) True",
            "methodcaller-type TypeError type 'operator.methodcaller' is not an acceptable base type (\"type 'operator.methodcaller' is not an acceptable base type\",) True",
        ],
    );
}

