// Adapted from CPython Lib/test/test_functools.py::TestPartial public call,
// attribute, and side-effect behavior. Placeholder behavior is covered by the
// focused subset below; pickling and weakref checks remain outside this runtime
// surface.
#[test]
fn cpython_functools_partial_subset() {
    assert_output(
        concat!(
            "from functools import partial\n",
            "def capture(*args, **kwargs):\n",
            "    return args, kwargs\n",
            "p = partial(capture, 1, 2, a=10, b=20)\n",
            "print(callable(p), type(p).__name__)\n",
            "print(type(p.__doc__).__name__, bool(p.__doc__))\n",
            "p.__doc__ = 'custom partial doc'\n",
            "print(p.__doc__, p.__dict__['__doc__'])\n",
            "del p.__doc__\n",
            "print(type(p.__doc__).__name__, bool(p.__doc__))\n",
            "print(p.__module__, '__module__' in p.__dict__)\n",
            "p.__module__ = 'custom'\n",
            "print(p.__module__, p.__dict__['__module__'])\n",
            "del p.__module__\n",
            "print(p.__module__, '__module__' in p.__dict__)\n",
            "print(p(3, 4, b=30, c=40))\n",
            "print(p.func is capture, p.args, p.keywords == {'a': 10, 'b': 20})\n",
            "rendered = repr(p)\n",
            "print(rendered.startswith('functools.partial(<function capture'), rendered.endswith(', 1, 2, a=10, b=20)'))\n",
            "print(repr(partial(int, base=2)))\n",
            "for expr in [lambda: partial(), lambda: partial(2), lambda: partial(2)()]:\n",
            "    try:\n",
            "        expr()\n",
            "    except TypeError as error:\n",
            "        print(error.__class__.__name__, str(error))\n",
            "d = {'a': 3}\n",
            "def func(a=10, b=20):\n",
            "    return a\n",
            "p = partial(func, a=5)\n",
            "print(p(**d), d)\n",
            "p(b=7)\n",
            "print(d)\n",
            "d = {'a': 3}\n",
            "p = partial(capture, **d)\n",
            "print(p())\n",
            "d['a'] = 5\n",
            "print(p())\n",
            "p = partial(capture)\n",
            "print(p.keywords, p(), p(1, 2))\n",
            "p = partial(capture, 1, 2)\n",
            "print(p(), p(3, 4))\n",
            "p = partial(capture, a=1)\n",
            "print(p.keywords, p(), p(b=2), p(a=3, b=2))\n",
            "class S(str):\n",
            "    pass\n",
            "p = partial(capture, a=1)\n",
            "live = p.keywords\n",
            "live['a'] = 2\n",
            "live['b'] = 3\n",
            "print(p(), live is p.keywords)\n",
            "p.keywords[S('c')] = 4\n",
            "print(p())\n",
            "p.keywords[1] = 5\n",
            "try:\n",
            "    p()\n",
            "except TypeError as error:\n",
            "    print(type(error).__name__, str(error))\n",
            "del p.keywords[1]\n",
            "print(p())\n",
            "frozen = ('p', 'q', 'r', 's')\n",
            "print([partial(capture, *frozen[:n])(9) == (frozen[:n] + (9,), {}) for n in range(5)])\n",
            "print([partial(capture, k=v)(z=0) == ((), {'k': v, 'z': 0}) for v in (b'', -1, (), 2.25)])\n",
            "p = partial(capture, 0, a=1)\n",
            "args1, kw1 = p(1, b=2)\n",
            "args2, kw2 = p()\n",
            "print(args1, kw1, args2, kw2)\n",
            "def div(x, y):\n",
            "    x / y\n",
            "for expr in [lambda: partial(div, 1, 0)(), lambda: partial(div, 1)(0), lambda: partial(div)(1, 0), lambda: partial(div, y=0)(1)]:\n",
            "    try:\n",
            "        expr()\n",
            "    except ZeroDivisionError as error:\n",
            "        print(error.__class__.__name__)\n",
            "p = partial(capture, 'first')\n",
            "p2 = partial(p, 'second')\n",
            "p2.new_attr = 'spam'\n",
            "print(p2(), p2.new_attr, p2.__dict__['new_attr'])\n",
            "print(p2.func is capture, p2.args, p2.keywords)\n",
            "p3 = partial(partial(capture, 'base', a=1), 'tail', a=2, b=3)\n",
            "print(p3.func is capture, p3.args, p3.keywords, p3())\n",
            "del p2.new_attr\n",
            "try:\n",
            "    p2.new_attr\n",
            "except AttributeError as error:\n",
            "    print(error.__class__.__name__)\n",
            "for attr in ['func', 'args', 'keywords']:\n",
            "    try:\n",
            "        setattr(p2, attr, 42)\n",
            "    except AttributeError as error:\n",
            "        print(attr, error.__class__.__name__)\n",
        ),
        &[
            "True partial",
            "str True",
            "custom partial doc custom partial doc",
            "str True",
            "functools False",
            "custom custom",
            "functools False",
            "((1, 2, 3, 4), {'a': 10, 'b': 30, 'c': 40})",
            "True (1, 2) True",
            "True True",
            "functools.partial(<class 'int'>, base=2)",
            "TypeError type 'partial' takes at least one argument",
            "TypeError the first argument must be callable",
            "TypeError the first argument must be callable",
            "3 {'a': 3}",
            "{'a': 3}",
            "((), {'a': 3})",
            "((), {'a': 3})",
            "{} ((), {}) ((1, 2), {})",
            "((1, 2), {}) ((1, 2, 3, 4), {})",
            "{'a': 1} ((), {'a': 1}) ((), {'a': 1, 'b': 2}) ((), {'a': 3, 'b': 2})",
            "((), {'a': 2, 'b': 3}) True",
            "((), {'a': 2, 'b': 3, 'c': 4})",
            "TypeError keywords must be strings",
            "((), {'a': 2, 'b': 3, 'c': 4})",
            "[True, True, True, True, True]",
            "[True, True, True, True]",
            "(0, 1) {'a': 1, 'b': 2} (0,) {'a': 1}",
            "ZeroDivisionError",
            "ZeroDivisionError",
            "ZeroDivisionError",
            "ZeroDivisionError",
            "(('first', 'second'), {}) spam spam",
            "True ('first', 'second') {}",
            "True ('base', 'tail') {'a': 2, 'b': 3} (('base', 'tail'), {'a': 2, 'b': 3})",
            "AttributeError",
            "func AttributeError",
            "args AttributeError",
            "keywords AttributeError",
        ],
    );
}

// Adapted from CPython Lib/test/test_functools.py::TestPartial placeholder
// rows. This covers the public Placeholder singleton surface and partial()
// positional placeholder filling without extending into pickle or weakref
// internals.
#[test]
fn cpython_functools_placeholder_partial_subset() {
    assert_output(
        r#"import functools
P = functools.Placeholder
print(P, repr(P), type(P).__name__, type(P).__module__, bool(P), P is functools.Placeholder)
print(type(P).__name__, P.__class__.__module__, hash(P) == hash(functools.Placeholder), {P: "x"}[functools.Placeholder])
def f(a, b, c=0):
    return (a, b, c)
p = functools.partial(f, P, 2)
print(p(1), p(1, 3), p.args, p.keywords)
p2 = functools.partial(p, 5)
print(p2(), p2.args, p2.keywords)
q = functools.partial(f, P, P, 3)
print(functools.partial(q, 1).args, functools.partial(q, 1)(2))
for label, expr in [("bare-call", lambda: P()), ("partial-no-fill", lambda: p()), ("partial-one-fill", lambda: q(1)), ("kw-placeholder", lambda: functools.partial(f, a=P))]:
    try:
        print(label, expr())
    except Exception as e:
        print(label, type(e).__name__, str(e))"#,
        &[
            "Placeholder Placeholder _PlaceholderType functools True True",
            "_PlaceholderType functools True x",
            "(1, 2, 0) (1, 2, 3) (Placeholder, 2) {}",
            "(5, 2, 0) (5, 2) {}",
            "(1, Placeholder, 3) (1, 2, 3)",
            "bare-call TypeError 'functools._PlaceholderType' object is not callable",
            "partial-no-fill TypeError missing positional arguments in 'partial' call; expected at least 1, got 0",
            "partial-one-fill TypeError missing positional arguments in 'partial' call; expected at least 2, got 1",
            "kw-placeholder TypeError Placeholder cannot be passed as a keyword argument",
        ],
    );
}

