// Adapted from CPython Lib/test/test_complex.py::ComplexTest::test_truediv,
// ::test_truediv_zero_division, ::test_floordiv, ::test_floordiv_zero_division,
// ::test_mod, ::test_mod_zero_division, ::test_divmod, and
// ::test_divmod_zero_division.
#[test]
fn cpython_complex_division_subset() {
    run_test_with_stack(64 * 1024 * 1024, || {
        assert_output_with_stack(
            "grid = [complex(a, b) for a in (-3, -0.5, 0, 2, 7) for b in (-4, 0, 1.5, 6)]\nbad = []\nfor x in grid:\n    for y in grid:\n        prod = x * y\n        if x and abs(prod / x - y) > 1e-9:\n            bad.append((x, y))\n        if y and abs(prod / y - x) > 1e-9:\n            bad.append((y, x))\nprint(len(grid), bad)\nprint(complex.__truediv__(6+2j, 1-1j), \"__truediv__\" in dir(complex), \"__truediv__\" in dir(1j))",
            &["20 []", "(2+4j) True True"],
            32 * 1024 * 1024,
        );
        assert_output(
            "for x in (complex(3e250, -2e250), complex(4e-250, 5e-250)):\n    one = 1 + 0j\n    prod = x * one\n    print(abs(prod / x - one) < 1e-9, abs(prod.__truediv__(one) - x) <= 1e-9 * abs(x))",
            &["True True", "True True"],
        );
        assert_output(
            "def show(z):\n    print(z, repr(z.real), repr(z.imag))\nfor z in ((3-6j) / 4.0, 2.0 / (3+4j), 2.0 / (-3+4j), 2.0 / (3-4j), -5 / (4+3j), 10 / (-4-3j), 1 / 1j):\n    show(z)",
            &["(0.75-1.5j) 0.75 -1.5", "(0.24-0.32j) 0.24 -0.32", "(-0.24-0.32j) -0.24 -0.32", "(0.24+0.32j) 0.24 0.32", "(-0.8+0.6j) -0.8 0.6", "(-1.6+1.2j) -1.6 1.2", "-1j 0.0 -1.0"],
        );
        assert_output(
            "NAN = float(\"nan\")\nfor den in (complex(0, NAN), complex(NAN, 0), complex(NAN, NAN), complex(NAN, 3)):\n    for num in (0j, 0.0, 5 + 5j):\n        q = num / den\n        print(q != q, repr(q.real), repr(q.imag))",
            &["True nan nan", "True nan nan", "True nan nan", "True nan nan", "True nan nan", "True nan nan", "True nan nan", "True nan nan", "True nan nan", "True nan nan", "True nan nan", "True nan nan"],
        );
        assert_output(
            "INF = float(\"inf\")\nNAN = float(\"nan\")\nspecials = [complex(INF, NAN), complex(INF, 1), complex(INF, -INF), complex(INF, INF), complex(NAN, INF),\n            complex(-INF, INF), complex(-INF, -INF), complex(1, INF), complex(-INF, NAN), complex(NAN, NAN),\n            complex(0.5, 0.25), complex(0.0, 1), complex(2 ** 1000, 2 ** -1000), complex(1, -0.0)]\nnumerators = specials + [INF, 1.0, -2.0]\nfor z in numerators:\n    row = []\n    for w in specials:\n        try:\n            row.append(repr(z / w))\n        except ZeroDivisionError:\n            row.append(\"ZeroDivisionError\")\n    print(repr(z), \" \".join(row))\nprint([repr(complex(INF, NAN) / d) for d in (2, -2, 0.5)])",
            &["(inf+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (inf-infj) (nan-infj) (inf-infj) (inf+nanj)", "(inf+1j) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (inf-infj) (nan-infj) (inf+nanj) (inf+nanj)", "(inf-infj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan-infj) (-inf-infj) (inf-infj) (inf-infj)", "(inf+infj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (inf+nanj) (inf-infj) (inf+infj) (inf+infj)", "(nan+infj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (inf+infj) (inf+nanj) (inf+infj) (nan+infj)", "(-inf+infj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+infj) (inf+infj) (-inf+infj) (-inf+infj)", "(-inf-infj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (-inf+nanj) (-inf+infj) (-inf-infj) (-inf-infj)", "(1+infj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (inf+infj) (inf+nanj) (nan+infj) (nan+infj)", "(-inf+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (-inf+infj) (nan+infj) (-inf+infj) (-inf+nanj)", "(nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj)", "(0.5+0.25j) 0j 0j 0j -0j -0j (-0-0j) (-0+0j) -0j (-0-0j) (nan+nanj) (1+0j) (0.25-0.5j) (4.6663180925160944e-302+2.3331590462580472e-302j) (0.5+0.25j)", "1j 0j 0j (-0+0j) 0j 0j -0j (-0-0j) 0j -0j (nan+nanj) (0.8+1.6j) (1+0j) 9.332636185032189e-302j 1j", "(1.0715086071862673e+301+9.332636185032189e-302j) 0j 0j 0j -0j -0j (-0-0j) (-0+0j) -0j (-0-0j) (nan+nanj) (1.7144137714980278e+301-8.572068857490139e+300j) (9.332636185032189e-302-1.0715086071862673e+301j) (1+0j) (1.0715086071862673e+301+9.332636185032189e-302j)", "(1-0j) -0j -0j 0j -0j -0j (-0-0j) (-0+0j) -0j (-0+0j) (nan+nanj) (1.6-0.8j) -1j (9.332636185032189e-302-0j) (1+0j)", "inf (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (nan+nanj) (inf-infj) (nan-infj) (inf+nanj) (inf+nanj)", "1.0 -0j -0j 0j -0j -0j (-0-0j) (-0+0j) -0j (-0-0j) (nan+nanj) (1.6-0.8j) -1j (9.332636185032189e-302-0j) (1+0j)", "-2.0 (-0+0j) (-0+0j) (-0-0j) (-0+0j) (-0+0j) 0j -0j (-0+0j) 0j (nan+nanj) (-3.2+1.6j) (-0+2j) (-1.8665272370064378e-301+0j) (-2-0j)", "['(inf+nanj)', '(-inf+nanj)', '(inf+nanj)']"],
        );
        assert_output(
            "import operator\nzero_pairs = [(3-1j, 0j), (3-1j, 0.0), (3-1j, 0), (2.0, 0j), (2, 0j), (0j, -0.0)]\nfor a, b in zero_pairs:\n    try:\n        a / b\n    except ZeroDivisionError as exc:\n        print(\"truediv\", type(exc).__name__)\nfor a, b in [(2j, None), (None, 2j), (2j, \"s\")]:\n    try:\n        operator.truediv(a, b)\n    except TypeError as exc:\n        print(\"truediv\", type(exc).__name__)\noperands = [(3-1j, 2+0j), (3-1j, 2.0), (3-1j, 2), (2.0, 3+0j), (2, 3+0j)] + zero_pairs\nfor name, op in ((\"floordiv\", operator.floordiv), (\"mod\", operator.mod), (\"divmod\", divmod)):\n    outcome = []\n    for a, b in operands:\n        try:\n            op(a, b)\n            outcome.append(\"ok\")\n        except TypeError:\n            outcome.append(\"TypeError\")\n        except ZeroDivisionError:\n            outcome.append(\"ZeroDivisionError\")\n    print(name, outcome)",
            &["truediv ZeroDivisionError", "truediv ZeroDivisionError", "truediv ZeroDivisionError", "truediv ZeroDivisionError", "truediv ZeroDivisionError", "truediv ZeroDivisionError", "truediv TypeError", "truediv TypeError", "truediv TypeError", "floordiv ['TypeError', 'TypeError', 'TypeError', 'TypeError', 'TypeError', 'TypeError', 'TypeError', 'TypeError', 'TypeError', 'TypeError', 'TypeError']", "mod ['TypeError', 'TypeError', 'TypeError', 'TypeError', 'TypeError', 'TypeError', 'TypeError', 'TypeError', 'TypeError', 'TypeError', 'TypeError']", "divmod ['TypeError', 'TypeError', 'TypeError', 'TypeError', 'TypeError', 'TypeError', 'TypeError', 'TypeError', 'TypeError', 'TypeError', 'TypeError']"],
        );
    });
}

// Adapted from CPython Lib/test/test_complex.py::ComplexTest::test_pow.
#[test]
fn cpython_complex_pow_subset() {
    assert_output(
        "def near(a, b):\n    return abs(a - b) < 1e-12\nprint(near(pow(2-3j, 0j), 1), near(pow(0j, 3+0j), 0), pow(0j, 777+0j), pow(0, 0j), pow(-5, 0j), pow(0j, 0))\nprint(near(pow(2j, -2), 1 / (2j * 2j)), near(pow(1j, 401), 1j), near(pow(-1+0j, 0.5), 1j))\nprint(near(pow(2+1j, 1-1j), (2+1j) ** (1-1j)), near(pow(4j, 0.5), complex(2 ** 0.5, 2 ** 0.5)))\nprint(complex.__pow__(1-1j, 2), \"__pow__\" in dir(complex), \"__pow__\" in dir(3j))",
        &["True True 0j (1+0j) (1+0j) (1+0j)", "True True True", "True True", "-2j True True"],
    );
    assert_output(
        "for label, fn in ((\"0j**2j\", lambda: pow(0j, 2j)), (\"0j**-3\", lambda: pow(0j, -3)), (\"0j**(-1+1j)\", lambda: 0j ** (-1+1j))):\n    try:\n        fn()\n    except ZeroDivisionError as exc:\n        print(label, type(exc).__name__, exc)\nfor label, fn in ((\"mod complex\", lambda: pow(2j, 2, 3j)), (\"mod int\", lambda: pow(2j, 2, 5)), (\"mod zero\", lambda: pow(1+1j, 2j, 0))):\n    try:\n        fn()\n    except ValueError as exc:\n        print(label, type(exc).__name__, exc)\nfor label, fn in ((\"exp None\", lambda: pow(2j, None)), (\"base None\", lambda: pow(None, 2j)), (\"exp str\", lambda: 2j ** \"2\")):\n    try:\n        fn()\n    except TypeError as exc:\n        print(label, type(exc).__name__)",
        &["0j**2j ZeroDivisionError zero to a negative or complex power", "0j**-3 ZeroDivisionError zero to a negative or complex power", "0j**(-1+1j) ZeroDivisionError zero to a negative or complex power", "mod complex ValueError complex modulo", "mod int ValueError complex modulo", "mod zero ValueError complex modulo", "exp None TypeError", "base None TypeError", "exp str TypeError"],
    );
    assert_output(
        "z = -1.75+2.5j\nfor e in (0j, 0.0+0.0j, 0, 0.0):\n    r = z ** e\n    print(repr(r), type(r).__name__)\nprint(repr(5j ** 0j), repr(5j ** 0), repr(0j ** 0), repr(0j ** 0j))\nprint(z ** 77 == z ** 77, z ** -77 == z ** -77, (z ** 12) == (z ** 6) ** 2)",
        &["(1+0j) complex", "(1+0j) complex", "(1+0j) complex", "(1+0j) complex", "(1+0j) (1+0j) (1+0j) (1+0j)", "True True True"],
    );
    assert_output(
        "print(repr((1.6360268865396872-1.8480122762013274j) ** (3.6337214881942703+2.975040219520314j)))\nclass IntSub(int):\n    pass\nprint(repr(2 ** IntSub(1)), repr(IntSub(2) ** 1j), repr((1j).__rpow__(IntSub(2))))",
        &["(305.9866910143363-124.66635753847375j)", "2 (0.7692389013639721+0.6389612763136348j) (0.7692389013639721+0.6389612763136348j)"],
    );
    assert_output(
        "import sys\nfor label, fn in ((\"huge base and exponent\", lambda: pow(3e250+2j, 1e250+5j)), (\"huge base int exponent\", lambda: pow(-4e180+1j, 4)),\n                  (\"imaginary tower\", lambda: 7j ** (25j ** 3))):\n    try:\n        fn()\n        print(label, \"no overflow\")\n    except OverflowError as exc:\n        print(label, type(exc).__name__)\nfor label, fn in ((\"zero to complex a\", lambda: 0j ** (1.5-2.5j)), (\"zero to complex b\", lambda: 0j ** (-2+7j))):\n    try:\n        fn()\n    except ZeroDivisionError as exc:\n        print(label, type(exc).__name__)\nedges = (sys.maxsize, sys.maxsize - 2, -sys.maxsize, sys.maxsize + 3, -sys.maxsize - 5)\ncrashed = []\nfor re_part in edges:\n    for im_part in edges:\n        base = complex(re_part, im_part)\n        for exponent in (re_part, base):\n            try:\n                base ** exponent\n            except OverflowError:\n                pass\n            except BaseException as exc:\n                crashed.append(type(exc).__name__)\nprint(\"edge exponents\", crashed)",
        &["huge base and exponent OverflowError", "huge base int exponent OverflowError", "imaginary tower OverflowError", "zero to complex a ZeroDivisionError", "zero to complex b ZeroDivisionError", "edge exponents []"],
    );
}

// Adapted from CPython Lib/test/test_complex.py::ComplexTest::
// test_pow_with_small_integer_exponents.
#[test]
fn cpython_complex_pow_small_integer_exponents_subset() {
    assert_output(
        "INF = float(\"inf\")\nbases = [complex(3.0, -4.0), complex(-2.5e120, 7.0e119), complex(INF, -1.0), complex(0.0, INF), complex(-8.0, 0.0), 1j]\ndef attempt(base, exponent):\n    try:\n        return str(base ** exponent)\n    except OverflowError:\n        return \"overflow\"\ndiffs = []\nfor base in bases:\n    for n in range(-11, 12, 2):\n        as_int = attempt(base, n)\n        if attempt(base, float(n)) != as_int or attempt(base, complex(n)) != as_int:\n            diffs.append((base, n))\nprint(\"mismatched exponent kinds:\", diffs)\nfor n in (2, 3, -1, -2):\n    print(n, attempt(1j, n), attempt(1j, float(n)), attempt(1j, complex(n)))",
        &["mismatched exponent kinds: []", "2 (-1+0j) (-1+0j) (-1+0j)", "3 (-0-1j) (-0-1j) (-0-1j)", "-1 -1j -1j -1j", "-2 (-1-0j) (-1-0j) (-1-0j)"],
    );
}

// Adapted from CPython Lib/test/test_complex.py::ComplexTest::test_abs.
#[test]
fn cpython_complex_abs_subset() {
    assert_output(
        "ok = True\nfor x in range(-9, 9):\n    for y in range(-9, 9):\n        num = complex(x / 3.0, y / 7.0)\n        expected = (num.real ** 2 + num.imag ** 2) ** 0.5\n        ok = ok and abs(expected - abs(num)) < 1e-12\nprint(ok)\nz = 3 + 4j\nprint(z.__abs__(), complex.__abs__(z), '__abs__' in dir(z))\nDBL_MAX = 1.7976931348623157e308\ntry:\n    abs(complex(DBL_MAX, DBL_MAX))\nexcept OverflowError as error:\n    print(error.__class__.__name__, error)",
        &[
            "True",
            "5.0 5.0 True",
            "OverflowError absolute value too large",
        ],
    );
}

// Adapted from CPython Lib/test/test_complex.py::ComplexTest::test_repr_str
// and ::test_negative_zero_repr_str.
#[test]
fn cpython_complex_repr_str_subset() {
    assert_output(
        "INF = float('inf')\nNAN = float('nan')\ndef show(value):\n    print(repr(value), str(value))\nfor value in [1+6j, 1-6j, complex(1., INF), complex(1., -INF), complex(INF, 1), complex(-INF, INF), complex(NAN, 1), complex(1, NAN), complex(NAN, NAN), complex(-NAN, -NAN), complex(0, INF), complex(0, -INF), complex(0, NAN)]:\n    show(value)\nprint(repr(-(1+0j)) != '(-1+-0j)', str(-(1+0j)) != '(-1+-0j)')\nprint(1-6j == complex(repr(1-6j)))\nprint(1+6j == complex(repr(1+6j)))\nprint(-6j == complex(repr(-6j)))\nprint(6j == complex(repr(6j)))",
        &[
            "(1+6j) (1+6j)",
            "(1-6j) (1-6j)",
            "(1+infj) (1+infj)",
            "(1-infj) (1-infj)",
            "(inf+1j) (inf+1j)",
            "(-inf+infj) (-inf+infj)",
            "(nan+1j) (nan+1j)",
            "(1+nanj) (1+nanj)",
            "(nan+nanj) (nan+nanj)",
            "(nan+nanj) (nan+nanj)",
            "infj infj",
            "-infj -infj",
            "nanj nanj",
            "True True",
            "True",
            "True",
            "True",
            "True",
        ],
    );
    assert_output(
        "def show(value):\n    print(repr(value), str(value))\nfor value in [complex(0., 1.), complex(-0., 1.), complex(0., -1.), complex(-0., -1.), complex(0., 0.), complex(0., -0.), complex(-0., 0.), complex(-0., -0.)]:\n    show(value)\nz = 3 + 4j\nprint(z.__repr__(), z.__str__(), complex.__repr__(z), complex.__str__(z))\nprint('__repr__' in dir(z), '__str__' in dir(z))",
        &[
            "1j 1j",
            "(-0+1j) (-0+1j)",
            "-1j -1j",
            "(-0-1j) (-0-1j)",
            "0j 0j",
            "-0j -0j",
            "(-0+0j) (-0+0j)",
            "(-0-0j) (-0-0j)",
            "(3+4j) (3+4j) (3+4j) (3+4j)",
            "True True",
        ],
    );
}

// Adapted from CPython Lib/test/test_complex.py::ComplexTest::test_pos
// and ::test_neg.
#[test]
fn cpython_complex_unary_subset() {
    assert_output(
        "z = 1 + 6j\nprint(+z, type(+z) is complex)\nprint(-z)\nprint(z.__pos__(), z.__neg__(), complex.__pos__(z), complex.__neg__(z))\nprint('__pos__' in dir(z), '__neg__' in dir(z))",
        &[
            "(1+6j) True",
            "(-1-6j)",
            "(1+6j) (-1-6j) (1+6j) (-1-6j)",
            "True True",
        ],
    );
}

// Adapted from CPython Lib/test/test_complex.py::ComplexTest::test_overflow.
