// Adapted from CPython's Lib/test/test_fstring.py::test_yield and
// ::test_yield_send. F-string replacement expressions can contain `yield`, so
// rendering the f-string must preserve generator suspension and resume values.
#[test]
fn cpython_f_string_yield_expression_subset() {
    assert_output(
        "def gen(n):\n    f\"first:{yield n + 1}\"\n    f\"{yield}\"\n    f\"{(yield 'third')!r:>8}\"\ng = gen(1)\nprint(next(g), next(g), next(g))",
        &["2 None third"],
    );
    assert_output(
        "def gen(base):\n    yield f\"got:{yield (lambda k: base - k)}!\"\ng = gen(50)\nfn = next(g)\nprint(fn(8), g.send(\"payload\"))",
        &["42 got:payload!"],
    );
}

