// Adapted from CPython public dict view dir and type lookup behavior. This
// covers the supported built-in dict view type/instance surface without
// requiring exact wrapper_descriptor vs method_descriptor identity parity.
#[test]
fn cpython_dict_view_dir_type_lookup_surface_subset() {
    assert_output(
        r#"_doc = lambda value: '<doc>' if isinstance(value, str) and value else value
source = {'a': 1, 'b': 2}
for label, view in [('keys', source.keys()), ('values', source.values()), ('items', source.items())]:
    typ = type(view)
    names = ['__base__', '__bases__', '__name__', '__module__', '__qualname__', '__iter__', '__len__', '__contains__', 'isdisjoint', 'mapping']
    print(label, 'visible-type', *(name in dir(typ) for name in names))
    print(label, 'visible-inst', *(name in dir(view) for name in names))
    print(label, 'type-attr-has', hasattr(typ, 'mapping'), hasattr(typ, '__contains__'), hasattr(typ, 'isdisjoint'))
    descriptor = typ.mapping
    print(label, 'mapping-descriptor', type(descriptor).__name__, descriptor.__name__, descriptor.__qualname__, descriptor.__objclass__.__name__, _doc(descriptor.__doc__))
    proxy = descriptor.__get__(view, typ)
    print(label, 'mapping-get', type(proxy).__name__, proxy['a'])
try:
    type(source.keys()).mapping.__get__(source.values(), type(source.values()))
except Exception as error:
    print('wrong-descriptor', error.__class__.__name__, str(error))
try:
    type(source.keys()).mapping.__set__(source.keys(), {})
except Exception as error:
    print('set-descriptor', error.__class__.__name__, str(error))
try:
    type(source.keys()).mapping.__delete__(source.keys())
except Exception as error:
    print('delete-descriptor', error.__class__.__name__, str(error))"#,
        &[
            "keys visible-type False False False False False True True True True True",
            "keys visible-inst False False False False False True True True True True",
            "keys type-attr-has True True True",
            "keys mapping-descriptor getset_descriptor mapping dict_keys.mapping dict_keys <doc>",
            "keys mapping-get mappingproxy 1",
            "values visible-type False False False False False True True False False True",
            "values visible-inst False False False False False True True False False True",
            "values type-attr-has True False False",
            "values mapping-descriptor getset_descriptor mapping dict_values.mapping dict_values <doc>",
            "values mapping-get mappingproxy 1",
            "items visible-type False False False False False True True True True True",
            "items visible-inst False False False False False True True True True True",
            "items type-attr-has True True True",
            "items mapping-descriptor getset_descriptor mapping dict_items.mapping dict_items <doc>",
            "items mapping-get mappingproxy 1",
            "wrong-descriptor TypeError descriptor 'mapping' for 'dict_keys' objects doesn't apply to a 'dict_values' object",
            "set-descriptor AttributeError attribute 'mapping' of 'dict_keys' objects is not writable",
            "delete-descriptor AttributeError attribute 'mapping' of 'dict_keys' objects is not writable",
        ],
    );
}

// Adapted from CPython public dict view type namespace behavior. This covers
