// Mirrors CPython's public `mappingproxy` instance `__doc__` type-attribute
// lookup without adding writable instance dictionaries.
#[test]
fn cpython_types_mappingproxy_instance_doc_attribute_subset() {
    assert_output(
        r#"_doc = lambda value: '<doc>' if isinstance(value, str) and value else value
from types import MappingProxyType
for label, value in [('exact', MappingProxyType({'a': 1})), ('class-dict', int.__dict__), ('view-mapping', {1: 2}.keys().mapping)]:
    doc = _doc(value.__doc__)
    print(label, type(doc).__name__, doc == _doc(type(value).__doc__), '__doc__' in dir(value), doc.split('\n')[0], len(doc))"#,
        &[
            "exact str True True <doc> 5",
            "class-dict str True True <doc> 5",
            "view-mapping str True True <doc> 5",
        ],
    );
}

