// Adapted from CPython Lib/test/test_collections.py::TestChainMap. This keeps
// the broad public ChainMap behavior together; copy/pickle/eval identity
// matrices are covered by the adjacent focused test.
#[test]
fn cpython_collections_chainmap_public_methods_subset() {
    assert_output(
        concat!(
            "from collections import ChainMap\n",
            "import copy\n",
            "print(ChainMap().maps)\n",
            "print(ChainMap({1: 2}).maps)\n",
            "print(bool(ChainMap()), bool(ChainMap({}, {})), bool(ChainMap({1: 2}, {})), bool(ChainMap({}, {1: 2})))\n",
            "c = ChainMap()\n",
            "c['a'] = 1\n",
            "c['b'] = 2\n",
            "m = {'b': 20, 'c': 30}\n",
            "d = c.new_child(m)\n",
            "print(d.maps, d.maps[0] is m)\n",
            "print(list(d.items()), list(d), len(d), dict(d))\n",
            "print('a' in d, 'b' in d, 'c' in d, 'z' in d)\n",
            "print(d['b'], d.parents['b'], d.get('z', 100))\n",
            "del d['b']\n",
            "print(d.maps, d['b'])\n",
            "e = c.new_child(b=20, c=30)\n",
            "print(e.maps)\n",
            "f = e.copy()\n",
            "print(f == e, f.maps == e.maps, f.maps[0] is e.maps[0], f.maps[1] is e.maps[1])\n",
            "g = copy.copy(e)\n",
            "print(g == e, g.maps[0] is e.maps[0], g.maps[1] is e.maps[1])\n",
            "baseline = {'music': 'bach', 'art': 'rembrandt'}\n",
            "adjustments = {'art': 'van gogh', 'opera': 'carmen'}\n",
            "cm = ChainMap(adjustments, baseline)\n",
            "print(cm.__repr__(), cm.__str__(), cm.__format__(''))\n",
            "print(ChainMap.__repr__(cm), ChainMap.__str__(cm), ChainMap.__format__(cm, ''))\n",
            "try:\n",
            "    cm.__format__('x')\n",
            "except TypeError as error:\n",
            "    print(error.__class__.__name__)\n",
            "combined = baseline.copy()\n",
            "combined.update(adjustments)\n",
            "print(list(combined.items()), list(cm.items()))\n",
            "print(dict(cm), dict(cm.items()))"
        ),
        &[
            "[{}]",
            "[{1: 2}]",
            "False False True True",
            "[{'b': 20, 'c': 30}, {'a': 1, 'b': 2}] True",
            "[('a', 1), ('b', 20), ('c', 30)] ['a', 'b', 'c'] 3 {'a': 1, 'b': 20, 'c': 30}",
            "True True True False",
            "20 2 100",
            "[{'c': 30}, {'a': 1, 'b': 2}] 2",
            "[{'b': 20, 'c': 30}, {'a': 1, 'b': 2}]",
            "True True False True",
            "True False True",
            "ChainMap({'art': 'van gogh', 'opera': 'carmen'}, {'music': 'bach', 'art': 'rembrandt'}) ChainMap({'art': 'van gogh', 'opera': 'carmen'}, {'music': 'bach', 'art': 'rembrandt'}) ChainMap({'art': 'van gogh', 'opera': 'carmen'}, {'music': 'bach', 'art': 'rembrandt'})",
            "ChainMap({'art': 'van gogh', 'opera': 'carmen'}, {'music': 'bach', 'art': 'rembrandt'}) ChainMap({'art': 'van gogh', 'opera': 'carmen'}, {'music': 'bach', 'art': 'rembrandt'}) ChainMap({'art': 'van gogh', 'opera': 'carmen'}, {'music': 'bach', 'art': 'rembrandt'})",
            "TypeError",
            "[('music', 'bach'), ('art', 'van gogh'), ('opera', 'carmen')] [('music', 'bach'), ('art', 'van gogh'), ('opera', 'carmen')]",
            "{'music': 'bach', 'art': 'van gogh', 'opera': 'carmen'} {'music': 'bach', 'art': 'van gogh', 'opera': 'carmen'}",
        ],
    );
}

// Mirrors CPython public collections.ChainMap __class_getitem__ behavior. This
// pins GenericAlias origin/args, direct type calls, exact instance lookup, and
// inherited subclass lookup without widening the ChainMap mapping API surface.
#[test]
fn cpython_collections_chainmap_class_getitem_generic_alias_subset() {
    assert_output(
        r#"from collections import ChainMap
typ = ChainMap
inst = ChainMap({'a': 1})
class C(ChainMap):
    pass
for label, expr in [
    ('visible', lambda: (hasattr(typ, '__class_getitem__'), '__class_getitem__' in dir(typ))),
    ('visible-inst', lambda: (hasattr(inst, '__class_getitem__'), '__class_getitem__' in dir(inst))),
    ('subscript-int', lambda: (type(typ[int]).__name__, str(typ[int]), typ[int].__origin__ is typ, typ[int].__args__)),
    ('call-int', lambda: (type(typ.__class_getitem__(int)).__name__, str(typ.__class_getitem__(int)), typ.__class_getitem__(int) == typ[int], typ.__class_getitem__(int).__origin__ is typ, typ.__class_getitem__(int).__args__)),
    ('call-pair', lambda: (str(typ.__class_getitem__((int, str))), typ.__class_getitem__((int, str)) == typ[int, str], typ.__class_getitem__((int, str)).__args__)),
    ('inst-exact', lambda: (inst.__class_getitem__(int) == typ[int], inst.__class_getitem__(int).__origin__ is typ)),
    ('type-sub', lambda: (type(C.__class_getitem__(int)).__name__, C.__class_getitem__(int).__origin__ is C, C.__class_getitem__(int).__args__)),
    ('inst-sub', lambda: (type(C().__class_getitem__(str)).__name__, C().__class_getitem__(str).__origin__ is C, C().__class_getitem__(str).__args__)),
    ('call-noargs', lambda: typ.__class_getitem__()),
    ('call-extra', lambda: typ.__class_getitem__(int, str)),
    ('call-keyword', lambda: typ.__class_getitem__(item=int)),
]:
    try:
        result = expr()
        print(label, type(result).__name__, result)
    except Exception as error:
        print(label, type(error).__name__, str(error), error.args)"#,
        &[
            "visible tuple (True, True)",
            "visible-inst tuple (True, True)",
            "subscript-int tuple ('GenericAlias', 'collections.ChainMap[int]', True, (<class 'int'>,))",
            "call-int tuple ('GenericAlias', 'collections.ChainMap[int]', True, True, (<class 'int'>,))",
            "call-pair tuple ('collections.ChainMap[int, str]', True, (<class 'int'>, <class 'str'>))",
            "inst-exact tuple (True, True)",
            "type-sub tuple ('GenericAlias', True, (<class 'int'>,))",
            "inst-sub tuple ('GenericAlias', True, (<class 'str'>,))",
            "call-noargs TypeError GenericAlias expected 2 arguments, got 1 ('GenericAlias expected 2 arguments, got 1',)",
            "call-extra TypeError GenericAlias expected 2 arguments, got 3 ('GenericAlias expected 2 arguments, got 3',)",
            "call-keyword TypeError GenericAlias() takes no keyword arguments ('GenericAlias() takes no keyword arguments',)",
        ],
    );
}

// Mirrors CPython's public `ChainMap` instance `__doc__` type-attribute
// lookup while leaving full writable instance dictionaries outside this slice.
#[test]
fn cpython_collections_chainmap_instance_doc_attribute_subset() {
    assert_output(
        r#"_doc = lambda value: '<doc>' if isinstance(value, str) and value else value
from collections import ChainMap
for label, value in [('empty', ChainMap()), ('single', ChainMap({'a': 1})), ('multi', ChainMap({'a': 1}, {'b': 2}))]:
    doc = _doc(value.__doc__)
    print(label, type(doc).__name__, doc == _doc(ChainMap.__doc__), '__doc__' in dir(value), doc.split('\n')[0], len(doc))"#,
        &[
            "empty str True True <doc> 5",
            "single str True True <doc> 5",
            "multi str True True <doc> 5",
        ],
    );
}

// Mirrors CPython's public `ChainMap` direct base metadata.
#[test]
fn cpython_collections_chainmap_type_base_metadata_subset() {
    assert_output(
        r#"from collections import ChainMap
from collections.abc import MutableMapping
base = object.__getattribute__(ChainMap, '__base__')
bases = object.__getattribute__(ChainMap, '__bases__')
print('base', base is MutableMapping, base.__module__, base.__qualname__)
print('bases', type(bases).__name__, len(bases), bases[0] is MutableMapping, bases[0].__module__, bases[0].__qualname__)"#,
        &[
            "base True collections.abc MutableMapping",
            "bases tuple 1 True collections.abc MutableMapping",
        ],
    );
}

// Adapted from CPython Lib/test/test_collections.py::TestChainMap constructor
// keyword rejection.
#[test]
fn cpython_collections_chainmap_keyword_error_subset() {
    assert_output(
        concat!(
            "from collections import ChainMap\n",
            "for label, callback in [\n",
            "    ('mapping', lambda: ChainMap(mapping={'a': 1})),\n",
            "    ('first-keyword', lambda: ChainMap(a={'a': 1}, b={'b': 2})),\n",
            "    ('pos-keyword', lambda: ChainMap({'a': 1}, mapping={'b': 2})),\n",
            "]:\n",
            "    try:\n",
            "        callback()\n",
            "    except TypeError as error:\n",
            "        print(label, type(error).__name__, str(error))"
        ),
        &[
            "mapping TypeError ChainMap.__init__() got an unexpected keyword argument 'mapping'",
            "first-keyword TypeError ChainMap.__init__() got an unexpected keyword argument 'a'",
            "pos-keyword TypeError ChainMap.__init__() got an unexpected keyword argument 'mapping'",
        ],
    );
}

// Adapted from CPython Lib/test/test_collections.py::TestChainMap constructor
// storage behavior: maps are not validated until mapping operations need them.
#[test]
fn cpython_collections_chainmap_constructor_lazy_mapping_subset() {
    assert_output(
        concat!(
            "from collections import ChainMap\n",
            "for label, source in [('int', 1), ('list', []), ('none', None), ('tuple', (1, 2))]:\n",
            "    chain = ChainMap(source)\n",
            "    print(label, type(chain).__name__, repr(chain.maps))"
        ),
        &[
            "int ChainMap [1]",
            "list ChainMap [[]]",
            "none ChainMap [None]",
            "tuple ChainMap [(1, 2)]",
        ],
    );
}

// Adapted from CPython Lib/test/test_collections.py::TestChainMap constructor
// repr behavior: ChainMap renders each stored source with repr().
#[test]
fn cpython_collections_chainmap_constructor_source_repr_subset() {
    assert_output(
        concat!(
            "from collections import ChainMap\n",
            "for label, source in [('str', 'abc'), ('tuple', (1, 2)), ('dict', {'a': 1})]:\n",
            "    chain = ChainMap(source)\n",
            "    print(label, repr(chain), str(chain))"
        ),
        &[
            "str ChainMap('abc') ChainMap('abc')",
            "tuple ChainMap((1, 2)) ChainMap((1, 2))",
            "dict ChainMap({'a': 1}) ChainMap({'a': 1})",
        ],
    );
}

// Adapted from CPython Lib/test/test_collections.py::TestChainMap repr
// behavior: ChainMap subclass display uses the subclass name while rendering
// stored sources with repr().
#[test]
fn cpython_collections_chainmap_subclass_source_repr_subset() {
    assert_output(
        concat!(
            "from collections import ChainMap\n",
            "class Sub(ChainMap):\n",
            "    pass\n",
            "for label, value in [('str', Sub('abc')), ('tuple', Sub((1, 2))), ('dict', Sub({'a': 1}))]:\n",
            "    print(label, repr(value), str(value), format(value, ''))\n",
            "value = Sub('abc')\n",
            "print('method-repr', ChainMap.__repr__(value))\n",
            "print('method-str', ChainMap.__str__(value))\n",
            "print('method-format', ChainMap.__format__(value, ''))\n",
            "try:\n",
            "    print(format(value, 'x'))\n",
            "except TypeError as error:\n",
            "    print('nonempty-format', type(error).__name__, str(error))"
        ),
        &[
            "str Sub('abc') Sub('abc') Sub('abc')",
            "tuple Sub((1, 2)) Sub((1, 2)) Sub((1, 2))",
            "dict Sub({'a': 1}) Sub({'a': 1}) Sub({'a': 1})",
            "method-repr Sub('abc')",
            "method-str Sub('abc')",
            "method-format Sub('abc')",
            "nonempty-format TypeError unsupported format string passed to Sub.__format__",
        ],
    );
}

