// Adapted from CPython Lib/test/test_collections.py public namedtuple coverage.
#[test]
fn cpython_collections_namedtuple_public_subset() {
    assert_output(
        concat!(
            "from collections import namedtuple\n",
            "Point = namedtuple('Point', 'x y')\n",
            "p = Point(11, 22)\n",
            "print(Point.__name__, Point.__slots__, Point._fields)\n",
            "print(p, p.x, p.y, p[0], p[-1])\n",
            "print(tuple(p), list(p), p == (11, 22), hash(p) == hash((11, 22)))\n",
            "print(Point._make([11, 22]) == p)\n",
            "print(p._replace(x=1))\n",
            "print(p._asdict())\n",
            "print(Point(x=11, y=22) == p, Point(y=22, x=11) == p)\n",
            "Zero = namedtuple('Zero', '')\n",
            "print(Zero(), Zero._fields, Zero()._asdict())\n",
            "Dot = namedtuple('Dot', 'd')\n",
            "print(Dot(1), Dot._make([1]), Dot(1)._replace(d=2), Dot(1)._asdict())\n",
            "bad = 0\n",
            "for typename, fields in [('class', 'x y'), ('Point', 'x x'), ('Point', '_x y'), ('9Point', 'x y')]:\n",
            "    try:\n",
            "        namedtuple(typename, fields)\n",
            "    except ValueError:\n",
            "        bad += 1\n",
            "print('bad', bad)"
        ),
        &[
            "Point () ('x', 'y')",
            "Point(x=11, y=22) 11 22 11 22",
            "(11, 22) [11, 22] True True",
            "True",
            "Point(x=1, y=22)",
            "{'x': 11, 'y': 22}",
            "True True",
            "Zero() () {}",
            "Dot(d=1) Dot(d=1) Dot(d=2) {'d': 1}",
            "bad 4",
        ],
    );
}

#[test]
fn cpython_collections_namedtuple_identity_subset() {
    assert_output(
        concat!(
            "from collections import namedtuple\n",
            "Point = namedtuple('Point', 'x y')\n",
            "p = Point(1, 2)\n",
            "alias = p\n",
            "print('alias', p is alias, id(p) == id(alias))\n",
            "items = [p]\n",
            "print('list', items[0] is p, id(items[0]) == id(p))\n",
            "box = {'p': p}\n",
            "print('dict', box['p'] is p, id(box['p']) == id(p))\n",
            "class Holder:\n",
            "    pass\n",
            "holder = Holder()\n",
            "holder.value = p\n",
            "print('attr', holder.value is p, id(holder.value) == id(p))\n",
            "q = Point(1, 2)\n",
            "print('fresh', p is q, p == q, id(p) == id(q))\n",
            "print('is-not', p is not q, p is not alias)\n",
            "print('tuple-same', p is tuple(p), p == tuple(p))"
        ),
        &[
            "alias True True",
            "list True True",
            "dict True True",
            "attr True True",
            "fresh False True False",
            "is-not True False",
            "tuple-same False True",
        ],
    );
}

