// Adapted from CPython Lib/test/test_collections.py public UserDict/UserList
// coverage.
#[test]
fn cpython_collections_userdict_userlist_public_subset() {
    assert_output(
        concat!(
            "from collections import UserDict, UserList\n",
            "from copy import copy\n",
            "ud = UserDict()\n",
            "ud[123] = 'abc'\n",
            "print(ud[123], list(ud), len(ud), 123 in ud, ud.get(999))\n",
            "inner = ud.copy()\n",
            "print(inner.data is ud.data, inner.data == ud.data, type(inner).__name__)\n",
            "ud.test = [1234]\n",
            "outer = copy(ud)\n",
            "print(outer.data is ud.data, outer.data == ud.data, outer.test is ud.test)\n",
            "del ud[123]\n",
            "print(list(ud), len(ud))\n",
            "ul = UserList()\n",
            "print(ul.data, type(ul).__name__)\n",
            "ul.append(123)\n",
            "print(ul.data, list(ul), len(ul), 123 in ul)\n",
            "ul_copy = ul.copy()\n",
            "print(ul_copy.data is ul.data, ul_copy.data == ul.data, type(ul_copy).__name__)\n",
            "ul.test = [1234]\n",
            "ul_outer = copy(ul)\n",
            "print(ul_outer.data is ul.data, ul_outer.data == ul.data, ul_outer.test is ul.test)\n",
            "constructed = UserList([1, 2])\n",
            "from_userlist = UserList(constructed)\n",
            "print(constructed.data, from_userlist.data, from_userlist.data is constructed.data)\n",
            "from_userlist[0] = 9\n",
            "del from_userlist[1]\n",
            "print(from_userlist.data, constructed.data)"
        ),
        &[
            "abc [123] 1 True None",
            "False True UserDict",
            "False True True",
            "[] 0",
            "[] UserList",
            "[123] [123] 1 True",
            "False True UserList",
            "False True True",
            "[1, 2] [1, 2] False",
            "[9] [1, 2]",
        ],
    );
}

// Adapted from CPython Lib/test/test_collections.py::TestChainMap::
// test_order_preservation. OrderedDict is currently a minimal constructor
// alias over MiniPython's insertion-ordered dict storage; this test targets
// ChainMap's combined-map iteration order.
#[test]
fn cpython_collections_chainmap_order_preservation_subset() {
    assert_output(
        "from collections import ChainMap, OrderedDict as OD\nlayers = ChainMap(OD(q=1, z=26), OD(), OD(m=13, b=2), OD(z=0, a=-1, m=0, y=25), OD(), OD(b=0, c=3))\nprint(\"\".join(layers), len(layers))\nprint(list(layers.items()))\nprint(list(layers.values()), list(reversed(list(layers))))",
        &["bczamyq 7", "[('b', 2), ('c', 3), ('z', 26), ('a', -1), ('m', 13), ('y', 25), ('q', 1)]", "[2, 3, 26, -1, 13, 25, 1] ['q', 'y', 'm', 'a', 'z', 'c', 'b']"],
    );
}

// Adapted from CPython Lib/test/test_collections.py::TestChainMap::test_basics.
// This ports the copy, pickle, eval(repr(...)), repr, and object-identity
// assertions that sit beyond the basic mapping operations covered above.
#[test]
fn cpython_collections_chainmap_copy_pickle_eval_identity_subset() {
    assert_output(
        "from collections import ChainMap\nimport copy, pickle\nbase = ChainMap()\nbase[\"x\"] = 7\nbase[\"y\"] = 8\nchild = base.new_child({\"z\": 9})\nchild[\"y\"] = 80\ndel child[\"y\"]\nprint(repr(child))\nfor label, dup in ((\"method\", child.copy()), (\"copy\", copy.copy(child))):\n    print(label, dup == child, dup is child, dup.maps[0] is child.maps[0], dup.maps[1] is child.maps[1], dup.maps == child.maps)\ndef independent(dup):\n    return dup == child and dup is not child and dup.maps == child.maps and all(a is not b for a, b in zip(dup.maps, child.maps))\nprint(\"pickle\", [independent(pickle.loads(pickle.dumps(child, p))) for p in range(pickle.HIGHEST_PROTOCOL + 1)])\nprint(\"deepcopy\", independent(copy.deepcopy(child)), \"eval\", independent(eval(repr(child))))",
        &["ChainMap({'z': 9}, {'x': 7, 'y': 8})", "method True False False True True", "copy True False False True True", "pickle [True, True, True, True, True, True]", "deepcopy True eval True"],
    );
}

// Adapted from CPython Lib/test/test_collections.py::TestChainMap::test_basics.
// This keeps the sandbox manifest evidence focused on pure in-memory shallow
// copy behavior; pickle and eval identity matrices remain subset-only.
#[test]
fn cpython_collections_chainmap_copy_sharing_subset() {
    assert_output(
        "from collections import ChainMap\nimport copy\nfront = {\"k\": 1}\nback = {\"k\": 0, \"j\": 2}\ncm = ChainMap(front, back)\nshallow = cm.copy()\nalso = copy.copy(cm)\nfor dup in (shallow, also):\n    print(type(dup).__name__, dup is cm, dup == cm, dup.maps == cm.maps, dup.maps[0] is front, dup.maps[1] is back)\nshallow[\"new\"] = 1\nback[\"j\"] = 20\nprint(cm, shallow, also[\"j\"])",
        &["ChainMap False True True False True", "ChainMap False True True False True", "ChainMap({'k': 1}, {'k': 0, 'j': 20}) ChainMap({'k': 1, 'new': 1}, {'k': 0, 'j': 20}) 20"],
    );
}

// Adapted from CPython Lib/test/test_collections.py::TestChainMap::test_new_child.
// This covers a custom dict subclass used as the new child mapping; ChainMap
// lookups must respect the child's mapping protocol instead of scanning the
// child's internal dict entries directly.
#[test]
fn cpython_collections_chainmap_new_child_custom_mapping_subset() {
    assert_output(
        concat!(
            "from collections import ChainMap\n",
            "class lowerdict(dict):\n",
            "    def __getitem__(self, key):\n",
            "        if isinstance(key, str):\n",
            "            key = key.lower()\n",
            "        return dict.__getitem__(self, key)\n",
            "    def __contains__(self, key):\n",
            "        if isinstance(key, str):\n",
            "            key = key.lower()\n",
            "        return dict.__contains__(self, key)\n",
            "c = ChainMap()\n",
            "c['a'] = 1\n",
            "c['b'] = 2\n",
            "m = lowerdict(b=20, c=30)\n",
            "d = c.new_child(m)\n",
            "print(d.maps[0] is m)\n",
            "print('a' in d, 'b' in d, 'c' in d, 'B' in d, 'C' in d)\n",
            "print(d.get('a', 100), d.get('B', 100), d.get('C', 100), d.get('z', 100))\n",
            "print(d['B'], d['C'])\n",
            "c = ChainMap({'a': 1, 'b': 2})\n",
            "d = c.new_child(b=20, c=30)\n",
            "print(d.maps)"
        ),
        &[
            "True",
            "True True True True True",
            "1 20 30 100",
            "20 30",
            "[{'b': 20, 'c': 30}, {'a': 1, 'b': 2}]",
        ],
    );
}

// Adapted from CPython Lib/test/test_collections.py::TestChainMap::test_missing
// plus the first-map mutation parts of ::test_basics.
#[test]
fn cpython_collections_chainmap_missing_and_first_map_mutation_subset() {
    assert_output(
        "from collections import ChainMap\nclass Fallback(ChainMap):\n    def __missing__(self, key):\n        return f\"<{key}>\"\nfb = Fallback({\"p\": 1, \"q\": 2}, {\"q\": 3, \"r\": 4})\nkeys = \"pqrs\"\nprint(type(fb).__name__, fb.maps)\nprint([fb[k] for k in keys], [fb.get(k, \"-\") for k in keys], [k in fb for k in keys])\nplain = ChainMap({\"p\": 1}, {\"q\": 2})\nfor lookup in (lambda: plain[\"nope\"], lambda: ChainMap.__getitem__(plain, \"nope\")):\n    try:\n        lookup()\n    except KeyError as err:\n        print(\"lookup\", repr(err.args[0]), str(err))\ndef drop():\n    del plain[\"q\"]\nfor label, action in ((\"pop\", lambda: plain.pop(\"q\")), (\"delitem\", lambda: ChainMap.__delitem__(plain, \"zz\")), (\"del\", drop)):\n    try:\n        action()\n    except KeyError as err:\n        print(label, err.args[0], type(err.args[0]).__name__, str(err) == repr(err.args[0]))\nfor label, action in ((\"first empty\", lambda: ChainMap({}, {\"w\": 1}).popitem()), (\"no maps\", lambda: ChainMap().popitem())):\n    try:\n        action()\n    except KeyError as err:\n        print(label, err.args[0], str(err) == repr(err.args[0]))\nprint(fb.pop(\"p\", \"default\"), fb.maps)\nprint(fb.pop(\"p\", \"default again\"), fb.maps)\nprint(fb.popitem(), fb.maps)\ntry:\n    fb.popitem()\nexcept KeyError as err:\n    print(\"drained\", type(err).__name__)\nfb2 = Fallback({\"p\": 1}, {\"r\": 4})\nfb2.clear()\nprint(fb2.maps, dict(fb2), fb2.get(\"r\"), \"p\" in fb2, fb2[\"gone\"])\nfb2[\"t\"] = 0\nprint(fb2.maps)\ndel fb2[\"t\"]\nprint(fb2.maps, fb2[\"t\"])",
        &["Fallback [{'p': 1, 'q': 2}, {'q': 3, 'r': 4}]", "[1, 2, 4, '<s>'] [1, 2, 4, '-'] [True, True, True, False]", "lookup 'nope' 'nope'", "lookup 'nope' 'nope'", "pop Key not found in the first mapping: 'q' str True", "delitem Key not found in the first mapping: 'zz' str True", "del Key not found in the first mapping: 'q' str True", "first empty No keys found in the first mapping. True", "no maps No keys found in the first mapping. True", "1 [{'q': 2}, {'q': 3, 'r': 4}]", "default again [{'q': 2}, {'q': 3, 'r': 4}]", "('q', 2) [{}, {'q': 3, 'r': 4}]", "drained KeyError", "[{}, {'r': 4}] {'r': 4} 4 False <gone>", "[{'t': 0}, {'r': 4}]", "[{}, {'r': 4}] <t>"],
    );
}

// Adapted from CPython Lib/test/test_collections.py::TestChainMap::
// test_iter_not_calling_getitem_on_maps. ChainMap iteration should use mapping
// keys, not value lookup through the underlying map's __getitem__.
#[test]
fn cpython_collections_chainmap_iter_does_not_call_getitem_subset() {
    assert_output(
        concat!(
            "from collections import ChainMap, UserDict\n",
            "class DictWithGetItem(UserDict):\n",
            "    def __init__(self, *args, **kwds):\n",
            "        self.called = False\n",
            "        UserDict.__init__(self, *args, **kwds)\n",
            "    def __getitem__(self, item):\n",
            "        self.called = True\n",
            "        UserDict.__getitem__(self, item)\n",
            "d = DictWithGetItem(a=1)\n",
            "c = ChainMap(d)\n",
            "d.called = False\n",
            "print(set(c), d.called)"
        ),
        &["{'a'} False"],
    );
}

// Adapted from CPython Lib/test/test_collections.py::TestChainMap::test_union_operators.
#[test]
fn cpython_collections_chainmap_union_operators_subset() {
    assert_output(
        "from collections import ChainMap\nleft = ChainMap({\"a\": 1, \"b\": 2}, {\"c\": 3})\nright = ChainMap({\"b\": 20, \"x\": 9}, {\"c\": 30, \"y\": 8})\nsnapshot = left.copy()\nplain = {\"a\": 100, \"z\": 0}\nmerged = left | right\nprint(merged.maps, left.maps)\nleft |= right\nprint(left.maps, left == merged)\nprint((right | plain).maps)\nprint((plain | right).maps, type(plain | right).__name__)\nright |= plain\nprint(right.maps)\ntry:\n    snapshot | [(\"k\", 1)]\nexcept TypeError as exc:\n    print(\"pairs with |:\", type(exc).__name__)\nbefore = snapshot.copy()\nsnapshot |= [(\"k\", 1), (\"a\", -1)]\nprint(snapshot.maps, before.maps)\nclass Mine(ChainMap):\n    pass\nclass MineRor(ChainMap):\n    def __ror__(self, other):\n        return super().__ror__(other)\nr1 = Mine({\"m\": 1}) | ChainMap({\"n\": 2})\nr2 = {\"o\": 0} | Mine({\"m\": 1}, {\"n\": 2})\nr3 = ChainMap({\"m\": 1}) | Mine({\"n\": 2})\nfor r in (r1, r2, r3):\n    print(type(r).__name__, r.maps)\nfor value in (ChainMap() | ChainMap(), ChainMap() | Mine(), Mine() | ChainMap(), ChainMap() | MineRor()):\n    print(type(value).__name__, type(value.maps[0]).__name__)",
        &["[{'a': 1, 'b': 20, 'c': 30, 'y': 8, 'x': 9}, {'c': 3}] [{'a': 1, 'b': 2}, {'c': 3}]", "[{'a': 1, 'b': 20, 'c': 30, 'y': 8, 'x': 9}, {'c': 3}] True", "[{'b': 20, 'x': 9, 'a': 100, 'z': 0}, {'c': 30, 'y': 8}]", "[{'a': 100, 'z': 0, 'c': 30, 'y': 8, 'b': 20, 'x': 9}] ChainMap", "[{'b': 20, 'x': 9, 'a': 100, 'z': 0}, {'c': 30, 'y': 8}]", "pairs with |: TypeError", "[{'a': -1, 'b': 2, 'k': 1}, {'c': 3}] [{'a': 1, 'b': 2}, {'c': 3}]", "Mine [{'m': 1, 'n': 2}]", "Mine [{'o': 0, 'n': 2, 'm': 1}]", "ChainMap [{'m': 1, 'n': 2}]", "ChainMap dict", "ChainMap dict", "Mine dict", "MineRor dict"],
    );
}

// Adapted from CPython Lib/test/test_collections.py::TestNamedTuple::
// test_factory, ::test_instance, ::test_tupleness, ::test_odd_sizes, and
// ::test_match_args. This first namedtuple slice focuses on public factory,
// tuple-like instance, field-helper, and metadata behavior rather than
// CPython-only descriptor internals.
#[test]
fn cpython_collections_namedtuple_factory_instance_subset() {
    assert_output(
        concat!(
            "from collections import namedtuple\n",
            "Point = namedtuple('Point', 'x y')\n",
            "print(Point.__name__)\n",
            "print(Point.__slots__)\n",
            "print(Point.__module__)\n",
            "print(Point._fields)\n",
            "print(Point.__match_args__)\n",
            "print(Point.__getitem__ == tuple.__getitem__)\n",
            "bad_specs = [('abc%', 'efg ghi'), ('class', 'efg ghi'), ('9abc', 'efg ghi'), ('abc', 'efg g%hi'), ('abc', 'abc class'), ('abc', '8efg 9ghi'), ('abc', '_efg ghi'), ('abc', 'efg efg ghi')]\n",
            "bad_count = 0\n",
            "for typename, fields in bad_specs:\n",
            "    try:\n",
            "        namedtuple(typename, fields)\n",
            "    except ValueError:\n",
            "        bad_count += 1\n",
            "print('factory-errors', bad_count, len(bad_specs))\n",
            "Point0 = namedtuple('Point0', 'x1 y2')\n",
            "Under = namedtuple('_', 'a b c')\n",
            "print(Point0._fields, Under.__name__)\n",
            "nt = namedtuple('nt', 'the quick brown fox')\n",
            "nt2 = namedtuple('nt', ('the', 'quick'))\n",
            "print(\"u'\" in repr(nt._fields), \"u'\" in repr(nt2._fields))\n",
            "p = Point(11, 22)\n",
            "print(p)\n",
            "print(Point.__getitem__(p, 0), tuple.__getitem__(p, 1))\n",
            "print(p == Point(x=11, y=22))\n",
            "print(p == Point(11, y=22))\n",
            "print(p == Point(y=22, x=11))\n",
            "print(p == Point(*(11, 22)))\n",
            "print(p == Point(**dict(x=11, y=22)))\n",
            "print(isinstance(p, tuple))\n",
            "print(p == (11, 22), tuple(p), list(p), max(p), max(*p))\n",
            "print(hash(p) == hash((11, 22)))\n",
            "x, y = p\n",
            "print(x, y, p.x, p.y, p[0], p[-1])\n",
            "print('__weakref__' in dir(p))\n",
            "print(p[:], p[0:1], p.count(11), p.count(99), p.index(22))\n",
            "print(p._fields)\n",
            "print(Point._make([11, 22]) == p)\n",
            "print(p._replace(x=1))\n",
            "print(p._asdict())\n",
            "for call in [lambda: Point(1), lambda: Point(1, 2, 3), lambda: Point(XXX=1, y=2), lambda: Point(x=1), lambda: Point._make([11]), lambda: Point._make([11, 22, 33]), lambda: p._replace(x=1, error=2)]:\n",
            "    try:\n",
            "        call()\n",
            "    except TypeError:\n",
            "        print('TypeError')\n",
            "try:\n",
            "    p.z\n",
            "except AttributeError:\n",
            "    print('AttributeError')\n",
            "try:\n",
            "    p[3]\n",
            "except IndexError:\n",
            "    print('IndexError')\n",
            "try:\n",
            "    p.index(99)\n",
            "except ValueError:\n",
            "    print('ValueError')\n",
            "Point = namedtuple('Point', 'x, y')\n",
            "print(Point(x=11, y=22))\n",
            "Point = namedtuple('Point', ('x', 'y'))\n",
            "print(Point(x=11, y=22))\n",
            "Zero = namedtuple('Zero', '')\n",
            "print(Zero(), Zero._make([]), Zero()._asdict(), Zero()._fields)\n",
            "Dot = namedtuple('Dot', 'd')\n",
            "print(Dot(1), Dot._make([1]), Dot(1).d, Dot(1)._asdict(), Dot(1)._replace(d=999), Dot(1)._fields)\n"
        ),
        &[
            "Point",
            "()",
            "__main__",
            "('x', 'y')",
            "('x', 'y')",
            "True",
            "factory-errors 8 8",
            "('x1', 'y2') _",
            "False False",
            "Point(x=11, y=22)",
            "11 22",
            "True",
            "True",
            "True",
            "True",
            "True",
            "True",
            "True (11, 22) [11, 22] 22 22",
            "True",
            "11 22 11 22 11 22",
            "False",
            "(11, 22) (11,) 1 0 1",
            "('x', 'y')",
            "True",
            "Point(x=1, y=22)",
            "{'x': 11, 'y': 22}",
            "TypeError",
            "TypeError",
            "TypeError",
            "TypeError",
            "TypeError",
            "TypeError",
            "TypeError",
            "AttributeError",
            "IndexError",
            "ValueError",
            "Point(x=11, y=22)",
            "Point(x=11, y=22)",
            "Zero() Zero() {} ()",
            "Dot(d=1) Dot(d=1) 1 {'d': 1} Dot(d=999) ('d',)",
        ],
    );
}

// Adapted from CPython Lib/test/test_collections.py::TestNamedTuple::
// test_defaults, ::test_name_fixer, ::test_readonly, ::test_module_parameter,
// and ::test_factory_doc_attr. This keeps the public namedtuple behavior while
// avoiding CPython-only descriptor implementation details.
#[test]
fn cpython_collections_namedtuple_defaults_rename_readonly_subset() {
    assert_output(
        concat!(
            "from collections import namedtuple\n",
            "import collections\n",
            "Point = namedtuple('Point', 'x y', defaults=(10, 20))\n",
            "print(Point._field_defaults)\n",
            "print(Point.__new__.__defaults__)\n",
            "print(Point(1, 2), Point(1), Point())\n",
            "Point = namedtuple('Point', 'x y', defaults=(20,))\n",
            "print(Point._field_defaults)\n",
            "print(Point.__new__.__defaults__)\n",
            "print(Point(1, 2), Point(1))\n",
            "Point = namedtuple('Point', 'x y', defaults=())\n",
            "print(Point._field_defaults)\n",
            "print(Point.__new__.__defaults__)\n",
            "print(Point(1, 2))\n",
            "for call in [lambda: Point(1), lambda: Point(), lambda: Point(1, 2, 3), lambda: namedtuple('Point', 'x y', defaults=(10, 20, 30)), lambda: namedtuple('Point', 'x y', defaults=10), lambda: namedtuple('Point', 'x y', defaults=False)]:\n",
            "    try:\n",
            "        call()\n",
            "    except TypeError:\n",
            "        print('TypeError')\n",
            "Point = namedtuple('Point', 'x y', defaults=None)\n",
            "print(Point._field_defaults)\n",
            "print(Point.__new__.__defaults__)\n",
            "print(Point(10, 20))\n",
            "try:\n",
            "    Point(10)\n",
            "except TypeError:\n",
            "    print('TypeError')\n",
            "Point = namedtuple('Point', 'x y', defaults=[10, 20])\n",
            "print(Point._field_defaults)\n",
            "print(Point.__new__.__defaults__)\n",
            "print(Point(1, 2), Point(1), Point())\n",
            "Point = namedtuple('Point', 'x y', defaults=iter([10, 20]))\n",
            "print(Point._field_defaults)\n",
            "print(Point.__new__.__defaults__)\n",
            "print(Point(1, 2), Point(1), Point())\n",
            "for spec in [('efg', 'g%hi'), ('abc', 'class'), ('8efg', '9ghi'), ('abc', '_efg'), ('abc', 'efg', 'efg', 'ghi'), ('abc', '', 'x')]:\n",
            "    print(namedtuple('NT', spec, rename=True)._fields)\n",
            "NT = namedtuple('NT', ['x', 'y'], module=collections)\n",
            "print(NT.__module__ == collections)\n",
            "Point = namedtuple('Point', 'x y')\n",
            "print(Point.__doc__)\n",
            "Point.__doc__ = '2D point'\n",
            "print(Point.__doc__)\n",
            "p = Point(11, 22)\n",
            "for action in [lambda: setattr(p, 'x', 33), lambda: delattr(p, 'x')]:\n",
            "    try:\n",
            "        action()\n",
            "    except AttributeError:\n",
            "        print('AttributeError')\n",
            "try:\n",
            "    p[0] = 33\n",
            "except TypeError:\n",
            "    print('TypeError')\n",
            "try:\n",
            "    del p[0]\n",
            "except TypeError:\n",
            "    print('TypeError')\n",
            "print(p.x, p[0])\n",
        ),
        &[
            "{'x': 10, 'y': 20}",
            "(10, 20)",
            "Point(x=1, y=2) Point(x=1, y=20) Point(x=10, y=20)",
            "{'y': 20}",
            "(20,)",
            "Point(x=1, y=2) Point(x=1, y=20)",
            "{}",
            "()",
            "Point(x=1, y=2)",
            "TypeError",
            "TypeError",
            "TypeError",
            "TypeError",
            "TypeError",
            "TypeError",
            "{}",
            "None",
            "Point(x=10, y=20)",
            "TypeError",
            "{'x': 10, 'y': 20}",
            "(10, 20)",
            "Point(x=1, y=2) Point(x=1, y=20) Point(x=10, y=20)",
            "{'x': 10, 'y': 20}",
            "(10, 20)",
            "Point(x=1, y=2) Point(x=1, y=20) Point(x=10, y=20)",
            "('efg', '_1')",
            "('abc', '_1')",
            "('_0', '_1')",
            "('abc', '_1')",
            "('abc', 'efg', '_2', 'ghi')",
            "('abc', '_1', 'x')",
            "True",
            "Point(x, y)",
            "2D point",
            "AttributeError",
            "AttributeError",
            "TypeError",
            "TypeError",
            "11 11",
        ],
    );
}

// Adapted from CPython Lib/test/test_collections.py::TestNamedTuple::
