#[test]
fn cpython_collections_namedtuple_copy_keyword_generic_alias_subset() {
    assert_output(
        concat!(
            "from collections import namedtuple\n",
            "import collections\n",
            "import copy\n",
            "Point = namedtuple('Point', 'x y z')\n",
            "p = Point(10, 20, 30)\n",
            "for copier in [copy.copy, copy.deepcopy]:\n",
            "    q = copier(p)\n",
            "    print(p == q, p._fields == q._fields, q)\n",
            "try:\n",
            "    namedtuple('NT', ['x', 'y'], True)\n",
            "except TypeError:\n",
            "    print('TypeError')\n",
            "NT = namedtuple('NT', ['abc', 'def'], rename=True)\n",
            "print(NT._fields)\n",
            "try:\n",
            "    namedtuple('NT', ['abc', 'def'], False, True)\n",
            "except TypeError:\n",
            "    print('TypeError')\n",
            "Group = collections.namedtuple('Group', 'key group')\n",
            "A = Group[int, list[int]]\n",
            "print(A.__origin__ == Group, A.__parameters__, A.__args__ == (int, list[int]))\n",
            "a = A(1, [2])\n",
            "print(type(a) is Group, a == (1, [2]), a)\n",
        ),
        &[
            "True True Point(x=10, y=20, z=30)",
            "True True Point(x=10, y=20, z=30)",
            "TypeError",
            "('abc', '_1')",
            "TypeError",
            "True () True",
            "True True Group(key=1, group=[2])",
        ],
    );
}

// Adapted from CPython Lib/test/test_collections.py::TestNamedTuple::
// test_name_conflicts. This keeps the full public field-name conflict matrix
// while printing behavioral checks instead of depending on set display order.
#[test]
fn cpython_collections_namedtuple_name_conflicts_subset() {
    assert_output(
        "from collections import namedtuple\nimport builtins\nTiny = namedtuple(\"Tiny\", [\"self\", \"cls\", \"tuple\", \"property\", \"itemgetter\"])\nt = Tiny(5, 4, 3, 2, 1)\nprint(t == (5, 4, 3, 2, 1), t._replace(self=0, cls=0, tuple=0, property=0, itemgetter=0) == (0,) * 5, t.self, t.tuple)\nrisky = [n for n in dir(builtins) if n.isidentifier() and not n.startswith(\"_\") and n not in (\"True\", \"False\", \"None\")]\nrisky += [\"self\", \"cls\", \"typename\", \"field_names\", \"rename\", \"defaults\", \"module\", \"num_fields\",\n          \"arg_list\", \"repr_fmt\", \"tuple_new\", \"namespace\", \"result\", \"itemgetter\", \"sys\",\n          \"f_globals\", \"kwds\", \"iterable\", \"index\", \"count\"]\nrisky = list(dict.fromkeys(risky))\nWide = namedtuple(\"Wide\", risky)\nvals = tuple(range(100, 100 + len(risky)))\nw = Wide._make(vals)\nchecks = [\n    Wide(*vals) == vals,\n    Wide(**dict(zip(risky, vals))) == vals,\n    w == vals,\n    repr(w).startswith(\"Wide(\"),\n    w._asdict() == dict(zip(risky, vals)),\n    w._replace(**{n: -v for n, v in zip(risky, vals)}) == tuple(-v for v in vals),\n    Wide._fields == tuple(risky),\n    w.__getnewargs__() == vals,\n    all(getattr(w, n) == v for n, v in zip(risky, vals)),\n]\nprint(len(risky) > 100, checks)",
        &["True True 5 3", "True [True, True, True, True, True, True, True, True, True]"],
    );
}

