// Adapted from CPython Lib/test/test_collections.py::TestNamedTuple::
// test_pickle. MiniPython's pickle module uses an internal payload rather than
// CPython's binary pickle byte stream, so this ports the public round-trip
// semantics and protocol acceptance.
#[test]
fn cpython_collections_namedtuple_pickle_subset() {
    assert_output(
        concat!(
            "import pickle\n",
            "from collections import namedtuple\n",
            "TestNT = namedtuple('TestNT', 'x y z')\n",
            "p = TestNT(x=10, y=20, z=30)\n",
            "protocols = [-1] + list(range(pickle.HIGHEST_PROTOCOL + 1))\n",
            "checked = 0\n",
            "for protocol in protocols:\n",
            "    payload = pickle.dumps(p, protocol)\n",
            "    q = pickle.loads(payload)\n",
            "    if p == q and p._fields == q._fields and type(q) is TestNT:\n",
            "        checked += 1\n",
            "print('pickle', checked, len(protocols))\n",
            "Box = namedtuple('Box', 'items')\n",
            "box = Box([1, 2])\n",
            "restored = pickle.loads(pickle.dumps(box, -1))\n",
            "restored.items.append(3)\n",
            "print(box.items, restored.items, box.items is restored.items)\n",
        ),
        &["pickle 7 7", "[1, 2] [1, 2, 3] False"],
    );
}

// Adapted from CPython Lib/test/test_collections.py::TestNamedTuple::
// test_field_doc. CPython-specific descriptor reuse and repr details are
// tracked separately because they validate implementation internals.
#[test]
fn cpython_collections_namedtuple_field_doc_subset() {
    assert_output(
        concat!(
            "from collections import namedtuple\n",
            "Point = namedtuple('Point', 'x y')\n",
            "print(Point.x.__doc__)\n",
            "print(Point.y.__doc__)\n",
            "Point.x.__doc__ = 'docstring for Point.x'\n",
            "print(Point.x.__doc__)\n",
            "print(Point(11, 22).x)\n",
            "Vector = namedtuple('Vector', 'x y')\n",
            "print(Vector.x.__doc__)\n",
            "Vector.x.__doc__ = 'docstring for Vector.x'\n",
            "print(Vector.x.__doc__)\n",
            "print(Point.x.__doc__)\n",
            "print(Point.x.__get__(None, Point) is Point.x)\n",
            "point = Point(11, 22)\n",
            "print(Point.x.__get__(point, Point))\n",
            "print(Point.x.__get__(point, None))\n",
            "for label, expected, expr in [\n",
            "    ('missing', '__get__ expected at least 1 argument, got 0', lambda: Point.x.__get__()),\n",
            "    ('too-many', '__get__ expected at most 2 arguments, got 3', lambda: Point.x.__get__(point, Point, 1)),\n",
            "    ('keyword', 'wrapper __get__() takes no keyword arguments', lambda: Point.x.__get__(obj=point, type=Point)),\n",
            "    ('bad-keyword', 'wrapper __get__() takes no keyword arguments', lambda: Point.x.__get__(bad=1)),\n",
            "    ('none-only', '__get__(None, None) is invalid', lambda: Point.x.__get__(None)),\n",
            "    ('none-none', '__get__(None, None) is invalid', lambda: Point.x.__get__(None, None)),\n",
            "]:\n",
            "    try:\n",
            "        expr()\n",
            "    except TypeError as error:\n",
            "        print(label, error.__class__.__name__, str(error), str(error) == expected)\n",
        ),
        &[
            "Alias for field number 0",
            "Alias for field number 1",
            "docstring for Point.x",
            "11",
            "Alias for field number 0",
            "docstring for Vector.x",
            "docstring for Point.x",
            "True",
            "11",
            "11",
            "missing TypeError __get__ expected at least 1 argument, got 0 True",
            "too-many TypeError __get__ expected at most 2 arguments, got 3 True",
            "keyword TypeError wrapper __get__() takes no keyword arguments True",
            "bad-keyword TypeError wrapper __get__() takes no keyword arguments True",
            "none-only TypeError __get__(None, None) is invalid True",
            "none-none TypeError __get__(None, None) is invalid True",
        ],
    );
}

// Mirrors CPython public collections.Counter __class_getitem__ behavior. This
// pins GenericAlias origin/args, direct type calls, exact instance lookup, and
// inherited subclass lookup without expanding Counter beyond the documented
// pure-memory mapping surface.
#[test]
fn cpython_collections_counter_class_getitem_generic_alias_subset() {
    assert_output(
        r#"from collections import Counter
typ = Counter
inst = Counter()
class C(Counter):
    pass
for label, expr in [
    ('visible', lambda: (hasattr(typ, '__class_getitem__'), '__class_getitem__' in dir(typ), type(typ.__class_getitem__).__name__)),
    ('visible-inst', lambda: (hasattr(inst, '__class_getitem__'), '__class_getitem__' in dir(inst))),
    ('subscript-int', lambda: (type(typ[int]).__name__, str(typ[int]), typ[int].__origin__ is typ, typ[int].__args__)),
    ('call-int', lambda: (type(typ.__class_getitem__(int)).__name__, str(typ.__class_getitem__(int)), typ.__class_getitem__(int) == typ[int], typ.__class_getitem__(int).__origin__ is typ, typ.__class_getitem__(int).__args__)),
    ('call-pair', lambda: (str(typ.__class_getitem__((int, str))), typ.__class_getitem__((int, str)) == typ[int, str], typ.__class_getitem__((int, str)).__args__)),
    ('inst-exact', lambda: (inst.__class_getitem__(int) == typ[int], inst.__class_getitem__(int).__origin__ is typ)),
    ('type-sub', lambda: (hasattr(C, '__class_getitem__'), '__class_getitem__' in dir(C), type(C.__class_getitem__).__name__, type(C.__class_getitem__(int)).__name__, C.__class_getitem__(int).__origin__ is C, C.__class_getitem__(int).__args__)),
    ('inst-sub', lambda: (hasattr(C(), '__class_getitem__'), '__class_getitem__' in dir(C()), type(C().__class_getitem__(str)).__name__, C().__class_getitem__(str).__origin__ is C, C().__class_getitem__(str).__args__)),
    ('call-noargs', lambda: typ.__class_getitem__()),
    ('call-extra', lambda: typ.__class_getitem__(int, str)),
    ('call-keyword', lambda: typ.__class_getitem__(item=int)),
    ('sub-keyword', lambda: C.__class_getitem__(item=int)),
]:
    try:
        result = expr()
        print(label, type(result).__name__, result)
    except Exception as error:
        print(label, type(error).__name__, str(error), error.args)"#,
        &[
            "visible tuple (True, True, 'builtin_function_or_method')",
            "visible-inst tuple (True, True)",
            "subscript-int tuple ('GenericAlias', 'collections.Counter[int]', True, (<class 'int'>,))",
            "call-int tuple ('GenericAlias', 'collections.Counter[int]', True, True, (<class 'int'>,))",
            "call-pair tuple ('collections.Counter[int, str]', True, (<class 'int'>, <class 'str'>))",
            "inst-exact tuple (True, True)",
            "type-sub tuple (True, True, 'builtin_function_or_method', 'GenericAlias', True, (<class 'int'>,))",
            "inst-sub tuple (True, True, 'GenericAlias', True, (<class 'str'>,))",
            "call-noargs TypeError Counter.__class_getitem__() takes exactly one argument (0 given) ('Counter.__class_getitem__() takes exactly one argument (0 given)',)",
            "call-extra TypeError Counter.__class_getitem__() takes exactly one argument (2 given) ('Counter.__class_getitem__() takes exactly one argument (2 given)',)",
            "call-keyword TypeError Counter.__class_getitem__() takes no keyword arguments ('Counter.__class_getitem__() takes no keyword arguments',)",
            "sub-keyword TypeError C.__class_getitem__() takes no keyword arguments ('C.__class_getitem__() takes no keyword arguments',)",
        ],
    );
}

