// Adapted from CPython Lib/test/test_collections.py::TestCounter::test_basics.
// This first Counter slice covers the public mapping-style behavior and core
// Counter helpers; arithmetic and multiset-specific methods remain separate.
#[test]
fn cpython_collections_counter_basics_subset() {
    assert_output(
        "from collections import Counter, OrderedDict\nfrom collections.abc import Mapping, Reversible\ntally = Counter(\"mississippi\")\nprint(tally == Counter({\"i\": 4, \"s\": 4, \"p\": 2, \"m\": 1}), tally == Counter(i=4, s=4, p=2, m=1), tally == {\"m\": 1, \"i\": 4, \"s\": 4, \"p\": 2})\nprint(isinstance(tally, dict), isinstance(tally, Mapping), issubclass(Counter, dict), issubclass(Counter, Mapping))\nprint(len(tally), sum(tally.values()), list(tally), list(tally.values()), list(tally.items()))\nprint(tally[\"s\"], tally[\"q\"], \"p\" in tally, \"q\" in tally, tally.get(\"m\", -1), tally.get(\"q\", -1))\nprint(repr(tally))\nprint(tally.most_common(), [tally.most_common(n) for n in (0, 1, 2, 9)])\nprint(\"\".join(tally.elements()))\ntally[\"m\"] += 2\ntally[\"p\"] -= 2\ndel tally[\"i\"]\ndel tally[\"i\"]\ntally[\"x\"] -= 3\ntally[\"y\"] = -1\ntally[\"z\"] += 5\nprint(dict(tally), \"\".join(tally.elements()))\nprint(tally.pop(\"z\"), \"z\" in tally)\nfor _ in range(2):\n    key, count = tally.popitem()\n    print(key, count, key in tally)\ntally.clear()\nprint(tally == {}, repr(tally))\nfor label, action in ((\"fromkeys\", lambda: Counter.fromkeys(\"ab\")), (\"hash\", lambda: hash(Counter()))):\n    try:\n        action()\n    except (NotImplementedError, TypeError) as exc:\n        print(label, type(exc).__name__)\ntally.update({\"a\": 2, \"b\": 1})\ntally.update(c=3)\ntally.update(Counter(\"aab\"))\ntally.update()\ntally.__init__(\"ccc\")\ntally.__init__()\nprint(sorted(tally.items()))\nprint(tally.setdefault(\"a\", 100), tally.setdefault(\"new\", 7), tally[\"new\"])\nprint(isinstance(OrderedDict(), Reversible), isinstance(Counter(), Reversible), list(reversed(Counter(\"xyzx\"))))",
        &["True True True", "True True True True", "4 11 ['m', 'i', 's', 'p'] [1, 4, 4, 2] [('m', 1), ('i', 4), ('s', 4), ('p', 2)]", "4 0 True False 1 -1", "Counter({'i': 4, 's': 4, 'p': 2, 'm': 1})", "[('i', 4), ('s', 4), ('p', 2), ('m', 1)] [[], [('i', 4)], [('i', 4), ('s', 4)], [('i', 4), ('s', 4), ('p', 2), ('m', 1)]]", "miiiisssspp", "{'m': 3, 's': 4, 'p': 0, 'x': -3, 'y': -1, 'z': 5} mmmsssszzzzz", "5 False", "y -1 False", "x -3 False", "True Counter()", "fromkeys NotImplementedError", "hash TypeError", "[('a', 4), ('b', 2), ('c', 6)]", "4 7 7", "True True ['z', 'y', 'x']"],
    );
}

