// Adapted from CPython Lib/test/test_compile.py::TestSourcePositions::
// test_multiline_assert_rewritten_as_method_call. This covers the public-AST
// compile path used by the source-position suite without claiming MiniPython
// has CPython's full code-object co_positions() model.
#[test]
fn cpython_compile_source_positions_multiline_assert_rewrite_subset() {
    assert_output(
        "import ast\nmodule = ast.parse(\"assert (\\n    flag\\n    and other\\n)\")\noriginal = module.body[0]\ncall = ast.Call(\n    func=ast.Attribute(value=ast.Name(id=\"checker\", ctx=ast.Load()), attr=\"verify\", ctx=ast.Load()),\n    args=[ast.Constant(value=\"from rewrite\")],\n    keywords=[],\n)\nreplacement = ast.copy_location(ast.Expr(value=call), original)\nast.fix_missing_locations(replacement)\nmodule.body[0] = replacement\ncode = compile(module, \"<rewritten>\", \"exec\")\nseen = []\nclass Checker:\n    def verify(self, value):\n        seen.append(value)\nexec(code, {\"checker\": Checker()})\nprint(seen, type(code).__name__)",
        &["['from rewrite'] code"],
    );
}

// Adapted from CPython Lib/test/test_compile.py::TestSourcePositions::
// test_simple_assignment. CPython checks that every non-artificial
// `co_positions()` line/column value belongs to one of the public AST offsets
// for the same source; `x = 1` exposes CPython's artificial module-start span
// plus the assignment value token rather than the whole physical line.
#[test]
fn cpython_compile_source_positions_code_positions_first_pass_subset() {
    assert_output(
        r#"co = compile("x = 1", "test_compile.py", "exec")
positions = list(co.co_positions())
print(positions)
print([line for line, end_line, col, end_col in positions])
print([line == end_line for line, end_line, col, end_col in positions])
print([
    (line, end_line, col, end_col) == (0, 1, 0, 0)
    or (line == 1 and end_line == 1 and col == 4 and end_col == 5)
    for line, end_line, col, end_col in positions
])"#,
        &[
            "[(0, 1, 0, 0), (1, 1, 4, 5)]",
            "[0, 1]",
            "[False, True]",
            "[True, True]",
        ],
    );
}

// Adapted from CPython Lib/test/test_compile.py::TestSourcePositions::
// test_lambda_return_position. MiniPython does not expose CPython opcode
// positions, but lambda code-object positions now stay inside the lambda body
// expression columns for the same public snippets.
