fn cpython_compile_source_positions_lambda_return_position_subset() {
    assert_output(
        "sources = [\"g = lambda: value\", \"g = lambda: 7 * 6\", \"g = lambda: left - right\", \"g = lambda: 'text'\"]\nfor text in sources:\n    scope = {}\n    exec(text, scope)\n    body_start = text.index(\":\") + 2\n    spans = list(scope[\"g\"].__code__.co_positions())\n    inside = [l1 == l2 == 1 and body_start <= c1 <= c2 <= len(text) for (l1, l2, c1, c2) in spans if (c1, c2) != (0, 0)]\n    print(text, bool(inside), all(inside))",
        &["g = lambda: value True True", "g = lambda: 7 * 6 True True", "g = lambda: left - right True True", "g = lambda: 'text' True True"],
    );
}

