fn cpython_compile_specifics_lineno_attribute_subset() {
    assert_output(
        "def rel_lines(code):\n    out = []\n    for _start, _end, ln in code.co_lines():\n        if ln is not None:\n            rel = ln - code.co_firstlineno\n            if not out or out[-1] != rel:\n                out.append(rel)\n    return out\n\ndef read_field():\n    return (\n        target\n        .field\n    )\n\ndef call_method():\n    return (\n        target.\n        method(\n            1,\n            2,\n        )\n    )\n\ndef write_field():\n    (\n        target\n        .field\n    ) = (\n        value\n    )\n\ndef bump_field():\n    (\n        target\n        .field\n    ) -= (\n        value\n    )\n\nfor fn in (read_field, call_method, write_field, bump_field):\n    print(fn.__name__, rel_lines(fn.__code__))",
        &["read_field [0, 2, 3, 1]", "call_method [0, 2, 3, 4, 5, 3, 1]", "write_field [0, 5, 2, 3]", "bump_field [0, 2, 3, 5, 1, 3]"],
    );
}

