// Adapted from CPython Lib/test/test_compile.py::TestSpecifics::
// test_lineno_after_implicit_return. This pins the public frame-line behavior:
// an implicit function return should leave `f_lineno` on the last executed
// source line, not on a skipped branch body.
#[test]
fn cpython_compile_specifics_lineno_after_implicit_return_subset() {
    assert_output(
        "import sys\nON = 1\ncaptured = []\ndef grab(*args):\n    captured.append(sys._getframe(1))\ndef only_if(cb):\n    cb(\"start\")\n    if ON:\n        pass\ndef with_else(cb):\n    cb()\n    if ON > 0:\n        pass\n    else:\n        pass\ndef else_return(cb):\n    cb()\n    if ON:\n        pass\n    else:\n        return cb\ndef negated(cb):\n    cb()\n    if not ON:\n        pass\nfor fn in (only_if, with_else, else_return, negated):\n    fn(grab)\n    frame = captured.pop()\n    print(fn.__name__, frame.f_lineno - fn.__code__.co_firstlineno)",
        &["only_if 3", "with_else 3", "else_return 3", "negated 2"],
    );
}

