// Adapted from CPython Lib/test/test_compile.py::TestSpecifics::
// test_line_number_synthetic_jump_multiple_predecessors,
// test_line_number_synthetic_jump_multiple_predecessors_nested, and
// test_line_number_synthetic_jump_multiple_predecessors_more_nested. CPython
// checks `JUMP_BACKWARD` opcode positions through `dis`; MiniPython pins the
// public function `co_lines()` order for the same try/loop cold-block shapes.
#[test]
fn cpython_compile_specifics_synthetic_jump_line_tables_subset() {
    assert_output(
        "def rel_lines(code):\n    out = []\n    for _start, _end, ln in code.co_lines():\n        if ln is not None:\n            rel = ln - code.co_firstlineno\n            if not out or out[-1] != rel:\n                out.append(rel)\n    return out\n\ndef drain_gen(queue):\n    while queue:\n        item = queue.pop()\n        try:\n            if item:\n                yield item\n        except LookupError:\n            item = None\n\ndef two_level(rows):\n    total = 0\n    for row in rows:\n        try:\n            total += row[0]\n        except IndexError:\n            try:\n                if row:\n                    total += 1\n            except TypeError:\n                total = 0\n    return total\n\ndef three_level(rows):\n    for row in rows:\n        try:\n            row.go()\n        except AttributeError:\n            try:\n                if row:\n                    if row > 1:\n                        row = 2\n            except TypeError:\n                try:\n                    if not row:\n                        if row is None:\n                            row = 3\n                except ValueError:\n                    pass\n    return rows\n\nfor fn in (drain_gen, two_level, three_level):\n    print(fn.__name__, rel_lines(fn.__code__))",
        &["drain_gen [0, 1, 2, 3, 4, 5, 4, 1, 6, 7, 6]", "two_level [0, 1, 2, 3, 4, 2, 11, 5, 6, 7, 8, 7, 9, 10, 9, 5]", "three_level [0, 1, 2, 3, 1, 16, 4, 5, 6, 7, 8, 7, 6, 9, 10, 11, 12, 13, 12, 11, 14, 15, 14, 9, 4]"],
    );
}

