fn cpython_compile_static_attributes_exact_subset() {
    assert_output(
        "class Point:\n    def setup(self):\n        self.px = self.py = 0\n        self.setup()\n        self.items[0]\n        self.px += 1\nprint(type(Point.__static_attributes__).__name__, sorted(Point.__static_attributes__))",
        &["tuple ['px', 'py']"],
    );
    assert_output(
        "class Many:\n    def one(self):\n        self.k = 1\n        self.m = 2\n        self.k = 3\n    def two(self, other):\n        self.m = 4\n        self.n = 5\n        def nested(self, q):\n            self.w = 6\n        other.self = 7\n        other.j = 8\nprint(sorted(Many.__static_attributes__))",
        &["['k', 'm', 'n', 'w']"],
    );
    assert_output(
        "class Outer:\n    def a(self):\n        self.p = 1\n    class Inner:\n        def b(self):\n            self.q = 2\n            self.p = 3\nclass Sub(Outer):\n    def c(self):\n        self.r = 4\nprint(sorted(Outer.__static_attributes__), sorted(Outer.Inner.__static_attributes__), sorted(Sub.__static_attributes__))",
        &["['p'] ['p', 'q'] ['r']"],
    );
}

// Adapted from CPython Lib/test/test_type_params.py examples for function,
// class, and type-alias type parameters. MiniPython keeps the same observable
// metadata surface for the supported subset: __type_params__, __name__,
// __bound__, __constraints__, __default__, and __value__.
#[test]
fn cpython_type_params_metadata_subset() {
    assert_output(
        "def func[T: int = str](x: T) -> T:\n    return x\nprint(func.__type_params__[0].__name__, func.__type_params__[0].__bound__.__name__, func.__type_params__[0].__default__.__name__)\nprint(func.__annotations__[\"x\"].__name__, func.__annotations__[\"return\"].__name__)",
        &["T int str", "T T"],
    );
    assert_output(
        "class ClassA[X: int = str]:\n    pass\nprint(ClassA.__type_params__[0].__name__, ClassA.__type_params__[0].__bound__.__name__, ClassA.__type_params__[0].__default__.__name__)",
        &["X int str"],
    );
    assert_output(
        "class Base:\n    pass\nclass ClassA[X](Base):\n    pass\nprint(ClassA.__type_params__[0].__name__, ClassA.__bases__[0].__name__)",
        &["X Base"],
    );
    assert_output(
        "type Alias[T: int = str] = int\nprint(Alias.__name__, Alias.__value__.__name__, Alias.__type_params__[0].__name__)",
        &["Alias int T"],
    );
    assert_output(
        "def trailing[T,]():\n    pass\nclass Generic[T, *Ts, **P,]:\n    pass\ntype Alias[T, *Ts, **P,] = int\nprint(trailing.__type_params__[0].__name__)\nprint(Generic.__type_params__[0].__name__, Generic.__type_params__[1].__kind__, Generic.__type_params__[2].__kind__)\nprint(Alias.__type_params__[0].__name__, Alias.__type_params__[1].__kind__, Alias.__type_params__[2].__kind__)",
        &["T", "T TypeVarTuple ParamSpec", "T TypeVarTuple ParamSpec"],
    );
    assert_output(
        "def constrained[T: (int, str) = bool]():\n    pass\nT, = constrained.__type_params__\nprint(T.__constraints__[0].__name__, T.__constraints__[1].__name__, T.__bound__, T.__default__.__name__)",
        &["int str None bool"],
    );
}

// Adapted from CPython
// Lib/test/test_type_params.py::TypeParamsTypeParamsDunder. Function and class
// type-parameter objects are available to nested scopes, exposed through
// __type_params__ / __parameters__, and can be overridden by attribute assignment.
#[test]
fn cpython_type_params_dunder_subset() {
    assert_output(
        "class Bare:\n    pass\ndef bare():\n    pass\nprint(Bare.__type_params__, bare.__type_params__, getattr(Bare, \"__parameters__\", \"absent\"))",
        &["() () absent"],
    );
    assert_output(
        "class Pairing[Left, Right]:\n    pass\nprint([t.__name__ for t in Pairing.__type_params__], [t.__name__ for t in Pairing.__parameters__])\nprint(Pairing.__parameters__ == Pairing.__type_params__, \"__parameters__\" in dir(Pairing))",
        &["['Left', 'Right'] ['Left', 'Right']", "True True"],
    );
    assert_output(
        "class Shell[P, Q]:\n    class Core[R, S]:\n        @classmethod\n        def capture(cls):\n            return (P, Q), (R, S)\nouter_pair, inner_pair = Shell.Core.capture()\nprint(Shell.__type_params__ == outer_pair, Shell.__parameters__ == outer_pair)\nprint(Shell.Core.__type_params__ == inner_pair, Shell.Core.__parameters__ == inner_pair)\nprint(any(n in vars(Shell) for n in \"PQ\"), any(n in vars(Shell.Core) for n in \"RS\"))",
        &["True True", "True True", "False False"],
    );
    assert_output(
        "def wrap[P, Q]():\n    def unwrap[R]():\n        return P, Q, R\n    return unwrap\nunwrap = wrap()\np, q, r = unwrap()\nprint(wrap.__type_params__ == (p, q), unwrap.__type_params__ == (r,))",
        &["True True"],
    );
    assert_output(
        "class Reset[Z]:\n    pass\ndef reset[Z]():\n    pass\nReset.__type_params__ = ()\nreset.__type_params__ = (\"replaced\",)\nprint(Reset.__type_params__, reset.__type_params__)",
        &["() ('replaced',)"],
    );
}

// Adapted from CPython Lib/test/test_type_params.py examples that combine
// type parameter scopes with parameterized class bases and annotations.
