// Adapted from CPython Lib/test/test_types.py::CoroutineTests. This covers the
// public `types.coroutine()` behavior MiniPython supports: wrong argument
// rejection, non-generator return pass-through, native coroutine function
// identity, coroutine-like object pass-through, iterable coroutine pass-through,
// generator-function idempotence and flags, and `_GeneratorWrapper` forwarding
// for native and functional duck generators, including generator frame and
// yield-from introspection aliases.
#[test]
fn cpython_types_coroutine_public_subset() {
    assert_output(
        concat!(
            "import types, inspect\n",
            "for expr in [lambda: types.coroutine(None), lambda: types.coroutine(1), lambda: types.coroutine(object())]:\n",
            "    try:\n",
            "        expr()\n",
            "    except TypeError as error:\n",
            "        print('wrong', type(error).__name__, 'expects a callable' in str(error))\n",
            "@types.coroutine\n",
            "def non_gen_string():\n",
            "    return 'spam'\n",
            "print('non-gen-string', non_gen_string())\n",
            "class Awaitable:\n",
            "    def __await__(self):\n",
            "        return iter(())\n",
            "aw = Awaitable()\n",
            "@types.coroutine\n",
            "def non_gen_awaitable():\n",
            "    return aw\n",
            "print('non-gen-awaitable', non_gen_awaitable() is aw)\n",
            "non_gen_awaitable = types.coroutine(non_gen_awaitable)\n",
            "print('non-gen-awaitable-2', non_gen_awaitable() is aw)\n",
            "async def native():\n",
            "    return 'native'\n",
            "decorated_native = types.coroutine(native)\n",
            "print('native-identity', decorated_native is native)\n",
            "coro = decorated_native()\n",
            "print('native-type', type(coro).__name__, isinstance(coro, types.CoroutineType), coro.__class__ is types.CoroutineType)\n",
            "print('native-close', coro.close())\n",
            "class CoroLike:\n",
            "    def send(self, value=None):\n",
            "        return value\n",
            "    def throw(self, *args):\n",
            "        return args\n",
            "    def close(self):\n",
            "        return None\n",
            "    def __await__(self):\n",
            "        return self\n",
            "coro_like = CoroLike()\n",
            "@types.coroutine\n",
            "def returns_coro_like():\n",
            "    return coro_like\n",
            "print('duck-coro', returns_coro_like() is coro_like, returns_coro_like().__await__() is coro_like)\n",
            "class CoroGenLike(CoroLike):\n",
            "    def __iter__(self):\n",
            "        return self\n",
            "    def __next__(self):\n",
            "        raise StopIteration\n",
            "coro_gen_like = CoroGenLike()\n",
            "@types.coroutine\n",
            "def returns_coro_gen_like():\n",
            "    return coro_gen_like\n",
            "print('duck-corogen', returns_coro_gen_like() is coro_gen_like, returns_coro_gen_like().__await__() is coro_gen_like)\n",
            "@types.coroutine\n",
            "def iterable_coro():\n",
            "    yield 'tick'\n",
            "gencoro = iterable_coro()\n",
            "@types.coroutine\n",
            "def returns_itercoro():\n",
            "    return gencoro\n",
            "print('returning-itercoro', returns_itercoro() is gencoro)\n",
            "returns_itercoro = types.coroutine(returns_itercoro)\n",
            "print('returning-itercoro-2', returns_itercoro() is gencoro)\n",
            "def gen():\n",
            "    yield 'x'\n",
            "print('genfunc-id', types.coroutine(gen) is gen, types.coroutine(types.coroutine(gen)) is gen)\n",
            "print('gen-flags', bool(gen.__code__.co_flags & inspect.CO_ITERABLE_COROUTINE), bool(gen.__code__.co_flags & inspect.CO_COROUTINE))\n",
            "g = gen()\n",
            "print('gen-code-flags', bool(g.gi_code.co_flags & inspect.CO_ITERABLE_COROUTINE), bool(g.gi_code.co_flags & inspect.CO_COROUTINE))\n",
            "print('gen-run', next(g), type(g).__name__)\n",
            "try:\n",
            "    next(g)\n",
            "except StopIteration:\n",
            "    print('gen-stop')\n",
            "def keyword_gen():\n",
            "    yield 'kw'\n",
            "keyword_decorated = types.coroutine(func=keyword_gen)\n",
            "print('keyword-func', keyword_decorated is keyword_gen, next(keyword_decorated()))\n",
            "for label, expr in [\n",
            "    ('keyword-bad', lambda: types.coroutine(bad=keyword_gen)),\n",
            "    ('keyword-dup', lambda: types.coroutine(keyword_gen, func=keyword_gen)),\n",
            "    ('keyword-missing', lambda: types.coroutine()),\n",
            "]:\n",
            "    try:\n",
            "        expr()\n",
            "    except TypeError as error:\n",
            "        print(label, str(error))"
        ),
        &[
            "wrong TypeError True",
            "wrong TypeError True",
            "wrong TypeError True",
            "non-gen-string spam",
            "non-gen-awaitable True",
            "non-gen-awaitable-2 True",
            "native-identity True",
            "native-type coroutine True True",
            "native-close None",
            "duck-coro True True",
            "duck-corogen True True",
            "returning-itercoro True",
            "returning-itercoro-2 True",
            "genfunc-id True True",
            "gen-flags True False",
            "gen-code-flags True False",
            "gen-run x generator",
            "gen-stop",
            "keyword-func True kw",
            "keyword-bad coroutine() got an unexpected keyword argument 'bad'",
            "keyword-dup coroutine() got multiple values for argument 'func'",
            "keyword-missing coroutine() missing 1 required positional argument: 'func'",
        ],
    );
}

#[test]
fn cpython_types_coroutine_async_def_subset() {
    assert_output(
        concat!(
            "import types\n",
            "async def running_cr():\n",
            "    print('cr-running-inside', running_coro.cr_running)\n",
            "    return running_coro.cr_running\n",
            "running_coro = running_cr()\n",
            "print('cr-running-before', running_coro.cr_running)\n",
            "try:\n",
            "    running_coro.send(None)\n",
            "except StopIteration as done:\n",
            "    print('cr-running-stop', done.value, running_coro.cr_running)\n",
            "async def foo():\n",
            "    pass\n",
            "foo_code = foo.__code__\n",
            "foo_flags = foo.__code__.co_flags\n",
            "decorated_foo = types.coroutine(foo)\n",
            "print('func-id', foo is decorated_foo)\n",
            "print('flags-stable', foo.__code__.co_flags == foo_flags)\n",
            "print('code-is', decorated_foo.__code__ is foo_code)\n",
            "foo_coro = foo()\n",
            "print('cr-frame-open', type(foo_coro.cr_frame).__name__, foo_coro.cr_frame is foo_coro.cr_frame, foo_coro.cr_frame.f_code is foo_coro.cr_code)\n",
            "def bar():\n",
            "    return foo_coro\n",
            "for index in range(2):\n",
            "    bar = types.coroutine(bar)\n",
            "    coro = bar()\n",
            "    print('coro-is', index, foo_coro is coro)\n",
            "    print('cr-code-flags', coro.cr_code.co_flags == foo_flags)\n",
            "    print('close', coro.close())\n",
            "    print('cr-frame-closed', coro.cr_frame is None)"
        ),
        &[
            "cr-running-before False",
            "cr-running-inside True",
            "cr-running-stop True False",
            "func-id True",
            "flags-stable True",
            "code-is True",
            "cr-frame-open frame True True",
            "coro-is 0 True",
            "cr-code-flags True",
            "close None",
            "cr-frame-closed True",
            "coro-is 1 True",
            "cr-code-flags True",
            "close None",
            "cr-frame-closed True",
        ],
    );
}

#[test]
fn cpython_types_coroutine_generator_wrapper_subset() {
    assert_output_with_stack(
        "import types, inspect, collections.abc as cabc\ndef relay():\n    got = yield \"first\"\n    final = yield got.upper()\n    return final * 2\ninner = relay()\n@types.coroutine\ndef hand_back():\n    return inner\nw = hand_back()\nprint(type(w).__name__, isinstance(w, types._GeneratorWrapper), isinstance(w, cabc.Coroutine), isinstance(w, cabc.Awaitable))\nprint(w.__await__() is inner, iter(w) is inner, w.__name__, w.__qualname__)\nsame = [getattr(w, n) is getattr(inner, n) for n in (\"gi_code\", \"gi_frame\", \"gi_running\", \"gi_suspended\", \"__name__\", \"__qualname__\")]\nprint(all(same), w.cr_code is inner.gi_code, w.cr_frame is inner.gi_frame)\nprint(bool(w.cr_code.co_flags & inspect.CO_GENERATOR), w.gi_running, w.gi_yieldfrom, w.gi_frame is None, w.gi_suspended)\nprint(next(w), w.send(\"abc\"), w.gi_suspended)\ntry:\n    w.send(21)\nexcept StopIteration as stop:\n    print(\"finished\", stop.value)\nvictim = relay()\ntw = types.coroutine(lambda: victim)()\ntw.send(None)\ntry:\n    tw.throw(KeyError(\"boom\"))\nexcept KeyError as exc:\n    print(\"thrown\", exc.args)\nprint(types.coroutine(hand_back)().__await__() is inner)\nfresh = types.coroutine(lambda: relay())()\ntext = repr(fresh)\nprint(\"GeneratorWrapper\" in text, text == str(fresh))\nwanted = {\"__await__\", \"__iter__\", \"__next__\", \"send\", \"throw\", \"close\", \"cr_code\", \"cr_frame\", \"cr_running\", \"cr_suspended\", \"gi_code\", \"gi_frame\", \"gi_running\", \"gi_suspended\"}\nprint(wanted <= set(dir(fresh)))",
        &["_GeneratorWrapper True True True", "True True relay relay", "True True True", "True False None False False", "first ABC True", "finished 42", "thrown ('boom',)", "True", "True True", "True"],
        16 * 1024 * 1024,
    );
}

