#[test]
fn cpython_types_coroutine_duck_generator_proxy_subset() {
    assert_output(
        concat!(
            "import types, collections.abc, weakref, unittest.mock\n",
            "class GenLike:\n",
            "    def send(self):\n",
            "        pass\n",
            "    def throw(self):\n",
            "        pass\n",
            "    def close(self):\n",
            "        pass\n",
            "    def __iter__(self):\n",
            "        pass\n",
            "    def __next__(self):\n",
            "        pass\n",
            "gen = unittest.mock.MagicMock(GenLike)\n",
            "gen.__iter__ = lambda gen: gen\n",
            "gen.__name__ = 'gen'\n",
            "gen.__qualname__ = 'test.gen'\n",
            "print('gen', isinstance(gen, collections.abc.Generator), iter(gen) is gen)\n",
            "@types.coroutine\n",
            "def foo():\n",
            "    return gen\n",
            "wrapper = foo()\n",
            "print('types', type(wrapper).__name__, isinstance(wrapper, types._GeneratorWrapper), isinstance(wrapper, collections.abc.Coroutine), isinstance(wrapper, collections.abc.Awaitable))\n",
            "print('await-iter', wrapper.__await__() is wrapper, iter(wrapper) is wrapper)\n",
            "print('names', wrapper.__name__ is gen.__name__, wrapper.__qualname__ is gen.__qualname__)\n",
            "for name in ['gi_running', 'gi_frame', 'gi_code', 'gi_yieldfrom', 'gi_suspended', 'cr_running', 'cr_frame', 'cr_code', 'cr_await', 'cr_suspended']:\n",
            "    try:\n",
            "        getattr(wrapper, name)\n",
            "        print('missing-attr', name, 'no-error')\n",
            "    except AttributeError:\n",
            "        print('missing-attr', name, 'AttributeError')\n",
            "gen.gi_running = object()\n",
            "gen.gi_frame = object()\n",
            "gen.gi_code = object()\n",
            "gen.gi_yieldfrom = object()\n",
            "gen.gi_suspended = object()\n",
            "print('attrs', wrapper.gi_running is gen.gi_running, wrapper.gi_frame is gen.gi_frame, wrapper.gi_code is gen.gi_code, wrapper.gi_yieldfrom is gen.gi_yieldfrom, wrapper.gi_suspended is gen.gi_suspended)\n",
            "print('crattrs', wrapper.cr_running is gen.gi_running, wrapper.cr_frame is gen.gi_frame, wrapper.cr_code is gen.gi_code, wrapper.cr_await is gen.gi_yieldfrom, wrapper.cr_suspended is gen.gi_suspended)\n",
            "wrapper.close()\n",
            "gen.close.assert_called_once_with()\n",
            "print('close-called')\n",
            "wrapper.send(1)\n",
            "gen.send.assert_called_once_with(1)\n",
            "gen.reset_mock()\n",
            "next(wrapper)\n",
            "gen.__next__.assert_called_once_with()\n",
            "gen.reset_mock()\n",
            "wrapper.throw(1, 2, 3)\n",
            "gen.throw.assert_called_once_with(1, 2, 3)\n",
            "gen.reset_mock()\n",
            "wrapper.throw(1, 2)\n",
            "gen.throw.assert_called_once_with(1, 2)\n",
            "gen.reset_mock()\n",
            "wrapper.throw(1)\n",
            "gen.throw.assert_called_once_with(1)\n",
            "gen.reset_mock()\n",
            "print('call-matrix')\n",
            "error = Exception()\n",
            "gen.throw.side_effect = error\n",
            "try:\n",
            "    wrapper.throw(1)\n",
            "except Exception as ex:\n",
            "    print('throw-prop', ex is error)\n",
            "gen.throw.side_effect = None\n",
            "gen.reset_mock()\n",
            "for label, call in [('throw0', lambda: wrapper.throw()), ('close1', lambda: wrapper.close(1)), ('send0', lambda: wrapper.send())]:\n",
            "    try:\n",
            "        call()\n",
            "    except TypeError:\n",
            "        print(label, 'TypeError')\n",
            "print('invalid-no-forward', not gen.throw.called, not gen.close.called, not gen.send.called)\n",
            "@types.coroutine\n",
            "def bar():\n",
            "    return wrapper\n",
            "print('double', bar() is wrapper)\n",
            "ref = weakref.ref(wrapper)\n",
            "print('weakref', ref() is wrapper, callable(ref), isinstance(ref, weakref.ReferenceType))"
        ),
        &[
            "gen True True",
            "types _GeneratorWrapper True True True",
            "await-iter True True",
            "names True True",
            "missing-attr gi_running AttributeError",
            "missing-attr gi_frame AttributeError",
            "missing-attr gi_code AttributeError",
            "missing-attr gi_yieldfrom AttributeError",
            "missing-attr gi_suspended AttributeError",
            "missing-attr cr_running AttributeError",
            "missing-attr cr_frame AttributeError",
            "missing-attr cr_code AttributeError",
            "missing-attr cr_await AttributeError",
            "missing-attr cr_suspended AttributeError",
            "attrs True True True True True",
            "crattrs True True True True True",
            "close-called",
            "call-matrix",
            "throw-prop True",
            "throw0 TypeError",
            "close1 TypeError",
            "send0 TypeError",
            "invalid-no-forward True True True",
            "double True",
            "weakref True True True",
        ],
    );
}

// Adapted from CPython Lib/test/test_types.py::FunctionTests. This covers the
// public `types.FunctionType` constructor over MiniPython code objects without
// depending on CPython's internal function layout.
#[test]
fn cpython_types_function_type_subset() {
    assert_output(
        "import types\ndef tmpl(x, /, y, *, z):\n    return [x, y, z]\nbuilt = types.FunctionType(tmpl.__code__, {}, \"built\", (10, 20), None, {\"z\": 30})\nprint(built(), built.__name__, built.__qualname__, built.__module__)\nprint(built.__defaults__, built.__kwdefaults__, type(built) is types.FunctionType, type(built).__name__)\nblank = types.FunctionType(tmpl.__code__, {})\nprint(blank.__name__, blank.__defaults__, blank.__kwdefaults__, blank(1, 2, z=3))\nnamed_mod = types.FunctionType(tmpl.__code__, {\"__name__\": \"pkg.mod\"}, None, (4, 5), None, {\"z\": 6})\nprint(named_mod(), named_mod.__name__, named_mod.__qualname__, named_mod.__module__)\nextra = types.FunctionType(tmpl.__code__, {}, \"extra\", (7, 8, 9), None, {\"z\": 0})\nprint(extra(), extra.__defaults__)\nbad_calls = {\n    \"code\": lambda: types.FunctionType(\"code\", {}),\n    \"globals\": lambda: types.FunctionType(tmpl.__code__, []),\n    \"name\": lambda: types.FunctionType(tmpl.__code__, {}, 5),\n    \"argdefs\": lambda: types.FunctionType(tmpl.__code__, {}, \"f\", [1]),\n    \"closure\": lambda: types.FunctionType(tmpl.__code__, {}, \"f\", None, [1]),\n    \"kwdefaults\": lambda: types.FunctionType(tmpl.__code__, {}, \"f\", None, None, [(\"z\", 1)]),\n}\nfor label, call in bad_calls.items():\n    try:\n        call()\n    except TypeError as e:\n        print(label, type(e).__name__, \"arg\" in str(e) or \"closure\" in str(e))",
        &["[10, 20, 30] built tmpl None", "(10, 20) {'z': 30} True function", "tmpl None None [1, 2, 3]", "[4, 5, 6] tmpl tmpl pkg.mod", "[8, 9, 0] (7, 8, 9)", "code TypeError True", "globals TypeError True", "name TypeError True", "argdefs TypeError True", "closure TypeError True", "kwdefaults TypeError True"],
    );
}

// Adapted from CPython public class-construction behavior for
// `types.FunctionType`. MiniPython recognizes the public function type object
// as a class-base candidate only so the final-base validator can reject it with
// CPython's public TypeError.
#[test]
fn cpython_types_functiontype_unacceptable_base_type_subset() {
    assert_output_with_stack(
        r#"import types

EXPECTED_MESSAGE = "type 'function' is not an acceptable base type"

def f():
    pass

def print_error(label, error):
    print(label, error.__class__.__name__, str(error), error.args, str(error) == EXPECTED_MESSAGE)

def show(label, callback):
    try:
        callback()
    except Exception as error:
        print_error(label, error)
    else:
        print(label, 'ok')

base = types.FunctionType
try:
    class FunctionClass(base):
        pass
except Exception as error:
    print_error('class-functiontype', error)
else:
    print('class-functiontype ok')

for label, call in [
    ('type-functiontype', lambda: type('FunctionTypeClass', (types.FunctionType,), {})),
    ('type-new-functiontype', lambda: type.__new__(type, 'FunctionTypeNew', (types.FunctionType,), {})),
    ('new-class-functiontype', lambda: types.new_class('FunctionTypeNewClass', (types.FunctionType,), {})),
    ('class-function-runtime', lambda: type('RuntimeFunctionClass', (f.__class__,), {})),
]:
    show(label, call)

class ModuleClass(types.ModuleType):
    pass
print('module-control', ModuleClass.__name__, ModuleClass.__bases__[0] is types.ModuleType)"#,
        &[
            "class-functiontype TypeError type 'function' is not an acceptable base type (\"type 'function' is not an acceptable base type\",) True",
            "type-functiontype TypeError type 'function' is not an acceptable base type (\"type 'function' is not an acceptable base type\",) True",
            "type-new-functiontype TypeError type 'function' is not an acceptable base type (\"type 'function' is not an acceptable base type\",) True",
            "new-class-functiontype TypeError type 'function' is not an acceptable base type (\"type 'function' is not an acceptable base type\",) True",
            "class-function-runtime TypeError type 'function' is not an acceptable base type (\"type 'function' is not an acceptable base type\",) True",
            "module-control ModuleClass True",
        ],
        32 * 1024 * 1024,
    );
}

