// Adapted from CPython public class-construction behavior for `types.CellType`.
// MiniPython recognizes the public cell type object and rejects it through the
// same class-base path used by direct class statements and type helpers.
#[test]
fn cpython_types_celltype_unacceptable_base_type_subset() {
    assert_output_with_stack(
        r#"import types

EXPECTED_MESSAGE = "type 'cell' is not an acceptable base type"

def make_cell(value):
    return (lambda x: lambda: x)(value).__closure__[0]

def print_error(label, error):
    print(label, error.__class__.__name__, str(error), error.args, str(error) == EXPECTED_MESSAGE)

def show(label, callback):
    try:
        callback()
    except Exception as error:
        print_error(label, error)
    else:
        print(label, 'ok')

base = types.CellType
try:
    class CellClass(base):
        pass
except Exception as error:
    print_error('class-celltype', error)
else:
    print('class-celltype ok')

for label, call in [
    ('type-celltype', lambda: type('CellTypeClass', (types.CellType,), {})),
    ('type-new-celltype', lambda: type.__new__(type, 'CellTypeNew', (types.CellType,), {})),
    ('new-class-celltype', lambda: types.new_class('CellTypeNewClass', (types.CellType,), {})),
    ('class-cell-closure', lambda: type('ClosureCellClass', (make_cell(1).__class__,), {})),
]:
    show(label, call)

class ModuleClass(types.ModuleType):
    pass
print('module-control', ModuleClass.__name__, ModuleClass.__bases__[0] is types.ModuleType)"#,
        &[
            "class-celltype TypeError type 'cell' is not an acceptable base type (\"type 'cell' is not an acceptable base type\",) True",
            "type-celltype TypeError type 'cell' is not an acceptable base type (\"type 'cell' is not an acceptable base type\",) True",
            "type-new-celltype TypeError type 'cell' is not an acceptable base type (\"type 'cell' is not an acceptable base type\",) True",
            "new-class-celltype TypeError type 'cell' is not an acceptable base type (\"type 'cell' is not an acceptable base type\",) True",
            "class-cell-closure TypeError type 'cell' is not an acceptable base type (\"type 'cell' is not an acceptable base type\",) True",
            "module-control ModuleClass True",
        ],
        32 * 1024 * 1024,
    );
}

// Adapted from CPython's `type_alias` grammar rule and PEP 695 soft-keyword
// behavior. `type` starts a type alias only in the statement form
// `type NAME [type_params] = expression`; otherwise it remains an ordinary name.
#[test]
fn cpython_type_alias_statement_subset() {
    assert_output(
        "type Alias = int\nprint(Alias.__name__, Alias.__value__.__name__)",
        &["Alias int"],
    );
    assert_output(
        "type Pair = tuple[int, str]\nprint(Pair.__name__, Pair.__value__.__origin__.__name__, Pair.__value__.__args__[0].__name__, Pair.__value__.__args__[1].__name__)",
        &["Pair tuple int str"],
    );
    assert_output(
        "type Alias[T] = list[T]\nprint(Alias.__name__, Alias.__type_params__[0].__name__, Alias.__value__.__origin__.__name__, Alias.__value__.__args__[0].__name__)",
        &["Alias T list T"],
    );
    assert_output("type = \"soft\"\nprint(type)", &["soft"]);
    assert_output(
        "def f():\n    type Local = int\n    return Local.__name__\nprint(f())",
        &["Local"],
    );
    assert_output(
        "class C:\n    type Local = int\nprint(C.Local.__name__)",
        &["Local"],
    );
    assert_output(
        "type type = int\nprint(type.__name__, type.__value__.__name__)",
        &["type int"],
    );
    assert_error(
        "type Alias int",
        "parse error: expected '=', found Identifier(\"int\")",
    );
}

// Adapted from CPython Lib/test/test_type_params.py duplicate-name syntax
// checks. MiniPython reports its own parse error wording, but preserves the
// same rejected source shapes.
#[test]
fn cpython_type_params_duplicate_name_subset() {
    assert_error(
        "def func[**A, A]():\n    pass",
        "parse error: duplicate type parameter name: A",
    );
    assert_error(
        "def func[A, *A]():\n    pass",
        "parse error: duplicate type parameter name: A",
    );
    assert_error(
        "def func[*A, **A]():\n    pass",
        "parse error: duplicate type parameter name: A",
    );
    assert_error(
        "class C[**A, A]():\n    pass",
        "parse error: duplicate type parameter name: A",
    );
    assert_error(
        "class C[A, *A]:\n    pass",
        "parse error: duplicate type parameter name: A",
    );
    assert_error(
        "class C[*A, **A]():\n    pass",
        "parse error: duplicate type parameter name: A",
    );
    assert_error(
        "type Alias[*A, **A] = int",
        "parse error: duplicate type parameter name: A",
    );
}

// Adapted from CPython
// Lib/test/test_type_params.py::TypeParamsInvalidTest name non-collision
// methods. Type parameter names are distinct from ordinary parameter, local,
// comprehension, annotation-target, nested generic, and global bindings.
#[test]
fn cpython_type_params_invalid_non_collision_subset() {
    assert_output(
        "def same[N](N):\n    return N * 2\ndef star[N](*N):\n    return len(N)\nprint(same(4), star(1, 2, 3), same.__type_params__[0].__name__, star.__type_params__[0].__name__)",
        &["8 3 N N"],
    );
    assert_output(
        "class Mangle:\n    def private[__V](self, __V):\n        return __V\n    def pre_mangled[_Mangle__V](self, __V):\n        return __V\nprint(Mangle().private(\"p\"), Mangle.private.__type_params__[0].__name__)\nprint(Mangle().pre_mangled(\"q\"), Mangle.pre_mangled.__type_params__[0].__name__)",
        &["p __V", "q _Mangle__V"],
    );
    assert_output(
        "class Holder[Y]:\n    def as_param(self, Y):\n        return Y\n    def as_local(self):\n        Y = \"local\"\n        return Y\n    def as_loop(self):\n        return [Y for Y in \"ab\"]\n    def again[Y](self):\n        return Y\n    Y: str\nouter, = Holder.__type_params__\ninner, = Holder.again.__type_params__\nprint(Holder().as_param(5), Holder().as_local(), Holder().as_loop())\nprint(outer.__name__, inner.__name__, outer is inner, Holder().again() is inner)\nprint(Holder.__annotations__[\"Y\"] is str)",
        &["5 local ['a', 'b']", "Y Y False True", "True"],
    );
    assert_output(
        "G = \"before\"\ndef factory():\n    def setter[G]():\n        global G\n        G = \"after\"\n    return setter\nprint(G)\nfactory()()\nprint(G)",
        &["before", "after"],
    );
}

// Adapted from CPython
// Lib/test/test_syntax.py::SyntaxErrorTestCase::test_disallowed_type_param_names.
// The source is CPython-only today, so this remains a MiniPython parser subset
