// Adapted from CPython Lib/test/test_type_params.py::TypeParamsAccessTest.
// This covers the supported core access semantics: annotations and type aliases
// reuse the exact type-parameter objects, defaults/decorators are outside the
// type-parameter scope, type parameters do not leak after their definition, and
// later type parameters can reference earlier ones in bounds.
#[test]
fn cpython_type_params_access_core_subset() {
    assert_output(
        "from typing import Generic\nimport types\nclass Table[Key, Val](dict[Key, Val]):\n    pass\nKey, Val = Table.__type_params__\nfirst, second = types.get_original_bases(Table)\nprint(Table.__bases__ == (dict, Generic))\nprint(first.__origin__ is dict, first.__args__ == (Key, Val))\nprint(second.__origin__ is Generic, second.__args__ == (Key, Val))",
        &["True", "True True", "True True"],
    );
    assert_output(
        "class Kind[M, N](type):\n    pass\nclass Thing[M, N](metaclass=Kind[M, N]):\n    pass\nmeta_params = Kind.__type_params__\nown_params = Thing.__type_params__\nprint([a is b for a, b in zip(meta_params, own_params)], type(Thing) is Kind)",
        &["[False, False] True"],
    );
    assert_error_contains(
        "def tagger(value):\n    return lambda cls: cls\n@tagger(Hidden)\nclass Visible[Hidden]:\n    pass",
        "NameError:",
    );
    assert_error_contains(
        "def tagger(value):\n    return lambda fn: fn\n@tagger(Hidden)\ndef visible[Hidden]():\n    pass",
        "NameError:",
    );
    assert_error_contains(
        "def defaulted[Hidden](arg=tuple[Hidden]):\n    pass",
        "NameError:",
    );
    assert_output(
        "def mapping[Key, Val](table: dict[Key, Val], fallback: Val) -> Key:\n    pass\nKey, Val = mapping.__type_params__\nnotes = mapping.__annotations__\nprint(notes[\"table\"].__args__ == (Key, Val), notes[\"fallback\"] is Val, notes[\"return\"] is Key)",
        &["True True True"],
    );
    assert_output(
        "class Host:\n    alias = bytes\n    count = 7\n    def method[Item](self, first: alias, second: Item, third: count):\n        pass\n(Item,) = Host.method.__type_params__\nnotes = Host.method.__annotations__\nprint(notes[\"first\"] is bytes, notes[\"second\"] is Item, notes[\"third\"])",
        &["True True 7"],
    );
    assert_output(
        "class Level1[P1]:\n    def level2[P2](self):\n        class Level3[P3]:\n            def level4[P4](self):\n                return lambda: [P1, P2, P3, P4]\n        return Level3\nLevel3 = Level1().level2()\nexpected = [Level1.__type_params__[0], Level1.level2.__type_params__[0],\n            Level3.__type_params__[0], Level3.level4.__type_params__[0]]\nprint(Level3().level4()() == expected, [t.__name__ for t in expected])",
        &["True ['P1', 'P2', 'P3', 'P4']"],
    );
    assert_error_contains(
        "class Scoped[Leaky]:\n    pass\nprint(Leaky)",
        "NameError:",
    );
    assert_error_contains(
        "class Outer[Seen]:\n    def method[Unseen](self):\n        pass\n    probe = Unseen",
        "NameError:",
    );
    assert_output(
        "from typing import Generic\nimport types\nclass Namespace:\n    class Parent:\n        pass\n    class Kid[Q](Parent):\n        pass\n(Q,) = Namespace.Kid.__type_params__\norig = types.get_original_bases(Namespace.Kid)\nprint(Namespace.Kid.__bases__ == (Namespace.Parent, Generic))\nprint(orig[0] is Namespace.Parent, orig[1].__origin__ is Generic, orig[1].__args__ == (Q,))",
        &["True", "True True True"],
    );
    assert_output(
        "class Shadow[S]:\n    S = \"class attribute wins\"\n    type Direct = S\nprint(Shadow.Direct.__value__)",
        &["class attribute wins"],
    );
    assert_output(
        "def wrapper[W]():\n    W = \"local\"\n    def change():\n        nonlocal W\n        W = \"changed\"\n        return W\n    return (lambda: W), change\n(W,) = wrapper.__type_params__\nread, change = wrapper()\nprint(W.__name__, read(), change(), read())",
        &["W local changed changed"],
    );
    assert_output(
        "from collections.abc import Mapping\ndef nested[K, V: Mapping[str, K]]():\n    pass\nK, V = nested.__type_params__\nprint(V.__bound__.__origin__ is Mapping, V.__bound__.__args__ == (str, K))",
        &["True True"],
    );
    assert_output(
        "class Animal:\n    def speak(self):\n        return \"generic\"\nclass Dog(Animal):\n    def speak[R](self, times: int) -> R:\n        return super().speak() + \"-dog\" * times\nprint(Dog().speak(2))",
        &["generic-dog-dog"],
    );
    assert_output(
        "type Thunk[Z] = lambda: Z\nprint(Thunk.__value__() is Thunk.__type_params__[0])",
        &["True"],
    );
    assert_output(
        "from typing import get_args\nimport types\ndef scope():\n    captured = \"captured\"\n    class Root[Z]:\n        pass\n    class Leaf[Z](Root[lambda: (captured, Z)]):\n        pass\n    root_alias, _ = types.get_original_bases(Leaf)\n    (thunk,) = get_args(root_alias)\n    print(thunk() == (\"captured\", Leaf.__type_params__[0]))\nscope()",
        &["True"],
    );
    assert_output(
        "Z = Y = \"module\"\nclass Plain:\n    Z = Y = \"class\"\n    type NoParams = lambda: Z\n    type WithParam[Z] = lambda: (Z, Y)\nprint(Plain.NoParams.__value__())\nz_val, y_val = Plain.WithParam.__value__()\nprint(z_val is Plain.WithParam.__type_params__[0], y_val)",
        &["module", "True module"],
    );
    assert_output(
        "class Gen[Z, Y]:\n    Z = Y = \"class\"\n    type NoParams = lambda: Z\n    type WithParam[Z] = lambda: (Z, Y)\nprint(Gen.NoParams.__value__() is Gen.__type_params__[0])\nz_val, y_val = Gen.WithParam.__value__()\nprint(z_val is Gen.WithParam.__type_params__[0], y_val is Gen.__type_params__[1])",
        &["True", "True True"],
    );
    assert_output(
        "Z = \"module\"\nclass Plain:\n    Z = \"class\"\n    type GenNo = (Z for _ in \"x\")\n    type GenParam[Z] = (Z for _ in \"x\")\n    type ListNo = [Z for _ in \"x\"]\n    type ListParam[Z] = [Z for _ in \"x\"]\nprint(next(Plain.GenNo.__value__), Plain.ListNo.__value__)\nprint(next(Plain.GenParam.__value__) is Plain.GenParam.__type_params__[0])\nprint(Plain.ListParam.__value__[0] is Plain.ListParam.__type_params__[0])",
        &["module ['module']", "True", "True"],
    );
    assert_output(
        "type Odd[Z: ([Z for Z in (Z, \"ab\")[1]], Z)] = [Z for Z in Z.__name__ * 2]\nprint(Odd.__value__)\n(Z,) = Odd.__type_params__\nprint(Z.__constraints__[0], Z.__constraints__[1] is Z, Z.__bound__)",
        &["['Z', 'Z']", "['a', 'b'] True None"],
    );
    assert_output(
        "type Odd[Z: [lambda: Z for Z in (Z, \"q\")[1]]] = [lambda: Z for Z in Z.__name__]\n(f,) = Odd.__value__\n(Z,) = Odd.__type_params__\n(g,) = Z.__bound__\nprint(f(), g())\ndef odd_func[Z: [lambda: Z for Z in (Z, \"q\")[1]]]():\n    return [lambda: Z for Z in Z.__name__]\n(f,) = odd_func()\n(g,) = odd_func.__type_params__[0].__bound__\nprint(f(), g())",
        &["Z q", "Z q"],
    );
    assert_output(
        "def carrier(value):\n    class Carrier:\n        payload = value\n    return Carrier\nclass Gen[Z]:\n    Z = \"class\"\n    class Inner(carrier(Z for _ in \"x\"), carrier([Z for _ in \"x\"]), carrier(Z)):\n        pass\n    class InnerGeneric[U](carrier(Z for _ in \"x\"), carrier([Z for _ in \"x\"]), carrier(Z)):\n        pass\n(Z,) = Gen.__type_params__\nfor cls in (Gen.Inner, Gen.InnerGeneric):\n    gen_base, list_base, plain_base = cls.__bases__[:3]\n    print(next(gen_base.payload) is Z, list_base.payload[0] is Z, plain_base.payload)",
        &["True True class", "True True class"],
    );
    assert_output(
        "class Gen[Z]:\n    Z = \"class\"\n    def method[U](a: (Z for _ in \"x\"), b: [Z for _ in \"x\"], c: Z):\n        pass\nnotes = Gen.method.__annotations__\n(Z,) = Gen.__type_params__\nprint(next(notes[\"a\"]) is Z, notes[\"b\"][0] is Z, notes[\"c\"])",
        &["True True class"],
    );
    assert_output(
        "print(type.__type_params__, object.__type_params__, int.__type_params__)",
        &["() () ()"],
    );
}

// Adapted from CPython Lib/test/test_type_params.py::TypeParamsManglingTest.
// Type parameter names retain their public spelling but are also visible
// through class-private mangled references inside class bodies, methods,
// aliases, bases, lambdas, and comprehensions.
#[test]
fn cpython_type_params_mangling_subset() {
    assert_output(
        "class Crate[__K]:\n    alias_k = __K\n    def put[__W](self, a: __K, b: __W) -> tuple:\n        return __K, __W\n    type Label[__L] = [__K, __L]\nK, = Crate.__type_params__\nW, = Crate.put.__type_params__\nL, = Crate.Label.__type_params__\nprint([t.__name__ for t in (K, W, L)], Crate.alias_k is K)\nnotes = Crate.put.__annotations__\nprint(notes[\"a\"] is K, notes[\"b\"] is W, Crate().put(0, 0) == (K, W))\nprint(Crate.Label.__value__ == [K, L])",
        &["['__K', '__W', '__L'] True", "True True True", "True"],
    );
    assert_output(
        "__first = 1\nclass Gap[Z]:\n    pass\n__second = 2\nprint(__first + __second)\ndef holder():\n    class Local[Z]:\n        pass\n    __hidden = \"plain\"\n    return sorted(k for k in locals() if k.startswith(\"__\")), __hidden\nprint(holder())\nclass Shell:\n    __a = \"shell a\"\n    class Core[Z]:\n        __b = \"core b\"\n    __c = \"shell c\"\nprint(Shell._Shell__a, Shell.Core._Core__b, Shell._Shell__c)",
        &["3", "(['__hidden'], 'plain')", "shell a core b shell c"],
    );
    assert_output(
        "from typing import Generic\ndef box(value):\n    class Carrier:\n        payload = value\n    return Carrier\nclass __Root:\n    def __init_subclass__(cls, **kw):\n        cls.kw = kw\nclass Leaf[Z](__Root, __flag=\"on\"):\n    pass\nprint(Leaf.__bases__ == (__Root, Generic), Leaf.kw)\nclass __Mark:\n    pass\nclass Tagged[Z: __Mark](box(lambda: __Mark), box(lambda: lambda: __Mark), box([m for m in (__Mark,)]), box(m for m in (__Mark,))):\n    pass\nZ, = Tagged.__type_params__\nb0, b1, b2, b3, _ = Tagged.__bases__\nprint(Z.__bound__ is __Mark, b0.payload() is __Mark, b1.payload()() is __Mark, b2.payload[0] is __Mark, next(b3.payload) is __Mark)\nclass Chain[__P, __Q: __P](box(__P), box(lambda: __Q)):\n    seen = __Q\nP, Q = Chain.__type_params__\nc0, c1, _ = Chain.__bases__\nprint(P.__name__, Q.__name__, Q.__bound__ is P, Chain.seen is Q, c0.payload is P, c1.payload() is Q)",
        &["True {'__flag': 'on'}", "True True True True True", "__P __Q True True True True"],
    );
}

