// Adapted from CPython Lib/test/test_type_params.py::
// TypeParamsLazyEvaluationTest.test_recursive_class and test_evaluation_error.
#[test]
fn cpython_type_params_lazy_evaluation_bounds_subset() {
    assert_output(
        "from typing import NoDefault\nclass Foo[T: Foo, U: (Foo, Foo)]:\n    pass\nT, U = Foo.__type_params__\nprint(T.__name__, T.__bound__ is Foo, T.__constraints__, T.__default__ is NoDefault)\nprint(U.__name__, U.__bound__, U.__constraints__[0] is Foo, U.__constraints__[1] is Foo, U.__default__ is NoDefault)",
        &["T True () True", "U None True True True"],
    );
    assert_output(
        "from typing import NoDefault\nclass Foo[T: Undefined, U: (Undefined,)]:\n    pass\nT, U = Foo.__type_params__\ndef show(label, fn):\n    try:\n        print(label, fn())\n    except NameError as error:\n        print(label, type(error).__name__)\nshow(\"T bound\", lambda: T.__bound__)\nprint(\"T constraints\", T.__constraints__)\nprint(\"U bound\", U.__bound__)\nshow(\"U constraints\", lambda: U.__constraints__)\nprint(T.__default__ is NoDefault, U.__default__ is NoDefault)\nUndefined = \"defined\"\nprint(T.__bound__)\nprint(T.__constraints__)\nprint(U.__bound__)\nprint(U.__constraints__)",
        &[
            "T bound NameError",
            "T constraints ()",
            "U bound None",
            "U constraints NameError",
            "True True",
            "defined",
            "()",
            "None",
            "('defined',)",
        ],
    );
}

// Adapted from CPython Lib/test/test_type_params.py::DefaultsTest coverage for
// default values on plain, variadic, and ParamSpec type parameters.
#[test]
fn cpython_type_param_defaults_subset() {
    assert_output(
        "def foo[T = int, **P = float, *Ts = None]():\n    pass\nprint(foo.__type_params__[0].__default__.__name__, foo.__type_params__[1].__default__.__name__, foo.__type_params__[2].__default__)",
        &["int float None"],
    );
    assert_output(
        "class Foo[T = int, **P = float, *Ts = None]:\n    pass\nprint(Foo.__type_params__[0].__default__.__name__, Foo.__type_params__[1].__default__.__name__, Foo.__type_params__[2].__default__)",
        &["int float None"],
    );
    assert_output(
        "type Foo[T = int, **P = float, *Ts = None] = int\nprint(Foo.__type_params__[0].__default__.__name__, Foo.__type_params__[1].__default__.__name__, Foo.__type_params__[2].__default__)",
        &["int float None"],
    );
    assert_output(
        "default = tuple[int, str]\ntype Alias[*Ts = *default] = Ts\nTs, = Alias.__type_params__\niter_t = iter(default)\nstarred = next(iter_t)\nprint(repr(starred))\nprint(Ts.__default__ == starred)\nprint(Ts.__default__.__origin__.__name__, Ts.__default__.__args__[0].__name__, Ts.__default__.__args__[1].__name__)\ntry:\n    next(iter_t)\nexcept StopIteration:\n    print(\"stopped\")",
        &["*tuple[int, str]", "True", "tuple int str", "stopped"],
    );
    assert_output(
        "def foo[T = list[int], **P = dict[str, int]]():\n    pass\nprint(foo.__type_params__[0].__default__.__origin__.__name__, foo.__type_params__[0].__default__.__args__[0].__name__)\nprint(foo.__type_params__[1].__default__.__origin__.__name__, foo.__type_params__[1].__default__.__args__[0].__name__, foo.__type_params__[1].__default__.__args__[1].__name__)",
        &["list int", "dict str int"],
    );
}

// Adapted from CPython Lib/test/test_type_params.py::TestEvaluateFunctions.
// MiniPython covers the public evaluate_* callable surface and the immutable
// const-evaluator type safety regression without modeling CPython's internals.
#[test]
fn cpython_type_params_evaluate_functions_subset() {
    assert_output(
        "import annotationlib as al\nfrom typing import ParamSpec, TypeAliasType, TypeVar, TypeVarTuple\ntype Native = bytes\nBuilt = TypeAliasType(\"Built\", bytes)\ndef gen[X: bytes = bytes, **Y = bytes, *Z = bytes]():\n    pass\nX, Y, Z = gen.__type_params__\nmX = TypeVar(\"mX\", bound=bytes, default=bytes)\nmY = ParamSpec(\"mY\", default=bytes)\nmZ = TypeVarTuple(\"mZ\", default=bytes)\nfuncs = [\n    Native.evaluate_value, Built.evaluate_value,\n    X.evaluate_bound, X.evaluate_default, Y.evaluate_default, Z.evaluate_default,\n    mX.evaluate_bound, mX.evaluate_default, mY.evaluate_default, mZ.evaluate_default,\n]\nF = al.Format\nfor fn in funcs:\n    results = [fn(1), al.call_evaluate_function(fn, F.VALUE), al.call_evaluate_function(fn, F.FORWARDREF)]\n    print(all(r is bytes for r in results), al.call_evaluate_function(fn, F.STRING))",
        &["True bytes", "True bytes", "True bytes", "True bytes", "True bytes", "True bytes", "True bytes", "True bytes", "True bytes", "True bytes"],
    );
    assert_output(
        "import annotationlib as al\nfrom typing import TypeVar\ndef g[C: (bytes, float)]():\n    pass\n(C,) = g.__type_params__\nfor tv in (C, TypeVar(\"D\", bytes, float)):\n    ev = tv.evaluate_constraints\n    same = [ev(1), al.call_evaluate_function(ev, al.Format.VALUE), al.call_evaluate_function(ev, al.Format.FORWARDREF)]\n    print(all(s == (bytes, float) for s in same), al.call_evaluate_function(ev, al.Format.STRING))",
        &["True (bytes, float)", "True (bytes, float)"],
    );
    assert_output(
        "from typing import TypeVar\ntv = TypeVar(\"tv\", bound=complex)\nev = tv.evaluate_bound\nprint(ev)\nkind = type(ev)\nfor label, action in [(\"new\", lambda: kind()), (\"setattr\", lambda: setattr(kind, \"extra\", 0))]:\n    try:\n        action()\n    except TypeError as e:\n        msg = str(e)\n        print(label, \"_typing._ConstEvaluator\" in msg, \"cannot create\" in msg or \"cannot set 'extra'\" in msg)",
        &["<constevaluator <class 'complex'>>", "new True True", "setattr True True"],
    );
}

// Adapted from CPython Lib/test/test_type_params.py::
