// Adapted from CPython Lib/test/test_type_params.py::
// DefaultsTest.test_lazy_evaluation, test_symtable_key_regression_default, and
// test_symtable_key_regression_name. Defaults are evaluated lazily and cached
// after a successful lookup, while default expressions keep the correct
// type-parameter symbol bindings.
#[test]
fn cpython_type_param_defaults_lazy_and_symtable_subset() {
    assert_output(
        "type Grid[R = Later, *Cols = Later, **Opts = Later] = None\nparams = Grid.__type_params__\nfor p in params:\n    try:\n        p.__default__\n    except NameError as err:\n        print(p.__name__, \"unresolved\", type(err).__name__)\nLater = 1\nprint([p.__default__ for p in params])\nLater = 2\nprint([p.__default__ for p in params])",
        &["R unresolved NameError", "Cols unresolved NameError", "Opts unresolved NameError", "[1, 1, 1]", "[1, 1, 1]"],
    );
    assert_output(
        "type Echo[E = {E: [E for E in (E,)]}] = E\n(E,) = Echo.__type_params__\ndefault = E.__default__\nprint(list(default) == [E], default[E][0] is E, Echo.__value__ is E)",
        &["True True True"],
    );
    assert_output(
        "type First[P = Alpha] = P\ntype Second[P = Beta] = P\nAlpha, Beta = \"alpha\", \"beta\"\nprint([alias.__type_params__[0].__default__ for alias in (First, Second)])",
        &["['alpha', 'beta']"],
    );
}

// Adapted from CPython Lib/test/test_type_params.py::
// DefaultsTest.test_nondefault_after_default. Once any type parameter in a
// list has a default, later parameters must also have defaults.
#[test]
fn cpython_type_param_nondefault_after_default_subset() {
    let message = "parse error: non-default type parameter 'U' follows default type parameter";
    assert_error("def func[T=int, U]():\n    pass", message);
    assert_error("class C[T=int, U]:\n    pass", message);
    assert_error("type A[T=int, U] = int", message);
}

// Adapted from CPython Lib/test/test_type_params.py::TypeParamsComplexCallsTest.
// These cases pressure generic functions with both defaults and kwdefaults,
// plus class-header unpacking and keyword propagation into __init_subclass__.
#[test]
fn cpython_type_params_complex_calls_subset() {
    assert_output(
        "def choose[V](x: V = 10, *, y: V = 20):\n    return x, y\n(V,) = choose.__type_params__\nprint(all(a is V for a in choose.__annotations__.values()))\nprint(choose(), choose(1), choose(y=2), choose(3, y=4))",
        &["True", "(10, 20) (1, 20) (10, 2) (3, 4)"],
    );
    assert_output(
        "from typing import Generic\nclass Recorder:\n    def __init_subclass__(cls, **options):\n        cls.options = sorted(options.items())\nextra = {\"z\": 26}\nclass Gen[K](Recorder, x=24, y=25, **extra):\n    pass\nprint(Gen.options, Gen.__bases__ == (Recorder, Generic), [p.__name__ for p in Gen.__type_params__])\nparents = [Recorder]\nclass Gen2[K](*parents, **extra):\n    pass\nprint(Gen2.options, Gen2.__bases__ == (Recorder, Generic))",
        &["[('x', 24), ('y', 25), ('z', 26)] True ['K']", "[('z', 26)] True"],
    );
    assert_output(
        "from typing import Generic\nclass Empty[K](*()):\n    pass\nprint(Empty.__bases__ == (Generic,), Empty.__type_params__[0].__name__)\nclass Plainbase:\n    pass\nclass Gen3[K](*(Plainbase,)):\n    pass\nprint(Gen3.__bases__ == (Plainbase, Generic))",
        &["True K", "True"],
    );
}

// Adapted from CPython Lib/test/test_type_params.py::
// TypeParamsTraditionalTypeVarsTest. Traditional typing.TypeVar objects can be
// used in ordinary annotations, but PEP 695 generic class headers cannot
// inherit from explicit Generic[...] or mix undeclared traditional TypeVars
// into their generic bases.
#[test]
fn cpython_type_params_traditional_typevars_subset() {
    assert_output(
        "from typing import Generic, TypeVar\nOld = TypeVar(\"Old\")\ntry:\n    class Wrapped[New](Generic[New]):\n        pass\nexcept TypeError as exc:\n    print(\"explicit Generic base:\", type(exc).__name__, \"Generic\" in str(exc))\ntry:\n    class Mixed[New](tuple[New, Old]):\n        pass\nexcept TypeError as exc:\n    print(\"undeclared TypeVar in base:\", type(exc).__name__)",
        &["explicit Generic base: TypeError True", "undeclared TypeVar in base: TypeError"],
    );
    assert_output(
        "from typing import TypeVar\nOld = TypeVar(\"Old\")\ndef pair[New](first: New, second: Old) -> New | Old:\n    return second\n(New,) = pair.__type_params__\nann = pair.__annotations__\nprint(pair(\"a\", \"b\"), ann[\"first\"] is New, ann[\"second\"] is Old, ann[\"return\"].__origin__.__name__)\nprint(Old.__name__, Old.__infer_variance__, Old.__covariant__, Old.__contravariant__)\nimport ast\nnode = ast.TypeVar(name=\"Z\")\nprint(type(node).__name__, node.name)",
        &["b True True Union", "Old False False False", "TypeVar Z"],
    );
}

// Adapted from CPython Lib/test/test_type_params.py::TypeParamsTypeVarTest.
// PEP 695 type parameters expose runtime objects compatible with
// typing.TypeVar, including lazy bounds, tuple constraints, variance metadata,
// and capture through generator/coroutine nested scopes.
#[test]
fn cpython_type_params_typevar_runtime_subset() {
    assert_output(
        "from typing import TypeVar\ndef probe[Num: float, Mixed: bytes | None, Pick: (list, dict)]():\n    return Num, Mixed, Pick\nn, m, p = probe()\nfor tv in (n, m, p):\n    print(isinstance(tv, TypeVar), tv.__name__, tv.__infer_variance__, tv.__covariant__, tv.__contravariant__)\nprint(n.__bound__ is float, n.__constraints__)\nprint(m.__bound__.__args__ == (bytes, type(None)), m.__constraints__)\nprint(p.__bound__, p.__constraints__ == (list, dict))",
        &["True Num True False False", "True Mixed True False False", "True Pick True False False", "True ()", "True ()", "None True"],
    );
    assert_output_with_stack(
        "from typing import TypeVar\ndef source[Outer]():\n    def leaf[Leaf]():\n        yield Leaf\n    def middle[Mid]():\n        yield Outer\n        yield Mid\n        yield from leaf()\n    return middle\nproduced = list(source()())\nprint([t.__name__ for t in produced], all(isinstance(t, TypeVar) for t in produced))",
        &["['Outer', 'Mid', 'Leaf'] True"],
        32 * 1024 * 1024,
    );
    assert_output(
        "from typing import TypeVar\ndef maker[First]():\n    async def job[Second]():\n        return First, Second\n    return job\npending = maker()()\ntry:\n    pending.send(None)\nexcept StopIteration as stop:\n    print([v.__name__ for v in stop.value], all(isinstance(v, TypeVar) for v in stop.value))",
        &["['First', 'Second'] True"],
    );
}

// Adapted from CPython Lib/test/test_type_params.py::
// TypeParamsTypeVarTupleTest and TypeParamsTypeVarParamSpecTest. Invalid
// variadic bounds are covered by `cpython_invalid_type_param_subset`; this
// runtime slice proves PEP 695 objects match typing.TypeVarTuple / ParamSpec.
#[test]
fn cpython_type_params_typevartuple_paramspec_runtime_subset() {
    assert_output(
        "from typing import TypeVarTuple, ParamSpec\ndef func1[*A]():\n    return A\ndef func2[**P]():\n    return P\na = func1()\np = func2()\nprint(isinstance(a, TypeVarTuple), a.__name__, a.__kind__)\nprint(isinstance(p, ParamSpec), p.__name__, p.__kind__, p.__infer_variance__, p.__covariant__, p.__contravariant__)",
        &["True A TypeVarTuple", "True P ParamSpec True False False"],
    );
    assert_output(
        "from typing import TypeVarTuple, ParamSpec, NoDefault\nTs = TypeVarTuple('Ts')\nP = ParamSpec('P')\nprint(isinstance(Ts, TypeVarTuple), Ts.__name__, Ts.__default__ is NoDefault)\nprint(isinstance(P, ParamSpec), P.__name__, P.__default__ is NoDefault, P.__infer_variance__, P.__covariant__, P.__contravariant__)",
        &["True Ts True", "True P True False False False"],
    );
}

// Adapted from CPython Lib/test/test_type_params.py::TypeParamsWeakRefTest.
// The CPython method asserts these public type-parameter objects accept
// `weakref.ref()`; it does not require collection-time clearing behavior.
#[test]
fn cpython_type_params_weakrefs_subset() {
    assert_output(
        concat!(
            "from typing import Generic, ParamSpec, TypeVar, TypeVarTuple\n",
            "import weakref\n",
            "T = TypeVar('T')\n",
            "P = ParamSpec('P')\n",
            "class OldStyle(Generic[T]):\n",
            "    pass\n",
            "class NewStyle[T]:\n",
            "    pass\n",
            "cases = [\n",
            "    T,\n",
            "    TypeVar('T', bound=int),\n",
            "    P,\n",
            "    P.args,\n",
            "    P.kwargs,\n",
            "    TypeVarTuple('Ts'),\n",
            "    OldStyle,\n",
            "    OldStyle[int],\n",
            "    OldStyle(),\n",
            "    NewStyle,\n",
            "    NewStyle[int],\n",
            "    NewStyle(),\n",
            "    Generic[T],\n",
            "]\n",
            "refs = [weakref.ref(case) for case in cases]\n",
            "print(len(refs), all(callable(ref) for ref in refs), all(isinstance(ref, weakref.ReferenceType) for ref in refs))\n",
            "print(type(P.args).__name__, P.args.__origin__ is P, type(P.kwargs).__name__, P.kwargs.__origin__ is P)"
        ),
        &["13 True True", "ParamSpecArgs True ParamSpecKwargs True"],
    );
}

// Adapted from CPython Lib/test/test_type_params.py::
